process.on('uncaughtException', (error) => {
  console.error('[Electron Main Uncaught Exception]:', error?.message || error)
  if (error?.stack) {
    console.error(error.stack)
  }
})

process.on('unhandledRejection', (reason) => {
  console.error('[Electron Main Unhandled Rejection]:', reason)
})

// Đảm bảo chỉ có DUY NHẤT 1 instance chạy trên toàn máy tính (Ngăn chặn mở nhiều ứng dụng trùng lặp gây lag máy)
const gotSingleInstanceLock = app.requestSingleInstanceLock()
if (!gotSingleInstanceLock) {
  app.quit()
  process.exit(0)
}

const execAsync = promisify(exec)

const BASE_URL = 'http://localhost:5173'

// Cấu hình tối ưu bộ nhớ V8 và hạn chế số lượng tiến trình nền (Đặc biệt tối ưu cho máy yếu)
const totalRamMB = Math.round(os.totalmem() / (1024 * 1024))
const isLowEndMachine = totalRamMB <= 6144

// Phân bổ heap thông minh: máy yếu (<=6GB) cấp tối đa 1.5GB để tránh chiếm hết RAM vật lý gây đơ hệ điều hành, máy mạnh cấp 4GB
const maxHeapSize = isLowEndMachine ? 1536 : 4096
app.commandLine.appendSwitch('js-flags', `--max-old-space-size=${maxHeapSize} --expose-gc`)

// Giảm số lượng Renderer Process: gom các tiến trình thay vì mở tràn lan
app.commandLine.appendSwitch('renderer-process-limit', '2')

// Tắt các dịch vụ chạy ngầm thừa thãi của Chromium (AudioService độc lập, Speech API) để giảm 2 tiến trình trong Task Manager
app.commandLine.appendSwitch(
  'disable-features',
  'AudioServiceOutOfProcess,CalculateNativeWinOcclusion'
)
app.commandLine.appendSwitch('disable-speech-api')
app.commandLine.appendSwitch('no-sandbox')
app.commandLine.appendSwitch('log-level', '3')

// Chỉ bật các cờ GPU chuyên sâu nếu máy có card/RAM đủ để tránh crash GPU Broker trên máy yếu
if (!isLowEndMachine) {
  app.commandLine.appendSwitch('ignore-gpu-blocklist')
  app.commandLine.appendSwitch('enable-gpu-rasterization')
  app.commandLine.appendSwitch('enable-zero-copy')
}

let width, height
let mainWindow
let settingsWindow = null
let preMaxBounds = null
let isWindowMaximized = false
let currentWindowMode = 'login'

function toggleMaximizeWindow(win) {
  if (!win || win.isDestroyed()) return
  if (win === mainWindow && currentWindowMode === 'login') return // Không cho phép phóng to khi đang ở màn hình Login

  if (process.platform === 'darwin') {
    const isFull = win.isFullScreen()
    win.setFullScreen(!isFull)
    if (win === mainWindow) {
      isWindowMaximized = !isFull
    }
    win.webContents.send('window:maximized-change', !isFull)
    return
  }

  if (win.isMaximized()) {
    win.unmaximize()
  } else {
    win.maximize()
  }
}

function getSettingsWindowPosition(settingsW, settingsH) {
  if (!mainWindow || mainWindow.isDestroyed()) {
    return { center: true }
  }

  const [mainX, mainY] = mainWindow.getPosition()
  const [mainW] = mainWindow.getSize()

  const display = screen.getDisplayMatching(mainWindow.getBounds())
  const workArea = display.workArea

  const gap = 5
  let targetX = mainX + mainW + gap
  let targetY = mainY

  targetY = Math.max(
    workArea.y + 5,
    Math.min(targetY, workArea.y + workArea.height - settingsH - 5)
  )

  if (targetX + settingsW > workArea.x + workArea.width - 5) {
    const leftX = mainX - settingsW - gap
    if (leftX >= workArea.x + 5) {
      targetX = leftX
    } else {
      targetX = Math.max(
        workArea.x + 5,
        Math.min(targetX, workArea.x + workArea.width - settingsW - 5)
      )
    }
  }

  return { x: targetX, y: targetY }
}

function openSettingsWindow() {
  if (currentWindowMode !== 'login') {
    if (settingsWindow && !settingsWindow.isDestroyed()) {
      settingsWindow.destroy()
      settingsWindow = null
    }
    return
  }

  const settingsW = 580
  const settingsH = 680
  const pos = getSettingsWindowPosition(settingsW, settingsH)

  if (settingsWindow && !settingsWindow.isDestroyed()) {
    if (!pos.center) {
      settingsWindow.setPosition(pos.x, pos.y)
    }
    settingsWindow.show()
    settingsWindow.focus()
    return
  }

  settingsWindow = new BrowserWindow({
    width: settingsW,
    height: settingsH,
    minWidth: settingsW,
    maxWidth: settingsW,
    minHeight: settingsH,
    maxHeight: settingsH,
    resizable: false,
    ...(pos.center ? { center: true } : { x: pos.x, y: pos.y }),
    show: true,
    frame: false,
    autoHideMenuBar: true,
    parent: mainWindow && !mainWindow.isDestroyed() ? mainWindow : null,
    modal: false,
    webPreferences: {
      preload: join(__dirname, '../preload/index.mjs'),
      sandbox: false,
      contextIsolation: true,
      nodeIntegration: false
    }
  })

  settingsWindow.setMenuBarVisibility(false)

  settingsWindow.on('closed', () => {
    settingsWindow = null
  })

  const loadUrl = getRendererUrl('/erp/u/settings')
  settingsWindow.loadURL(loadUrl)
}

function getCursorAdjustedPosition(windowWidth, windowHeight) {
  const cursorPoint = screen.getCursorScreenPoint()
  const display = screen.getDisplayNearestPoint(cursorPoint)

  const adjustedX = Math.min(
    cursorPoint.x,
    display.workArea.x + display.workArea.width - windowWidth
  )
  const adjustedY = Math.min(
    cursorPoint.y,
    display.workArea.y + display.workArea.height - windowHeight
  )

  return {
    x: adjustedX,
    y: adjustedY
  }
}

function registerWindowShortcuts(win) {
  if (!win || win.isDestroyed()) return

  win.webContents.on('before-input-event', (event, input) => {
    if (input.type !== 'keyDown') return

    // DevTools lock in Production
    if (
      !is.dev &&
      (input.key === 'F12' || (input.control && input.shift && input.key?.toLowerCase() === 'i'))
    ) {
      event.preventDefault()
      return
    }

    const isCtrlOrCmd = input.control || input.meta
    if (isCtrlOrCmd) {
      const key = input.key ? input.key.toLowerCase() : ''
      // Ctrl + S: Save
      if (key === 's' && !input.shift) {
        event.preventDefault()
        win.webContents.send('action:save')
      }
      // Ctrl + Q: Search (Query data from server)
      else if (key === 'q') {
        event.preventDefault()
        win.webContents.send('action:search')
      }
      // Ctrl + F: Find (Filter / Find on Sheet)
      else if (key === 'f') {
        event.preventDefault()
        win.webContents.send('action:find')
      }
      // Ctrl + Shift + D: Delete sheet row (or Ctrl + Delete)
      else if (
        (key === 'd' && input.shift) ||
        input.key === 'Delete' ||
        input.key === 'Del' ||
        key === 'delete'
      ) {
        event.preventDefault()
        win.webContents.send('action:delete')
      }
    }
  })
}

function createWindow() {
  if (mainWindow && !mainWindow.isDestroyed()) {
    return
  }

  const primaryDisplay = screen.getPrimaryDisplay()
  const workAreaSize = primaryDisplay.workAreaSize
  width = workAreaSize.width
  height = workAreaSize.height

  mainWindow = new BrowserWindow({
    width: 750,
    height: 420,
    minWidth: 750,
    maxWidth: 750,
    minHeight: 420,
    maxHeight: 420,
    resizable: false,
    maximizable: false,
    fullscreenable: false,
    center: true,
    show: false,
    frame: false,
    autoHideMenuBar: true,
    icon,
    webPreferences: {
      preload: join(__dirname, '../preload/index.mjs'),
      sandbox: false,
      contextIsolation: true,
      nodeIntegration: false,
      spellcheck: true,
      nativeWindowOpen: true,
      backgroundThrottling: true,
      webgl: true,
      devTools: is.dev // Khóa hoàn toàn F12 / DevTools trên môi trường Production
    }
  })

  // Đăng ký phím tắt hệ thống (Ctrl+S, Ctrl+F, Ctrl+Del) và bảo mật DevTools
  registerWindowShortcuts(mainWindow)

  mainWindow.setMenuBarVisibility(false)

  mainWindow.webContents.on('did-finish-load', () => {
    mainWindow.webContents.session.setSpellCheckerLanguages(['vi-VN', 'en-US'])
  })

  mainWindow.on('ready-to-show', () => {
    mainWindow.show()
  })

  mainWindow.on('minimize', () => {
    // Tự động thu gọn và giải phóng RAM khi người dùng thu nhỏ cửa sổ
    try {
      if (global.gc) global.gc()
    } catch {}
  })

  mainWindow.on('maximize', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      if (currentWindowMode === 'login') {
        mainWindow.unmaximize()
        return
      }
      isWindowMaximized = true
      mainWindow.webContents.send('window:maximized-change', true)
    }
  })

  mainWindow.on('unmaximize', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      isWindowMaximized = false
      mainWindow.webContents.send('window:maximized-change', false)
    }
  })

  mainWindow.on('enter-full-screen', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      if (currentWindowMode === 'login') {
        mainWindow.setFullScreen(false)
        return
      }
      isWindowMaximized = true
      mainWindow.webContents.send('window:maximized-change', true)
    }
  })

  mainWindow.on('leave-full-screen', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      isWindowMaximized = false
      mainWindow.webContents.send('window:maximized-change', false)
    }
  })

  mainWindow.on('resize', () => {
    if (mainWindow && !mainWindow.isDestroyed() && currentWindowMode === 'main') {
      const isMax = mainWindow.isMaximized() || mainWindow.isFullScreen()
      isWindowMaximized = isMax
      mainWindow.webContents.send('window:maximized-change', isMax)
    }
  })

  mainWindow.webContents.setWindowOpenHandler((details) => {
    shell.openExternal(details.url)
    return {
      action: 'deny'
    }
  })

  const loadUrl = getRendererUrl('/erp/u/login')
  mainWindow.loadURL(loadUrl).catch(() => {
    const html = `
        <html>
          <head><title>Offline</title></head>
          <body style="display:flex;justify-content:center;align-items:center;height:100vh;font-family:sans-serif">
            <h2>Không thể kết nối tới ứng dụng.<br />Vui lòng kiểm tra mạng hoặc thử lại sau.</h2>
          </body>
        </html>
      `
    mainWindow.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(html)}`)
  })

  const { Menu } = require('electron')

  const menu = Menu.buildFromTemplate([
    {
      label: 'View',
      submenu: [
        {
          type: 'separator'
        },
        {
          role: 'resetZoom'
        },
        {
          role: 'zoomIn'
        },
        {
          role: 'zoomOut'
        },
        {
          type: 'separator'
        },
        {
          role: 'togglefullscreen'
        }
      ]
    },
    {
      label: 'Edit',
      submenu: [
        {
          role: 'reload'
        },
        {
          role: 'forceReload'
        },
        ...(is.dev ? [{ role: 'toggleDevTools' }] : []),
        {
          role: 'undo'
        },
        {
          role: 'redo'
        },
        {
          type: 'separator'
        },
        {
          role: 'cut'
        },
        {
          role: 'copy'
        },
        {
          role: 'paste'
        },
        {
          role: 'selectAll'
        }
      ]
    },
    {
      label: 'Window',
      submenu: [
        {
          role: 'minimize'
        },
        {
          role: 'close'
        }
      ]
    }
  ])

  Menu.setApplicationMenu(menu)
}

ipcMain.on('open-pdf-window-view', (_, pdfUrl) => {
  const win = new BrowserWindow({
    width: 650,
    height: 1000,
    autoHideMenuBar: true,
    webPreferences: {
      sandbox: false,
      contextIsolation: true,
      enableRemoteModule: false,
      nodeIntegration: false
    }
  })

  win.loadURL(pdfUrl)
})

ipcMain.on('open-pdf-window', async (event, pdfUrl) => {
  const printWindow = new BrowserWindow({
    width: 650,
    height: 1000,
    show: true,
    autoHideMenuBar: true,
    webPreferences: {
      sandbox: false,
      contextIsolation: true,
      enableRemoteModule: false,
      nodeIntegration: false
    }
  })

  printWindow.loadURL(pdfUrl)

  printWindow.webContents.on('did-finish-load', () => {
    setTimeout(() => {
      printWindow.webContents.print(
        {
          silent: false,
          printBackground: true
        },
        (success, errorType) => {
          if (!success) {
            console.error('error', errorType)
          } else {
            console.log('In thành công')
          }
        }
      )
    }, 1500) // ← điều chỉnh thời gian nếu cần
  })

  printWindow.webContents.on('did-fail-load', (event, errorCode, errorDescription) => {
    console.error('❌ Không tải được file PDF:', errorDescription)
    printWindow.close()
  })
})

ipcMain.on('PRINT_PDF', (event, url) => {
  const win = new BrowserWindow({ show: false })

  win.loadURL(url)
  win.webContents.on('did-finish-load', () => {
    win.webContents.print({ silent: false, printBackground: true }, () => win.close())
  })
})

ipcMain.handle('save-to-file', async (event, filePath, data) => {
  const userDirectory = app.getPath('userData')
  const normalizedPath = path.join(userDirectory, filePath)
  const directory = path.dirname(normalizedPath)
  try {
    if (!fs.existsSync(directory)) {
      fs.mkdirSync(directory, {
        recursive: true
      })
    }

    await fs.promises.writeFile(normalizedPath, JSON.stringify(data, null, 2))
    return 'File saved successfully'
  } catch (error) {
    throw new Error(`Failed to save file: ${error.message}`)
  }
})

ipcMain.handle('read-from-file', async (event, filePath) => {
  const userDirectory = app.getPath('userData')
  const normalizedPath = path.join(userDirectory, filePath)

  try {
    if (!fs.existsSync(normalizedPath)) {
      // Nếu file chưa có, trả về mảng rỗng thay vì lỗi
      return []
    }

    const fileData = await fs.promises.readFile(normalizedPath, 'utf-8')
    return JSON.parse(fileData)
  } catch (error) {
    console.error('Failed to read file:', error)
    // Trả về giá trị mặc định thay vì throw error
    return []
  }
})

ipcMain.handle('delete-file', async (_, filePath) => {
  const userDirectory = app.getPath('userData')
  const normalizedPath = path.join(userDirectory, filePath)

  try {
    if (fs.existsSync(normalizedPath)) {
      fs.unlinkSync(normalizedPath)
      return {
        success: true
      }
    } else {
      return {
        success: false,
        error: 'File not found'
      }
    }
  } catch (error) {
    return {
      success: false,
      error: error.message
    }
  }
})

ipcMain.handle('save-binary-file', async (event, filePath, bufferBase64) => {
  const userDirectory = app.getPath('userData')
  const normalizedPath = path.join(userDirectory, filePath)
  const directory = path.dirname(normalizedPath)
  try {
    if (!fs.existsSync(directory)) {
      fs.mkdirSync(directory, { recursive: true })
    }
    const buffer = Buffer.from(bufferBase64, 'base64')
    await fs.promises.writeFile(normalizedPath, buffer)
    return 'Binary file saved successfully'
  } catch (error) {
    throw new Error(`Failed to save binary file: ${error.message}`)
  }
})

ipcMain.handle('system:get-download-path', async () => {
  try {
    return app.getPath('downloads')
  } catch {
    return app.getPath('desktop')
  }
})

ipcMain.handle('dialog:select-directory', async (event, defaultPath) => {
  try {
    const win =
      BrowserWindow.fromWebContents(event.sender) || BrowserWindow.getFocusedWindow() || mainWindow
    let safeDefault = defaultPath
    if (!safeDefault || typeof safeDefault !== 'string' || !fs.existsSync(safeDefault)) {
      try {
        safeDefault = app.getPath('downloads')
      } catch {
        safeDefault = app.getPath('desktop')
      }
    }
    const result = await dialog.showOpenDialog(win, {
      title: 'Chọn thư mục lưu file kết xuất',
      defaultPath: safeDefault,
      properties: ['openDirectory', 'createDirectory', 'promptToCreate']
    })
    if (!result.canceled && result.filePaths && result.filePaths.length > 0) {
      return result.filePaths[0]
    }
    return null
  } catch (err) {
    console.error('Error selecting directory:', err)
    return null
  }
})

ipcMain.handle('dialog:show-save-dialog', async (event, options) => {
  try {
    const win =
      BrowserWindow.fromWebContents(event.sender) || BrowserWindow.getFocusedWindow() || mainWindow
    const result = await dialog.showSaveDialog(win, {
      title: options?.title || 'Lưu file kết xuất',
      defaultPath:
        options?.defaultPath ||
        path.join(app.getPath('downloads'), options?.defaultFileName || 'export.xlsx'),
      filters: options?.filters || [
        { name: 'Excel Workbook (*.xlsx)', extensions: ['xlsx'] },
        { name: 'Excel 97-2003 (*.xls)', extensions: ['xls'] },
        { name: 'All Files (*.*)', extensions: ['*'] }
      ]
    })
    if (!result.canceled && result.filePath) {
      return result.filePath
    }
    return null
  } catch (err) {
    console.error('Error in showSaveDialog:', err)
    return null
  }
})

ipcMain.handle('file:save-file-absolute', async (event, fullFilePath, base64Data, options = {}) => {
  try {
    let targetPath = fullFilePath
    const dir = path.dirname(targetPath)
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true })
    }

    const { overwriteExisting = true } = options || {}
    if (!overwriteExisting && fs.existsSync(targetPath)) {
      const ext = path.extname(targetPath)
      const base = path.basename(targetPath, ext)
      let counter = 1
      while (fs.existsSync(path.join(dir, `${base} (${counter})${ext}`))) {
        counter++
      }
      targetPath = path.join(dir, `${base} (${counter})${ext}`)
    }

    const buffer = Buffer.from(base64Data, 'base64')
    await fs.promises.writeFile(targetPath, buffer)
    return { success: true, filePath: targetPath }
  } catch (error) {
    console.error('Failed to save absolute file:', error)
    return { success: false, error: error.message }
  }
})

ipcMain.handle('get-template-path', async (event, folderName, fileName) => {
