      mainWindow.setMinimumSize(800, 500)
      mainWindow.setMaximumSize(100000, 100000)
      const targetW = Math.max(900, Math.min(sysW - 80, 1600))
      const targetH = Math.max(600, Math.min(sysH - 60, 1000))
