import path from 'path'
import fs from 'fs'
import * as grpc from '@grpc/grpc-js'
import * as protoLoader from '@grpc/proto-loader'

let client = null
let currentStream = null
let reconnectTimer = null
let isManuallyClosed = false
let retryAttempt = 0
let activeParams = null
let isWatchingChannel = false

const INITIAL_RETRY_DELAY_MS = 2000
const MAX_RETRY_DELAY_MS = 30000

function sendToWindow(targetWindow, channel, payload) {
  if (!targetWindow) return
  try {
    if (typeof targetWindow.send === 'function') {
      targetWindow.send(channel, payload)
    } else if (targetWindow.webContents && typeof targetWindow.webContents.send === 'function') {
      targetWindow.webContents.send(channel, payload)
    }
  } catch (err) {
    console.error(`[IPC Send Error on channel ${channel}]`, err)
  }
}

function calculateJitterBackoff(attempt) {
  // Exponential Backoff với Full Jitter: Tránh Thundering Herd DDOS Server khi khôi phục mạng hàng loạt
  const expDelay = Math.min(MAX_RETRY_DELAY_MS, INITIAL_RETRY_DELAY_MS * Math.pow(2, attempt))
  const jitteredDelay = Math.floor(expDelay * (0.5 + Math.random() * 0.5))
  return jitteredDelay
}

function getProtoPath() {
  const sharedProto = path.resolve(process.cwd(), '../service/proto/realtime/realtime.proto')
  if (fs.existsSync(sharedProto)) return sharedProto

  const internalDevProto = path.resolve(process.cwd(), 'src/main/realtime/proto/realtime.proto')
  if (fs.existsSync(internalDevProto)) return internalDevProto

  return path.resolve(__dirname, './proto/realtime.proto')
}

let currentServerAddress = ''

function getRealtimeClient(customAddress = null) {
  const serverAddress =
    customAddress ||
    process.env.VITE_REALTIME_HUB_ADDR ||
    process.env.REALTIME_HUB_ADDR ||
    '127.0.0.1:50055'

  if (client && currentServerAddress === serverAddress) return client

  if (client) {
    try {
      client.close()
    } catch (_) {}
    client = null
  }

  currentServerAddress = serverAddress

  const protoPath = getProtoPath()
  console.log('[gRPC Client] Loading proto file from:', protoPath)

  if (!fs.existsSync(protoPath)) {
    throw new Error(`Proto file not found at path: ${protoPath}`)
  }

  const packageDefinition = protoLoader.loadSync(protoPath, {
    keepCase: true,
    longs: String,
    enums: String,
    defaults: true,
    oneofs: true
  })

  const protoDescriptor = grpc.loadPackageDefinition(packageDefinition)
  const realtimeProto =
    protoDescriptor['realtime.realtime'] ||
    protoDescriptor.realtime?.realtime ||
    protoDescriptor.realtime

  if (!realtimeProto || !realtimeProto.RealtimeService) {
    console.error('[gRPC Client] Available packages in descriptor:', Object.keys(protoDescriptor))
    throw new Error('RealtimeService not found in loaded proto descriptor')
  }

  console.log('[gRPC Client] Connecting to Realtime Hub at:', serverAddress)

  client = new realtimeProto.RealtimeService(serverAddress, grpc.credentials.createInsecure(), {
    'grpc.keepalive_time_ms': 60000, // Ping mỗi 60s
    'grpc.keepalive_timeout_ms': 20000,
    'grpc.keepalive_permit_without_calls': 0, // Không ping khi không có stream
    'grpc.http2.min_ping_interval_without_data_ms': 30000
  })

  return client
}

/**
 * Hủy stream một cách an toàn tuyệt đối, không bao giờ để lọt lỗi Uncaught Exception vào Node.js / Electron
 */
function cleanupStream(stream) {
  if (!stream) return
  try {
    // 1. Gỡ các listener hiện tại
    stream.removeAllListeners()
    // 2. QUAN TRỌNG: Luôn gắn no-op error handler để gRPC-js nếu có emit async error/status sau khi hủy
    // thì Node.js EventEmitter sẽ KHÔNG coi đó là Uncaught Exception làm hiện popup lỗi Windows
    stream.on('error', () => {})
    if (typeof stream.cancel === 'function') {
      stream.cancel()
    }
    if (typeof stream.destroy === 'function') {
      stream.destroy()
    }
  } catch (_) {}
}

function scheduleReconnect(targetWindow) {
  if (isManuallyClosed || !activeParams) return
  if (reconnectTimer) return

  const delay = calculateJitterBackoff(retryAttempt)
  retryAttempt++

  sendToWindow(targetWindow, 'realtime:status', {
    status: 'RECONNECTING',
    message: `Mất kết nối với Server. Tự động thử lại sau ${(delay / 1000).toFixed(1)}s (Lần ${retryAttempt})...`
  })

  reconnectTimer = setTimeout(() => {
    reconnectTimer = null
    if (!isManuallyClosed && activeParams) {
      connectRealtimeStream(targetWindow, activeParams, true)
    }
  }, delay)
}

function monitorChannelState(targetWindow, clientInstance) {
  if (isWatchingChannel || isManuallyClosed || !clientInstance) return
  isWatchingChannel = true

  try {
    const channel = clientInstance.getChannel()
    if (!channel || typeof channel.getConnectivityState !== 'function') {
      isWatchingChannel = false
      return
    }

    const currentState = channel.getConnectivityState(true)

    channel.watchConnectivityState(currentState, Date.now() + 3600000, function onStateChange(err) {
      isWatchingChannel = false
      if (err || isManuallyClosed) return

      try {
        const newState = channel.getConnectivityState(false)
        // Nếu channel chuyển sang READY, kích hoạt kết nối Stream lại ngay lập tức
        if (newState === grpc.connectivityState.READY && !currentStream && activeParams) {
          console.log('[gRPC Channel] Server READY detected! Connecting stream immediately...')
          if (reconnectTimer) {
            clearTimeout(reconnectTimer)
            reconnectTimer = null
          }
          retryAttempt = 0
          connectRealtimeStream(targetWindow, activeParams, true)
        } else if (!isManuallyClosed && activeParams) {
          monitorChannelState(targetWindow, clientInstance)
        }
      } catch (_) {}
    })
  } catch (_) {
    isWatchingChannel = false
  }
}

export function connectRealtimeStream(targetWindow, params = {}, isInternalRetry = false) {
  const {
    userId,
    apiKey,
    deviceId = 'DEV_LOCAL',
    topic = '*',
    channel = 'default',
    serverAddress = null
  } = params

  if (!userId || !apiKey) {
    console.warn('[gRPC Stream] Rejecting connection: Missing authenticated userId or JWT Token!')
    sendToWindow(targetWindow, 'realtime:status', {
      status: 'DISCONNECTED',
      message: 'Authentication Required: Missing UserId or JWT Token'
    })
    return
  }

  // Chống kết nối lặp: Nếu đang có stream hoạt động với cùng thông số thì giữ nguyên
  if (
    !isInternalRetry &&
    currentStream &&
    activeParams &&
    activeParams.userId === userId &&
    activeParams.apiKey === apiKey &&
    activeParams.deviceId === deviceId &&
    activeParams.topic === topic &&
    activeParams.channel === channel &&
    activeParams.serverAddress === serverAddress
  ) {
    return
  }

  isManuallyClosed = false
  activeParams = { userId, apiKey, deviceId, topic, channel, serverAddress }

  if (!isInternalRetry) {
    retryAttempt = 0
    console.log(
      `[gRPC Stream] Connect requested by User: ${userId} (Device: ${deviceId}), Topic: ${topic}`
    )
  }

  if (currentStream) {
    cleanupStream(currentStream)
    currentStream = null
  }

  if (reconnectTimer) {
    clearTimeout(reconnectTimer)
    reconnectTimer = null
  }

  try {
    const clientInstance = getRealtimeClient(serverAddress)
    monitorChannelState(targetWindow, clientInstance)

    const metadata = new grpc.Metadata()
    metadata.add('x-user-id', userId)
    metadata.add('x-api-key', apiKey)
    metadata.add('x-device-id', deviceId)

    if (!isInternalRetry) {
      sendToWindow(targetWindow, 'realtime:status', {
        status: 'CONNECTING',
        message: `Connecting to gRPC Server ${currentServerAddress}...`
      })
    }

    const stream = clientInstance.SubscribeEvents({ topic, channel, user_id: userId }, metadata)
    currentStream = stream

    stream.on('data', (data) => {
      // Khi nhận tin nhắn thành công -> reset ngay số lần thử lại
      retryAttempt = 0
      sendToWindow(targetWindow, 'realtime:status', {
        status: 'CONNECTED',
        message: `Realtime Stream Active (Topic: ${topic})`
      })
      sendToWindow(targetWindow, 'realtime:data-received', data)
    })

    stream.on('error', (err) => {
      const errMsg = err?.details || err?.message || 'Stream error'
      const errCode = err?.code

      // Clean up stream an toàn
      if (currentStream === stream) {
        cleanupStream(currentStream)
        currentStream = null
      } else {
        cleanupStream(stream)
      }

      // Nếu lỗi xác thực token -> ngắt hẳn không bao giờ retry
      if (errCode === grpc.status.UNAUTHENTICATED) {
        console.warn('[gRPC Stream Auth Rejected]: Invalid or expired token. Stream stopped.')
        isManuallyClosed = true
        activeParams = null
        if (reconnectTimer) {
          clearTimeout(reconnectTimer)
          reconnectTimer = null
        }
        sendToWindow(targetWindow, 'realtime:status', {
          status: 'AUTH_ERROR',
          message: `Authentication error: ${errMsg}`
        })
        return
      }

      // Xử lý log im lặng gọn gàng khi Server offline, không làm rác log console
      if (errCode === grpc.status.UNAVAILABLE || errMsg.includes('ECONNREFUSED')) {
        if (retryAttempt === 1 || retryAttempt % 5 === 0) {
          console.warn(
            `[gRPC Stream Offline] Server unavailable at ${currentServerAddress}. Retrying silently...`
          )
        }
      } else if (errCode !== grpc.status.CANCELLED) {
        console.error('[gRPC Stream ERROR]', errCode, errMsg)
      }

      sendToWindow(targetWindow, 'realtime:status', {
        status: 'DISCONNECTED',
        message: `Stream Error (${errCode}): ${errMsg}`
      })

      scheduleReconnect(targetWindow)
    })

    stream.on('status', (status) => {
      if (status && status.code !== grpc.status.OK && status.code !== grpc.status.CANCELLED) {
        // Status event handled cleanly
      }
    })

    stream.on('end', () => {
      if (currentStream === stream) {
        cleanupStream(currentStream)
        currentStream = null
      } else {
        cleanupStream(stream)
      }

      if (!isManuallyClosed) {
        sendToWindow(targetWindow, 'realtime:status', {
          status: 'DISCONNECTED',
          message: 'Realtime Stream Disconnected by Server'
        })
        scheduleReconnect(targetWindow)
      }
    })
  } catch (err) {
    console.error('[gRPC Exception]', err?.message || err)
    sendToWindow(targetWindow, 'realtime:status', {
      status: 'DISCONNECTED',
      message: `Connection Exception: ${err?.message || err}`
    })
    scheduleReconnect(targetWindow)
  }
}

export function disconnectRealtimeStream(targetWindow) {
  isManuallyClosed = true
  activeParams = null
  retryAttempt = 0

  if (reconnectTimer) {
    clearTimeout(reconnectTimer)
    reconnectTimer = null
  }
  if (currentStream) {
    cleanupStream(currentStream)
    currentStream = null
  }
  sendToWindow(targetWindow, 'realtime:status', {
    status: 'DISCONNECTED',
    message: 'Disconnected by User'
  })
}

export function publishRealtimeEvent({
  userId,
  apiKey,
  topic = 'erp.client.events',
  key = `KEY_${Date.now()}`,
  payload
}) {
  if (!userId || !apiKey) {
    return Promise.reject(new Error('Publish rejected: Missing authenticated UserId or JWT Token'))
  }
  return new Promise((resolve, reject) => {
    try {
      const clientInstance = getRealtimeClient()
      const metadata = new grpc.Metadata()
      metadata.add('x-user-id', userId)
      metadata.add('x-api-key', apiKey)

      clientInstance.PublishEvent(
        {
          topic,
          key,
          payload: typeof payload === 'object' ? JSON.stringify(payload) : payload,
          user_id: userId
        },
        metadata,
        (err, response) => {
          if (err) {
            console.error('[gRPC Publish Error]', err?.message || err)
            reject(err)
          } else {
            console.log('[gRPC Publish Success]', response)
            resolve(response)
          }
        }
      )
    } catch (err) {
      reject(err)
    }
  })
}

import crypto from 'crypto'
import os from 'os'
import path from 'path'
import fs from 'fs'
import { app, ipcMain } from 'electron'

// Phân rã mảng byte khóa chính và khóa phụ kết hợp XOR Mask chống quét chuỗi tĩnh (Decompilation Static String Scan)
const XOR_MASK = 0x5a
const OBFUSCATED_KEY_MAIN = [
  0x6a, 0x6b, 0x68, 0x69, 0x6e, 0x6f, 0x6c, 0x6d, 0x62, 0x63, 0x3b, 0x38, 0x39, 0x3e, 0x3f, 0x3c,
  0x6a, 0x6b, 0x68, 0x69, 0x6e, 0x6f, 0x6c, 0x6d, 0x62, 0x63, 0x3b, 0x38, 0x39, 0x3e, 0x3f, 0x3c
]

const OBFUSCATED_KEY_SUB = [
  0x3b, 0x38, 0x39, 0x3e, 0x3f, 0x3c, 0x6a, 0x6b, 0x68, 0x69, 0x6e, 0x6f, 0x6c, 0x6d, 0x62, 0x63,
  0x3b, 0x38, 0x39, 0x3e, 0x3f, 0x3c, 0x6a, 0x6b, 0x68, 0x69, 0x6e, 0x6f, 0x6c, 0x6d, 0x62, 0x63
]

function getSecretKey(obfuscatedArray) {
  return Buffer.from(obfuscatedArray.map((b) => b ^ XOR_MASK))
}

/**
 * Mã hóa AES-256-GCM
 */
export function encryptAES256GCM(data, keyBuffer) {
  const iv = crypto.randomBytes(12) // 12 bytes IV chuẩn AES-GCM
  const cipher = crypto.createCipheriv('aes-256-gcm', keyBuffer, iv)

  const jsonStr = typeof data === 'string' ? data : JSON.stringify(data)
  const encrypted = Buffer.concat([cipher.update(jsonStr, 'utf8'), cipher.final()])
  const tag = cipher.getAuthTag() // 16 bytes Authentication Tag

  // Ghép Ciphertext + Tag (Chuẩn AES-GCM của Web Crypto & Golang)
  const fullCipher = Buffer.concat([encrypted, tag])

  return {
    iv: iv.toString('base64'),
    data: fullCipher.toString('base64')
  }
}

/**
 * Lấy hoặc sinh mã DeviceId vĩnh viễn lưu an toàn trong userData của máy
 */
function getPersistentDeviceId() {
  try {
    const userDataPath = app.getPath('userData')
    const deviceIdPath = path.join(userDataPath, '.sys_device_id')
    if (fs.existsSync(deviceIdPath)) {
      const id = fs.readFileSync(deviceIdPath, 'utf8').trim()
      if (id) return id
    }
    const newId = crypto.randomUUID()
    fs.writeFileSync(deviceIdPath, newId, 'utf8')
    return newId
  } catch {
    return crypto.randomUUID()
  }
}

/**
 * Khởi tạo IPC handlers phục vụ bảo mật ở Main Process
 */
export function setupSecurityIpc() {
  const mainKey = getSecretKey(OBFUSCATED_KEY_MAIN)
  const subKey = getSecretKey(OBFUSCATED_KEY_SUB)

  ipcMain.handle('security:encrypt-device-payload', async (_, payload) => {
    try {
      return encryptAES256GCM(payload, mainKey)
    } catch (err) {
      console.error('[Security] Encrypt payload failed:', err)
      throw err
    }
  })

  ipcMain.handle('security:get-device-token', async (_, userToken) => {
    try {
      const deviceId = getPersistentDeviceId()
      const payload = {
        deviceId,
        token: userToken || crypto.randomUUID(),
        ts: Date.now()
      }

      // Mã hóa lớp 1 với khóa chính
      const firstLayer = encryptAES256GCM(payload, mainKey)
      // Mã hóa lớp 2 với khóa phụ
      const secondLayer = encryptAES256GCM(firstLayer, subKey)

      return JSON.stringify(secondLayer)
    } catch (err) {
      console.error('[Security] Get device token failed:', err)
      return null
    }
  })
}

/**
 * SQLite IPC Handlers for Production Calculation Engine
 * Xử lý động cơ tính toán ma trận TKSX (98 cột) và KHSX (18 chỉ tiêu) trực tiếp trong SQLite
 */
import { ipcMain } from 'electron'
import { getDb, getFullDataForFileType } from './db.js'

export function setupCalcEngineIpc() {
  // 1. Tính toán trực tiếp KHSX & TKSX từ CSDL SQLite
  ipcMain.handle('sqlite:calculate-production', async () => {
    const db = getDb()
    if (!db) {
      return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    }
    try {
      const stmt = db.prepare('SELECT file_type FROM calc_architecture_files')
      const rows = stmt.all()
      const files = {}
      for (const r of rows) {
        if (r.file_type) {
          files[r.file_type] = {
            data: getFullDataForFileType(r.file_type)
          }
        }
      }

      const statReportData = files.stat_report?.data || []
      const summaryOpData = files.summary_op?.data || []
      const unfinishedOpData = files.unfinished_op?.data || []
      const mesApprovalData = files.mes_approval?.data || []

      // Tạo từ điển tra cứu KHSX Lệnh thao tác
      const opOrderPlanMap = new Map()
      const normalize = (v) => (v ? String(v).trim().toUpperCase() : '')

      const extractTicketCode = (row) => {
        if (!row || typeof row !== 'object') return ''
        const direct = [
          row.BravoStatCode,
          row.BravoStatSlipNo,
          row['Mã lệnh thống kê Bravo'],
          row['Mã lệnh thống kê bravo'],
          row['Mã lệnh thống kê'],
          row['Mã thống kê Bravo'],
          row['Mã thống kê bravo'],
          row['Mã lệnh TK Bravo'],
          row['Mã TK Bravo'],
          row.StatSlipNo,
          row.ApprovalSlipNo,
          row.TicketNo,
          row.StatTicketNo,
          row.SlipNo,
          row.StatCode,
          row.RegCode,
          row['Phiếu TK'],
          row['Phiếu tk'],
          row['phiếu tk'],
          row['Phiếu Tk'],
          row['Mã TK'],
          row['Mã tk'],
          row['mã tk'],
          row['Mã Thống kê'],
          row['Mã Thống Kê'],
          row['Mã thống kê'],
          row['mã thống kê'],
          row['Số phiếu thống kê'],
          row['Số phiếu TK'],
          row['Số phiếu tk'],
          row['Số phiếu'],
          row['Số thống kê'],
          row['Số TK'],
          row['Số tk'],
          row['Mã phiếu'],
          row['Mã phiếu TK'],
          row['Mã phiếu tk'],
          row['Mã phiếu thống kê'],
          row['Số phiếu duyệt'],
          row['Mã phiếu duyệt'],
          row['Phiếu thống kê'],
          row['Phiếu duyệt'],
          row['Số TK']
        ]
        for (const c of direct) {
          if (c !== undefined && c !== null && String(c).trim() !== '') return normalize(c)
        }
        for (const [k, v] of Object.entries(row)) {
          if (v === undefined || v === null || String(v).trim() === '') continue
          const cleanKey = k.toLowerCase().replace(/[_\s\-\r\n]+/g, '')
          if (
            cleanKey.includes('statslipno') ||
            cleanKey.includes('approvalslipno') ||
            cleanKey.includes('mathongke') ||
            cleanKey.includes('sothongke') ||
            cleanKey.includes('sophieuthongke') ||
            cleanKey.includes('sophieutk') ||
            cleanKey.includes('sophieuduyet') ||
            cleanKey.includes('maphieutk') ||
            cleanKey.includes('maphieu') ||
            cleanKey.includes('matk') ||
            cleanKey.includes('sotk') ||
            (cleanKey.includes('sophieu') &&
              !cleanKey.includes('xuat') &&
              !cleanKey.includes('nhap'))
          ) {
            return normalize(v)
          }
        }
        return ''
      }

      const extractApprovedTime = (row) => {
        if (!row || typeof row !== 'object') return ''
        const direct = [
          row.ApprovedTime,
          row.ApprovalTime,
          row.MesApprovedTime,
          row.ApprovedDate,
          row.ApprovalDate,
          row.ApproveTime,
          row.TimeApproved,
          row['Thời gian duyệt'],
          row['Thời gian duyệt ở MES'],
          row['Thời gian duyệt phiếu ở MES'],
          row['Thời gian duyệt phiếu'],
          row['Thời gian phê duyệt'],
          row['Thời gian duyệt MES'],
          row['Ngày duyệt'],
          row['Ngày phê duyệt'],
          row['Ngày duyệt phiếu'],
          row['Ngày duyệt ở MES'],
          row['Giờ duyệt'],
          row['TG duyệt']
        ]
        for (const c of direct) {
          if (c !== undefined && c !== null && String(c).trim() !== '') return String(c).trim()
        }
        for (const [k, v] of Object.entries(row)) {
          if (v === undefined || v === null || String(v).trim() === '') continue
          const cleanKey = k.toLowerCase().replace(/[_\s\-\r\n]+/g, '')
          if (
            cleanKey.includes('approvedtime') ||
            cleanKey.includes('approvaltime') ||
            cleanKey.includes('mesapprovedtime') ||
            cleanKey.includes('thoigianduyet') ||
            cleanKey.includes('ngayduyet') ||
            cleanKey.includes('thoigianpheduyet') ||
            cleanKey.includes('ngaypheduyet') ||
            cleanKey.includes('tgduyet') ||
            cleanKey.includes('gioduyet') ||
            (cleanKey.includes('duyet') &&
              (cleanKey.includes('time') ||
                cleanKey.includes('date') ||
                cleanKey.includes('thoigian') ||
                cleanKey.includes('ngay')))
          ) {
            return String(v).trim()
          }
        }
        return ''
      }

      const getLookupKeys = (code) => {
        if (!code) return []
        const norm = normalize(code)
        const clean = norm.replace(/[^A-Z0-9]/g, '')
        const keys = new Set([norm])
        if (clean) {
          keys.add(clean)
          const noLeadingZero = clean.replace(/^0+/, '')
          if (noLeadingZero) keys.add(noLeadingZero)
        }
        return Array.from(keys)
      }

      summaryOpData.forEach((row) => {
        const code = normalize(
          row.OperationOrderNo ?? row['Lệnh thao tác'] ?? row['Số lệnh thao tác'] ?? ''
        )
        if (code) {
          const keys = getLookupKeys(code)
          keys.forEach((k) => opOrderPlanMap.set(k, 'KHSX'))
        }
      })

      unfinishedOpData.forEach((row) => {
        const code = normalize(
          row.OperationOrderNo ?? row['Số lệnh thao tác'] ?? row['Lệnh thao tác'] ?? ''
        )
        if (code) {
          const keys = getLookupKeys(code)
          keys.forEach((k) => {
            if (!opOrderPlanMap.has(k)) opOrderPlanMap.set(k, 'KHSX')
          })
        }
      })

      // Tạo từ điển tra cứu MES
      const mesApprovalMap = new Map()
      mesApprovalData.forEach((row) => {
        const approvedTime = extractApprovedTime(row)
        if (!approvedTime) return

        // 1. Khóa chính: Mã lệnh thống kê Bravo (VD: TK2609-453717, TK2609-031222)
        const bravoCode =
          row.BravoStatCode ??
          row.BravoStatSlipNo ??
          row['Mã lệnh thống kê Bravo'] ??
          row['Mã lệnh thống kê bravo'] ??
          row['Mã lệnh thống kê'] ??
          row['Lệnh thống kê Bravo'] ??
          row['lệnh thống kê Bravo'] ??
          row['Lệnh thống kê'] ??
          row['lệnh thống kê'] ??
          row['Mã thống kê Bravo'] ??
          row['Mã thống kê'] ??
          ''
        if (bravoCode) {
          const keys = getLookupKeys(bravoCode)
          keys.forEach((k) => mesApprovalMap.set(k, approvedTime))
        }

        // 2. Khóa phụ: Mã phiếu duyệt MES (VD: SLIP-TH-GS1-260929-049)
        const slipNo =
          row.SlipNo ??
          row.ApprovalSlipNo ??
          row['Mã phiếu'] ??
          row['Số phiếu duyệt'] ??
          extractTicketCode(row)
        if (slipNo) {
          const keys = getLookupKeys(slipNo)
          keys.forEach((k) => mesApprovalMap.set(k, approvedTime))
        }

        // 3. Khóa dự phòng: Mã lệnh thao tác (VD: CD03-0926-0364(234))
        const opOrderNo = normalize(row.OperationOrderNo ?? row['Mã lệnh thao tác'] ?? '')
        if (opOrderNo) {
          const keys = getLookupKeys(opOrderNo)
          keys.forEach((k) => {
            if (!mesApprovalMap.has(k)) mesApprovalMap.set(k, approvedTime)
          })
        }
      })

      // Đếm phiếu trùng
      const slipCountMap = new Map()
      statReportData.forEach((row) => {
        const slipNo = extractTicketCode(row)
        if (slipNo) {
          slipCountMap.set(slipNo, (slipCountMap.get(slipNo) || 0) + 1)
        }
      })

      // Tính toán 98 cột chuẩn TKSX
      let totalProducedQty = 0
      let totalQualifiedQty = 0
      let totalDefectQty = 0
      let totalDowntimeMinutes = 0
      let totalSyncDelaySec = 0
      let syncCount = 0
      let insidePlanCount = 0
      let outsidePlanCount = 0
      let mesUserCount = 0
      let bravoUserCount = 0
      let duplicateSlipCount = 0

      const statByMachine = {}
      const statByTeam = {}
      const statByTechnician = {}

      const calculatedRows = statReportData.map((row, idx) => {
        const rowObj = { ...row }
        const produced =
          parseFloat(
            String(
              row.ProducedQty ?? row['Số lượng sản xuất'] ?? row['Số lượng thực hiện'] ?? 0
            ).replace(/,/g, '')
          ) || 0
        const qualified =
          parseFloat(String(row.QualifiedQty ?? row['Số lượng đạt'] ?? 0).replace(/,/g, '')) || 0
        const defect =
          parseFloat(String(row.DefectQty ?? row['Số lượng lỗi'] ?? 0).replace(/,/g, '')) || 0
        const downtime =
          parseFloat(
            String(
              row.TotalDowntimeMinutes ??
                row['Tổng tg hao phí\r\n(5)=1+2+3+4'] ??
                row['Tổng tg hao phí\n(5)=1+2+3+4'] ??
                row['Tổng tg hao phí (5)=1+2+3+4'] ??
                row['Tổng tg hao phí'] ??
                0
            ).replace(/,/g, '')
          ) || 0

        // Parse giờ phút
        const startVal = row.StartTime ?? row['Bắt đầu'] ?? row['Thời gian bắt đầu'] ?? ''
        const endVal = row.EndTime ?? row['Kết thúc'] ?? row['Thời gian kết thúc'] ?? ''

        const parseMinutes = (val) => {
          if (val === undefined || val === null || val === '') return null
          if (typeof val === 'number') {
            if (val >= 0 && val <= 1) return val * 1440
            if (val > 1) return (val - Math.floor(val)) * 1440
            return val
          }
          const str = String(val).trim()
          if (!str) return null
          if (/^\d+(\.\d+)?$/.test(str)) {
            const num = parseFloat(str)
            if (!isNaN(num)) {
              if (num >= 0 && num <= 1) return num * 1440
              if (num > 1) return (num - Math.floor(num)) * 1440
            }
          }
          const m = str.match(/(?:^|\s)(\d{1,2}):(\d{2})(?::(\d{2}))?/)
          if (m) {
            const h = parseInt(m[1], 10)
            const mi = parseInt(m[2], 10)
            const s = m[3] ? parseInt(m[3], 10) : 0
            return h * 60 + mi + s / 60
          }
          return null
        }

        const sMin = parseMinutes(startVal)
        const eMin = parseMinutes(endVal)
        let actualRunTime = ''
        if (sMin !== null && eMin !== null) {
          let diffMin = eMin - sMin
          if (diffMin < 0) diffMin += 1440
          const rawRunTime = diffMin - downtime
          actualRunTime = Math.max(0, Number(rawRunTime.toFixed(2)))
        } else if (row.ActualRunTime !== undefined && row.ActualRunTime !== '') {
          actualRunTime = parseFloat(String(row.ActualRunTime).replace(/,/g, '')) || 0
        }

        // Col 92: capa
        let actualCapa = ''
        if (typeof actualRunTime === 'number') {
          actualCapa = actualRunTime > 0 ? Number(((produced * 60) / actualRunTime).toFixed(2)) : 0
        } else if (row.ActualCapa !== undefined && row.ActualCapa !== '') {
          actualCapa = parseFloat(String(row.ActualCapa).replace(/,/g, '')) || 0
        }

        // Col 93: check khsx
        const opOrderNo = normalize(
          row.OperationOrderNo ?? row['Số lệnh thao tác'] ?? row['Lệnh thao tác'] ?? ''
        )
        let checkKhsx = 'Khác KHSX'
        if (opOrderNo) {
          const keys = getLookupKeys(opOrderNo)
          const isPlan = keys.some((k) => opOrderPlanMap.has(k))
          if (isPlan) {
            checkKhsx = 'KHSX'
            insidePlanCount++
          } else {
            outsidePlanCount++
          }
        } else {
          outsidePlanCount++
        }

        // Col 94: thời gian duyệt MES
        const statSlipNo = extractTicketCode(row)
        let mesApprovedTime = ''
        if (statSlipNo) {
          const keys = getLookupKeys(statSlipNo)
          for (const k of keys) {
            if (mesApprovalMap.has(k)) {
              mesApprovedTime = mesApprovalMap.get(k)
              break
            }
          }
        }
        if (!mesApprovedTime) {
          mesApprovedTime =
            extractApprovedTime(row) ||
            row.MesApprovedTime ||
            row['Thời gian duyệt phiếu ở MES'] ||
            row['Thời gian duyệt ở MES'] ||
            row['Thời gian duyệt'] ||
            ''
        }

        // Col 95: Độ trễ đồng bộ 2 hệ thống
        const slipCreatedDate = String(row.SlipCreatedDate ?? row['Ngày tạo phiếu'] ?? '').trim()
        let syncLatencySeconds = ''
        if (slipCreatedDate && mesApprovedTime) {
          const parseTs = (dtStr) => {
            const m = dtStr.match(
              /(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?)?/i
            )
            if (m) {
              const day = parseInt(m[1], 10)
              const month = parseInt(m[2], 10)
              let year = parseInt(m[3], 10)
              if (year < 100) year += 2000
              let hours = m[4] ? parseInt(m[4], 10) : 0
              const mins = m[5] ? parseInt(m[5], 10) : 0
              const secs = m[6] ? parseInt(m[6], 10) : 0
              const ampm = m[7] ? m[7].toUpperCase() : ''
              if (ampm === 'PM' && hours < 12) hours += 12
              if (ampm === 'AM' && hours === 12) hours = 0
              return new Date(year, month - 1, day, hours, mins, secs).getTime()
            }
            return null
          }
          const cTs = parseTs(slipCreatedDate)
          const aTs = parseTs(mesApprovedTime)
          if (cTs && aTs) {
            const diffSec = Math.abs(Math.round((aTs - cTs) / 1000))
            const pad = (n) => String(n).padStart(2, '0')
            const h = Math.floor(diffSec / 3600)
            const mi = Math.floor((diffSec % 3600) / 60)
            const s = diffSec % 60
            syncLatencySeconds = `${pad(h)}:${pad(mi)}:${pad(s)}`
            totalSyncDelaySec += diffSec
            syncCount++
          }
        }

        // Col 96: phiếu trùng
        let isDuplicateSlip = 0
        if (statSlipNo && (slipCountMap.get(statSlipNo) || 0) > 1) {
          isDuplicateSlip = 1
          duplicateSlipCount++
        }

        // Col 97: vị trí tạo phiếu tk
        const statEmp = String(row.StatEmployee ?? row['Nhân viên thống kê'] ?? '').trim()
        let createdLocation = statEmp.toUpperCase().includes('MES') ? 'MES' : 'Bravo'
        if (createdLocation === 'MES') mesUserCount++
        else bravoUserCount++

        // Col 98: Sinh phiếu xuất/nhập tự động
        const autoExport =
          parseInt(row.IsAutoExport ?? row.AutoExport ?? row['Xuất tự động'] ?? 0, 10) || 0
        const autoImport =
          parseInt(row.IsAutoImport ?? row.AutoImport ?? row['Nhập tự động'] ?? 0, 10) || 0
        const exportSlipNo = String(
          row.ExportSlipNo ??
            row['Số phiếu xuất'] ??
            row['Phiếu xuất'] ??
            row.ExportDocNo ??
            row.StatSlipNo_87 ??
            ''
        ).trim()
        const importSlipNo = String(
          row.ImportSlipNo ??
            row['Số phiếu nhập'] ??
            row['Phiếu nhập'] ??
            row.ImportDocNo ??
            row.StatSlipNo_88 ??
            ''
        ).trim()

        let autoExportImportGenerated = 'Không sử dụng NVL'
        if (autoExport === 0 && autoImport === 0) {
          autoExportImportGenerated = 'Không sử dụng NVL'
        } else {
          const parts = []
          if (autoExport !== 0) parts.push(exportSlipNo ? 'Có XKTĐ' : 'Không có XKTĐ')
          if (autoImport !== 0) parts.push(importSlipNo ? 'Có NKTĐ' : 'Không NKTĐ')
          autoExportImportGenerated = parts.join(', ') || 'Không sử dụng NVL'
        }

        rowObj.ActualRunTime = actualRunTime
        rowObj['Thời gian chạy thực tế'] = actualRunTime
        rowObj.ActualCapa = actualCapa
        rowObj['capa thực tế'] = actualCapa
        rowObj.CheckKhsx = checkKhsx
        rowObj['CHECK KHSX'] = checkKhsx
        rowObj['Cột 93'] = checkKhsx
        rowObj.MesApprovedTime = mesApprovedTime
        rowObj['Thời gian duyệt phiếu ở MES'] = mesApprovedTime
        rowObj['Thời gian duyệt ở MES'] = mesApprovedTime
        rowObj['Thời gian duyệt'] = mesApprovedTime
        rowObj.SyncLatencySeconds = syncLatencySeconds
        rowObj['Độ trễ thời gian đồng bộ 2 hệ thống'] = syncLatencySeconds
        rowObj.IsDuplicateSlip = isDuplicateSlip
        rowObj['Phiếu sinh trùng'] = isDuplicateSlip
        rowObj.CreatedLocation = createdLocation
        rowObj['Vị trí tạo phiếu tk'] = createdLocation
        rowObj.AutoExportImportGenerated = autoExportImportGenerated
        rowObj['Sinh phiếu xuất/nhập tự động'] = autoExportImportGenerated

        totalProducedQty += produced
        totalQualifiedQty += qualified
        totalDefectQty += defect
        totalDowntimeMinutes += downtime

        const machine = String(
          row.MachineName ??
            row['Tên máy sản xuất'] ??
            row.MachineCode ??
            row['Mã máy sản xuất'] ??
            'Khác'
        ).trim()
        const team = String(row.ProductionTeam ?? row['Tổ sản xuất'] ?? 'Khác').trim()
        const leadTech = String(
          row.LeadTechnicianName ?? row['Thợ chính'] ?? row['Họ tên thợ chính'] ?? 'Khác'
        ).trim()

        if (!statByMachine[machine]) {
          statByMachine[machine] = {
            machine,
            producedQty: 0,
            qualifiedQty: 0,
            defectQty: 0,
            ticketCount: 0
          }
        }
        statByMachine[machine].producedQty += produced
        statByMachine[machine].qualifiedQty += qualified
        statByMachine[machine].defectQty += defect
        statByMachine[machine].ticketCount += 1

        if (!statByTeam[team]) {
          statByTeam[team] = { team, producedQty: 0, qualifiedQty: 0, defectQty: 0 }
        }
        statByTeam[team].producedQty += produced
        statByTeam[team].qualifiedQty += qualified
        statByTeam[team].defectQty += defect

        if (leadTech && leadTech !== 'Khác') {
          if (!statByTechnician[leadTech]) {
            statByTechnician[leadTech] = {
              technician: leadTech,
              producedQty: 0,
              qualifiedQty: 0,
              defectQty: 0
            }
          }
          statByTechnician[leadTech].producedQty += produced
          statByTechnician[leadTech].qualifiedQty += qualified
          statByTechnician[leadTech].defectQty += defect
        }

        if (!rowObj.IdSeq) {
          rowObj.IdSeq = `TKSX-${Date.now()}-${idx + 1}`
        }
        if (rowObj.RowVersion === undefined) {
          rowObj.RowVersion = 1
        }
        if (!rowObj.CreatedAt) {
          rowObj.CreatedAt = new Date().toISOString()
        }
        if (!rowObj.WorkingTag && !rowObj.Status) {
          rowObj.WorkingTag = 'A'
        }

        return rowObj
      })

      // Đối soát MES
      let mesApprovedProducedQty = 0
      let mesApprovedQualifiedQty = 0
      let mesApprovedDefectQty = 0
      mesApprovalData.forEach((row) => {
        mesApprovedProducedQty +=
          parseFloat(String(row['SL sản xuất'] ?? row.ProducedQty ?? 0).replace(/,/g, '')) || 0
        mesApprovedQualifiedQty +=
          parseFloat(String(row['SL đạt'] ?? row.QualifiedQty ?? 0).replace(/,/g, '')) || 0
        mesApprovedDefectQty +=
          parseFloat(String(row['SL lỗi'] ?? row.DefectQty ?? 0).replace(/,/g, '')) || 0
      })

      const defectRate =
        totalProducedQty > 0 ? Number(((totalDefectQty / totalProducedQty) * 100).toFixed(2)) : 0
      const avgSyncDelay = syncCount > 0 ? Number((totalSyncDelaySec / syncCount).toFixed(1)) : 0

      const statFile = db
        .prepare('SELECT columns FROM calc_architecture_files WHERE file_type = ?')
        .get('stat_report')
      let statCols = []
      try {
        statCols = statFile?.columns ? JSON.parse(statFile.columns) : []
      } catch {}

      const statResult = {
        totalProducedQty,
        totalQualifiedQty,
        totalDefectQty,
        defectRate,
        totalTickets: statReportData.length,
        totalDowntimeMinutes,
        avgSyncDelaySeconds: avgSyncDelay,
        insidePlanCount,
        outsidePlanCount,
        mesUserCount,
        bravoUserCount,
        duplicateSlipCount,
        mesApproval: {
          totalApprovedTickets: mesApprovalData.length,
          approvedProducedQty: mesApprovedProducedQty,
          approvedQualifiedQty: mesApprovedQualifiedQty,
          approvedDefectQty: mesApprovedDefectQty,
          discrepancyProducedQty: totalProducedQty - mesApprovedProducedQty,
          discrepancyQualifiedQty: totalQualifiedQty - mesApprovedQualifiedQty
        },
        machineBreakdown: Object.values(statByMachine).sort(
          (a, b) => b.producedQty - a.producedQty
        ),
        teamBreakdown: Object.values(statByTeam).sort((a, b) => b.producedQty - a.producedQty),
        technicianBreakdown: Object.values(statByTechnician).sort(
          (a, b) => b.producedQty - a.producedQty
        ),
        columns: statCols,
        calculatedRows
      }

      // 1. Tổng hợp thực tế sản xuất theo lệnh
      const actualByOp = new Map()
      statReportData.forEach((row) => {
        const op = normalize(
          row.OperationOrderNo ?? row['Số lệnh thao tác'] ?? row['Lệnh thao tác'] ?? ''
        )
        if (!op) return
        const p =
          parseFloat(String(row.ProducedQty ?? row['Số lượng sản xuất'] ?? 0).replace(/,/g, '')) ||
          0
        const q =
          parseFloat(String(row.QualifiedQty ?? row['Số lượng đạt'] ?? 0).replace(/,/g, '')) || 0
        const d =
          parseFloat(String(row.DefectQty ?? row['Số lượng lỗi'] ?? 0).replace(/,/g, '')) || 0
        const rt =
          parseFloat(
            String(row.ActualRunTime ?? row['Thời gian chạy thực tế'] ?? 0).replace(/,/g, '')
          ) || 0
        if (!actualByOp.has(op)) {
          actualByOp.set(op, { p: 0, q: 0, d: 0, rt: 0 })
        }
        const cur = actualByOp.get(op)
        cur.p += p
        cur.q += q
        cur.d += d
        cur.rt += rt
      })

      // 2. Lọc danh sách duy nhất theo Số lệnh thao tác (Deduplication)
      const uniquePlanMap = new Map()
      summaryOpData.forEach((row, idx) => {
        const op = normalize(
          row.OperationOrderNo ??
            row.PlannedOperationOrderNo ??
            row['Lệnh thao tác'] ??
            row['Số lệnh thao tác'] ??
            row['Số lệnh TT'] ??
            `KHSX-${idx + 1}`
        )
        if (!op) return
        if (!uniquePlanMap.has(op)) {
          uniquePlanMap.set(op, row)
        }
      })

      const planCalculatedRows = []
      let totalPlannedQty = 0

      uniquePlanMap.forEach((row, op) => {
        const pic = String(
          row.OrderIssuer ??
            row.PicCoordinator ??
            row['Người phát hành lệnh thao tác'] ??
            row['PIC ĐP'] ??
            ''
        ).trim()
        const opDate = String(
          row.OperationDate ??
            row.KhsxOpDate ??
            row['Ngày KHSX thao tác'] ??
            row['Ngày thực hiện thao tác'] ??
            ''
        ).trim()
        const stageOrderNo = String(
          row.StageOrderNo ?? row['Lệnh công đoạn'] ?? row['Số lệnh công đoạn'] ?? ''
        ).trim()
        const stageCreatedDate = String(
          row.OpOrderReleaseDate ??
            row.StageOrderCreatedDate ??
            row['Ngày phát hành lệnh thao tác'] ??
            ''
        ).trim()
        const matCode = String(row.MaterialCode ?? row['Mã vật tư'] ?? row['Mã hàng'] ?? '').trim()
        const matName = String(
          row.MaterialName ?? row['Tên vật tư'] ?? row['Tên hàng'] ?? ''
        ).trim()
        const opName = String(
          row.PlannedOperationTypeName ?? row.OperationName ?? row['Tên phân loại thao tác'] ?? ''
        ).trim()
        const machine = String(
          row.PlannedMachineName ?? row.MachineName ?? row['Tên máy'] ?? ''
        ).trim()
        const unit = String(row.Unit ?? row['ĐVT'] ?? row['Đvt'] ?? 'Pcs').trim()

        const rawPlanned =
          parseFloat(
            String(
              row['Số lượng cần sx (1)'] ??
                row['Số lượng \ncần sx \n(1)'] ??
                row['Số lượng cần sản xuất'] ??
                row.PlannedQty ??
                0
            ).replace(/,/g, '')
          ) || 0
        const rawTarget =
          parseFloat(
            String(
              row['Số lượng cần đạt (2)'] ??
                row['Số lượng \ncần đạt \n(2)'] ??
                row['Số lượng cần đạt'] ??
                row.TargetQty ??
                0
            ).replace(/,/g, '')
          ) || 0
        const startTime = String(
          row.PlannedStartTime ??
            row.StartTime ??
            row['Thời gian bắt đầu (5)'] ??
            row['Thời gian bắt đầu'] ??
            ''
        ).trim()
        const endTime = String(
          row.PlannedEndTime ??
            row.EndTime ??
            row['Thời gian kết thúc (6)'] ??
            row['Thời gian kết thúc'] ??
            ''
        ).trim()

        let rawDuration =
          parseFloat(
            String(
              row.PlannedTotalHours ?? row['Tổng thời gian kế hoạch (7)=(6)-(5)'] ?? 0
            ).replace(/,/g, '')
          ) || 0
        let standardRunMin = rawDuration > 0 ? Math.round(rawDuration * 60) : 0

        const act = actualByOp.get(op) || { p: 0, q: 0, d: 0, rt: 0 }
        let standardCapa =
          standardRunMin > 0 && rawTarget > 0
            ? Number(((rawTarget / standardRunMin) * 60).toFixed(4))
            : 0
        let actualCapa = act.rt > 0 && act.q > 0 ? Number(((act.q / act.rt) * 60).toFixed(4)) : 0

        let coordinatorStatus = 'Trượt KH'
        if (act.q >= rawTarget && rawTarget > 0) {
          coordinatorStatus = act.q > rawTarget * 1.05 ? 'Vượt KH' : 'Đạt KH'
        } else if (act.q > 0) {
          coordinatorStatus = 'Đang chạy'
        }

        totalPlannedQty += rawPlanned

        planCalculatedRows.push({
          PicCoordinator: pic,
          OperationOrderNo: op,
          OperationDate: opDate,
          StageOrderNo: stageOrderNo,
          StageOrderCreatedDate: stageCreatedDate,
          MaterialCode: matCode,
          MaterialName: matName,
          OperationName: opName,
          OperationTypeName: opName,
          MachineName: machine,
          Unit: unit,
          OpTargetQty: rawTarget,
          OpPlannedQty: rawPlanned,
          ActualQualifiedQty: act.q,
          StartTime: startTime,
          EndTime: endTime,
          StandardRunMinutes: standardRunMin,
          ActualRunMinutes: act.rt,
          StandardCapa: standardCapa,
          ActualCapa: actualCapa,
          CoordinatorStatus: coordinatorStatus,
          TimeStatus:
            act.rt > 0 && standardRunMin > 0
              ? act.rt <= standardRunMin
                ? 'Đạt thời gian'
                : 'Vượt giờ ĐM'
              : '',
          CapaStatus:
            actualCapa > 0 && standardCapa > 0
              ? actualCapa >= standardCapa
                ? 'Đạt Capa'
                : 'Chưa đạt Capa'
              : '',
          KhsxStatus: 'KHSX'
        })
      })

      let totalUnfinishedQty = 0
      unfinishedOpData.forEach((row) => {
        totalUnfinishedQty +=
          parseFloat(String(row['Số lượng còn lại'] ?? row.RemainingQty ?? 0).replace(/,/g, '')) ||
          0
      })

      const planResult = {
        totalPlannedQty,
        totalUnfinishedQty,
        totalPlannedOrders: planCalculatedRows.length,
        totalUnfinishedOrders: unfinishedOpData.length,
        calculatedRows: planCalculatedRows
      }

      const completionRate =
        totalPlannedQty > 0 ? Number(((totalProducedQty / totalPlannedQty) * 100).toFixed(2)) : 0

      const result = {
        success: true,
        calculatedAt: new Date().toISOString(),
        summary: {
          completionRate,
          plannedQty: totalPlannedQty,
          producedQty: totalProducedQty,
          qualifiedQty: totalQualifiedQty,
          defectQty: totalDefectQty,
          defectRate,
          unfinishedQty: totalUnfinishedQty
        },
        plan: planResult,
        stat: statResult
      }

      // Tự động lưu kết quả vào bảng calc_results trong SQLite
      try {
        const insStmt = db.prepare(`
          INSERT INTO calc_results (id, summary, plan_data, stat_data, calculated_at)
          VALUES (?, ?, ?, ?, ?)
          ON CONFLICT(id) DO UPDATE SET
            summary = excluded.summary,
            plan_data = excluded.plan_data,
            stat_data = excluded.stat_data,
            calculated_at = excluded.calculated_at
        `)
        insStmt.run(
          'CURRENT_CALC',
          JSON.stringify(result.summary || {}),
          JSON.stringify(result.plan || {}),
          JSON.stringify(result.stat || {}),
          result.calculatedAt
        )
      } catch (saveErr) {
        console.warn('[SQLite] Lưu kết quả calc_results:', saveErr)
      }

      return result
    } catch (err) {
      console.error('[SQLite IPC] Lỗi tính toán:', err)
      return { success: false, error: err.message }
    }
  })

  // 2. Lưu kết quả tính toán (hỗ trợ cả payload {id, data}, (id, data) và payload trực tiếp)
  ipcMain.handle('sqlite:save-calc-results', async (_, payload, maybeData) => {
    const db = getDb()
    if (!db) return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    try {
      let targetId = ''
      let dataObj = {}

      if (typeof payload === 'string') {
        targetId = payload
        dataObj = maybeData || {}
      } else if (payload && typeof payload === 'object') {
        targetId = payload.id || payload.regCode || ''
        dataObj = payload.data !== undefined ? payload.data : payload
      }

      if (!targetId) {
        return { success: false, error: 'Thiếu mã định danh phiếu khi lưu kết quả tính toán' }
      }

      const summary = dataObj?.summary || {}
      const plan = dataObj?.planData ? { calculatedRows: dataObj.planData } : dataObj?.plan || {}
      const stat = dataObj?.statData ? { calculatedRows: dataObj.statData } : dataObj?.stat || {}
      const calculatedAt = dataObj?.calculatedAt || new Date().toISOString()

      const stmt = db.prepare(`
        INSERT INTO calc_results (id, summary, plan_data, stat_data, calculated_at)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          summary = excluded.summary,
          plan_data = excluded.plan_data,
          stat_data = excluded.stat_data,
          calculated_at = excluded.calculated_at
      `)

      const sumJson = typeof summary === 'string' ? summary : JSON.stringify(summary)
      const planJson = typeof plan === 'string' ? plan : JSON.stringify(plan)
      const statJson = typeof stat === 'string' ? stat : JSON.stringify(stat)

      stmt.run(targetId, sumJson, planJson, statJson, calculatedAt)

      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lưu kết quả tính:', err)
      return { success: false, error: err.message }
    }
  })

  // 3. Lấy kết quả tính toán theo đúng mã phiếu id (cô lập 100%, không dùng fallback rò rỉ)
  ipcMain.handle('sqlite:get-calc-results', async (_, id) => {
    const db = getDb()
    if (!db || !id) return null
    try {
      const stmt = db.prepare('SELECT * FROM calc_results WHERE id = ?')
      const r = stmt.get(id)
      if (!r) return null
      return {
        id: r.id,
        summary: JSON.parse(r.summary || '{}'),
        plan: JSON.parse(r.plan_data || '{}'),
        stat: JSON.parse(r.stat_data || '{}'),
        calculatedAt: r.calculated_at
      }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy calc results:', err)
      return null
    }
  })
}

/**
 * SQLite IPC Handlers for Architecture Files (4 Files)
 * Quản lý lưu trữ/truy vấn 4 file kiến trúc theo Chunking và Phân trang (1.500 dòng/trang)
 */
import { ipcMain } from 'electron'
import { getDb, getFullDataForFileType } from './db.js'

export function setupFilesIpc() {
  // 1. Lưu từng khúc (Chunk) của 1 file kiến trúc (Batch Insert siêu tốc)
  ipcMain.handle('sqlite:save-calc-file-chunk', async (_, payload) => {
    const db = getDb()
    if (!db) {
      return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    }
    try {
      const {
        regCode = '',
        fileType,
        fileName,
        fileSize,
        rowCount,
        columns,
        chunk,
        chunkIndex,
        isFirstChunk,
        uploadedAt
      } = payload

      const activeRegCode = regCode || payload.reg_code || ''

      const tx = db.transaction(() => {
        if (isFirstChunk) {
          const metaStmt = db.prepare(`
            INSERT INTO calc_architecture_files (reg_code, file_type, file_name, file_size, row_count, columns, data, uploaded_at)
            VALUES (?, ?, ?, ?, ?, ?, '', ?)
            ON CONFLICT(reg_code, file_type) DO UPDATE SET
              file_name = excluded.file_name,
              file_size = excluded.file_size,
              row_count = excluded.row_count,
              columns = excluded.columns,
              data = '',
              uploaded_at = excluded.uploaded_at
          `)
          metaStmt.run(
            activeRegCode,
            fileType,
            fileName || '',
            fileSize || 0,
            rowCount || 0,
            typeof columns === 'string' ? columns : JSON.stringify(columns || []),
            uploadedAt || new Date().toISOString()
          )

          db.prepare(
            'DELETE FROM calc_architecture_chunks WHERE LOWER(file_type) = LOWER(?) AND reg_code = ?'
          ).run(fileType, activeRegCode)
        }

        if (chunk && chunk.length > 0) {
          const chunkStmt = db.prepare(`
            INSERT OR REPLACE INTO calc_architecture_chunks (reg_code, file_type, chunk_index, row_count, data)
            VALUES (?, ?, ?, ?, ?)
          `)
          chunkStmt.run(
            activeRegCode,
            fileType,
            chunkIndex,
            chunk.length,
            typeof chunk === 'string' ? chunk : JSON.stringify(chunk)
          )
        }
      })

      tx()
      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lưu file chunk:', err)
      return { success: false, error: err.message }
    }
  })

  // 2. Lưu 1 file kiến trúc (nguyên khối fallback)
  ipcMain.handle('sqlite:save-calc-file', async (_, payload) => {
    const db = getDb()
    if (!db) {
      return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    }
    try {
      const activeRegCode = payload.regCode || payload.reg_code || ''
      const stmt = db.prepare(`
        INSERT INTO calc_architecture_files (reg_code, file_type, file_name, file_size, row_count, columns, data, uploaded_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(reg_code, file_type) DO UPDATE SET
          file_name = excluded.file_name,
          file_size = excluded.file_size,
          row_count = excluded.row_count,
          columns = excluded.columns,
          data = excluded.data,
          uploaded_at = excluded.uploaded_at
      `)

      stmt.run(
        activeRegCode,
        payload.fileType,
        payload.fileName || '',
        payload.fileSize || 0,
        payload.rowCount || 0,
        typeof payload.columns === 'string'
          ? payload.columns
          : JSON.stringify(payload.columns || []),
        typeof payload.data === 'string' ? payload.data : JSON.stringify(payload.data || []),
        payload.uploadedAt || new Date().toISOString()
      )

      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lưu file:', err)
      return { success: false, error: err.message }
    }
  })

  // 3. Lấy Metadata tóm tắt của tất cả các file (KHÔNG đọc cột data dung lượng lớn -> Cực nhanh < 1ms)
  ipcMain.handle('sqlite:get-all-file-summaries', async (_, payload) => {
    const db = getDb()
    if (!db) return []
    try {
      const regCode =
        typeof payload === 'string'
          ? payload.trim()
          : (payload?.regCode || payload?.reg_code || '').trim()
      let rows = []
      if (regCode) {
        const stmt = db.prepare(
          'SELECT file_type, file_name, file_size, row_count, columns, uploaded_at FROM calc_architecture_files WHERE reg_code = ?'
        )
        rows = stmt.all(regCode)
      } else {
        // Nếu không có regCode, không tự động lấy dữ liệu tàn dư của các phiếu khác
        rows = []
      }
      return rows.map((row) => ({
        regCode: row.reg_code || regCode,
        fileType: row.file_type,
        fileName: row.file_name,
        fileSize: row.file_size,
        rowCount: row.row_count,
        columns: JSON.parse(row.columns || '[]'),
        uploadedAt: row.uploaded_at
      }))
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy tóm tắt files:', err)
      return []
    }
  })

  // 4. Lấy chi tiết 1 file (bao gồm data được ghép từ chunks)
  ipcMain.handle('sqlite:get-calc-file', async (_, payload) => {
    const db = getDb()
    const fileType = typeof payload === 'string' ? payload : payload?.fileType
    const regCode = (
      typeof payload === 'object' ? payload?.regCode || payload?.reg_code || '' : ''
    ).trim()
    if (!db || !fileType) return null
    try {
      let row = null
      if (regCode) {
        row = db
          .prepare(
            'SELECT * FROM calc_architecture_files WHERE LOWER(file_type) = LOWER(?) AND reg_code = ?'
          )
          .get(fileType, regCode)
      } else {
        row = null
      }
      if (!row) return null
      const fullData = getFullDataForFileType(fileType, regCode)
      return {
        regCode: row.reg_code || regCode,
        fileType: row.file_type,
        fileName: row.file_name,
        fileSize: row.file_size,
        rowCount: row.row_count || fullData.length,
        columns: JSON.parse(row.columns || '[]'),
        data: fullData,
        uploadedAt: row.uploaded_at
      }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy file:', err)
      return null
    }
  })

  // 5. Lấy dữ liệu phân trang (mặc định 1.500 dòng/trang) cho 1 fileType để cuộn mượt mà không nghẽn RAM (kèm lọc tìm kiếm trực tiếp trong DB SQLite)
  ipcMain.handle(
    'sqlite:get-calc-file-page',
    async (
      _,
      {
        regCode = '',
        fileType,
        page = 1,
        pageSize = 1500,
        searchText = '',
        filterValues = {},
        statusFilter = 'ALL'
      } = {}
    ) => {
      const db = getDb()
      if (!db || !fileType) return { rows: [], total: 0, page: 1, pageSize: 1500, totalPages: 0 }
      try {
        let meta = null
        if (regCode) {
          meta = db
            .prepare(
              'SELECT file_type, file_name, file_size, row_count, columns, uploaded_at FROM calc_architecture_files WHERE LOWER(file_type) = LOWER(?) AND reg_code = ?'
            )
            .get(fileType, regCode)
        } else {
          return { rows: [], total: 0, page: 1, pageSize: 1500, totalPages: 0 }
        }
        if (!meta) {
          return {
            fileType,
            fileName: '',
            fileSize: 0,
            columns: [],
            rows: [],
            total: 0,
            page: 1,
            pageSize,
            totalPages: 0,
            uploadedAt: null
          }
        }

        const hasSearchText = Boolean(searchText && String(searchText).trim())
        const hasStatusFilter = Boolean(statusFilter && statusFilter !== 'ALL')
        const hasFilterValues = Boolean(
          filterValues &&
          typeof filterValues === 'object' &&
          Object.values(filterValues).some(
            (v) => v !== undefined && v !== null && String(v).trim() !== ''
          )
        )
        const hasFilter = hasSearchText || hasStatusFilter || hasFilterValues

        const totalRows = meta.row_count || 0
        const totalPagesCount = Math.max(1, Math.ceil(totalRows / pageSize))
        const offset = (Math.max(1, page) - 1) * pageSize

        // TỐI ƯU SIÊU TỐC: Khi không có bộ lọc tìm kiếm, CHỈ nạp đúng 1-2 Chunks liên quan đến trang hiện tại (< 2ms)
        if (!hasFilter && totalRows > 0) {
          const CHUNK_SIZE = 2500
          const startChunkIdx = Math.floor(offset / CHUNK_SIZE)
          const endChunkIdx = Math.floor((offset + pageSize - 1) / CHUNK_SIZE)

          let targetedChunks = []
          if (regCode) {
            targetedChunks = db
              .prepare(
                'SELECT chunk_index, data FROM calc_architecture_chunks WHERE LOWER(file_type) = LOWER(?) AND reg_code = ? AND chunk_index >= ? AND chunk_index <= ? ORDER BY chunk_index ASC'
              )
              .all(fileType, regCode, startChunkIdx, endChunkIdx)
          } else {
            targetedChunks = db
              .prepare(
                "SELECT chunk_index, data FROM calc_architecture_chunks WHERE LOWER(file_type) = LOWER(?) AND (reg_code IS NULL OR reg_code = '') AND chunk_index >= ? AND chunk_index <= ? ORDER BY chunk_index ASC"
              )
              .all(fileType, startChunkIdx, endChunkIdx)
          }

          if (targetedChunks && targetedChunks.length > 0) {
            const windowRows = []
            for (const ch of targetedChunks) {
              if (ch.data) {
                try {
                  const arr = typeof ch.data === 'string' ? JSON.parse(ch.data) : ch.data
                  if (Array.isArray(arr)) windowRows.push(...arr)
                } catch {}
              }
            }
            const localStart = offset - startChunkIdx * CHUNK_SIZE
            const pageRows = windowRows.slice(localStart, localStart + pageSize)

            return {
              fileType,
              fileName: meta?.file_name || '',
              fileSize: meta?.file_size || 0,
              columns: meta?.columns ? JSON.parse(meta.columns) : [],
              rows: pageRows,
              total: totalRows,
              page: Math.max(1, page),
              pageSize,
              totalPages: totalPagesCount,
              uploadedAt: meta?.uploaded_at || null
            }
          }
        }

        const fullData = getFullDataForFileType(fileType, regCode)

        let filteredData = fullData

        // 1. Lọc theo ô tìm kiếm chung SearchText (hỗ trợ nhiều từ khóa phân tách bằng dấu phẩy, chấm phẩy, xuống dòng, tab, pipe)
        if (searchText && String(searchText).trim()) {
          const tokens = String(searchText)
            .split(/[,;\n\r\t|]+/)
            .map((t) => t.trim().toLowerCase())
            .filter(Boolean)

          if (tokens.length > 0) {
            filteredData = filteredData.filter((row) => {
              if (!row) return false
              return Object.values(row).some((val) => {
                if (val === null || val === undefined) return false
                const strVal = String(val).toLowerCase()
                return tokens.some((token) => strVal.includes(token))
              })
            })
          }
        }

        // 2. Lọc theo trạng thái statusFilter
        if (statusFilter && statusFilter !== 'ALL') {
          const sf = String(statusFilter).toLowerCase()
          filteredData = filteredData.filter((row) => {
            if (!row) return false
            const tag = String(
              row.CoordinatorStatus ||
                row['Trạng thái ĐP - SX'] ||
                row.StatusDpSx ||
                row.CheckKhsx ||
                row['CHECK KHSX'] ||
                row.KhsxStatus ||
                row.Status ||
                row.OpInfoStatus ||
                row['Trạng thái LTT'] ||
                ''
            ).toLowerCase()
            return tag === sf || tag.includes(sf) || sf.includes(tag)
          })
        }

        // 3. Lọc theo các trường lọc động filterValues
        if (filterValues && typeof filterValues === 'object') {
          const activeFilters = Object.entries(filterValues).filter(
            ([, val]) => val !== undefined && val !== null && String(val).trim() !== ''
          )
          if (activeFilters.length > 0) {
            filteredData = filteredData.filter((row) => {
              if (!row) return false
              return activeFilters.every(([key, filterVal]) => {
                const tokens = String(filterVal)
                  .split(/[,;\n\r\t|]+/)
                  .map((t) => t.trim().toLowerCase())
                  .filter(Boolean)
                if (tokens.length === 0) return true
                const rowVal =
                  row[key] !== undefined
                    ? row[key]
                    : row[key.toLowerCase()] !== undefined
                      ? row[key.toLowerCase()]
                      : Object.entries(row).find(
                          ([k]) => k.toLowerCase() === key.toLowerCase()
                        )?.[1]
                if (rowVal === null || rowVal === undefined) return false
                const rowValStr = String(rowVal).toLowerCase()
                return tokens.some((token) => rowValStr.includes(token))
              })
            })
          }
        }

        const total = filteredData.length
        const totalPages = Math.max(1, Math.ceil(total / pageSize))

        if (page > totalPages || total === 0) {
          return {
            fileType,
            fileName: meta?.file_name || '',
            fileSize: meta?.file_size || 0,
            columns: meta?.columns ? JSON.parse(meta.columns) : [],
            rows: [],
            total,
            page,
            pageSize,
            totalPages,
            uploadedAt: meta?.uploaded_at || null
          }
        }

        const finalOffset = (Math.max(1, page) - 1) * pageSize
        const pageRows = filteredData.slice(finalOffset, finalOffset + pageSize)

        return {
          fileType,
          fileName: meta?.file_name || '',
          fileSize: meta?.file_size || 0,
          columns: meta?.columns ? JSON.parse(meta.columns) : [],
          rows: pageRows,
          total,
          page: Math.max(1, page),
          pageSize,
          totalPages,
          uploadedAt: meta?.uploaded_at || null
        }
      } catch (err) {
        console.error('[SQLite IPC] Lỗi lấy phân trang file:', err)
        return { rows: [], total: 0, page: 1, pageSize: 1500, totalPages: 0, error: err.message }
      }
    }
  )

  // 6. Lấy toàn bộ các file (chỉ dùng khi tính toán KHSX & TKSX)
  ipcMain.handle('sqlite:get-all-calc-files', async (_, payload) => {
    const db = getDb()
    if (!db) return []
    try {
      const regCode =
        typeof payload === 'string' ? payload : payload?.regCode || payload?.reg_code || ''
      let rows = []
      if (regCode) {
        const stmt = db.prepare('SELECT * FROM calc_architecture_files WHERE reg_code = ?')
        rows = stmt.all(regCode)
      } else {
        const stmt = db.prepare(
          "SELECT * FROM calc_architecture_files WHERE reg_code IS NULL OR reg_code = ''"
        )
        rows = stmt.all()
      }
      return rows.map((row) => {
        const fullData = getFullDataForFileType(row.file_type, row.reg_code || regCode)
        return {
          regCode: row.reg_code,
          fileType: row.file_type,
          fileName: row.file_name,
          fileSize: row.file_size,
          rowCount: row.row_count || fullData.length,
          columns: JSON.parse(row.columns || '[]'),
          data: fullData,
          uploadedAt: row.uploaded_at
        }
      })
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy toàn bộ files:', err)
      return []
    }
  })

  // 7. Xóa 1 file hoặc xóa toàn bộ (kèm xóa chunks)
  ipcMain.handle('sqlite:delete-calc-file', async (_, payload) => {
    const db = getDb()
    if (!db) return { success: false }
    try {
      const fileType = typeof payload === 'string' ? payload : payload?.fileType
      const regCode = typeof payload === 'object' ? payload?.regCode || payload?.reg_code || '' : ''
      if (fileType) {
        if (regCode) {
          db.prepare(
            'DELETE FROM calc_architecture_files WHERE LOWER(file_type) = LOWER(?) AND reg_code = ?'
          ).run(fileType, regCode)
          db.prepare(
            'DELETE FROM calc_architecture_chunks WHERE LOWER(file_type) = LOWER(?) AND reg_code = ?'
          ).run(fileType, regCode)
        } else {
          db.prepare('DELETE FROM calc_architecture_files WHERE LOWER(file_type) = LOWER(?)').run(
            fileType
          )
          db.prepare('DELETE FROM calc_architecture_chunks WHERE LOWER(file_type) = LOWER(?)').run(
            fileType
          )
        }
      } else {
        if (regCode) {
          db.prepare('DELETE FROM calc_architecture_files WHERE reg_code = ?').run(regCode)
          db.prepare('DELETE FROM calc_architecture_chunks WHERE reg_code = ?').run(regCode)
        } else {
          db.exec('DELETE FROM calc_architecture_files; DELETE FROM calc_architecture_chunks;')
        }
      }
      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi xóa file:', err)
      return { success: false, error: err.message }
    }
  })

  // 8. Dọn dẹp toàn bộ cache mồ côi / dữ liệu tạm trong SQLite
  ipcMain.handle('sqlite:clean-cache', async () => {
    const db = getDb()
    if (!db) return { success: false }
    try {
      const delFiles = db
        .prepare("DELETE FROM calc_architecture_files WHERE reg_code IS NULL OR reg_code = ''")
        .run()
      const delChunks = db
        .prepare("DELETE FROM calc_architecture_chunks WHERE reg_code IS NULL OR reg_code = ''")
        .run()
      const delResults = db
        .prepare(
          "DELETE FROM calc_results WHERE id IN ('latest_calculation', 'CURRENT_CALC') OR id IS NULL OR id = ''"
        )
        .run()
      try {
        db.exec('VACUUM;')
      } catch {}
      return {
        success: true,
        deletedFiles: delFiles.changes,
        deletedChunks: delChunks.changes,
        deletedResults: delResults.changes
      }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi dọn dẹp cache:', err)
      return { success: false, error: err.message }
    }
  })
}

/**
 * SQLite IPC Handlers for Master Registrations
 * Quản lý các phiếu đăng ký báo cáo sản xuất (Master)
 */
import { ipcMain } from 'electron'
import { getDb } from './db.js'
function ensureMasterColumns(db) {
  if (!db) return
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN is_published INTEGER DEFAULT 0;`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN version TEXT DEFAULT '1.0';`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN published_at TEXT;`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN registered_by TEXT;`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN raw_size_mb REAL DEFAULT 0;`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN compressed_size_mb REAL DEFAULT 0;`)
  } catch {}
  try {
    db.exec(`ALTER TABLE calc_master_registrations ADD COLUMN compression_ratio TEXT;`)
  } catch {}
}

export function setupMasterIpc() {
  const dbInit = getDb()
  if (dbInit) ensureMasterColumns(dbInit)

  // 1. Lưu đăng ký Master (hỗ trợ version, is_published, published_at)
  ipcMain.handle('sqlite:save-master-reg', async (_, payload) => {
    const db = getDb()
    if (!db) return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    ensureMasterColumns(db)
    try {
      const stmt = db.prepare(`
        INSERT INTO calc_master_registrations (
          reg_code, factory_name, apply_date, production_team, remark, status,
          stat_report_rows, unfinished_op_rows, summary_op_rows, mes_approval_rows, total_rows,
          file_summaries, registered_at, version, is_published, published_at, registered_by,
          raw_size_mb, compressed_size_mb, compression_ratio
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(reg_code) DO UPDATE SET
          factory_name = excluded.factory_name,
          apply_date = excluded.apply_date,
          production_team = excluded.production_team,
          remark = excluded.remark,
          status = excluded.status,
          stat_report_rows = excluded.stat_report_rows,
          unfinished_op_rows = excluded.unfinished_op_rows,
          summary_op_rows = excluded.summary_op_rows,
          mes_approval_rows = excluded.mes_approval_rows,
          total_rows = excluded.total_rows,
          file_summaries = excluded.file_summaries,
          registered_at = excluded.registered_at,
          version = excluded.version,
          is_published = excluded.is_published,
          published_at = excluded.published_at,
          registered_by = excluded.registered_by,
          raw_size_mb = excluded.raw_size_mb,
          compressed_size_mb = excluded.compressed_size_mb,
          compression_ratio = excluded.compression_ratio
      `)

      const status = payload.status || 'DRAFT'
      const version = payload.version || '1.0'
      const isPublished = payload.isPublished ? 1 : 0
      const publishedAt = payload.publishedAt || (isPublished ? new Date().toISOString() : null)
      const registeredBy = payload.registeredBy || payload.createdBy || ''
      const rawSizeMB = payload.rawSizeMB || payload.raw_size_mb || 0
      const compressedSizeMB = payload.compressedSizeMB || payload.compressed_size_mb || 0
      const compressionRatio = payload.compressionRatio || payload.compression_ratio || ''

      stmt.run(
        payload.regCode,
        payload.factoryName || 'GS1 Hà Nội',
        payload.applyDate || '',
        payload.productionTeam || 'Tất cả các tổ',
        payload.remark || '',
        status,
        payload.statReportRows || 0,
        payload.unfinishedOpRows || 0,
        payload.summaryOpRows || 0,
        payload.mesApprovalRows || 0,
        payload.totalRows || 0,
        typeof payload.fileSummaries === 'string'
          ? payload.fileSummaries
          : JSON.stringify(payload.fileSummaries || {}),
        payload.registeredAt || new Date().toISOString(),
        version,
        isPublished,
        publishedAt,
        registeredBy,
        rawSizeMB,
        compressedSizeMB,
        compressionRatio
      )
      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lưu master reg:', err)
      return { success: false, error: err.message }
    }
  })

  // 2. Công bố báo cáo (Publish Version)
  ipcMain.handle('sqlite:publish-master-reg', async (_, payload) => {
    const db = getDb()
    if (!db) return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    ensureMasterColumns(db)
    try {
      const regCode = typeof payload === 'string' ? payload : payload?.regCode
      const version = payload?.version || '1.0'
      const publishedAt = new Date().toISOString()

      const stmt = db.prepare(`
        UPDATE calc_master_registrations
        SET status = 'PUBLISHED',
            version = ?,
            is_published = 1,
            published_at = ?
        WHERE reg_code = ?
      `)
      stmt.run(version, publishedAt, regCode)
      return { success: true, version, publishedAt, status: 'PUBLISHED' }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi công bố báo cáo:', err)
      return { success: false, error: err.message }
    }
  })

  // 3. Lấy tất cả đăng ký Master
  ipcMain.handle('sqlite:get-all-master-regs', async () => {
    const db = getDb()
    if (!db) return []
    try {
      const stmt = db.prepare('SELECT * FROM calc_master_registrations ORDER BY registered_at DESC')
      const rows = stmt.all()
      return rows.map((r) => ({
        regCode: r.reg_code,
        factoryName: r.factory_name,
        applyDate: r.apply_date,
        productionTeam: r.production_team || 'Tất cả các tổ',
        remark: r.remark,
        status: r.status || 'DRAFT',
        version: r.version || '1.0',
        isPublished: Boolean(r.is_published),
        publishedAt: r.published_at,
        statReportRows: r.stat_report_rows,
        unfinishedOpRows: r.unfinished_op_rows,
        summaryOpRows: r.summary_op_rows,
        mesApprovalRows: r.mes_approval_rows,
        totalRows: r.total_rows,
        rawSizeMB: r.raw_size_mb || 0,
        compressedSizeMB: r.compressed_size_mb || 0,
        compressionRatio: r.compression_ratio || '',
        fileSummaries: JSON.parse(r.file_summaries || '{}'),
        registeredAt: r.registered_at,
        registeredBy: r.registered_by || 'Admin'
      }))
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy danh sách master reg:', err)
      return []
    }
  })

  // 4. Lấy 1 đăng ký Master theo regCode
  ipcMain.handle('sqlite:get-master-reg', async (_, regCode) => {
    const db = getDb()
    if (!db || !regCode) return null
    try {
      const stmt = db.prepare('SELECT * FROM calc_master_registrations WHERE reg_code = ?')
      const r = stmt.get(regCode)
      if (!r) return null
      return {
        regCode: r.reg_code,
        factoryName: r.factory_name,
        applyDate: r.apply_date,
        productionTeam: r.production_team || 'Tất cả các tổ',
        remark: r.remark,
        status: r.status || 'DRAFT',
        version: r.version || '1.0',
        isPublished: Boolean(r.is_published),
        publishedAt: r.published_at,
        statReportRows: r.stat_report_rows,
        unfinishedOpRows: r.unfinished_op_rows,
        summaryOpRows: r.summary_op_rows,
        mesApprovalRows: r.mes_approval_rows,
        totalRows: r.total_rows,
        rawSizeMB: r.raw_size_mb || 0,
        compressedSizeMB: r.compressed_size_mb || 0,
        compressionRatio: r.compression_ratio || '',
        fileSummaries: JSON.parse(r.file_summaries || '{}'),
        registeredAt: r.registered_at,
        registeredBy: r.registered_by || 'Admin'
      }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi lấy master reg:', err)
      return null
    }
  })

  // 5. Xóa đăng ký Master (xóa sạch toàn bộ files, chunks, kết quả tính toán và bundle liên quan)
  ipcMain.handle('sqlite:delete-master-reg', async (_, regCode) => {
    const db = getDb()
    if (!db || !regCode) return { success: false }
    try {
      db.prepare('DELETE FROM calc_master_registrations WHERE reg_code = ?').run(regCode)
      db.prepare('DELETE FROM calc_architecture_files WHERE reg_code = ?').run(regCode)
      db.prepare('DELETE FROM calc_architecture_chunks WHERE reg_code = ?').run(regCode)
      db.prepare('DELETE FROM calc_results WHERE id = ?').run(regCode)
      db.prepare('DELETE FROM calc_versioned_bundles WHERE reg_code = ?').run(regCode)
      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi xóa master reg:', err)
      return { success: false, error: err.message }
    }
  })

  // 6. Cập nhật trạng thái Master (ví dụ: chuyển sang CANCELLED)
  ipcMain.handle('sqlite:update-master-status', async (_, payload) => {
    const db = getDb()
    if (!db) return { success: false, error: 'Database SQLite chưa sẵn sàng' }
    try {
      const regCode = typeof payload === 'string' ? payload : payload?.regCode
      const status = payload?.status || 'CANCELLED'
      const remark = payload?.remark
      if (!regCode) return { success: false, error: 'Thiếu regCode' }

      if (remark !== undefined && remark !== null) {
        db.prepare(
          'UPDATE calc_master_registrations SET status = ?, remark = ? WHERE reg_code = ?'
        ).run(status, remark, regCode)
      } else {
        db.prepare('UPDATE calc_master_registrations SET status = ? WHERE reg_code = ?').run(
          status,
          regCode
        )
      }
      return { success: true }
    } catch (err) {
      console.error('[SQLite IPC] Lỗi cập nhật trạng thái master reg:', err)
      return { success: false, error: err.message }
    }
  })
}

import { app, ipcMain, BrowserWindow, shell } from 'electron'
import { join } from 'path'
import fs from 'fs'
import crypto from 'crypto'
import https from 'https'
import http from 'http'
import { exec, spawn } from 'child_process'
import { promisify } from 'util'
import { is } from '@electron-toolkit/utils'

const execAsync = promisify(exec)

// Khóa bảo mật AES-256 dùng để giải mã gói OTA giao diện
const OTA_SECRET_PASS = 'GsHub-Enterprise-ERP-Secret-OTA-Key-2026'
const OTA_SECRET_KEY = crypto.createHash('sha256').update(OTA_SECRET_PASS).digest()

function decryptOtaBuffer(encryptedBuffer) {
  const iv = encryptedBuffer.subarray(0, 16)
  const ciphertext = encryptedBuffer.subarray(16)
  const decipher = crypto.createDecipheriv('aes-256-cbc', OTA_SECRET_KEY, iv)
  return Buffer.concat([decipher.update(ciphertext), decipher.final()])
}

// ==========================================
// CẤU HÌNH GITHUB REPOSITORY DÙNG ĐỂ UPDATE
// ==========================================
export const GITHUB_CONFIG = {
  owner: 'hoangvantuan123',
  repo: 'gshub-releases',
  // Link raw file manifest để kiểm tra Hot Update UI nhanh
  get rawUiManifestUrl() {
    return `https://raw.githubusercontent.com/${this.owner}/${this.repo}/main/ui-release.json`
  },
  // API lấy release mới nhất của UI từ GitHub Releases
  get latestUiReleaseUrl() {
    return `https://api.github.com/repos/${this.owner}/${this.repo}/releases/tags/ui-latest`
  },
  // API lấy danh sách releases từ GitHub Releases
  get releasesApiUrl() {
    return `https://api.github.com/repos/${this.owner}/${this.repo}/releases`
  }
}

// Đường dẫn lưu trữ UI bundle cục bộ trên máy người dùng
const USER_DATA_DIR = app.getPath('userData')
const UI_BUNDLES_DIR = join(USER_DATA_DIR, 'ui_bundles')
const ACTIVE_UI_CONFIG_PATH = join(USER_DATA_DIR, 'active_ui.json')
const DEFAULT_RENDERER_DIR = join(__dirname, '../renderer')

// State quản lý trạng thái update trong Main process
let updateState = {
  status: 'idle', // 'idle' | 'checking' | 'ui-available' | 'native-available' | 'downloading' | 'ui-ready' | 'native-ready' | 'error' | 'up-to-date',
  message: 'Hệ thống đã sẵn sàng',
  nativeVersion: app.getVersion(),
  uiVersion: app.getVersion(),
  newUiVersion: null,
  newNativeVersion: null,
  progress: 0,
  releaseNotes: '',
  uiDownloadUrl: '',
  nativeDownloadUrl: ''
}

// ==========================================
// 1. QUẢN LÝ PHIÊN BẢN VÀ ĐƯỜNG DẪN RENDERER
// ==========================================

export function getActiveUiInfo() {
  const nativeVersion = app.getVersion()

  try {
    if (fs.existsSync(ACTIVE_UI_CONFIG_PATH)) {
      const data = JSON.parse(fs.readFileSync(ACTIVE_UI_CONFIG_PATH, 'utf8'))
      const customUiVersion = data.uiVersion || '0.0.0'

      // Nếu phiên bản app native chính thức lớn hơn hoặc bằng bản UI OTA cũ đã lưu
      // -> Bản build native đã chứa renderer mới nhất, lập tức bỏ qua UI OTA cũ
      if (!isNewerVersion(customUiVersion, nativeVersion)) {
        console.log(
          `[Updater] Phiên bản Native (v${nativeVersion}) mới hơn hoặc bằng UI OTA cũ (v${customUiVersion}). Tự động dùng UI gốc của bộ cài.`
        )
        try {
          fs.unlinkSync(ACTIVE_UI_CONFIG_PATH)
        } catch {}

        return {
          bundlePath: DEFAULT_RENDERER_DIR,
          uiVersion: nativeVersion,
          isCustomBundle: false
        }
      }

      const indexPath = join(data.bundlePath, 'index.html')
      if (fs.existsSync(indexPath)) {
        return {
          bundlePath: data.bundlePath,
          uiVersion: customUiVersion,
          isCustomBundle: true
        }
      }
    }
  } catch (err) {
    console.warn('[Updater] Không thể đọc active_ui.json, dùng bundle mặc định:', err.message)
  }

  return {
    bundlePath: DEFAULT_RENDERER_DIR,
    uiVersion: nativeVersion,
    isCustomBundle: false
  }
}

export function getRendererUrl(routePath = '') {
  const normalizedRoute = routePath.startsWith('#')
    ? routePath
    : routePath.startsWith('/')
      ? `#${routePath}`
      : `#/${routePath}`

  if (is.dev && process.env['ELECTRON_RENDERER_URL']) {
    const devBase = process.env['ELECTRON_RENDERER_URL'].replace(/\/$/, '')
    return `${devBase}/${normalizedRoute}`
  }

  const { bundlePath } = getActiveUiInfo()
  const indexPath = join(bundlePath, 'index.html')

  // Trả về định dạng file:///...#route
  const fileUrl = `file://${indexPath.replace(/\\/g, '/')}`
  return `${fileUrl}${normalizedRoute}`
}

// Thông báo trạng thái tới tất cả các cửa sổ Renderer
function broadcastStatus(patch = {}) {
  updateState = { ...updateState, ...patch }
  BrowserWindow.getAllWindows().forEach((win) => {
    if (!win.isDestroyed()) {
      win.webContents.send('updater:status-changed', updateState)
    }
  })
}

// Helper tải file qua HTTPS
function downloadFile(url, destPath, onProgress) {
  return new Promise((resolve, reject) => {
    const client = url.startsWith('https') ? https : http
    const options = {
      headers: {
        'User-Agent': 'GsHub-Desktop-App',
        Accept: 'application/octet-stream, application/json, */*'
      }
    }

    const request = client.get(url, options, (res) => {
      // Xử lý chuyển hướng redirect (301, 302) của GitHub Releases
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return downloadFile(res.headers.location, destPath, onProgress).then(resolve).catch(reject)
      }

      if (res.statusCode !== 200) {
        return reject(new Error(`Lỗi tải file: HTTP ${res.statusCode}`))
      }

      const totalBytes = parseInt(res.headers['content-length'] || '0', 10)
      let downloadedBytes = 0

      const fileStream = fs.createWriteStream(destPath)
      res.on('data', (chunk) => {
        downloadedBytes += chunk.length
        if (totalBytes > 0 && onProgress) {
          const percent = Math.round((downloadedBytes / totalBytes) * 100)
          onProgress(percent)
        }
      })

      fileStream.on('finish', () => {
        fileStream.close(() => resolve(destPath))
      })

      fileStream.on('error', (err) => {
        fs.unlink(destPath, () => reject(err))
      })
      res.pipe(fileStream)
    })

    request.on('error', reject)
    request.setTimeout(30000, () => {
      request.destroy()
      reject(new Error('Hết thời gian chờ tải file (Timeout)'))
    })
  })
}

// Helper giải nén file zip (Sử dụng lệnh hệ thống OS có sẵn, không cần native library phức tạp)
async function extractZip(zipPath, targetDir) {
  if (!fs.existsSync(targetDir)) {
    fs.mkdirSync(targetDir, { recursive: true })
  }

  if (process.platform === 'win32') {
    // Windows PowerShell giải nén cực nhanh và an toàn
    const command = `powershell.exe -NoProfile -Command "Expand-Archive -Path '${zipPath}' -DestinationPath '${targetDir}' -Force"`
    await execAsync(command)
  } else {
    // macOS / Linux sử dụng tar hoặc unzip
    const command = `unzip -o -q "${zipPath}" -d "${targetDir}"`
    await execAsync(command)
  }
}

// So sánh phiên bản semver (v1.0.1 > v1.0.0)
function isNewerVersion(remoteVer, currentVer) {
  if (!remoteVer || !currentVer) return false
  const clean = (v) => v.replace(/^v/, '').split('.').map(Number)
  const [r1 = 0, r2 = 0, r3 = 0] = clean(remoteVer)
  const [c1 = 0, c2 = 0, c3 = 0] = clean(currentVer)

  if (r1 > c1) return true
  if (r1 === c1 && r2 > c2) return true
  if (r1 === c1 && r2 === c2 && r3 > c3) return true
  return false
}

// ==========================================
// 2. LOẠI 1: HOT UPDATE GIAO DIỆN (OTA UI UPDATE)
// ==========================================

export async function checkUiHotUpdate(options = { autoDownload: true }) {
  const { uiVersion } = getActiveUiInfo()
  const nativeVersion = app.getVersion()
  const baseVersion = isNewerVersion(uiVersion, nativeVersion) ? uiVersion : nativeVersion

  try {
    broadcastStatus({
      status: 'checking',
      message: 'Đang kiểm tra cập nhật giao diện...'
    })

    // 1. Thử kiểm tra qua raw json (Cách nhanh nhất và không bị giới hạn GitHub API rate-limit)
    const manifest = await fetchJson(GITHUB_CONFIG.rawUiManifestUrl).catch(() => null)

    if (manifest && manifest.version) {
      // Chỉ tải và áp dụng UI mới khi version OTA lớn hơn cả bản build Native và bản UI hiện tại
      if (isNewerVersion(manifest.version, baseVersion)) {
        broadcastStatus({
          status: 'ui-available',
          message: `Phát hiện giao diện mới v${manifest.version}!`,
          newUiVersion: manifest.version,
          releaseNotes: manifest.description || 'Cập nhật và tối ưu giao diện người dùng.',
          uiDownloadUrl: manifest.downloadUrl
        })

        // Tự động tải ngầm và chuẩn bị sẵn nếu bật autoDownload
        if (options.autoDownload && manifest.downloadUrl) {
          updateState.uiDownloadUrl = manifest.downloadUrl
          updateState.newUiVersion = manifest.version
          downloadAndApplyUiUpdate().catch((err) => {
            console.warn('[Auto OTA Download Error]:', err.message)
          })
        }

        return { available: true, manifest }
      }
    }

    // 2. Nếu không có bản mới
    broadcastStatus({
      status: 'up-to-date',
      message: 'Giao diện đã ở phiên bản mới nhất.'
    })
    return { available: false }
  } catch (error) {
    console.error('[Updater OTA Error]:', error.message)
    broadcastStatus({
      status: 'error',
      message: `Lỗi kiểm tra giao diện: ${error.message}`
    })
    return { available: false, error: error.message }
  }
}

export async function downloadAndApplyUiUpdate() {
  const { uiDownloadUrl, newUiVersion } = updateState
  if (!uiDownloadUrl || !newUiVersion) {
    throw new Error('Không tìm thấy link tải bản cập nhật giao diện!')
  }

  try {
    broadcastStatus({
      status: 'downloading',
      message: `Đang tải gói giao diện mới v${newUiVersion}...`,
      progress: 0
    })

    const tempDir = join(USER_DATA_DIR, 'temp')
    if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true })

    const isEncrypted =
      uiDownloadUrl.endsWith('.gshub') ||
      uiDownloadUrl.includes('.gshub') ||
      uiDownloadUrl.endsWith('.syscore') ||
      uiDownloadUrl.includes('.syscore')
    const downloadExt = isEncrypted
      ? uiDownloadUrl.includes('.gshub')
        ? 'gshub'
        : 'syscore'
      : 'zip'
    const downloadedFilePath = join(tempDir, `download-ui-${newUiVersion}.${downloadExt}`)
    const readyZipPath = join(tempDir, `extracted-ui-${newUiVersion}.zip`)
    const targetExtractDir = join(UI_BUNDLES_DIR, `v${newUiVersion}`)

    // Tải file gói giao diện
    await downloadFile(uiDownloadUrl, downloadedFilePath, (progress) => {
      broadcastStatus({ progress, message: `Đang tải giao diện: ${progress}%` })
    })

    // Nếu là file mã hóa AES-256 (.gshub / .syscore), giải mã trước khi giải nén
    if (isEncrypted) {
      broadcastStatus({ message: 'Đang giải mã gói giao diện (AES-256)...' })
      const encryptedBuf = fs.readFileSync(downloadedFilePath)
      const decryptedZipBuf = decryptOtaBuffer(encryptedBuf)
      fs.writeFileSync(readyZipPath, decryptedZipBuf)
    } else {
      fs.copyFileSync(downloadedFilePath, readyZipPath)
    }

    // Giải nén zip
    broadcastStatus({ message: 'Đang giải nén và cấu hình giao diện mới...' })
    await extractZip(readyZipPath, targetExtractDir)

    // Xóa các file tạm để giải phóng dung lượng và bảo mật
    try {
      if (fs.existsSync(downloadedFilePath)) fs.unlinkSync(downloadedFilePath)
      if (fs.existsSync(readyZipPath)) fs.unlinkSync(readyZipPath)
    } catch {}

    // Lưu phiên bản đang active
    const activeConfig = {
      uiVersion: newUiVersion,
      bundlePath: targetExtractDir,
      updatedAt: new Date().toISOString()
    }
    fs.writeFileSync(ACTIVE_UI_CONFIG_PATH, JSON.stringify(activeConfig, null, 2), 'utf8')

    broadcastStatus({
      status: 'ui-ready',
      message: `Giao diện v${newUiVersion} đã sẵn sàng! Bấm để áp dụng ngay.`,
      uiVersion: newUiVersion,
      newUiVersion: null
    })

    return { success: true, version: newUiVersion }
  } catch (err) {
    console.error('[OTA Apply Error]:', err)
    broadcastStatus({
      status: 'error',
      message: `Lỗi cập nhật giao diện: ${err.message}`
    })
    throw err
  }
}

// Nạp lại toàn bộ cửa sổ với bundle mới vừa tải (Chỉ mất 0.5s - 1s!)
export function reloadAllWindowsWithNewUi() {
  BrowserWindow.getAllWindows().forEach((win) => {
    if (!win.isDestroyed()) {
      const currentUrl = win.webContents.getURL()
      let hash = ''
      try {
        const u = new URL(currentUrl)
        hash = u.hash || ''
      } catch {}

      const targetUrl = getRendererUrl(hash || '#/erp/u/login')
      win.loadURL(targetUrl)
    }
  })
}

// ==========================================
// 3. LOẠI 2: FULL NATIVE UPDATE (ELECTRON-BUILDER & GITHUB RELEASES)
// ==========================================

let autoUpdaterInstance = null

export async function initNativeAutoUpdater() {
  if (is.dev) return // Không chạy electron-updater ở môi trường dev

  try {
    const { autoUpdater } = await import('electron-updater')
    autoUpdaterInstance = autoUpdater
    autoUpdaterInstance.autoDownload = false // Cho phép người dùng xác nhận tải hoặc tải thủ công
    autoUpdaterInstance.autoInstallOnAppQuit = true

    autoUpdaterInstance.on('checking-for-update', () => {
      broadcastStatus({ status: 'checking', message: 'Đang kiểm tra bản cập nhật phần mềm...' })
    })

    autoUpdaterInstance.on('update-available', (info) => {
      broadcastStatus({
        status: 'native-available',
        message: `Đã có bản cập nhật phần mềm mới v${info.version}!`,
        newNativeVersion: info.version,
        releaseNotes: info.releaseNotes || 'Cập nhật hệ thống & tối ưu hiệu năng.'
      })
    })

    autoUpdaterInstance.on('update-not-available', () => {
      broadcastStatus({
        status: 'up-to-date',
        message: 'Phần mềm đang ở phiên bản mới nhất.'
      })
    })

    autoUpdaterInstance.on('download-progress', (progressObj) => {
      const percent = Math.round(progressObj.percent)
      broadcastStatus({
        status: 'downloading',
        progress: percent,
        message: `Đang tải bản cập nhật phần mềm: ${percent}%`
      })
    })

    autoUpdaterInstance.on('update-downloaded', (info) => {
      broadcastStatus({
        status: 'native-ready',
        message: `Bản cài đặt v${info.version} đã sẵn sàng. Khởi động lại để cập nhật.`,
        newNativeVersion: info.version
      })
    })

    autoUpdaterInstance.on('error', (err) => {
      if (
        updateState.downloadedInstallerPath &&
        fs.existsSync(updateState.downloadedInstallerPath)
      ) {
        return
      }
      const msg = err?.message || ''
      if (msg.includes('No published versions') || msg.includes('404')) {
        console.log('[Native Updater] Chưa có bản release công khai trên GitHub:', msg)
        broadcastStatus({
          status: 'up-to-date',
          message: 'Phần mềm đang ở phiên bản mới nhất.'
        })
        return
      }
      broadcastStatus({
        status: 'error',
        message: `Lỗi cập nhật phần mềm: ${msg}`
      })
    })
  } catch (e) {
    console.warn('[Native Updater]: electron-updater chưa sẵn sàng:', e.message)
  }
}

export async function checkNativeUpdate() {
  const currentNative = app.getVersion()
  try {
    broadcastStatus({ status: 'checking', message: 'Đang kiểm tra bản cập nhật phần mềm...' })

    // 1. Kiểm tra trực tiếp qua GitHub Releases API (Hoạt động cả trong dev lẫn production)
    const releases = await fetchJson(GITHUB_CONFIG.releasesApiUrl).catch(() => [])

    if (Array.isArray(releases) && releases.length > 0) {
      // Lọc các bản release ứng dụng (không phải release tag UI hot update "ui-*")
      const nativeReleases = releases.filter((r) => !r.tag_name?.startsWith('ui-') && !r.draft)
      if (nativeReleases.length > 0) {
        const latest = nativeReleases[0]
        const remoteVersion = latest.tag_name?.replace(/^v/, '')

        if (isNewerVersion(remoteVersion, currentNative)) {
          const exeAsset = latest.assets?.find(
            (a) =>
              a.name.endsWith('.exe') || a.name.endsWith('.dmg') || a.name.endsWith('.AppImage')
          )
          const downloadUrl = exeAsset ? exeAsset.browser_download_url : latest.html_url

          broadcastStatus({
            status: 'native-available',
            message: `Phát hiện bản phần mềm mới v${remoteVersion}!`,
            newNativeVersion: remoteVersion,
            releaseNotes: latest.body || 'Bản cập nhật phần mềm mới từ hệ thống.',
            nativeDownloadUrl: downloadUrl
          })
          return { available: true, version: remoteVersion, downloadUrl, releaseNotes: latest.body }
        }
      }
    }

    // 2. Nếu có electron-updater instance và app đã đóng gói
    if (!is.dev && autoUpdaterInstance) {
      try {
        await autoUpdaterInstance.checkForUpdates()
      } catch (e) {
        if (!e?.message?.includes('No published versions')) {
          console.warn('[electron-updater check error]:', e.message)
        }
      }
    }

    if (updateState.status === 'checking') {
      broadcastStatus({
        status: 'up-to-date',
        message: 'Phần mềm đang ở phiên bản mới nhất.'
      })
    }

    return { available: false }
  } catch (e) {
    console.error('[checkNativeUpdate error]:', e)
    broadcastStatus({ status: 'error', message: `Lỗi kiểm tra phần mềm: ${e.message}` })
    return { available: false, error: e.message }
  }
}

export async function downloadNativeUpdate() {
  const { nativeDownloadUrl, newNativeVersion } = updateState

  // Tải nền trực tiếp file installer trong app (Background In-App Download)
  if (nativeDownloadUrl) {
    try {
      broadcastStatus({
        status: 'downloading',
        progress: 0,
        message: `Đang tải bản cài đặt v${newNativeVersion || ''}...`
      })

      const tempDir = join(USER_DATA_DIR, 'temp')
      if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true })

      const ext = nativeDownloadUrl.endsWith('.dmg')
        ? 'dmg'
        : nativeDownloadUrl.endsWith('.AppImage')
          ? 'AppImage'
          : 'exe'
      const installerPath = join(tempDir, `gshub-update-${newNativeVersion || 'latest'}.${ext}`)

      await downloadFile(nativeDownloadUrl, installerPath, (progress) => {
        broadcastStatus({
          status: 'downloading',
          progress,
          message: `Đang tải bản cập nhật: ${progress}%`
        })
      })

      updateState.downloadedInstallerPath = installerPath

      broadcastStatus({
        status: 'native-ready',
        message: `Bản cài đặt v${newNativeVersion || ''} đã tải xong. Bấm để khởi động lại & cài đặt.`,
        progress: 100
      })

      return true
    } catch (err) {
      console.error('[Download Native Update Error]:', err)
      broadcastStatus({
        status: 'error',
        message: `Lỗi tải bản cập nhật phần mềm: ${err.message}`
      })
      throw err
    }
  }

  if (autoUpdaterInstance && !is.dev) {
    broadcastStatus({
      status: 'downloading',
      progress: 0,
      message: 'Bắt đầu tải bản cập nhật phần mềm...'
    })
    try {
      await autoUpdaterInstance.downloadUpdate()
      return true
    } catch (e) {
      console.warn('[electron-updater download fallback]:', e.message)
    }
  }
}

export function restartAndInstallNativeUpdate() {
  broadcastStatus({
    status: 'installing',
    message: 'Đang tiến hành cài đặt bản cập nhật và khởi động lại...'
  })

  // 1. Ưu tiên chạy file installer đã tải về ngầm
  if (updateState.downloadedInstallerPath && fs.existsSync(updateState.downloadedInstallerPath)) {
    try {
      if (process.platform === 'win32') {
        // Chạy installer trên Windows ở chế độ Silent (/S) và thoát ứng dụng
        const child = spawn(updateState.downloadedInstallerPath, ['/S', '--updated'], {
          detached: true,
          stdio: 'ignore'
        })
        child.unref()
        setTimeout(() => {
          app.quit()
        }, 500)
        return
      } else {
        // macOS / Linux
        shell.openPath(updateState.downloadedInstallerPath)
        setTimeout(() => app.quit(), 1000)
        return
      }
    } catch (err) {
      console.error('[Restart and Install Error]:', err)
      shell.openPath(updateState.downloadedInstallerPath)
      return
    }
  }

  // 2. Nếu qua electron-updater
  if (autoUpdaterInstance && !is.dev) {
    try {
      autoUpdaterInstance.quitAndInstall()
      return
    } catch (e) {
      console.warn('[quitAndInstall fallback]:', e.message)
    }
  }
}

// Tự động kiểm tra và tải cập nhật ngầm khi khởi động ứng dụng
export function startAutoUpdateWatcher() {
