import { createContext, useContext, useState } from 'react'

const RealtimeContext = createContext(null)

export function RealtimeProvider({ children }) {
  const [statusInfo] = useState({
    status: 'DISCONNECTED',
    message: 'Realtime WebSocket / gRPC đã tắt'
  })
  const [events] = useState([])
  const [latestEvent] = useState(null)
  const [currentUser] = useState(null)

  const value = {
    status: statusInfo.status,
    statusMessage: statusInfo.message,
    isConnected: false,
    events,
    latestEvent,
    currentUser,
    connect: () => {},
    disconnect: () => {},
    publish: () => Promise.resolve({ success: true })
  }

  return <RealtimeContext.Provider value={value}>{children}</RealtimeContext.Provider>
}

export function useRealtimeContext() {
  const context = useContext(RealtimeContext)
  if (!context) {
    return {
      status: 'DISCONNECTED',
      statusMessage: 'Realtime đã tắt',
      isConnected: false,
      events: [],
      latestEvent: null,
      currentUser: null,
      connect: () => {},
      disconnect: () => {},
      publish: () => Promise.resolve({ success: true })
    }
  }
  return context
}

export default RealtimeContext

/**
 * Realtime API - Disabled (WebSocket and gRPC removed)
 */
class RealtimeServiceBridge {
  constructor() {
    this.statusListeners = new Set()
    this.dataListeners = new Set()
    this.currentStatus = {
      status: 'DISCONNECTED',
      message: 'Realtime WebSocket & gRPC đã được tắt'
    }
  }

  connect() {
    // Disabled
  }

  disconnect() {
    // Disabled
  }

  notifyStatus(statusObj) {
    this.currentStatus = statusObj
    this.statusListeners.forEach((cb) => {
      try {
        cb(statusObj)
      } catch (_) {}
    })
  }

  notifyData(data) {
    this.dataListeners.forEach((cb) => {
      try {
        cb(data)
      } catch (_) {}
    })
  }

  publish() {
    return Promise.resolve({ success: true })
  }

  onStatus(cb) {
    if (typeof cb !== 'function') return () => {}
    this.statusListeners.add(cb)
    cb(this.currentStatus)
    return () => {
      this.statusListeners.delete(cb)
    }
  }

  onData(cb) {
    if (typeof cb !== 'function') return () => {}
    this.dataListeners.add(cb)
    return () => {
      this.dataListeners.delete(cb)
    }
  }
}

export const realtimeApi = new RealtimeServiceBridge()
export default realtimeApi

