    finalResult = result.userIds.map((uid, idx) => ({
      GroupId: Number(result.groupId || result.GroupId || 0),
      UserId: String(uid),
      Type: 'user',
      IdxNo: idx + 1
    }))
  }
  return apiPost('/role/UserRoleA', { result: finalResult }, options)
}

