export default function ExportExcelModal({
  isOpen = false,
  onClose,
  title,
  reportName = 'Báo cáo thống kê sản xuất',
  totalRows = 0,
  loadedCount = 0,
  selectedCount = 0,
  columns = [],
  activeFilters = {},
  defaultFileName = '',
  onConfirmExport
}) {
  const { t } = useTranslation()
  const modalRef = useRef(null)

  // File name without extension
  const [baseFileName, setBaseFileName] = useState('')
  const [saveDirectory, setSaveDirectory] = useState('')

  // Tùy chọn kết xuất: 'selected' | 'loaded' | 'all'
  const [exportScope, setExportScope] = useState('all')

  const [isExporting, setIsExporting] = useState(false)
  const [errorMsg, setErrorMsg] = useState('')

  // Kiểm tra môi trường Electron Desktop
  const isElectron = Boolean(window?.electron?.selectDirectory)

  // Load initial settings
  useEffect(() => {
    if (!isOpen) return

    const sanitizedBase = (
      defaultFileName ||
      `BCTKSX_${reportName.replace(/[\s/\\:*?"<>|]+/g, '_')}_${new Date().toISOString().slice(0, 10).replace(/-/g, '')}`
    ).replace(/\.[a-zA-Z0-9]+$/, '')

    setBaseFileName(sanitizedBase)
    setExportScope('all')
    setIsExporting(false)
    setErrorMsg('')

    // Load saved directory from localStorage or Electron default download folder
    const savedDir = localStorage.getItem(STORAGE_KEY_LAST_DIR)
    if (savedDir && savedDir.trim()) {
      setSaveDirectory(savedDir.trim())
    } else if (window?.electron?.getDefaultDownloadPath) {
      window.electron
        .getDefaultDownloadPath()
        .then((p) => {
          if (p && typeof p === 'string') {
            setSaveDirectory(p.trim())
            localStorage.setItem(STORAGE_KEY_LAST_DIR, p.trim())
          }
        })
        .catch(() => {})
    }
  }, [isOpen, defaultFileName, reportName, totalRows, selectedCount])

  // Cột xuất
  const exportableCols = useMemo(() => {
    return (columns || []).filter(
      (c) =>
        c.id !== 'WorkingTag' &&
        c.id !== 'isEdited' &&
        c.id !== 'Id' &&
        c.id !== 'IdRow' &&
        c.id !== 'IdSeq' &&
        c.id !== 'RowVersion' &&
        c.visible !== false
    )
  }, [columns])

  // Format breadcrumb path: D: » GoldSun » DATA_GS » 2809 » GS51B (Desktop) hoặc Downloads (Web)
  const formattedBreadcrumb = useMemo(() => {
    if (!isElectron) return 'Trình duyệt Web » Tải về mặc định (Downloads)'
    if (!saveDirectory) return 'C: » Downloads'
    return saveDirectory.replace(/\\/g, '/').split('/').filter(Boolean).join(' » ')
  }, [saveDirectory, isElectron])

  // Số lượng dòng sẽ xuất thực tế theo lựa chọn
  const targetRowCount = useMemo(() => {
    if (exportScope === 'all') return totalRows || loadedCount
    if (exportScope === 'selected') return selectedCount || 1
    return loadedCount
  }, [exportScope, totalRows, loadedCount, selectedCount])

  // Browse directory: Chỉ hoạt động trên Electron Desktop
  const handleBrowseDirectory = async () => {
    if (!isElectron) return
    try {
      if (window?.electron?.selectDirectory) {
        const selected = await window.electron.selectDirectory(saveDirectory)
        if (selected && typeof selected === 'string' && selected.trim()) {
          setSaveDirectory(selected.trim())
          localStorage.setItem(STORAGE_KEY_LAST_DIR, selected.trim())
        }
      }
    } catch (err) {
      if (err?.name !== 'AbortError') {
        console.error('Lỗi khi duyệt thư mục:', err)
      }
    }
  }

  // Handle Execute Export
  const handleExecute = async () => {
    if (!baseFileName.trim()) {
      setErrorMsg(t('Vui lòng nhập tên file kết xuất!'))
      return
    }

    setIsExporting(true)
    setErrorMsg('')
    try {
      const cleanBaseName = baseFileName.trim().replace(/\.xlsx$/i, '')
      const fullFileName = `${cleanBaseName}.xlsx`
      if (saveDirectory) {
        localStorage.setItem(STORAGE_KEY_LAST_DIR, saveDirectory.trim())
      }

      await onConfirmExport?.({
        scope: exportScope,
        fileName: fullFileName,
        saveDirectory: isElectron ? saveDirectory.trim() : '',
        includeHeaders: true,
        exportableCols,
        targetRowCount,
        selectedFormat: 'xlsx'
      })

      onClose?.()
    } catch (err) {
      console.error('Lỗi khi kết xuất file:', err)
      setErrorMsg(err?.message || t('Lỗi không xác định khi kết xuất file'))
    } finally {
      setIsExporting(false)
    }
  }

  // Hotkeys
  useEffect(() => {
    if (!isOpen) return
    const handleKeyDown = (e) => {
      if (e.key === 'Escape' && !isExporting) {
        e.preventDefault()
        onClose?.()
      } else if (e.key === 'Enter' && !isExporting && e.target.tagName !== 'BUTTON') {
        e.preventDefault()
        handleExecute()
      }
    }
    window.addEventListener('keydown', handleKeyDown, true)
    return () => window.removeEventListener('keydown', handleKeyDown, true)
  }, [isOpen, isExporting, baseFileName, saveDirectory, exportScope, targetRowCount])

  if (!isOpen) return null

  const modalContent = (
    <div className="fixed inset-0 z-[99999] flex items-center justify-center bg-black/45 backdrop-blur-[1px] p-4 select-none animate-in fade-in duration-100 font-sans">
      {/* Modal Dialog Chuẩn phong cách phần mềm Desktop ERP - Gọn gàng chuyên biệt xuất Excel */}
      <div
        ref={modalRef}
        className="w-full max-w-[580px] bg-white rounded-[2px] border border-[#7ba4c9] shadow-2xl overflow-hidden flex flex-col text-slate-800"
        onClick={(e) => e.stopPropagation()}
      >
        {/* 1. Header Cửa sổ: Chỉ để chữ tiêu đề và nút ✕ đóng */}
        <div className="flex items-center justify-between px-3.5 py-2 bg-[#f5f8fa] border-b border-[#d0dbe5] select-none">
          <span className="text-[13px] font-medium text-slate-800">
            {t('Kết xuất')} / {reportName || title || t('Báo cáo thống kê sản xuất')}
          </span>

          <button
            type="button"
            onClick={onClose}
            disabled={isExporting}
            className="p-1 hover:bg-rose-500 hover:text-white rounded text-slate-600 transition-colors cursor-pointer"
            title="Đóng (Esc)"
          >
            <X size={15} />
          </button>
        </div>

        {/* 2. Thân Modal - Bố cục trực diện chuyên biệt cho xuất Excel */}
        <div className="p-4 space-y-4 bg-white">
          {/* PHẦN 1: ĐƯỜNG DẪN KẾT XUẤT */}
          <div className="space-y-1">
            <div className="flex items-center justify-between">
              <h4 className="text-[13px] font-semibold text-[#0088cc] uppercase tracking-wide">
                {t('ĐƯỜNG DẪN KẾT XUẤT')}
              </h4>
            </div>

            {/* Dòng đường dẫn breadcrumb: D: » GoldSun » DATA_GS » ... */}
            <div
              onClick={isElectron ? handleBrowseDirectory : undefined}
              className={`text-[12px] text-slate-600 truncate font-sans py-0.5 ${
                isElectron
                  ? 'cursor-pointer hover:text-[#0088cc] transition-colors'
                  : 'cursor-default'
              }`}
              title={
                isElectron
                  ? t('Nhấp để đổi thư mục lưu')
                  : t('Trên Web, file sẽ tự động tải về thư mục Downloads')
              }
            >
              {formattedBreadcrumb}
            </div>

            {/* Ô nhập tên file lớn viền xanh, nút ... */}
            <div className="flex items-center border border-[#0088cc] rounded-[2px] bg-white overflow-hidden shadow-2xs">
              <input
                type="text"
                value={baseFileName}
                onChange={(e) => setBaseFileName(e.target.value)}
                disabled={isExporting}
                className="flex-1 px-3 py-1.5 text-[15px] font-normal text-[#005580] outline-none bg-transparent"
                placeholder="BCTKSX_GS51B_28"
              />
              {isElectron && (
                <button
                  type="button"
                  onClick={handleBrowseDirectory}
                  disabled={isExporting}
                  className="px-3.5 py-1.5 border-l border-[#0088cc] text-slate-600 hover:bg-[#f0f8ff] hover:text-[#0088cc] font-bold text-sm transition-colors shrink-0 cursor-pointer"
                  title={t('Duyệt thư mục lưu file...')}
                >
                  ...
                </button>
              )}
            </div>
          </div>

          {/* PHẦN 2: TÙY CHỌN KẾT XUẤT & PHẠM VI DỮ LIỆU */}
          <div className="space-y-3 pt-1">
            <div className="space-y-2">
              <div className="flex items-center justify-between pb-0.5 border-b border-[#f0f4f8]">
                <h4 className="text-[13px] font-semibold text-[#0088cc] uppercase tracking-wide">
                  {t('TÙY CHỌN KẾT XUẤT')}
                </h4>
                <span className="text-[11.5px] text-slate-500">
                  {exportableCols.length} {t('cột dữ liệu')}
                </span>
              </div>

              {/* Danh sách 3 switch tùy chọn phạm vi */}
              <div className="space-y-2 pt-1">
                <ErpSwitch
                  checked={exportScope === 'selected'}
                  onChange={(val) => setExportScope(val ? 'selected' : 'all')}
                  label={t('Kết xuất các dòng đã chọn')}
                  hint={
                    selectedCount > 0
                      ? `(${selectedCount.toLocaleString('vi-VN')} dòng được chọn)`
                      : ''
                  }
                  disabled={selectedCount === 0}
                />

                <ErpSwitch
                  checked={exportScope === 'loaded'}
                  onChange={(val) => setExportScope(val ? 'loaded' : 'all')}
                  label={t('Kết xuất dữ liệu đang xem')}
                  hint={`(${loadedCount.toLocaleString('vi-VN')} dòng đang hiển thị trên bảng)`}
                />

                <ErpSwitch
                  checked={exportScope === 'all'}
                  onChange={(val) => setExportScope(val ? 'all' : 'loaded')}
                  label={t('Kết xuất toàn bộ dữ liệu báo cáo')}
                  hint={`(${(totalRows || loadedCount).toLocaleString('vi-VN')} dòng theo điều kiện tìm kiếm)`}
                />
              </div>
            </div>
          </div>

          {/* Thông báo lỗi nếu có */}
          {errorMsg && (
            <div className="flex items-center gap-2 p-2 bg-rose-50 border border-rose-200 text-rose-700 text-xs rounded-[2px]">
              <AlertCircle size={14} className="shrink-0" />
              <span>{errorMsg}</span>
            </div>
          )}
        </div>

        {/* 3. Thanh nút bấm dưới đáy: Nằm ở BÊN PHẢI [ ▶ Bắt đầu thực hiện ] [ Thoát ra ] */}
        <div className="flex items-center justify-end px-3.5 py-2.5 bg-[#f4f7fa] border-t border-[#d0dbe5] select-none gap-2">
          {/* Nút Bắt đầu thực hiện: viền xanh #0088cc, icon ▶ tam giác xanh lá */}
          <button
            type="button"
            onClick={handleExecute}
            disabled={isExporting}
            className="flex items-center gap-1.5 px-3.5 py-1 bg-white hover:bg-[#e8f4fc] active:bg-[#d8ecf8] text-slate-800 border border-[#0088cc] rounded-[2px] text-xs font-normal transition-colors disabled:opacity-50 cursor-pointer shadow-2xs"
          >
            {isExporting ? (
              <>
                <Loader2 size={12} className="animate-spin text-[#0088cc]" />
                <span>{t('Đang thực hiện...')}</span>
              </>
            ) : (
              <>
                <span className="text-[#107c41] font-black text-[11px]">▶</span>
                <span className="font-medium text-slate-800">{t('Bắt đầu thực hiện')}</span>
              </>
            )}
          </button>

          {/* Nút Thoát ra: nền trắng, viền xám nhẹ */}
          <button
            type="button"
            onClick={onClose}
            disabled={isExporting}
            className="px-3.5 py-1 bg-white hover:bg-slate-100 text-slate-700 border border-[#c0d0e0] rounded-[2px] text-xs font-normal transition-colors disabled:opacity-50 cursor-pointer shadow-2xs"
          >
            {t('Thoát ra')}
          </button>
        </div>
      </div>
    </div>
  )

  return typeof document !== 'undefined' ? createPortal(modalContent, document.body) : null
}

import { useState, useMemo, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { Filter, RotateCcw } from 'lucide-react'
import GenericCodeHelpModal from './GenericCodeHelpModal'
import QueryFieldItem, { checkHasValue } from './QueryFieldItem'
import QuerySettingsDrawer from './QuerySettingsDrawer'
import { useDateFormat } from '../../../hooks/useDateFormat'

// Mapping class số cột tĩnh để Tailwind CSS compile chính xác 100% (Khống chế tối đa 4 cột / 1 hàng)
const GRID_COL_MAP = {
  1: 'grid-cols-1',
  2: 'grid-cols-1 sm:grid-cols-2',
  3: 'grid-cols-1 sm:grid-cols-2 md:grid-cols-3',
  4: 'grid-cols-1 sm:grid-cols-2 md:grid-cols-4'
}

/**
 * DynamicQueryBar - Thanh tìm kiếm động ERP chuẩn giao diện hệ thống
 * Đã được module hóa sạch đẹp, hỗ trợ đa ngôn ngữ và định dạng thời gian tự động.
 * Khống chế tối đa 4 cột điều kiện / so sánh trên 1 hàng.
 */
export default function DynamicQueryBar({
  fields = [],
  allAvailableFields = [],
  values = {},
  onChange,
  onSearch,
  onCodeHelp,
  disabled = false,
  columns = 4,
  className = '',
  showSettings = true,
  onToggleField,
  onResetFields
}) {
  const { t } = useTranslation()
  const { settings, parseDate } = useDateFormat()
  const [activeModalField, setActiveModalField] = useState(null)
  const [isSettingsOpen, setIsSettingsOpen] = useState(false)
  const lastSearchTimeRef = useRef(0)

  // Khống chế số cột tối đa trên 1 hàng là 4
  const effectiveColumns = Math.min(Math.max(1, Number(columns) || 4), 4)

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && onSearch) {
      const now = Date.now()
      // Chống kẹt phím liên hồi (< 300ms)
      if (now - lastSearchTimeRef.current < 300) {
        e.preventDefault()
        return
      }

      lastSearchTimeRef.current = now
      onSearch()
    }
  }

  // Lọc chỉ lấy các trường visible !== false
  const visibleFields = useMemo(() => {
    return fields.filter((f) => f && f.key && f.visible !== false)
  }, [fields])

  // Đếm số lượng trường đang có giá trị lọc kích hoạt
  const activeFiltersCount = useMemo(() => {
    let count = 0
    visibleFields.forEach((field) => {
      if (checkHasValue(values[field.key], field.type)) {
        count++
      }
    })
    return count
  }, [visibleFields, values])

  // Xóa toàn bộ giá trị đang lọc trên tất cả các ô
  const handleClearAllValues = () => {
    visibleFields.forEach((field) => {
      if (checkHasValue(values[field.key], field.type)) {
        if (field.type === 'date-range' || field.type === 'month-range') {
          onChange && onChange(field.key, ['', ''])
        } else {
          onChange && onChange(field.key, '')
        }
      }
    })
    if (onResetFields) {
      onResetFields()
    }
  }

  // Tính toán tổng số span để bù ô trống cân đối viền table
  const totalSpans = useMemo(() => {
    return visibleFields.reduce((acc, f) => acc + Math.min(f?.colSpan || 1, effectiveColumns), 0)
  }, [visibleFields, effectiveColumns])

  const emptySlots = useMemo(() => {
    const remainder = totalSpans % effectiveColumns
    return remainder === 0 ? 0 : effectiveColumns - remainder
  }, [totalSpans, effectiveColumns])

  const gridColsClass =
    GRID_COL_MAP[effectiveColumns] || 'grid-cols-1 sm:grid-cols-2 md:grid-cols-4'

  // Danh sách trường cho Drawer cài đặt (loại bỏ cột hệ thống Status, IndexNo, IdSeq, StatusAcc, userStatus)
  const settingsFieldsList = useMemo(() => {
    const map = new Map()
    const forbiddenKeys = new Set(['status', 'indexno', 'idseq', 'statusacc', 'userstatus'])
    // 1. Thêm allAvailableFields trước
    ;(allAvailableFields || []).forEach((f) => {
      if (f && f.key && !forbiddenKeys.has(f.key.toLowerCase())) map.set(f.key, f)
    })
    // 2. Thêm fields hiện tại nếu chưa có
    ;(fields || []).forEach((f) => {
      if (f && f.key && !forbiddenKeys.has(f.key.toLowerCase()) && !map.has(f.key)) {
        map.set(f.key, f)
      }
    })
    return Array.from(map.values())
  }, [allAvailableFields, fields])

  const currentVisibleKeys = useMemo(() => {
    return new Set(visibleFields.map((f) => f.key))
  }, [visibleFields])

  return (
    <div className={`w-full bg-white select-none relative ${className}`}>
      <style>{`
        .query-date-has-value .ant-picker-input > input {
          color: #1d4ed8 !important;
          font-weight: 600 !important;
        }
        .query-date-empty .ant-picker-input > input {
          color: #334155 !important;
        }
        .erp-query-segmented {
          height: 22px !important;
          line-height: 20px !important;
        }
        .erp-query-segmented .ant-segmented-item {
          min-height: 20px !important;
          line-height: 20px !important;
        }
      `}</style>

      <div
        className={`grid ${gridColsClass} w-full border-t border-l border-slate-200 bg-slate-50/20`}
      >
        {visibleFields.map((field) => (
          <QueryFieldItem
            key={field.key}
            field={field}
            value={values[field.key]}
            onChange={onChange}
            onKeyDown={handleKeyDown}
            onCodeHelp={onCodeHelp}
            onSetActiveModalField={setActiveModalField}
            parseDate={parseDate}
            settings={settings}
            disabled={disabled}
          />
        ))}
        {Array.from({ length: emptySlots }).map((_, idx) => (
          <div
            key={`empty-slot-${idx}`}
            className="hidden md:block col-span-1 h-[28px] border-b border-r border-slate-200 bg-slate-50/30"
          />
        ))}
      </div>

      <div className="absolute -top-[23px] right-2 z-10 flex items-center gap-1.5">
        {/* Nút Mở cài đặt bộ lọc */}
        {showSettings && (
          <button
            type="button"
            onClick={() => setIsSettingsOpen(true)}
            className="flex items-center gap-1 text-[10px] text-slate-600 hover:text-indigo-600 transition-colors cursor-pointer select-none font-medium px-1.5 py-0.5 rounded hover:bg-slate-100"
            title={t('Cài đặt điều kiện')}
          >
            <Filter className="w-3 h-3 text-indigo-600" />
            <span>{t('Bộ lọc')}</span>
          </button>
        )}
      </div>

      {/* Drawer Cài đặt điều kiện tìm kiếm */}
      <QuerySettingsDrawer
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        fieldsList={settingsFieldsList}
        visibleKeys={currentVisibleKeys}
        onToggleField={onToggleField}
        onResetFields={onResetFields}
      />

      {/* Modal CodeHelp tự động mở ra khi ô CodeHelp kích hoạt */}
      {activeModalField && (
        <GenericCodeHelpModal
          isOpen={!!activeModalField}
          onClose={() => setActiveModalField(null)}
          title={activeModalField.helpTitle || activeModalField.label || 'Tra cứu danh mục'}
          helpData={activeModalField.helpData || []}
          fetchHelpData={activeModalField.fetchHelpData}
          columns={activeModalField.helpCols || activeModalField.columns || []}
          initialSearchText={values[activeModalField.key] || ''}
          onSelect={(selectedItem) => {
            const colList = activeModalField.helpCols || activeModalField.columns || []
            const codeKey = activeModalField.codeKey || colList?.[0]?.id || 'Code' || 'IdSeq'
            const nameKey = activeModalField.nameKey || colList?.[1]?.id || 'Name'
            const selectedCode =
              selectedItem[codeKey] ||
              selectedItem.Code ||
              selectedItem.IdSeq ||
              selectedItem.UserId ||
              ''
            const selectedName =
              selectedItem[nameKey] || selectedItem.Name || selectedItem.UserName || ''

            onChange && onChange(activeModalField.key, selectedCode)
            if (activeModalField.nameFieldKey) {
              onChange && onChange(activeModalField.nameFieldKey, selectedName)
            }
            if (activeModalField.onSelect) {
              activeModalField.onSelect(selectedItem)
            } else if (activeModalField.onSelectHelp) {
              activeModalField.onSelectHelp(selectedItem)
            }
          }}
        />
      )}
    </div>
  )
}

import { memo } from 'react'
import QueryTextInput from './fields/QueryTextInput'
import QueryCodeHelpInput from './fields/QueryCodeHelpInput'
import QuerySelectInput from './fields/QuerySelectInput'
import QueryDateInput from './fields/QueryDateInput'
import QueryDateRangeInput from './fields/QueryDateRangeInput'
import QueryMonthInput from './fields/QueryMonthInput'
import QueryMonthRangeInput from './fields/QueryMonthRangeInput'
import QueryCheckboxInput from './fields/QueryCheckboxInput'

/**
 * QueryFieldRenderer - Điều phối và render đúng loại Input theo field.type
 */
const QueryFieldRenderer = memo(function QueryFieldRenderer({
  field,
  value,
  onChange,
  onKeyDown,
  onTriggerCodeHelp,
  parseDate,
  settings,
  disabled = false,
  hasValue = false,
  valueTextColor = ''
}) {
  const type = field.type || 'text'

  // 1. Text & Multi-code inputs
  if (type === 'text' || type === 'input' || type === 'multi-code' || type === 'multi-input') {
    return (
      <QueryTextInput
        field={field}
        value={value}
        onChange={onChange}
        onKeyDown={onKeyDown}
        disabled={disabled}
        valueTextColor={valueTextColor}
      />
    )
  }

  // 2. CodeHelp
  if (type === 'codehelp') {
    return (
      <QueryCodeHelpInput
        field={field}
        value={value}
        onChange={onChange}
        onKeyDown={onKeyDown}
        onTriggerCodeHelp={onTriggerCodeHelp}
        disabled={disabled}
        valueTextColor={valueTextColor}
      />
    )
  }

  // 3. Select & Segmented Dropdown
  if (type === 'select' || type === 'segmented') {
    return (
      <QuerySelectInput
        field={field}
        value={value}
        onChange={onChange}
        onKeyDown={onKeyDown}
        disabled={disabled}
        valueTextColor={valueTextColor}
      />
    )
  }

  // 4. Date (Ngày đơn)
  if (type === 'date') {
    return (
      <QueryDateInput
        field={field}
        value={value}
        onChange={onChange}
        parseDate={parseDate}
        settings={settings}
        disabled={disabled}
        hasValue={hasValue}
      />
    )
  }

  // 5. Date Range (Khoảng ngày)
  if (type === 'date-range') {
    return (
      <QueryDateRangeInput
        field={field}
        value={value}
        onChange={onChange}
        parseDate={parseDate}
        settings={settings}
        disabled={disabled}
        hasValue={hasValue}
      />
    )
  }

  // 6. Month (Tháng đơn)
  if (type === 'month') {
    return (
      <QueryMonthInput
        field={field}
        value={value}
        onChange={onChange}
        parseDate={parseDate}
        settings={settings}
        disabled={disabled}
        hasValue={hasValue}
      />
    )
  }

  // 7. Month Range (Khoảng tháng)
  if (type === 'month-range') {
    return (
      <QueryMonthRangeInput
        field={field}
        value={value}
        onChange={onChange}
        parseDate={parseDate}
        settings={settings}
        disabled={disabled}
        hasValue={hasValue}
      />
    )
  }

  // 8. Checkbox
  if (type === 'checkbox') {
    return (
      <QueryCheckboxInput
        field={field}
        value={value}
        onChange={onChange}
        disabled={disabled}
        hasValue={hasValue}
      />
    )
  }

  // 9. Custom render
  if (type === 'custom' && field.render) {
    return field.render({
      value,
      hasValue,
      valueTextColor,
      onChange: (newVal) => onChange && onChange(field.key, newVal),
      disabled,
      handleKeyDown: onKeyDown
    })
  }

  return null
})

export default QueryFieldRenderer

import { memo } from 'react'
import { Drawer, Checkbox, Button } from 'antd'
import { Filter, RotateCcw } from 'lucide-react'
import { useTranslation } from 'react-i18next'

/**
 * QuerySettingsDrawer - Drawer cài đặt ẩn/hiện điều kiện tìm kiếm và nút Đặt lại mặc định
 */
const QuerySettingsDrawer = memo(function QuerySettingsDrawer({
  isOpen,
  onClose,
  fieldsList = [],
  visibleKeys = new Set(),
  onToggleField,
  onResetFields
}) {
  const { t } = useTranslation()

  return (
    <Drawer
      title={
        <div className="flex items-center justify-between w-full text-xs font-bold uppercase text-slate-700">
