              autoFocus={true}
              onChange={handleOnChange}
              placeholder="Nhập từ khóa để tìm kiếm..."
              onKeyDown={(e) => {
                if (e.key === 'Enter' && filteredData.length > 0) {
                  handleRowClick(filteredData[0])
                }
                if (e.key === 'Escape') {
