    if (isUiReady) {
      return (
        <div
          onClick={(e) => {
            e.stopPropagation()
            handleApplyUi()
          }}
          className="flex items-center gap-1.5 px-2.5 h-full border-l border-gray-200 hover:bg-slate-50 transition-colors cursor-pointer text-slate-700 select-none normal-case font-semibold"
