    }

    const lines = notes.split('\n')
    return (
      <div className="space-y-1 text-[11px]">
        {lines.map((line, idx) => {
          const trimmed = line.trim()
          if (!trimmed) return null
          const isHeading = trimmed.startsWith('#')
          const isBullet =
            trimmed.startsWith('-') || trimmed.startsWith('*') || trimmed.startsWith('•')

          if (isHeading) {
