import { useState, useCallback, useEffect, useRef } from 'react'
import { CompactSelection } from '@glideapps/glide-data-grid'
import { loadFromLocalStorageSheet } from '../../localStorage/sheet/sheet'
import { onRowAppended } from '../components/sheet/js/onRowAppended'
import { generateEmptyData } from '../components/sheet/js/generateEmptyData'
import { updateIndexNo } from '../components/sheet/js/updateIndexNo'
import { usePageData } from '../../context/PageDataContext'
import { ensureStatusFirstColumn, SYSTEM_INTERNAL_HIDDEN_COLUMNS } from '../../utils/systemColumns'

/**
 * Hàm tính toán chỉ số thống kê (Sum, Count, Average, Min, Max, Cột, Dòng) theo chuẩn Excel khi bôi đen / chọn vùng
 */
export function calculateSelectionStats(selection, gridData, cols) {
  if (
    !selection ||
    !Array.isArray(gridData) ||
    gridData.length === 0 ||
    !Array.isArray(cols) ||
    cols.length === 0
  ) {
    return null
  }

  let count = 0
  let numericCount = 0
  let sum = 0
  let min = Infinity
  let max = -Infinity
  let totalProcessed = 0
  const MAX_STATS_CELLS = 5000

  const rowsSet = new Set()
  const colsSet = new Set()

  const processCell = (r, c) => {
    if (totalProcessed >= MAX_STATS_CELLS) return
    const rowData = gridData[r]
    const column = cols[c]
    if (!rowData || !column) return

    totalProcessed++
    const colKey = column.id || column.key || ''
    if (!colKey) return

    const val = rowData[colKey] ?? rowData[colKey.charAt(0).toLowerCase() + colKey.slice(1)]
    if (val !== undefined && val !== null && val !== '') {
      count++
      const cleanVal = typeof val === 'string' ? val.replace(/,/g, '').trim() : val
      const num = typeof cleanVal === 'number' ? cleanVal : Number(cleanVal)
      if (!isNaN(num) && typeof val !== 'boolean' && cleanVal !== '') {
        numericCount++
        sum += num
        if (num < min) min = num
        if (num > max) max = num
      }
    }
  }

  // 1. Vùng ô bôi đen qua chuột (Cell range hoặc Single cell)
  if (selection.current) {
    const { cell, range, rangeStack } = selection.current
    const ranges = [range, ...(rangeStack || [])].filter(Boolean)

    if (ranges.length > 0) {
      for (let i = 0; i < ranges.length; i++) {
        const r = ranges[i]
        const endX = Math.min(cols.length, r.x + r.width)
        const endY = Math.min(gridData.length, r.y + r.height)
        for (let y = r.y; y < endY; y++) {
          rowsSet.add(y)
          for (let x = r.x; x < endX; x++) {
            colsSet.add(x)
            processCell(y, x)
            if (totalProcessed >= MAX_STATS_CELLS) break
          }
          if (totalProcessed >= MAX_STATS_CELLS) break
        }
        if (totalProcessed >= MAX_STATS_CELLS) break
      }
    } else if (cell) {
      const [colIdx, rowIdx] = cell
      if (colIdx >= 0 && colIdx < cols.length && rowIdx >= 0 && rowIdx < gridData.length) {
        rowsSet.add(rowIdx)
        colsSet.add(colIdx)
        processCell(rowIdx, colIdx)
      }
    }
  }

  // 2. Dòng được chọn (Row selection)
  if (selection.rows && selection.rows.length > 0) {
    if (selection.rows.items && selection.rows.items.length > 0) {
      for (let i = 0; i < selection.rows.items.length; i++) {
        const [startRow, endRow] = selection.rows.items[i]
        const actualEndRow = Math.min(gridData.length, endRow)
        for (let y = startRow; y < actualEndRow; y++) {
          rowsSet.add(y)
          for (let x = 0; x < cols.length; x++) {
            colsSet.add(x)
            processCell(y, x)
            if (totalProcessed >= MAX_STATS_CELLS) break
          }
          if (totalProcessed >= MAX_STATS_CELLS) break
        }
        if (totalProcessed >= MAX_STATS_CELLS) break
      }
    } else if (typeof selection.rows.toArray === 'function') {
      const rowArr = selection.rows.toArray()
      for (const y of rowArr) {
        if (y < gridData.length) {
          rowsSet.add(y)
          for (let x = 0; x < cols.length; x++) {
            colsSet.add(x)
            processCell(y, x)
            if (totalProcessed >= MAX_STATS_CELLS) break
          }
        }
        if (totalProcessed >= MAX_STATS_CELLS) break
      }
    }
  }

  // 3. Cột được chọn (Column selection)
  if (selection.columns && selection.columns.length > 0) {
    if (selection.columns.items && selection.columns.items.length > 0) {
      for (let i = 0; i < selection.columns.items.length; i++) {
        const [startCol, endCol] = selection.columns.items[i]
        const actualEndCol = Math.min(cols.length, endCol)
        for (let x = startCol; x < actualEndCol; x++) {
          colsSet.add(x)
          for (let y = 0; y < gridData.length; y++) {
            rowsSet.add(y)
            processCell(y, x)
            if (totalProcessed >= MAX_STATS_CELLS) break
          }
          if (totalProcessed >= MAX_STATS_CELLS) break
        }
        if (totalProcessed >= MAX_STATS_CELLS) break
      }
    } else if (typeof selection.columns.toArray === 'function') {
      const colArr = selection.columns.toArray()
      for (const x of colArr) {
        if (x < cols.length) {
          colsSet.add(x)
          for (let y = 0; y < gridData.length; y++) {
            rowsSet.add(y)
            processCell(y, x)
            if (totalProcessed >= MAX_STATS_CELLS) break
          }
        }
        if (totalProcessed >= MAX_STATS_CELLS) break
      }
    }
  }

  const totalCells = rowsSet.size * colsSet.size
  if (count === 0 && totalCells === 0) return null

  return {
    count: count > 0 ? count : totalCells,
    totalCells,
    numericCount,
    selectedColsCount: colsSet.size,
    selectedRowsCount: rowsSet.size,
    hasNumericStats: numericCount > 0,
    sum: numericCount > 0 ? sum : 0,
    average: numericCount > 0 ? sum / numericCount : 0,
    min: numericCount > 0 && min !== Infinity ? min : 0,
    max: numericCount > 0 && max !== -Infinity ? max : 0
  }
}

/**
 * Hook quản lý State và hành vi chuẩn của Glide Data Grid cho các trang ERP
 * @param {string} storageKey - Khóa lưu localStorage cho columns (vd: 'S_ERP_COLS_PAGE_USERS_MANAGE')
 * @param {Array} defaultCols - Danh sách cột mặc định từ hook cols
 * @param {boolean} canCreate - Quyền thêm dòng mới
 * @param {number} initialRowCount - Số dòng trống khởi tạo ban đầu (mặc định 100)
 */
export function useDataGridSheet({
  storageKey,
  defaultCols = [],
  canCreate = true,
  canView = true,
  initialRowCount = 100
}) {
  const { registerDirtyChecker, setSelectionStats, setPageData, setStatusMessage } =
    usePageData() || {}
  const [gridData, setGridData] = useState([])
  const [selection, setSelection] = useState({
    columns: CompactSelection.empty(),
    rows: CompactSelection.empty()
  })
  const [showSearch, setShowSearch] = useState(false)
  const [addedRows, setAddedRows] = useState([])
  const [editedRows, setEditedRows] = useState([])
  const [numRows, setNumRows] = useState(0)

  // Khởi tạo cột từ LocalStorage hoặc cấu hình default
  const [cols, setCols] = useState(() => {
    const rawCols = storageKey
      ? loadFromLocalStorageSheet(
          storageKey,
          defaultCols.filter((col) => col.visible)
        )
      : defaultCols.filter((col) => col.visible)
    return ensureStatusFirstColumn(rawCols, defaultCols)
  })

  const prevColsSignatureRef = useRef('')

  // Cập nhật lại cols nếu defaultCols thực sự thay đổi nội dung (tránh re-render loop gây lag máy)
  useEffect(() => {
    if (storageKey && Array.isArray(defaultCols)) {
      const signature = defaultCols
        .map(
          (col) => `${col.id}:${col.visible !== false}:${col.readonly || false}:${col.title || ''}`
        )
        .join('|')

      if (prevColsSignatureRef.current === signature) {
        return
      }
      prevColsSignatureRef.current = signature

      const rawCols = loadFromLocalStorageSheet(
        storageKey,
        defaultCols.filter((col) => col.visible)
      )
      setCols(ensureStatusFirstColumn(rawCols, defaultCols))
    }
  }, [storageKey, defaultCols])

  // Cập nhật tổng số cột vào PageDataContext khi số lượng cột thay đổi thực sự
  useEffect(() => {
    if (setPageData && cols) {
      setPageData((prev) => {
        if (!prev || prev.totalColumns === cols.length) return prev
        return { ...prev, totalColumns: cols.length }
      })
    }
  }, [cols?.length, setPageData])

  const isInitializedRef = useRef(false)

  // Khởi tạo dòng trống lúc load ban đầu (chỉ tạo 1 lần duy nhất lúc mount nếu có quyền Xem canView)
  useEffect(() => {
    if (!isInitializedRef.current && canView && defaultCols && defaultCols.length > 0) {
      isInitializedRef.current = true
      const emptyData = generateEmptyData(initialRowCount, defaultCols)
      const updatedData = updateIndexNo(emptyData)
      setGridData(updatedData)
      setNumRows(updatedData.length)
    } else if (!canView) {
      setGridData([])
      setNumRows(0)
    }
  }, [canView, defaultCols, initialRowCount])

  const gridDataRef = useRef(gridData)
  gridDataRef.current = gridData

  useEffect(() => {
    if (!registerDirtyChecker) return

    return registerDirtyChecker(() => {
      const data = gridDataRef.current
      if (!Array.isArray(data) || data.length === 0) return false

      const systemKeys = new Set([
        'Id',
        'IdRow',
        'IdSeq',
        'CreatedBy',
        'CreatedAt',
        'CreatedByName',
        'CreatedDate',
        'UpdatedBy',
        'UpdatedAt',
        'UpdatedByName',
        'UpdatedDate',
        'isEdited',
        'WorkingTag',
        'Status',
        'IdxNo',
        'Idx'
      ])

      return data.some((row) => {
        if (!row) return false
        const tag = row.WorkingTag || row.Status
        if (tag === 'U' || tag === 'E' || tag === 'D') return true
        if (tag === 'A') {
          const keys = Object.keys(row)
          return keys.some((k) => {
            if (systemKeys.has(k)) return false
            const val = row[k]
            return val !== '' && val !== null && val !== undefined
          })
        }
        return false
      })
    })
  }, [registerDirtyChecker])

  // Tự động tính toán số liệu thống kê kiểu Excel khi bôi đen (Debounced requestAnimationFrame chống giật lag)
  const statsRafRef = useRef(null)
  useEffect(() => {
    if (!setSelectionStats) return

    if (statsRafRef.current) {
      cancelAnimationFrame(statsRafRef.current)
    }

    statsRafRef.current = requestAnimationFrame(() => {
      const stats = calculateSelectionStats(selection, gridData, cols)
      setSelectionStats(stats)
    })

    return () => {
      if (statsRafRef.current) {
        cancelAnimationFrame(statsRafRef.current)
      }
    }
  }, [selection, gridData, cols, setSelectionStats])

  // Đồng bộ số lượng trạng thái dòng (A, U, D, E) xuống StatusBar (A chỉ tính dòng hợp lệ có dữ liệu)
  const statusCountsRafRef = useRef(null)
  useEffect(() => {
    if (!setPageData) return

    if (statusCountsRafRef.current) {
      cancelAnimationFrame(statusCountsRafRef.current)
    }

    statusCountsRafRef.current = requestAnimationFrame(() => {
      let aCount = 0
      let uCount = 0
      let dCount = 0
      let eCount = 0

      if (Array.isArray(gridData) && gridData.length > 0) {
        for (let i = 0; i < gridData.length; i++) {
          const row = gridData[i]
          if (!row) continue
          const tag = row.WorkingTag || row.Status
          if (tag === 'E' || Boolean(row.ErrorMessage || row.Error)) {
            eCount++
          }
          if (tag === 'U') {
            uCount++
          } else if (tag === 'D') {
            dCount++
          } else if (tag === 'A') {
            // Chỉ đếm dòng 'A' có dữ liệu thực sự hợp lệ (không tính dòng mẫu/AA/trắng)
            const businessKeys = Object.keys(row).filter(
              (k) =>
                ![
                  'Id',
                  'IdRow',
                  'IdSeq',
                  'CreatedBy',
                  'CreatedAt',
                  'UpdatedBy',
                  'UpdatedAt',
                  'isEdited',
                  'WorkingTag',
                  'Status',
                  'IdxNo',
                  'Idx'
                ].includes(k)
            )
            const hasData = businessKeys.some((k) => {
              const val = row[k]
              return val !== '' && val !== null && val !== undefined
            })
            if (hasData) {
              aCount++
            }
          }
        }
      }

      setPageData((prev) => {
        const prevCounts = prev?.rowStatusCounts
        if (
          prevCounts &&
          prevCounts.aCount === aCount &&
          prevCounts.uCount === uCount &&
          prevCounts.dCount === dCount &&
          prevCounts.eCount === eCount
        ) {
          return prev
        }
        return {
          ...prev,
          rowStatusCounts: { aCount, uCount, dCount, eCount }
        }
      })
    })

    return () => {
      if (statusCountsRafRef.current) {
        cancelAnimationFrame(statusCountsRafRef.current)
      }
    }
  }, [gridData, setPageData])

  // Đồng bộ thông tin Audit Log của dòng đang chọn xuống StatusBar (Chỉ kích hoạt khi đổi dòng thực tế)
  const lastAuditedRowRef = useRef(null)
  useEffect(() => {
    if (!setPageData) return
    let selectedRowIdx = null
    const selectedRows = selection?.rows?.items
    if (selectedRows && selectedRows.length > 0) {
      selectedRowIdx = selectedRows[0][0]
    } else if (selection?.current?.cell) {
      selectedRowIdx = selection.current.cell[1]
    }

    if (selectedRowIdx === null || selectedRowIdx === undefined) return
    const selectedRowData = gridData[selectedRowIdx]
    if (!selectedRowData) return

    const auditKey = `${selectedRowIdx}_${selectedRowData.CreatedAt}_${selectedRowData.UpdatedAt}_${selectedRowData.CreatedByName || selectedRowData.CreatedBy}_${selectedRowData.UpdatedByName || selectedRowData.UpdatedBy}`
    if (lastAuditedRowRef.current === auditKey) return
    lastAuditedRowRef.current = auditKey

    if (
      selectedRowData.CreatedAt ||
      selectedRowData.UpdatedAt ||
      selectedRowData.CreatedByName ||
      selectedRowData.UpdatedByName ||
      selectedRowData.CreatedBy ||
      selectedRowData.UpdatedBy
    ) {
      const formatTime = (val) => {
        if (!val) return ''
        try {
          const d = new Date(val)
          if (isNaN(d.getTime())) return String(val)
          return d.toLocaleString('vi-VN', {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
          })
        } catch {
          return String(val)
        }
      }

      setPageData((prev) => ({
        ...prev,
        createdAt: formatTime(selectedRowData.CreatedAt),
        createdBy: selectedRowData.CreatedByName || selectedRowData.CreatedBy || '',
        updatedAt: formatTime(selectedRowData.UpdatedAt),
        updatedBy: selectedRowData.UpdatedByName || selectedRowData.UpdatedBy || ''
      }))
    }
  }, [selection, gridData, setPageData])

  // Dọn dẹp thống kê khi unmount
  useEffect(() => {
    return () => {
      setSelectionStats && setSelectionStats(null)
    }
  }, [setSelectionStats])

  // Reset bảng và đưa con trỏ chuột về ô đầu tiên [0, 0] của dòng đầu tiên
  const resetTable = useCallback(() => {
    setSelection({
      current: { cell: [0, 0], range: { x: 0, y: 0, width: 1, height: 1 }, rangeStack: [] },
      columns: CompactSelection.empty(),
      rows: CompactSelection.empty()
    })
    setAddedRows([])
    setEditedRows([])
    if (setSelectionStats) {
      setSelectionStats(null)
    }
  }, [setSelectionStats])

  // Lấy các dòng đang được chọn từ selection.rows
  const getSelectedRows = useCallback(() => {
    const selectedRows = selection.rows.items
    let rows = []
    selectedRows.forEach((range) => {
      const start = range[0]
      const end = range[1] - 1
      for (let i = start; i <= end; i++) {
        if (gridData[i]) {
          rows.push(gridData[i])
        }
      }
    })
    return rows
  }, [selection, gridData])

  // Thêm dòng mới vào bảng (Kiểm soát chặt chẽ theo phân quyền canCreate)
  const handleRowAppend = useCallback(
    (numRowsToAdd) => {
      if (!canCreate) {
        if (setStatusMessage) {
          setStatusMessage({
            type: 'warning',
            text: 'Bạn không có quyền thêm dữ liệu trên trang này!'
          })
        }
        return
      }
      onRowAppended(cols, setGridData, setNumRows, setAddedRows, numRowsToAdd)
    },
    [canCreate, cols, setStatusMessage]
  )

  // Gom các props thường xuyên truyền cho Table component
  const tableProps = {
    cols,
    setCols,
    gridData,
    setGridData,
    numRows,
    setNumRows,
    selection,
    setSelection,
    showSearch,
    setShowSearch,
    handleRowAppend: canCreate ? handleRowAppend : null,
    canCreate,
    addedRows,
    setAddedRows,
    editedRows,
    setEditedRows,
    defaultCols,
    resetTable
  }

  return {
    gridData,
    setGridData,
    selection,
    setSelection,
    showSearch,
    setShowSearch,
    addedRows,
    editedRows,
    numRows,
    setNumRows,
    cols,
    setCols,
    resetTable,
    getSelectedRows,
    handleRowAppend,
    tableProps
  }
}

import { useCallback, useRef } from 'react'
import { togglePageInteraction } from '../../utils/togglePageInteraction'
import { HandleError } from '../page/default/handleError'
import { updateIndexNo } from '../components/sheet/js/updateIndexNo'
import { generateEmptyData } from '../components/sheet/js/generateEmptyData'

export const useFetchGenericData = (loadingBarRef, controllers, setStatusMessage) => {
  const defaultControllersRef = useRef({})
  const activeControllers = controllers || defaultControllersRef
  const activeFetchCountRef = useRef(0)

  const increaseFetchCount = useCallback(() => {
    activeFetchCountRef.current += 1
    if (activeFetchCountRef.current === 1) {
      loadingBarRef?.current?.continuousStart?.()
    }
  }, [loadingBarRef])

  const decreaseFetchCount = useCallback(() => {
    activeFetchCountRef.current = Math.max(0, activeFetchCountRef.current - 1)
    if (activeFetchCountRef.current === 0) {
      loadingBarRef?.current?.complete?.()
    }
  }, [loadingBarRef])

  const fetchGenericData = useCallback(
    async ({
      controllerKey,
      postFunction,
      searchParams,
      useEmptyData = true,
      defaultCols,
      setStatusMessage: callerSetStatusMessage,
      afterFetch = () => {}
    }) => {
      if (activeControllers.current?.[controllerKey]) {
        activeControllers.current[controllerKey].abort()
        await new Promise((resolve) => setTimeout(resolve, 10))
      }

      increaseFetchCount()

      const controller = new AbortController()
      if (activeControllers.current) {
        activeControllers.current[controllerKey] = controller
      }
      const { signal } = controller

      loadingBarRef.current?.continuousStart()

      try {
        const response = await postFunction(searchParams, signal)

        // Bỏ qua nếu request bị hủy / abort bởi thao tác tìm kiếm mới
        if (response?.isCanceled || response?.message === 'canceled') {
          return
        }

        const effectiveSetStatus = callerSetStatusMessage || setStatusMessage
        if (!response.success) {
          const errMsg = response.message || 'Đã xảy ra lỗi vui lòng thử lại!'
          if (typeof effectiveSetStatus === 'function') {
            effectiveSetStatus({
              type: 'error',
              text: errMsg
            })
          } else {
            HandleError([
              {
                success: false,
                message: errMsg
              }
            ])
          }
        }
        const rawData = response.success ? response.data : []
        const data = Array.isArray(rawData)
          ? rawData
          : rawData && typeof rawData === 'object'
            ? [rawData]
            : []

        let mergedData = updateIndexNo(data)

        if (useEmptyData) {
          const emptyData = updateIndexNo(generateEmptyData(100, defaultCols))
          mergedData = updateIndexNo([...data, ...emptyData])
        }

        await afterFetch(mergedData, response)
      } catch (error) {
        const isCanceled =
          error?.name === 'CanceledError' ||
          error?.code === 'ERR_CANCELED' ||
          error?.message === 'canceled'

        if (isCanceled) {
          return
        }

        let emptyData = []

        if (useEmptyData) {
          emptyData = updateIndexNo(generateEmptyData(100, defaultCols))
        }

        await afterFetch(emptyData, null)
      } finally {
        decreaseFetchCount()
        if (activeControllers.current && activeControllers.current[controllerKey] === controller) {
          activeControllers.current[controllerKey] = null
        }
      }
    },
    [increaseFetchCount, decreaseFetchCount, activeControllers, loadingBarRef]
  )

  const fetchNextPage = useCallback(
    async ({
      postFunction,
      searchParams,
      pageInfo,
      setPageInfo,
      setGridData,
      setNumRows,
      setStatusMessage,
      t = (s) => s
    }) => {
      if (!pageInfo || !pageInfo.hasMore || pageInfo.isLoading) return false

      setPageInfo((prev) => ({ ...prev, isLoading: true }))
      const nextPage = (pageInfo.page || 1) + 1
      const params = {
        ...searchParams,
        Page: nextPage,
        Cursor: pageInfo.nextCursor || '',
        LastId: pageInfo.nextCursor || '',
        Limit: pageInfo.pageSize || 1500
      }

      if (typeof setStatusMessage === 'function') {
        setStatusMessage({
          type: 'info',
          text: t(`Đang tải thêm dữ liệu (Trang {{page}})...`, { page: nextPage })
        })
      }

      try {
        const response = await postFunction(params)
        if (!response || !response.success) {
          setPageInfo((prev) => ({ ...prev, isLoading: false }))
          return false
        }

        const newItems = Array.isArray(response.data)
          ? response.data
          : response.data
            ? [response.data]
            : []
        if (newItems.length === 0) {
          setPageInfo((prev) => ({ ...prev, hasMore: false, isLoading: false }))
          return false
        }

        setGridData((prev) => {
          const realItems = prev.filter(
            (item) => item && (item.Id || item.Key || item.Label || item.Status)
          )
          const nextCombined = updateIndexNo([...realItems, ...newItems])
          if (typeof setNumRows === 'function') {
            setNumRows(nextCombined.length)
          }
          return nextCombined
        })

        const resPage = response.page || {}
        const total = resPage.total !== undefined ? resPage.total : pageInfo.total
        const totalAll = resPage.totalAll !== undefined ? resPage.totalAll : pageInfo.totalAll
        const loadedCount = (pageInfo.loadedCount || 0) + newItems.length
        const hasMore = resPage.hasMore !== undefined ? resPage.hasMore : loadedCount < total
        const nextCursor = resPage.nextCursor || String(newItems[newItems.length - 1]?.Id || '')

        setPageInfo((prev) => ({
          ...prev,
          page: nextPage,
          loadedCount,
          total,
          totalAll,
          hasMore,
          nextCursor,
          isLoading: false
        }))

        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'success',
            text:
              total !== totalAll && totalAll > 0
                ? t(`Đã tải {{loaded}} / {{totalAll}} Root Menu`, { loaded: loadedCount, totalAll })
                : t(`Đã tải {{loaded}} / {{total}} Root Menu`, { loaded: loadedCount, total })
          })
        }

        return true
      } catch (err) {
        console.error('Lỗi khi tải trang tiếp theo:', err)
        setPageInfo((prev) => ({ ...prev, isLoading: false }))
        return false
      }
    },
    []
  )

  return { fetchGenericData, fetchNextPage }
}

import { useCallback } from 'react'
import { togglePageInteraction } from '../../utils/togglePageInteraction'
import { HandleError } from '../page/default/handleError'
import { updateIndexNo } from '../components/sheet/js/updateIndexNo'
import { filterValidRows } from '../../utils/filterUorA'

export const useSaveGenericData = (loadingBarRef) => {
  const handleSave = useCallback(
    async ({
      canCreate,
      gridData,
      setGridData,
      addFunction,
      updateFunction,
      userFrom,
      setStatusMessage,
      maxRowsPerSave = 3000,
      loadingText = 'Đang lưu dữ liệu...',
      successText = 'Lưu dữ liệu thành công!',
      matchKey = 'IdxNo',
      mapReturnedFields = (found) => ({ WorkingTag: '', Status: '', [matchKey]: found[matchKey] }),
      prepareAddRows = (rows) =>
        rows.map((item) => ({
          ...item,
          CreatedBy: userFrom?.UserSeq,
          UpdatedBy: userFrom?.UserSeq
        })),
      prepareUpdateRows = (rows) => rows.map((item) => ({ ...item, UpdatedBy: userFrom?.UserSeq }))
    }) => {
      if (!canCreate) return true

      // ── BƯỚC 1: QUÉT NHANH 1 PASS O(N) LỌC DÒNG CẦN LƯU VÀ CẮT TỐI ĐA 1500 DÒNG ──
      const isRowEmpty = (row) => {
        for (const k in row) {
          if (
            k === 'WorkingTag' ||
            k === 'Status' ||
            k === 'IdxNo' ||
            k === 'IndexNo' ||
            k === 'Id' ||
            k === 'IdRow' ||
            k === 'CreatedBy' ||
            k === 'CreatedByName' ||
            k === 'CreatedAt' ||
            k === 'UpdatedBy' ||
            k === 'UpdatedByName' ||
            k === 'UpdatedAt' ||
            k === 'RowVersion' ||
            k === 'Utilities' ||
            k === 'Active' ||
            k === 'isEdited' ||
            k === 'IsDefaultAllow' ||
            k === 'IsActive'
          ) {
            continue
          }
          const val = row[k]
          if (typeof val === 'boolean') {
            continue
          }
          if (val !== undefined && val !== null && String(val).trim() !== '') {
            return false
          }
        }
        return true
      }

      const rowsA = []
      const rowsU = []
      let totalPendingA = 0
      let totalPendingU = 0
      const len = gridData?.length || 0

      for (let i = 0; i < len; i++) {
        const row = gridData[i]
        if (!row) continue

        const status = row.WorkingTag || row.Status
        if (status === 'A') {
          // Bỏ qua các dòng trống mặc định chưa được người dùng nhập liệu
          if (!isRowEmpty(row)) {
            totalPendingA++
            if (rowsA.length + rowsU.length < maxRowsPerSave) {
              rowsA.push(row)
            }
          }
        } else if (status === 'U') {
          totalPendingU++
          if (rowsA.length + rowsU.length < maxRowsPerSave) {
            rowsU.push(row)
          }
        }
      }

      const totalPending = totalPendingA + totalPendingU
      const currentBatchCount = rowsA.length + rowsU.length
      const remainingAfterBatch = totalPending - currentBatchCount

      const resulA = prepareAddRows(rowsA)
      const resulU = prepareUpdateRows(rowsU)

      // Nếu không có bất kỳ dòng nào cần lưu -> Dừng ngay lập tức mà không phát bất kỳ thông báo "Đang lưu..." nào
      if (resulA.length === 0 && resulU.length === 0) {
        togglePageInteraction(false)
        loadingBarRef.current?.complete()
        return false
      }

      // CHỈ KHI CÓ DỮ LIỆU THỰC SỰ MỚI HIỂN THỊ "ĐANG LƯU..."
      const dynamicLoadingText =
        totalPending > maxRowsPerSave
          ? `Đang lưu đợt ${currentBatchCount.toLocaleString()} / ${totalPending.toLocaleString()} dòng...`
          : loadingText

      if (typeof setStatusMessage === 'function') {
        setStatusMessage({ type: 'info', text: dynamicLoadingText })
      }
      togglePageInteraction(true)
      loadingBarRef.current?.continuousStart()

      try {
        let resA = null
        let resU = null

        if (resulA.length > 0 && addFunction) {
          resA = await addFunction(resulA)
        }

        if ((!resA || resA.success) && resulU.length > 0 && updateFunction) {
          resU = await updateFunction(resulU)
        }

        const safeExtractArray = (res) => {
          if (!res || !res.success || !res.data) return []
          return Array.isArray(res.data) ? res.data : [res.data]
        }

        const dataA = safeExtractArray(resA)
        const dataU = safeExtractArray(resU)

        // ── BƯỚC 2: XÂY DỰNG HASH MAP O(1) ĐỂ KHỚP DỮ LIỆU TỨC THÌ ──
        const mapAByIdx = new Map()
        const mapAByKey = new Map()
        for (let i = 0; i < dataA.length; i++) {
          const item = dataA[i]
          if (!item) continue
          if (item.IdxNo !== undefined) mapAByIdx.set(String(item.IdxNo), item)
          if (item.Key) mapAByKey.set(String(item.Key), item)
          if (matchKey && item[matchKey] !== undefined) mapAByIdx.set(String(item[matchKey]), item)
        }

        const mapUById = new Map()
        for (let i = 0; i < dataU.length; i++) {
          const item = dataU[i]
          if (!item) continue
          if (item.Id !== undefined && item.Id !== null && item.Id !== '')
            mapUById.set(String(item.Id), item)
          if (item.IdSeq !== undefined && item.IdSeq !== null && item.IdSeq !== '')
            mapUById.set(String(item.IdSeq), item)
          if (item.UserSeq !== undefined && item.UserSeq !== null && item.UserSeq !== '')
            mapUById.set(String(item.UserSeq), item)
        }

        // Xử lý thông báo trạng thái dưới status bottom
        const errorMessages = []

        // Trích xuất danh sách dòng lỗi trực tiếp từ cấu trúc dữ liệu chuẩn Backend trả về (data / error / errors)
        const errorRowIndices = new Set()
        const errorRowIds = new Set()

        const collectStructuredErrors = (res, defaultFallback) => {
          if (!res || res.success) return
          let rawData = res.data
          if (typeof rawData === 'string' && rawData.trim()) {
            try {
              rawData = JSON.parse(rawData)
            } catch (e) {
              // Ignore JSON parse error
            }
          }
          const details = Array.isArray(rawData)
            ? rawData
            : Array.isArray(res.errors)
              ? res.errors
              : Array.isArray(res.error?.details)
                ? res.error.details
                : res.error && typeof res.error === 'object'
                  ? [res.error]
                  : []

          let hasItemMsg = false
          for (let i = 0; i < details.length; i++) {
            const errItem = details[i]
            if (!errItem || typeof errItem !== 'object') continue
            const msg = errItem.Message || errItem.message
            if (msg) {
              errorMessages.push(msg)
              hasItemMsg = true
            }
            if (errItem.IdxNo !== undefined && errItem.IdxNo !== null) {
              errorRowIndices.add(Number(errItem.IdxNo))
            }
            if (errItem.idxNo !== undefined && errItem.idxNo !== null) {
              errorRowIndices.add(Number(errItem.idxNo))
            }
            if (errItem.Id !== undefined && errItem.Id !== null && errItem.Id !== '') {
              errorRowIds.add(String(errItem.Id))
            }
            if (errItem.id !== undefined && errItem.id !== null && errItem.id !== '') {
              errorRowIds.add(String(errItem.id))
            }
          }

          if (!hasItemMsg) {
            errorMessages.push(res.message || defaultFallback)
          }
        }

        collectStructuredErrors(resA, 'Lỗi thêm mới dữ liệu')
        collectStructuredErrors(resU, 'Lỗi cập nhật dữ liệu')

        // ── BƯỚC 3: CẬP NHẬT GRIDDATA BẰNG 1 PASS TUYẾN TÍNH O(N) ──
        setGridData((prev) => {
          let hasChanges = false
          let aSeqIdx = 0
          const updated = new Array(prev.length)
          for (let i = 0; i < prev.length; i++) {
            const item = prev[i]
            if (!item) {
              updated[i] = item
              continue
            }

            const rowIdx = item.IdxNo !== undefined ? Number(item.IdxNo) : i + 1
            const itemIdStr =
              item.Id !== undefined && item.Id !== null && item.Id !== '' ? String(item.Id) : null

            // Nếu dòng này nằm trong danh sách lỗi/xung đột có cấu trúc từ Backend trả về -> Đổi Status của đúng dòng đó về 'E'
            if (errorRowIndices.has(rowIdx) || (itemIdStr && errorRowIds.has(itemIdStr))) {
              updated[i] = {
                ...item,
                WorkingTag: 'E',
                Status: 'E'
              }
              hasChanges = true
              continue
            }

            const itemStatus = item.WorkingTag || item.Status

            // Xử lý dòng thêm mới (Status / WorkingTag: 'A') - Chỉ reset khi API Add thành công
            if (itemStatus === 'A' && resA && resA.success) {
              let found =
                (item.Key ? mapAByKey.get(String(item.Key)) : null) ||
                (item.IdxNo !== undefined ? mapAByIdx.get(String(item.IdxNo)) : null) ||
                (matchKey && item[matchKey] !== undefined
                  ? mapAByIdx.get(String(item[matchKey]))
                  : null)

              if (!found && aSeqIdx < dataA.length) {
                found = dataA[aSeqIdx]
              }
              aSeqIdx++

              if (found) {
                updated[i] = {
                  ...item,
                  ...mapReturnedFields(found),
                  Id: found.Id !== undefined ? found.Id : item.Id,
                  WorkingTag: '',
                  Status: ''
                }
                hasChanges = true
                continue
              }
            }

            // Xử lý dòng chỉnh sửa (Status / WorkingTag: 'U') - Chỉ reset khi API Update thành công
            if (itemStatus === 'U' && resU && resU.success) {
              const key = item.Id ?? item.IdSeq ?? item.UserSeq
              const found =
                key !== undefined && key !== null && key !== '' ? mapUById.get(String(key)) : null

              if (found) {
                updated[i] = {
                  ...item,
                  ...mapReturnedFields(found),
                  WorkingTag: '',
                  Status: ''
                }
                hasChanges = true
                continue
              }
            }

            // Mọi trường hợp còn lại: Giữ nguyên item và Status
            updated[i] = item
          }
          return hasChanges ? updateIndexNo(updated) : prev
        })

        if (errorMessages.length > 0) {
          if (typeof setStatusMessage === 'function') {
            setStatusMessage({ type: 'error', text: errorMessages.join(' | ') })
          }
          return false
        } else {
          if (typeof setStatusMessage === 'function') {
            const finalSuccessText =
              remainingAfterBatch > 0
                ? `Đã lưu thành công ${currentBatchCount.toLocaleString()} dòng! (Còn lại ${remainingAfterBatch.toLocaleString()} dòng chưa lưu, vui lòng tiếp tục bấm Lưu)`
                : successText
            setStatusMessage({ type: 'success', text: finalSuccessText })
          }
          return true
        }
      } catch (error) {
        const errorMsg = error.message || 'Đã xảy ra lỗi khi lưu!'
        if (typeof setStatusMessage === 'function') {
          setStatusMessage({ type: 'error', text: errorMsg })
        }
        return false
      } finally {
        loadingBarRef.current?.complete()
        togglePageInteraction(false)
      }
    },
    [loadingBarRef]
  )

  return { handleSave }
}

