                  type="button"
                  onClick={() => handleReasonChange(r)}
                  className="text-[10.5px] px-1.5 py-0.5 rounded bg-slate-100 hover:bg-slate-200 text-slate-600 transition-colors"
                >
                  {r}
                </button>
              ))}
            </div>
          </div>

          {/* Lưu ý nghiệp vụ chuẩn ERP */}

          <div className="flex items-center gap-1.5 text-[11px] text-slate-500 italic">
            <ShieldAlert size={13} className="text-slate-400 shrink-0" />
            <span>
              {t('Sau khi hủy, phiếu sẽ không còn được dùng để làm báo cáo KHSX và TKSX.')}
            </span>
          </div>
        </div>

        {/* Footer */}
        <div className="px-4 py-2.5 bg-slate-50 border-t border-slate-200 flex items-center justify-end gap-2">
          <Button onClick={onClose} size="small" className="text-xs">
            {t('Quay lại')}
          </Button>
          <Button
            danger
            type="primary"
            onClick={handleExecute}
            size="small"
            className="text-xs font-bold bg-rose-600 hover:bg-rose-700"
          >
            {t('Xác nhận hủy phiếu')}
          </Button>
        </div>
      </div>
    </div>,
    document.body
  )
}

import { useState, useCallback, useEffect, useRef, useMemo } from 'react'
import dayjs from 'dayjs'
import * as XLSX from 'xlsx'
import { openChildWindow } from '@renderer/utils/openChildWindow'
import storageAdapter from '../storageAdapterProxy'
import {
  queryProductionBundlesOnline,
  downloadProductionBundleOnline,
  deleteProductionBundleOnline,
  cancelProductionBundleOnline
} from '@renderer/api/production/calcBundleApi'
import { unpackProductionBundle } from '../../calcProduction/engine/bundlePacker'
import { clearReportCache } from '../../../common/reportDataCache'

export function useCalcMasterQueryLogic({ setStatusMessage } = {}) {
  const [filters, setFilters] = useState({
    FactoryName: '',
    RegCode: '',
    ApplyDate: '',
    FromDate: dayjs().subtract(30, 'day').format('YYYY-MM-DD'),
    ToDate: dayjs().format('YYYY-MM-DD'),
    Status: '',
    Version: '',
    ProductionTeam: '',
    RegisteredBy: '',
    Remark: '',
    Keyword: ''
  })

  const [rawMasters, setRawMasters] = useState([])
  const [queriedRows, setQueriedRows] = useState([])
  const [isLoading, setIsLoading] = useState(false)
  const [isSyncing, setIsSyncing] = useState(false)
  const [selectedRegCode, setSelectedRegCode] = useState(null)

  const filtersRef = useRef(filters)
  filtersRef.current = filters

  const notify = useCallback(
    (type, text) => {
      if (typeof setStatusMessage === 'function') {
        setStatusMessage({ type, text })
      }
    },
    [setStatusMessage]
  )

  const handleFilterChange = useCallback((key, value) => {
    setFilters((prev) => ({
      ...prev,
      [key]: value
    }))
  }, [])

  // Lấy dữ liệu Master đồng thời từ Server DataHub Database và CSDL Local Cache
  const fetchMasterList = useCallback(
    async (customFilters = null) => {
      const currentFilters = customFilters || filtersRef.current
      setIsLoading(true)
      notify('info', 'Đang truy vấn CSDL Server DataHub & Local Cache...')
      try {
        // 1. Lấy từ Local Storage / SQLite
        let localList = []
        try {
          localList = (await storageAdapter.getAllMasterRegistrations()) || []
        } catch (e) {
          console.warn('Lỗi lấy local master registrations:', e)
        }

        // 2. Lấy trực tiếp từ Server DataHub DB qua gRPC Gateway
        let serverList = []
        try {
          const serverRes = await queryProductionBundlesOnline({
            from_date: currentFilters.FromDate || currentFilters.fromDate || '',
            to_date: currentFilters.ToDate || currentFilters.toDate || '',
            factory_name:
              (currentFilters.FactoryName || currentFilters.factory) === 'Tất cả'
                ? ''
                : currentFilters.FactoryName || currentFilters.factory || '',
            production_team:
              (currentFilters.ProductionTeam || currentFilters.team) === 'Tất cả'
                ? ''
                : currentFilters.ProductionTeam || currentFilters.team || '',
            reg_code: currentFilters.RegCode || currentFilters.regCode || '',
            status:
              (currentFilters.Status || currentFilters.status) === 'Tất cả'
                ? ''
                : currentFilters.Status || currentFilters.status || ''
          })

          const rawBundles = serverRes?.bundles || serverRes?.data || serverRes?.items || []
          if (Array.isArray(rawBundles)) {
            serverList = rawBundles.map((b) => {
              let fSummaries = {}
              try {
                if (typeof b.file_summaries === 'string' && b.file_summaries.startsWith('{')) {
                  fSummaries = JSON.parse(b.file_summaries)
                } else if (typeof b.fileSummaries === 'string' && b.fileSummaries.startsWith('{')) {
                  fSummaries = JSON.parse(b.fileSummaries)
                } else if (typeof b.file_summaries === 'object') {
                  fSummaries = b.file_summaries || {}
                } else if (typeof b.fileSummaries === 'object') {
                  fSummaries = b.fileSummaries || {}
                }
              } catch (_e) {
                // ignore json parse error
              }

              const statRows =
                b.stat_report_rows || b.statReportRows || fSummaries.stat_report?.rowCount || 0
              const unfinRows =
                b.unfinished_op_rows ||
                b.unfinishedOpRows ||
                fSummaries.unfinished_op?.rowCount ||
                0
              const sumRows =
                b.summary_op_rows || b.summaryOpRows || fSummaries.summary_op?.rowCount || 0
              const mesRows =
                b.mes_approval_rows || b.mesApprovalRows || fSummaries.mes_approval?.rowCount || 0

              const total = b.total_rows || b.totalRows || statRows + unfinRows + sumRows + mesRows

              const formatRegisteredAt = (val) => {
                if (!val) return ''
                const d = dayjs(val)
                return d.isValid() ? d.format('YYYY-MM-DD HH:mm:ss') : String(val)
              }

              const rawMb = Number(b.raw_size_mb || b.rawSizeMb || b.rawSizeMB || b.RawSizeMB || 0)
              const compMb = Number(
                b.compressed_size_mb ||
                  b.compressedSizeMb ||
                  b.compressedSizeMB ||
                  b.CompressedSizeMB ||
                  0
              )
              const ratio = b.compression_ratio || b.compressionRatio || b.CompressionRatio || ''

              return {
                regCode: b.reg_code || b.regCode,
                factoryName: b.factory_name || b.factoryName,
                applyDate: b.apply_date || b.applyDate,
                productionTeam: b.production_team || b.productionTeam,
                status: b.status || 'PUBLISHED',
                version: b.version || '1.0',
                totalRows: total,
                rawSizeMB: rawMb,
                compressedSizeMB: compMb,
                compressionRatio: ratio,
                statReportRows: statRows,
                unfinishedOpRows: unfinRows,
                summaryOpRows: sumRows,
                mesApprovalRows: mesRows,
                resultTksxRows:
                  b.result_tksx_rows || b.resultTksxRows || fSummaries.result_tksx?.rowCount || 0,
                resultKhsxRows:
                  b.result_khsx_rows || b.resultKhsxRows || fSummaries.result_khsx?.rowCount || 0,
                fileSummaries: fSummaries,
                registeredAt: formatRegisteredAt(
                  b.created_at || b.createdAt || b.registered_at || b.registeredAt
                ),
                registeredBy:
                  b.created_by || b.createdBy || b.registeredBy || b.registered_by || 'Admin',
                remark: b.remark || '',
                isServerRecord: true
              }
            })
          }
        } catch (serverErr) {
          console.warn('Không thể kết nối Server DataHub:', serverErr.message)
        }

        // 3. Hợp nhất danh sách (Server DB + Local DB)
        const mergedMap = new Map()

        const formatRegisteredAt = (val) => {
          if (!val) return ''
          const d = dayjs(val)
          return d.isValid() ? d.format('YYYY-MM-DD HH:mm:ss') : String(val)
        }

        const isUuidStr = (str) =>
          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(str || ''))

        const resolveUserDisplayName = (val, existingVal) => {
          if (existingVal && !isUuidStr(existingVal)) {
            return existingVal
          }
          if (val && !isUuidStr(val)) {
            return val
          }
          try {
            const curUser = JSON.parse(localStorage.getItem('userInfo') || '{}')
            const curSeq = curUser.UserSeq || curUser.UserId || ''
            if (curSeq && (curSeq === val || curSeq === existingVal)) {
              return curUser.UserName || curUser.EmpName || curUser.UserId || 'Admin'
            }
          } catch {}
          return existingVal && !isUuidStr(existingVal)
            ? existingVal
            : val && !isUuidStr(val)
              ? val
              : 'Admin'
        }

        const compareVersions = (v1, v2) => {
          if (!v1 && !v2) return 0
          if (!v1) return -1
          if (!v2) return 1
          const clean1 = String(v1)
            .replace(/^[^\d]*/, '')
            .trim()
          const clean2 = String(v2)
            .replace(/^[^\d]*/, '')
            .trim()
          const parts1 = clean1.split('.').map((p) => parseInt(p, 10) || 0)
          const parts2 = clean2.split('.').map((p) => parseInt(p, 10) || 0)
          for (let i = 0; i < Math.max(parts1.length, parts2.length); i++) {
            const num1 = parts1[i] || 0
            const num2 = parts2[i] || 0
            if (num1 > num2) return 1
            if (num1 < num2) return -1
          }
          return 0
        }

        const resolveLatestVersion = (v1, v2) => {
          return compareVersions(v1, v2) >= 0 ? v1 || '1.0' : v2 || '1.0'
        }

        // Đưa danh sách Server DB vào trước (giữ bản ghi có version cao nhất và đầy đủ số liệu nhất)
        serverList.forEach((s) => {
          if (!s.regCode) return
          const existing = mergedMap.get(s.regCode)
          if (!existing) {
            mergedMap.set(s.regCode, s)
          } else {
            // So sánh version để ưu tiên bản ghi có version cao hơn
            const isSNewer = compareVersions(s.version, existing.version) > 0
            const chosen = isSNewer ? s : existing
            const older = isSNewer ? existing : s
            const isPublished = s.status === 'PUBLISHED' || existing.status === 'PUBLISHED'

            mergedMap.set(s.regCode, {
              ...older,
              ...chosen,
              status: isPublished ? 'PUBLISHED' : chosen.status,
              version: chosen.version || '1.0',
              totalRows:
                chosen.totalRows && chosen.totalRows > 0 ? chosen.totalRows : older.totalRows,
              statReportRows:
                chosen.statReportRows && chosen.statReportRows > 0
                  ? chosen.statReportRows
                  : older.statReportRows,
              unfinishedOpRows:
                chosen.unfinishedOpRows && chosen.unfinishedOpRows > 0
                  ? chosen.unfinishedOpRows
                  : older.unfinishedOpRows,
              summaryOpRows:
                chosen.summaryOpRows && chosen.summaryOpRows > 0
                  ? chosen.summaryOpRows
                  : older.summaryOpRows,
              mesApprovalRows:
                chosen.mesApprovalRows && chosen.mesApprovalRows > 0
                  ? chosen.mesApprovalRows
                  : older.mesApprovalRows,
              resultTksxRows:
                chosen.resultTksxRows && chosen.resultTksxRows > 0
                  ? chosen.resultTksxRows
                  : older.resultTksxRows || 0,
              resultKhsxRows:
                chosen.resultKhsxRows && chosen.resultKhsxRows > 0
                  ? chosen.resultKhsxRows
                  : older.resultKhsxRows || 0,
              rawSizeMB: chosen.rawSizeMB || older.rawSizeMB || 0,
              compressedSizeMB: chosen.compressedSizeMB || older.compressedSizeMB || 0,
              compressionRatio: chosen.compressionRatio || older.compressionRatio || '',
              registeredAt: chosen.registeredAt || older.registeredAt,
              registeredBy: resolveUserDisplayName(chosen.registeredBy, older.registeredBy)
            })
          }
        })

        // Đưa danh sách Local DB vào (đồng bộ trạng thái nhưng TUYỆT ĐỐI không ghi đè số dòng = 0 lên dữ liệu server)
        localList.forEach((l) => {
          if (!l.regCode) return
          const existing = mergedMap.get(l.regCode)
          if (!existing) {
            mergedMap.set(l.regCode, {
              ...l,
              rawSizeMB: Number(l.rawSizeMB || l.raw_size_mb || l.rawSizeMb || 0),
              compressedSizeMB: Number(
                l.compressedSizeMB || l.compressed_size_mb || l.compressedSizeMb || 0
              ),
              compressionRatio: l.compressionRatio || l.compression_ratio || '',
              registeredAt: formatRegisteredAt(l.registeredAt || new Date()),
              resultTksxRows: l.resultTksxRows || l.fileSummaries?.result_tksx?.rowCount || 0,
              resultKhsxRows: l.resultKhsxRows || l.fileSummaries?.result_khsx?.rowCount || 0,
              registeredBy: resolveUserDisplayName(
                l.registeredBy || l.registered_by || l.createdBy
              ),
              isLocalCached: true
            })
          } else {
            const isLocalNewer = compareVersions(l.version, existing.version) > 0
            const isPublished = existing.status === 'PUBLISHED' || l.status === 'PUBLISHED'
            const hasLocalRows = Number(l.totalRows || 0) > 0

            mergedMap.set(l.regCode, {
              ...existing,
              version: isLocalNewer && hasLocalRows ? l.version : existing.version,
              status: isPublished ? 'PUBLISHED' : existing.status || l.status || 'DRAFT',
              totalRows:
                existing.totalRows && existing.totalRows > 0
                  ? existing.totalRows
                  : l.totalRows || 0,
              statReportRows:
                existing.statReportRows && existing.statReportRows > 0
                  ? existing.statReportRows
                  : l.statReportRows || 0,
              unfinishedOpRows:
                existing.unfinishedOpRows && existing.unfinishedOpRows > 0
                  ? existing.unfinishedOpRows
                  : l.unfinishedOpRows || 0,
              summaryOpRows:
                existing.summaryOpRows && existing.summaryOpRows > 0
                  ? existing.summaryOpRows
                  : l.summaryOpRows || 0,
              mesApprovalRows:
                existing.mesApprovalRows && existing.mesApprovalRows > 0
                  ? existing.mesApprovalRows
                  : l.mesApprovalRows || 0,
              resultTksxRows:
                existing.resultTksxRows && existing.resultTksxRows > 0
                  ? existing.resultTksxRows
                  : l.resultTksxRows || l.fileSummaries?.result_tksx?.rowCount || 0,
              resultKhsxRows:
                existing.resultKhsxRows && existing.resultKhsxRows > 0
                  ? existing.resultKhsxRows
                  : l.resultKhsxRows || l.fileSummaries?.result_khsx?.rowCount || 0,
              rawSizeMB: Number(
                existing.rawSizeMB || l.rawSizeMB || l.raw_size_mb || l.rawSizeMb || 0
              ),
              compressedSizeMB: Number(
                existing.compressedSizeMB ||
                  l.compressedSizeMB ||
                  l.compressed_size_mb ||
                  l.compressedSizeMb ||
                  0
              ),
              compressionRatio:
                existing.compressionRatio || l.compressionRatio || l.compression_ratio || '',
              registeredAt: existing.registeredAt || formatRegisteredAt(l.registeredAt),
              registeredBy: resolveUserDisplayName(
                existing.registeredBy,
                l.registeredBy || l.registered_by || l.createdBy
              ),
              remark: existing.remark || l.remark || '',
              isLocalCached: true
            })
          }
        })

        const combined = Array.from(mergedMap.values())
        setRawMasters(combined)

        // Áp dụng bộ lọc tìm kiếm
        const filtered = combined.filter((item) => {
          const factoryFilter = currentFilters.FactoryName || currentFilters.factory
          if (
            factoryFilter &&
            factoryFilter !== 'Tất cả' &&
            factoryFilter !== '' &&
            item.factoryName !== factoryFilter
          ) {
            return false
          }
          const teamFilter = currentFilters.ProductionTeam || currentFilters.team
          if (
            teamFilter &&
            teamFilter !== 'Tất cả' &&
            teamFilter !== '' &&
            item.productionTeam &&
            item.productionTeam !== teamFilter
          ) {
            return false
          }
          const regCodeFilter = currentFilters.RegCode || currentFilters.regCode
          if (
            regCodeFilter &&
            regCodeFilter.trim() &&
            !String(item.regCode || '')
              .toLowerCase()
              .includes(regCodeFilter.trim().toLowerCase())
          ) {
            return false
          }
          const statusFilter = currentFilters.Status || currentFilters.status
          if (
            statusFilter &&
            statusFilter !== 'Tất cả' &&
            statusFilter !== '' &&
            item.status !== statusFilter
          ) {
            return false
          }
          const versionFilter = currentFilters.Version || currentFilters.version
          if (
            versionFilter &&
            versionFilter.trim() &&
            !String(item.version || '')
              .toLowerCase()
              .includes(versionFilter.trim().toLowerCase())
          ) {
            return false
          }
          const applyDateFilter = currentFilters.ApplyDate || currentFilters.applyDate
          if (applyDateFilter && item.applyDate && item.applyDate !== applyDateFilter) {
            return false
          }
          const fromDate = currentFilters.FromDate || currentFilters.fromDate
          const toDate = currentFilters.ToDate || currentFilters.toDate
          if (item.applyDate && fromDate && toDate) {
            if (item.applyDate < fromDate || item.applyDate > toDate) {
              return false
            }
          }
          const userFilter =
            currentFilters.RegisteredBy || currentFilters.registeredBy || currentFilters.createdBy
          if (
            userFilter &&
            userFilter.trim() &&
            !String(item.registeredBy || '')
              .toLowerCase()
              .includes(userFilter.trim().toLowerCase())
          ) {
            return false
          }
          const remarkFilter = currentFilters.Remark || currentFilters.remark
          if (
            remarkFilter &&
            remarkFilter.trim() &&
            !String(item.remark || '')
              .toLowerCase()
              .includes(remarkFilter.trim().toLowerCase())
          ) {
            return false
          }
          const keyword = currentFilters.Keyword || currentFilters.keyword
          if (keyword && keyword.trim()) {
            const kw = keyword.trim().toLowerCase()
            const match =
              String(item.regCode || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.remark || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.factoryName || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.productionTeam || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.registeredBy || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.version || '')
                .toLowerCase()
                .includes(kw) ||
              String(item.status || '')
                .toLowerCase()
                .includes(kw)
            if (!match) return false
          }
          return true
        })

        setQueriedRows(filtered)
        notify('success', `Đã nạp ${filtered.length.toLocaleString('vi-VN')} phiếu kế hoạch`)
      } catch (err) {
        console.error('Lỗi truy vấn master:', err)
        notify('error', `Lỗi truy vấn dữ liệu: ${err.message}`)
      } finally {
        setIsLoading(false)
      }
    },
    [notify]
  )

  const handleResetFilters = useCallback(() => {
    const emptyFilters = {
      FactoryName: '',
      RegCode: '',
      ApplyDate: '',
      FromDate: dayjs().subtract(30, 'day').format('YYYY-MM-DD'),
      ToDate: dayjs().format('YYYY-MM-DD'),
      Status: '',
      Version: '',
      ProductionTeam: '',
      RegisteredBy: '',
      Remark: '',
      Keyword: ''
    }
    setFilters(emptyFilters)
    setRawMasters([])
    setQueriedRows([])
    setSelectedRegCode(null)
    notify('info', 'Đã đặt lại bộ lọc tìm kiếm')
  }, [notify])

  // Mở cửa sổ xem chi tiết (Tự động đồng bộ và giải nén có modal tại cửa sổ chi tiết)
  const handleNavigateToDetail = useCallback(
    (regCode) => {
      const code = regCode || selectedRegCode
      if (!code) {
        notify('warning', 'Vui lòng chọn 1 phiếu đăng ký để xem chi tiết')
        return
      }

      notify('info', `Đang mở cửa sổ chi tiết cho phiếu [${code}]...`)
      openChildWindow({
        path: `/sub/report/calc-production-query/detail/${encodeURIComponent(code)}`,
        title: `Chi tiết KHSX & TKSX - [${code}]`,
        width: 1400,
        height: 850,
        id: `calc_detail_${code}`
      })
    },
    [selectedRegCode, notify]
  )

  // Kiểm tra phiếu đang chọn có phải do chính người dùng hiện tại tạo hay không
  const isMySelectedRecord = useMemo(() => {
    if (!selectedRegCode) return false
    const targetMaster = rawMasters.find(
      (m) =>
        String(m.regCode || m.RegCode || '').toUpperCase() === String(selectedRegCode).toUpperCase()
    )
    if (!targetMaster) return false
    try {
      const curUser = JSON.parse(localStorage.getItem('userInfo') || '{}')
      const myIdentifiers = [
        curUser.UserId,
        curUser.UserSeq,
        curUser.UserCode,
        curUser.UserName,
        curUser.EmpName
      ]
        .filter(Boolean)
        .map((x) => String(x).toLowerCase())

      const recordCreators = [
        targetMaster.createdBy,
        targetMaster.CreatedBy,
        targetMaster.registeredBy,
        targetMaster.registered_by,
        targetMaster.UserSeq
      ]
        .filter(Boolean)
        .map((x) => String(x).toLowerCase())

      return recordCreators.some((creator) => myIdentifiers.includes(creator))
    } catch {
      return false
    }
  }, [selectedRegCode, rawMasters])

  const [deleteModalState, setDeleteModalState] = useState({
    isOpen: false,
    regCode: '',
    isMyRecord: false,
    creatorName: '',
    recordTitle: '',
    deleteMode: 'server'
  })

  // Trạng thái phiếu đang chọn có phải là CANCELLED không
  const isSelectedRecordCancelled = useMemo(() => {
    if (!selectedRegCode) return false
    const target = rawMasters.find(
      (m) =>
        String(m.regCode || m.RegCode || '').toUpperCase() === String(selectedRegCode).toUpperCase()
    )
    return target?.status === 'CANCELLED'
  }, [selectedRegCode, rawMasters])

  // Yêu cầu xóa: Bắt buộc mở Modal xác nhận thông báo rõ ràng
  const handleDeleteMaster = useCallback(
    (regCode = null) => {
      const code = regCode || selectedRegCode
      if (!code) {
        notify('warning', 'Vui lòng chọn 1 phiếu đăng ký để thao tác')
        return
      }

      const targetMaster = rawMasters.find(
        (m) => String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
      )

      let isMyRecord = false
      let creatorName = 'Người dùng khác'
      try {
        const curUser = JSON.parse(localStorage.getItem('userInfo') || '{}')
        const myIdentifiers = [
          curUser.UserId,
          curUser.UserSeq,
          curUser.UserCode,
          curUser.UserName,
          curUser.EmpName
        ]
          .filter(Boolean)
          .map((x) => String(x).toLowerCase())

        const recordCreators = [
          targetMaster?.createdBy,
          targetMaster?.CreatedBy,
          targetMaster?.registeredBy,
          targetMaster?.registered_by,
          targetMaster?.UserSeq
        ]
          .filter(Boolean)
          .map((x) => String(x).toLowerCase())

        isMyRecord = recordCreators.some((creator) => myIdentifiers.includes(creator))
        creatorName =
          targetMaster?.registeredBy ||
          targetMaster?.registered_by ||
          targetMaster?.createdBy ||
          'Người dùng khác'
      } catch {}

      setDeleteModalState({
        isOpen: true,
        regCode: code,
        isMyRecord,
        creatorName,
        recordTitle: targetMaster?.factoryName ? `${targetMaster.factoryName} - ${code}` : code,
        deleteMode: isMyRecord ? 'server' : 'local'
      })
    },
    [selectedRegCode, rawMasters, notify]
  )

  // Xác nhận thực hiện xóa sau khi người dùng bấm trong Modal
  const handleConfirmDelete = useCallback(
    async (overrideMode = null) => {
      const { regCode: code, isMyRecord, deleteMode } = deleteModalState
      const finalMode = overrideMode || deleteMode || 'server'
      setDeleteModalState((prev) => ({ ...prev, isOpen: false }))
      if (!code) return

      if (isMyRecord && finalMode === 'server') {
        try {
          await deleteProductionBundleOnline(code)
          notify('success', `Đã xóa vĩnh viễn phiếu [${code}] trên máy chủ DataHub thành công.`)
        } catch (err) {
          console.error('Lỗi xóa trên server:', err)
          notify('error', `Lỗi xóa phiếu trên Server: ${err.message}`)
          return
        }
      } else if (isMyRecord) {
        notify(
          'success',
          `Đã dọn dẹp dữ liệu cục bộ của phiếu [${code}] trên máy tính này (Bản nén trên Server được bảo lưu nguyên vẹn).`
        )
      } else {
        notify('success', `Đã xóa bộ nhớ đệm (cache) của phiếu [${code}] trên máy tính này.`)
      }

      if (isMyRecord) {
        setRawMasters((prev) =>
          prev.filter(
            (m) => String(m.regCode || m.RegCode || '').toUpperCase() !== String(code).toUpperCase()
          )
        )
        setQueriedRows((prev) =>
          prev.filter(
            (m) => String(m.regCode || m.RegCode || '').toUpperCase() !== String(code).toUpperCase()
          )
        )
        setSelectedRegCode(null)
      } else {
        setRawMasters((prev) =>
          prev.map((m) =>
            String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
              ? { ...m, isLocalCached: false }
              : m
          )
        )
        setQueriedRows((prev) =>
          prev.map((m) =>
            String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
              ? { ...m, isLocalCached: false }
              : m
          )
        )
      }

      // 3. Dọn dẹp ngầm toàn bộ dữ liệu cục bộ trong nền (SQLite/IndexedDB/Cache)
      Promise.allSettled([
        storageAdapter.deleteMasterRegistration(code),
        Promise.resolve().then(() => {
          try {
            localStorage.removeItem(`S_MASTER_REG_${code}`)
            localStorage.removeItem(`S_CALC_RESULTS_${code}`)
            sessionStorage.removeItem(`S_MASTER_REG_${code}`)
            sessionStorage.removeItem(`S_CALC_RESULTS_${code}`)
            if (localStorage.getItem('GS_ACTIVE_DETAIL_REG_CODE') === code) {
              localStorage.removeItem('GS_ACTIVE_DETAIL_REG_CODE')
            }
            clearReportCache(code)
            clearReportCache()
          } catch {}
        })
      ]).catch((err) => {
        console.warn('Lỗi dọn dẹp ngầm:', err)
      })
    },
    [deleteModalState, notify]
  )

  // ── Quản lý Modal Hủy Phiếu (Chuyển đổi trạng thái sang CANCELLED) ──
  const [cancelModalState, setCancelModalState] = useState({
    isOpen: false,
    regCode: '',
    isMyRecord: false,
    creatorName: '',
    recordTitle: '',
    cancelReason: ''
  })

  const handleCancelMaster = useCallback(
    (regCode = null) => {
      const code = regCode || selectedRegCode
      if (!code) {
        notify('warning', 'Vui lòng chọn 1 phiếu đăng ký để thao tác')
        return
      }

      const targetMaster = rawMasters.find(
        (m) => String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
      )

      if (targetMaster?.status === 'CANCELLED') {
        notify('warning', `Phiếu [${code}] đã ở trạng thái Bản hủy (CANCELLED).`)
        return
      }

      let isMyRecord = false
      let creatorName = 'Người dùng khác'
      try {
        const curUser = JSON.parse(localStorage.getItem('userInfo') || '{}')
        const myIdentifiers = [
          curUser.UserId,
          curUser.UserSeq,
          curUser.UserCode,
          curUser.UserName,
          curUser.EmpName
        ]
          .filter(Boolean)
          .map((x) => String(x).toLowerCase())

        const recordCreators = [
          targetMaster?.createdBy,
          targetMaster?.CreatedBy,
          targetMaster?.registeredBy,
          targetMaster?.registered_by,
          targetMaster?.UserSeq
        ]
          .filter(Boolean)
          .map((x) => String(x).toLowerCase())

        isMyRecord = recordCreators.some((creator) => myIdentifiers.includes(creator))
        creatorName =
          targetMaster?.registeredBy ||
          targetMaster?.registered_by ||
          targetMaster?.createdBy ||
          'Người dùng khác'
      } catch {}

      setCancelModalState({
        isOpen: true,
        regCode: code,
        isMyRecord,
        creatorName,
        recordTitle: targetMaster?.factoryName ? `${targetMaster.factoryName} - ${code}` : code,
        cancelReason: ''
      })
    },
    [selectedRegCode, rawMasters, notify]
  )

  const handleConfirmCancel = useCallback(async () => {
    const { regCode: code, cancelReason } = cancelModalState
    setCancelModalState((prev) => ({ ...prev, isOpen: false }))
    if (!code) return

    try {
      const reason = (cancelReason || '').trim() || 'Người dùng hủy phiếu'
      await cancelProductionBundleOnline(code, reason)
      await storageAdapter.updateMasterStatus(code, 'CANCELLED', reason)

      // Cập nhật trạng thái hiển thị trên bảng
      setRawMasters((prev) =>
        prev.map((m) =>
          String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
            ? {
                ...m,
                status: 'CANCELLED',
                remark: m.remark ? `${m.remark} | [HỦY]: ${reason}` : `[HỦY]: ${reason}`
              }
            : m
        )
      )
      setQueriedRows((prev) =>
        prev.map((m) =>
          String(m.regCode || m.RegCode || '').toUpperCase() === String(code).toUpperCase()
            ? {
                ...m,
                status: 'CANCELLED',
                remark: m.remark ? `${m.remark} | [HỦY]: ${reason}` : `[HỦY]: ${reason}`
              }
            : m
        )
      )

      notify(
        'success',
        `Đã chuyển đổi phiếu [${code}] sang trạng thái Bản hủy (CANCELLED) thành công.`
      )
    } catch (err) {
      console.error('Lỗi hủy phiếu:', err)
      notify('error', `Lỗi hủy phiếu: ${err.message}`)
    }
  }, [cancelModalState, notify])

  const [isExportModalOpen, setIsExportModalOpen] = useState(false)
  const [targetExportRegCode, setTargetExportRegCode] = useState('')
  const [isExportProgressOpen, setIsExportProgressOpen] = useState(false)
  const [exportProgressInfo, setExportProgressInfo] = useState({
    percent: 10,
    step: 'INIT',
    message: 'Đang chuẩn bị xuất dữ liệu...',
    detail: '',
    statusTag: 'Xuất dữ liệu Excel'
  })

  // Mở cửa sổ tính toán mới
  const handleOpenCalcProduction = useCallback(() => {
    notify('info', 'Đang mở màn hình Tính KHSX và TKSX...')
    openChildWindow({
      path: '/sub/report/calc-production',
      title: 'Tính KHSX và TKSX',
      width: 1400,
      height: 850,
      id: 'calc_production_window'
    })
  }, [notify])

  // Mở hộp thoại xuất Excel chuẩn ERP
  const handleExportDataKhsx = useCallback(
    (targetCode = null) => {
      const regCodeToExport = targetCode || selectedRegCode
      if (!regCodeToExport) {
        notify('warning', 'Vui lòng chọn 1 dòng phiếu đăng ký trên bảng để xuất Data KHSX.')
        return
      }
      setTargetExportRegCode(regCodeToExport)
      setIsExportModalOpen(true)
    },
    [selectedRegCode, notify]
  )

  // Thực thi xuất toàn bộ dữ liệu KHSX (6 bảng) của phiếu được chọn ra 1 file Excel siêu nhẹ
  const executeExportDataKhsx = useCallback(
    async ({ fileName, saveDirectory } = {}) => {
      const regCodeToExport = targetExportRegCode || selectedRegCode
      if (!regCodeToExport) return

      setIsExportModalOpen(false)
      setIsExportProgressOpen(true)
      setExportProgressInfo({
        percent: 10,
        step: 'DOWNLOAD',
        message: `Đang nạp gói dữ liệu KHSX [${regCodeToExport}]...`,
        detail: 'Đang truy vấn CSDL Server DataHub & Local Cache',
        statusTag: 'Đang nạp dữ liệu'
      })

      try {
        // 1. Lấy bundle binary từ hệ thống online hoặc đọc local
        let binaryBuffer = null
        try {
          binaryBuffer = await downloadProductionBundleOnline(regCodeToExport)
        } catch (err) {
          console.warn('Tải online thất bại, thử đọc local:', err)
        }

        let unpacked = null
        if (binaryBuffer && binaryBuffer.length > 0) {
          unpacked = unpackProductionBundle(binaryBuffer)
        }

        // 2. Nếu chưa có unpacked từ online, đọc từ local storage adapter
        let calcResults = unpacked?.calcResults || null
        if (!calcResults) {
          try {
            calcResults = await storageAdapter.getCalcResults(regCodeToExport)
          } catch (e) {}
        }

        const allFiles =
          unpacked?.filesData || (await storageAdapter.getAllFiles(regCodeToExport)) || {}

        // Import động bộ xuất Excel chuẩn 6 bảng tiếng Việt
        const { exportFull6TabsProductionExcel } =
          await import('../../calcProduction/engine/calcExcelExporter')

        const finalFileName =
          fileName || `DATA_KHSX_${regCodeToExport}_${dayjs().format('YYYYMMDD_HHmmss')}.xlsx`

        await exportFull6TabsProductionExcel({
          calcResults,
          allFiles,
          regCode: regCodeToExport,
          fileName: finalFileName,
          saveDirectory,
          onProgress: (prog) => {
            setExportProgressInfo((prev) => ({
              ...prev,
              ...prog
            }))
          }
        })

        notify('success', `Đã xuất thành công file: ${finalFileName}`)
      } catch (err) {
        console.error('Lỗi xuất Data KHSX:', err)
        notify('error', `Không thể xuất Data KHSX: ${err.message}`)
        setExportProgressInfo({
          percent: 100,
          isComplete: true,
          message: `Lỗi xuất dữ liệu: ${err.message}`,
          detail: 'Vui lòng kiểm tra lại đường truyền hoặc dữ liệu nguồn.',
          statusTag: 'Xuất lỗi'
        })
      }
    },
    [targetExportRegCode, selectedRegCode, notify]
  )

  return {
    filters,
    handleFilterChange,
    handleResetFilters,
    fetchMasterList,
    handleNavigateToDetail,
    handleOpenCalcProduction,
    handleDeleteMaster,
    handleExportDataKhsx,
    executeExportDataKhsx,
    isExportModalOpen,
    setIsExportModalOpen,
    targetExportRegCode,
    isExportProgressOpen,
    setIsExportProgressOpen,
    exportProgressInfo,
    setExportProgressInfo,
    queriedRows,
    selectedRegCode,
    setSelectedRegCode,
    isLoading,
    isSyncing,
    deleteModalState,
    setDeleteModalState,
    handleConfirmDelete,
    isMySelectedRecord,
    isSelectedRecordCancelled,
    cancelModalState,
    setCancelModalState,
    handleCancelMaster,
    handleConfirmCancel
  }
}

import { useState, useEffect } from 'react'
import { createPortal } from 'react-dom'
import {
  Loader2,
  Calculator,
  ShieldCheck,
  Cpu,
  CheckCircle2,
  Clock,
  AlertTriangle,
  XCircle
} from 'lucide-react'
import { Button } from 'antd'

/**
 * CalculationProgressOverlay - Modal Hiển thị Tiến trình Tính Toán & Đồng Bộ KHSX & TKSX
 * Thiết kế vuông vắn chuẩn ERP GsHub, thể hiện rõ tiến độ từ CSDL / Server DataHub
 * Hỗ trợ trạng thái hoàn tất và trạng thái lỗi, yêu cầu người dùng bấm xác nhận để đóng modal.
 */
export default function CalculationProgressOverlay({
  isCalculating = false,
  progressInfo = {},
  title = 'TIẾN TRÌNH TÍNH TOÁN KHSX & TKSX',
  icon: IconComponent = Calculator,
  steps = ['1. Chuẩn bị dữ liệu', '2. Tổng hợp TKSX', '3. Đối soát KHSX', '4. Hoàn tất báo cáo'],
  subMessage = 'Thao tác đang được bảo vệ an toàn để bảo đảm tính toàn vẹn dữ liệu.',
  onClose = null
}) {
  const isError = Boolean(progressInfo?.isError || progressInfo?.step === 'ERROR')

  const isCompleted =
    !isError &&
    Boolean(
      progressInfo?.isComplete ||
      progressInfo?.step === 'COMPLETED' ||
      (progressInfo?.percent !== undefined && progressInfo?.percent >= 100)
    )

  const [elapsedSeconds, setElapsedSeconds] = useState(0)

  // Bộ đếm thời gian thực thi (giây)
  useEffect(() => {
    if (!isCalculating) {
      setElapsedSeconds(0)
      return
    }
    if (isCompleted || isError) return

    const timer = setInterval(() => {
      setElapsedSeconds((prev) => prev + 1)
    }, 1000)

    return () => clearInterval(timer)
  }, [isCalculating, isCompleted, isError])

  const formatDuration = (sec) => {
    const m = Math.floor(sec / 60)
    const s = sec % 60
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
  }

  // Chặn phím tắt và F5 khi đang thực hiện tác vụ (khi chưa hoàn tất và không lỗi)
  useEffect(() => {
    if (!isCalculating || isCompleted || isError) return

    const handleBeforeUnload = (e) => {
      e.preventDefault()
      e.returnValue = 'Hệ thống đang thực hiện tác vụ. Bạn có chắc chắn muốn rời khỏi?'
      return e.returnValue
    }

    const handleKeyDown = (e) => {
      if (
        e.key === 'F5' ||
        ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'r') ||
        (e.altKey && e.key === 'F4') ||
        ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'w')
      ) {
        e.preventDefault()
        e.stopPropagation()
      }
    }

    window.addEventListener('beforeunload', handleBeforeUnload)
    window.addEventListener('keydown', handleKeyDown, true)

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload)
      window.removeEventListener('keydown', handleKeyDown, true)
    }
  }, [isCalculating, isCompleted, isError])

  if (!isCalculating) return null

  const percent = isCompleted
    ? 100
    : isError
      ? progressInfo?.percent || 85
      : Math.min(100, Math.max(10, progressInfo?.percent || 15))

  const message = isError
    ? progressInfo?.message || 'Tác vụ thất bại do phát sinh lỗi!'
    : isCompleted
      ? progressInfo?.message || 'Đã hoàn tất tác vụ thành công!'
      : progressInfo?.message || 'Đang chuẩn bị dữ liệu...'

  const detail = progressInfo?.detail || ''
  const statusTag = isError
    ? progressInfo?.statusTag || 'Thất bại'
    : isCompleted
      ? 'Hoàn tất thành công'
      : progressInfo?.statusTag || 'Đang xử lý dữ liệu'

  const stepList =
    Array.isArray(steps) && steps.length >= 4
      ? steps
      : ['1. Chuẩn bị dữ liệu', '2. Tổng hợp TKSX', '3. Đối soát KHSX', '4. Hoàn tất báo cáo']

  return createPortal(
    <div
      className="fixed inset-0 z-[99999] flex items-center justify-center bg-black/45 backdrop-blur-[2px] select-none p-4"
      style={{ pointerEvents: 'all' }}
      onClick={(e) => {
        e.preventDefault()
        e.stopPropagation()
      }}
    >
      <style>{`
        @keyframes modalPopIn {
          0% { opacity: 0; transform: scale(0.95); }
          100% { opacity: 1; transform: scale(1); }
        }
      `}</style>

      {/* KHUNG MODAL TIẾN TRÌNH VUÔNG VẮN CHUẨN ERP GSHUB */}
      <div
        className={`bg-[#f8fafc] rounded-none shadow-2xl border ${
          isError
            ? 'border-rose-600/70'
            : isCompleted
              ? 'border-emerald-600/70'
              : 'border-blue-600/60'
        } w-[94vw] max-w-[620px] min-w-[360px] flex flex-col overflow-hidden font-sans`}
        style={{ animation: 'modalPopIn 0.2s cubic-bezier(0.16, 1, 0.3, 1)' }}
      >
        {/* 1. Header Vuông Liền MẠCH */}
        <div className="px-3.5 py-2.5 bg-[#f1f5f9] border-b border-slate-300 flex items-center justify-between gap-3 shrink-0">
          <div className="flex items-center gap-2 min-w-0 flex-1 truncate">
            <span
              className={`w-2.5 h-2.5 inline-block shrink-0 ${
                isError ? 'bg-rose-600' : isCompleted ? 'bg-emerald-600' : 'bg-blue-600'
              }`}
            />
            <span className="text-xs font-bold text-slate-800 tracking-wide uppercase truncate flex items-center gap-2">
              {isError ? (
                <XCircle size={16} className="text-rose-600 shrink-0" />
              ) : isCompleted ? (
                <CheckCircle2 size={16} className="text-emerald-600 shrink-0" />
              ) : (
                <IconComponent size={15} className="text-blue-600 shrink-0" />
              )}
              {title}
            </span>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            <div className="flex items-center gap-1 px-2 py-0.5 rounded bg-slate-200/70 border border-slate-300 text-slate-700 font-mono text-[11px] font-semibold">
              <Clock
                size={11}
                className={
                  isError
                    ? 'text-rose-600'
                    : isCompleted
                      ? 'text-emerald-600'
                      : 'text-blue-600 animate-spin'
                }
              />
              <span>{formatDuration(elapsedSeconds)}</span>
            </div>
            <span
              className={`text-[10px] font-semibold px-2 py-0.5 border shrink-0 ${
                isError
                  ? 'bg-rose-50 text-rose-700 border-rose-300'
                  : isCompleted
                    ? 'bg-emerald-50 text-emerald-700 border-emerald-300'
                    : 'bg-blue-50 text-blue-700 border-blue-200'
              }`}
            >
              {statusTag}
            </span>
          </div>
        </div>

        {/* 2. Thân Modal & Thông Số */}
        <div className="p-4 bg-white space-y-4">
          {/* Hộp Thông Tin Trạng Thái */}
          <div
            className={`p-3 border text-xs space-y-2 ${
              isError
                ? 'bg-rose-50/70 border-rose-300'
                : isCompleted
                  ? 'bg-emerald-50/60 border-emerald-300'
                  : 'bg-slate-50 border-slate-300'
            }`}
          >
            <div className="flex items-center justify-between text-slate-800 font-bold gap-2">
              <div className="flex items-center gap-2 truncate flex-1 min-w-0">
                {isError ? (
                  <AlertTriangle size={16} className="text-rose-600 shrink-0" />
                ) : isCompleted ? (
                  <CheckCircle2 size={16} className="text-emerald-600 shrink-0" />
                ) : (
                  <Cpu size={15} className="text-indigo-600 shrink-0 animate-pulse" />
                )}
                <span
                  className={`truncate font-semibold ${
                    isError
                      ? 'text-rose-900 font-bold'
                      : isCompleted
                        ? 'text-emerald-900 font-bold'
                        : 'text-slate-800'
                  }`}
                >
                  {message}
                </span>
              </div>
            </div>

            {detail && (
              <div
                className={`text-[11px] pl-6 truncate border-t pt-1.5 ${
                  isError
                    ? 'text-rose-800 border-rose-200 font-medium'
                    : isCompleted
                      ? 'text-emerald-800 border-emerald-200'
                      : 'text-slate-600 border-slate-200'
                }`}
                title={detail}
              >
                {detail}
              </div>
            )}
          </div>

          {/* Thanh Tiến Trình (Progress Bar) */}
          <div>
            <div className="flex items-center justify-between text-xs mb-1.5">
              <span className="font-semibold text-slate-700 flex items-center gap-1.5 truncate">
                {isError ? (
                  <XCircle size={13} className="text-rose-600 shrink-0" />
                ) : isCompleted ? (
                  <CheckCircle2 size={13} className="text-emerald-600 shrink-0" />
                ) : (
                  <Loader2 size={13} className="text-blue-600 animate-spin shrink-0" />
                )}
                <span
                  className={`truncate text-[11px] ${isError ? 'text-rose-600 font-semibold' : 'text-slate-600'}`}
                >
                  {isError
                    ? 'Tiến trình dừng do lỗi hệ thống!'
                    : isCompleted
                      ? 'Đã hoàn tất 100% dữ liệu!'
                      : 'Đang xử lý dữ liệu...'}
                </span>
              </span>
              <span
                className={`font-mono font-bold text-sm shrink-0 ${
                  isError ? 'text-rose-700' : isCompleted ? 'text-emerald-700' : 'text-blue-700'
                }`}
              >
                {percent}%
              </span>
            </div>

            <div className="w-full bg-slate-200 h-2.5 overflow-hidden border border-slate-300">
              <div
                className={`h-full transition-all duration-250 ease-out ${
                  isError
                    ? 'bg-rose-600'
                    : isCompleted
                      ? 'bg-emerald-600'
                      : 'bg-gradient-to-r from-blue-600 to-indigo-600'
                }`}
                style={{ width: `${percent}%` }}
              />
            </div>
          </div>

          {/* 4 Bước Tiến Trình Chuẩn ERP */}
          <div className="grid grid-cols-4 gap-1.5 text-[10px] text-center pt-1 font-semibold">
            <div
              className={`p-1.5 border transition-all ${
                percent >= 20
                  ? 'border-emerald-400 bg-emerald-50 text-emerald-800'
                  : 'border-slate-300 bg-slate-50 text-slate-400'
              }`}
            >
              {stepList[0]}
            </div>
            <div
              className={`p-1.5 border transition-all ${
                percent >= 50
                  ? 'border-emerald-400 bg-emerald-50 text-emerald-800'
                  : 'border-slate-300 bg-slate-50 text-slate-400'
              }`}
            >
              {stepList[1]}
            </div>
            <div
              className={`p-1.5 border transition-all ${
                isError && percent < 90
                  ? 'border-rose-400 bg-rose-50 text-rose-800'
                  : percent >= 80
                    ? 'border-emerald-400 bg-emerald-50 text-emerald-800'
                    : 'border-slate-300 bg-slate-50 text-slate-400'
              }`}
            >
              {stepList[2]}
            </div>
            <div
              className={`p-1.5 border transition-all ${
                isError
                  ? 'border-rose-300 bg-rose-50/50 text-rose-500'
                  : percent >= 98 || isCompleted
                    ? 'border-emerald-400 bg-emerald-50 text-emerald-800'
                    : 'border-slate-300 bg-slate-50 text-slate-400'
              }`}
            >
              {stepList[3]}
            </div>
          </div>
        </div>

        {/* 3. Footer Cảnh Báo An Toàn & Nút Xác Nhận Khi Hoàn Tất Hoặc Khi Có Lỗi */}
        <div className="px-3.5 py-2.5 bg-[#f1f5f9] border-t border-slate-300 flex items-center justify-between gap-3 shrink-0">
          <div className="flex items-center gap-2 text-[10px] text-slate-600 min-w-0 flex-1 truncate">
            {isError ? (
              <AlertTriangle size={14} className="text-rose-600 shrink-0" />
            ) : (
              <ShieldCheck size={14} className="text-emerald-600 shrink-0" />
            )}
            <span className={`truncate ${isError ? 'text-rose-700 font-medium' : ''}`}>
              {isError
                ? 'Vui lòng kiểm tra lại thông tin hoặc đăng nhập lại trước khi thử lại.'
                : subMessage}
            </span>
          </div>

          {isCompleted && typeof onClose === 'function' && (
            <Button
              type="primary"
              size="small"
              onClick={onClose}
              className="bg-emerald-600 hover:bg-emerald-700 active:bg-emerald-800 text-white rounded-none text-xs font-bold px-4 h-7 shrink-0 shadow flex items-center gap-1.5"
            >
              <CheckCircle2 size={13} className="text-white shrink-0" />
              <span>Đồng ý</span>
            </Button>
          )}

          {isError && typeof onClose === 'function' && (
            <Button
              danger
              size="small"
              onClick={onClose}
              className="bg-rose-600 hover:bg-rose-700 active:bg-rose-800 text-white rounded-none text-xs font-bold px-4 h-7 shrink-0 shadow flex items-center gap-1.5"
            >
              <XCircle size={13} className="text-white shrink-0" />
              <span>Đóng</span>
            </Button>
          )}
        </div>
      </div>
    </div>,
    document.body
  )
}

/* eslint-disable react/prop-types */
import { useState, useMemo, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { useTranslation } from 'react-i18next'
import {
  X,
  Maximize2,
  Minimize2,
  Table as TableIcon,
  Columns,
  Sparkles,
  FileSpreadsheet,
  Check,
  RotateCcw
} from 'lucide-react'
import { Select } from 'antd'

/**
 * ExcelMappingModal - Modal Ánh Xạ Cột Excel
 * Phối màu & cấu trúc chuẩn 100% theo giao diện CodeHelp Modal (GenericCodeHelpModal) của hệ thống GsHub.
 * 1 khối bảng tính duy nhất (Full-width Sheet), 100% góc vuông phẳng (rounded-none).
 */
export default function ExcelMappingModal({
  isOpen = false,
  file,
  rawFile,
  targetTabId,
  fileType,
  tabTitle,
  matrixPreview,
  rawMatrix = [],
  detectedHeaderRow = 0,
  initialHeaderRow = 0,
  detectedDataStartRow = 1,
  initialDataStartRow = 1,
  availableSchema = [],
  initialMapping = {},
  initialMappings = {},
  onConfirm,
  onClose,
  onCancel
}) {
  const { t } = useTranslation()

  // Đồng bộ props linh hoạt
  const effectiveFile = file || rawFile
  const effectiveTabId = targetTabId || fileType || ''
  const effectiveMatrix =
    matrixPreview && matrixPreview.length > 0 ? matrixPreview : rawMatrix || []
  const effectiveHeaderRow = initialHeaderRow ?? detectedHeaderRow ?? 0
  const effectiveDataStartRow =
    initialDataStartRow ?? detectedDataStartRow ?? effectiveHeaderRow + 1
  const effectiveInitialMapping = initialMapping || initialMappings || {}
  const handleClose = onClose || onCancel

  const [isMaximized, setIsMaximized] = useState(false)
  const [headerRowIdx, setHeaderRowIdx] = useState(effectiveHeaderRow)
  const [dataStartRowIdx, setDataStartRowIdx] = useState(effectiveDataStartRow)
  const [columnMappings, setColumnMappings] = useState(effectiveInitialMapping)

  // Cập nhật khi mở modal
  useEffect(() => {
    if (isOpen) {
      setHeaderRowIdx(effectiveHeaderRow)
      setDataStartRowIdx(effectiveDataStartRow)
      setColumnMappings(effectiveInitialMapping || {})
      setIsMaximized(false)
    }
  }, [isOpen, effectiveHeaderRow, effectiveDataStartRow]) // eslint-disable-line react-hooks/exhaustive-deps

  // Phím tắt bàn phím toàn cục
  useEffect(() => {
    if (!isOpen) return
    const handleGlobalKeyDown = (e) => {
      if (e.key === 'Escape') {
        e.preventDefault()
        e.stopPropagation()
        handleClose && handleClose()
      }
    }
    window.addEventListener('keydown', handleGlobalKeyDown, true)
    return () => window.removeEventListener('keydown', handleGlobalKeyDown, true)
  }, [isOpen, handleClose])

  // Trích xuất dòng Header đang chọn
  const rawHeaderRow = useMemo(() => {
    return Array.isArray(effectiveMatrix[headerRowIdx]) ? effectiveMatrix[headerRowIdx] : []
  }, [effectiveMatrix, headerRowIdx])

  const maxCols = useMemo(() => {
    let max = rawHeaderRow.length
    effectiveMatrix.slice(0, 30).forEach((r) => {
      if (Array.isArray(r)) max = Math.max(max, r.length)
    })
    return max
  }, [effectiveMatrix, rawHeaderRow])

  // Tự động map cột dựa trên tên tiêu đề
  const autoMatchColumns = () => {
    const newMappings = {}
    for (let c = 0; c < maxCols; c++) {
      const headerTitle = String(rawHeaderRow[c] || '')
        .trim()
        .toLowerCase()
      if (!headerTitle) continue

      const matched = availableSchema.find((s) => {
        const sLower = s.title.toLowerCase()
        return (
          sLower === headerTitle ||
          (sLower.includes(headerTitle) && headerTitle.length >= 3) ||
          (headerTitle.includes(sLower) && sLower.length >= 3)
        )
      })

      if (matched) {
        newMappings[c] = matched.key
      } else {
        newMappings[c] = `CUSTOM_${c}`
      }
    }
    setColumnMappings(newMappings)
  }

  // Chạy tự động khớp khi đổi Header Row
  useEffect(() => {
    if (isOpen && effectiveMatrix.length > 0) {
      autoMatchColumns()
    }
  }, [headerRowIdx]) // eslint-disable-line react-hooks/exhaustive-deps

  const handleMappingChange = (colIndex, targetKey) => {
    setColumnMappings((prev) => ({
      ...prev,
      [colIndex]: targetKey
    }))
  }

  const handleApply = () => {
    onConfirm?.({
      tabId: effectiveTabId,
      file: effectiveFile,
      headerRowIndex: headerRowIdx,
      dataStartRowIndex: dataStartRowIdx,
      columnMappings
    })
  }

  if (!isOpen) return null

  // Chuyển chỉ số cột 0, 1, 2 sang A, B, C
  const getColLetter = (index) => {
    let letter = ''
    while (index >= 0) {
      letter = String.fromCharCode((index % 26) + 65) + letter
      index = Math.floor(index / 26) - 1
    }
    return letter
  }

  // Đếm số lượng cột đã khớp hợp lệ
  const mappedCount = Object.values(columnMappings).filter(
    (key) => key && !key.startsWith('CUSTOM_') && key !== '__IGNORE__'
  ).length

  return createPortal(
    <div
      className={`fixed inset-0 bg-black/40 backdrop-blur-[2px] flex items-center justify-center z-[99999] select-none transition-[padding] duration-200 ease-out ${
        isMaximized ? 'p-0' : 'p-3 sm:p-5'
      }`}
      style={{ animation: 'macBackdropFade 0.15s ease-out' }}
      onClick={(e) => {
        if (e.target === e.currentTarget) {
          handleClose && handleClose()
        }
      }}
    >
      <style>{`
        @keyframes macBackdropFade {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes macOriginIn {
          0% { opacity: 0; transform: scale(0.92); }
          100% { opacity: 1; transform: scale(1); }
        }
      `}</style>

      {/* KHUNG DIALOG VUÔNG CHUẨN CODEHELP GSHUB */}
      <div
        className={`bg-[#f8fafc] flex flex-col shadow-2xl border border-slate-500 font-sans rounded-none select-none transition-[width,height,max-width,max-height,transform] duration-200 ease-out transform-gpu will-change-[width,height,transform] ${
          isMaximized
            ? 'w-full h-full max-w-full max-h-full border-0'
            : 'w-[94vw] max-w-[1360px] h-[86vh] max-h-[800px] min-h-[480px]'
        }`}
        style={{ animation: 'macOriginIn 0.2s cubic-bezier(0.16, 1, 0.3, 1)' }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* 1. HEADER DIALOG VUÔNG LIỀN MẠCH CHUẨN CODEHELP */}
        <div className="flex items-center justify-between px-3 py-2 bg-[#f1f5f9] border-b border-slate-300 shrink-0">
          <div className="flex items-center gap-2">
            <span className="w-2.5 h-2.5 bg-blue-600 inline-block" />
            <span className="text-xs font-bold text-slate-800 tracking-wide uppercase truncate">
              {t('Cấu Hình Dòng Tiêu Đề & Ánh Xạ Cột Excel')}
              {tabTitle ? ` — [${tabTitle}]` : ''}
            </span>
          </div>

          <div className="flex gap-2 items-center">
            <button
              type="button"
              onClick={() => setIsMaximized((prev) => !prev)}
              title={isMaximized ? t('Thu nhỏ') : t('Phóng to')}
              className="p-1 text-slate-600 hover:text-slate-900 hover:bg-slate-200 transition-colors rounded-none cursor-pointer"
            >
              {isMaximized ? <Minimize2 size={13} /> : <Maximize2 size={13} />}
            </button>
            <button
              type="button"
              onClick={handleClose}
              title={t('Đóng (Esc)')}
              className="p-1 text-slate-600 hover:text-red-600 hover:bg-red-100 transition-colors rounded-none cursor-pointer"
            >
              <X size={14} />
            </button>
          </div>
        </div>

        {/* 2. TOOLBAR TÍCH HỢP CHUẨN CODEHELP */}
        <div className="bg-white border-b border-slate-300 flex items-center justify-between px-3 py-1.5 shrink-0 text-xs">
          <div className="flex items-center gap-5">
            {/* Dòng Tiêu Đề */}
            <div className="flex items-center gap-1.5 text-slate-700">
              <span className="font-semibold text-xs text-slate-700 flex items-center gap-1">
                <Columns size={13} className="text-blue-600" />
                <span>{t('Dòng Tiêu Đề:')}</span>
              </span>
              <div className="flex items-center border border-slate-300 bg-slate-50 px-1.5 py-0.5 rounded-none">
                <input
                  type="number"
                  min={1}
                  max={Math.min(30, effectiveMatrix.length || 30)}
                  value={headerRowIdx + 1}
                  onChange={(e) => {
                    const val = parseInt(e.target.value, 10) || 1
                    const idx = Math.max(0, val - 1)
                    setHeaderRowIdx(idx)
                    if (dataStartRowIdx <= idx) {
                      setDataStartRowIdx(idx + 1)
                    }
                  }}
                  className="w-8 text-center font-bold text-blue-700 bg-transparent outline-none text-xs font-mono"
                />
                <span className="text-[10px] text-slate-500">dòng</span>
              </div>
            </div>

            {/* Dòng Bắt Đầu Data */}
            <div className="flex items-center gap-1.5 text-slate-700">
              <span className="font-semibold text-xs text-slate-700 flex items-center gap-1">
                <TableIcon size={13} className="text-emerald-600" />
                <span>{t('Dòng Bắt Đầu Data:')}</span>
              </span>
              <div className="flex items-center border border-slate-300 bg-slate-50 px-1.5 py-0.5 rounded-none">
                <input
                  type="number"
                  min={headerRowIdx + 2}
                  max={Math.min(50, effectiveMatrix.length || 50)}
                  value={dataStartRowIdx + 1}
                  onChange={(e) => {
                    const val = parseInt(e.target.value, 10) || headerRowIdx + 2
                    setDataStartRowIdx(Math.max(headerRowIdx + 1, val - 1))
                  }}
                  className="w-8 text-center font-bold text-emerald-700 bg-transparent outline-none text-xs font-mono"
                />
                <span className="text-[10px] text-slate-500">dòng</span>
              </div>
            </div>

            {/* Nút Tự Động Khớp */}
            <button
              type="button"
              onClick={autoMatchColumns}
              className="px-2.5 py-1 bg-slate-50 hover:bg-slate-100 border border-slate-300 text-xs font-semibold text-slate-700 outline-none cursor-pointer rounded-none flex items-center gap-1 select-none transition-colors"
            >
              <Sparkles size={12} className="text-blue-600" />
              <span>{t('Tự Động Khớp Lại Cột')}</span>
            </button>
          </div>

          {/* Thống kê cột CodeHelp */}
          <div className="flex items-center gap-3 text-xs text-slate-600 font-medium">
            <span>
              Tổng cột: <b className="text-slate-800 font-mono">{maxCols}</b>
            </span>
            <span>•</span>
            <span>
              Đã khớp: <b className="text-blue-700 font-mono">{mappedCount}</b>
            </span>
            <span>•</span>
            <span>
              Cột tự do: <b className="text-slate-700 font-mono">{maxCols - mappedCount}</b>
            </span>
          </div>
        </div>

        {/* 3. BẢNG DỮ LIỆU SHEET FULL-WIDTH CHUẨN CODEHELP */}
        <div className="flex-1 w-full relative bg-white overflow-auto border-b border-slate-300 min-h-0">
          <table className="w-full border-collapse text-xs font-sans">
            <thead>
              {/* TẦNG 1: KÝ TỰ CỘT (A, B, C...) & TRẠNG THÁI KHỚP */}
              <tr className="bg-[#f1f5f9] sticky top-0 z-30 border-b border-slate-300 text-slate-700 text-xs select-none">
                <th className="p-1 border-r border-slate-300 text-center w-12 bg-[#e2e8f0] sticky left-0 z-40 font-bold">
                  #
                </th>
                {Array.from({ length: maxCols }).map((_, c) => {
                  const colLetter = getColLetter(c)
                  const currentMapped = columnMappings[c] || `CUSTOM_${c}`
                  const isMatched =
                    currentMapped &&
                    !currentMapped.startsWith('CUSTOM_') &&
                    currentMapped !== '__IGNORE__'
                  const isIgnored = currentMapped === '__IGNORE__'

                  return (
                    <th
                      key={c}
                      className="p-1.5 border-r border-slate-300 text-center font-mono min-w-[200px] max-w-[260px] bg-[#f1f5f9]"
                    >
                      <div className="flex items-center justify-between px-1">
                        <span className="font-bold text-slate-800 text-xs">{colLetter}</span>
                        {isMatched ? (
                          <span className="text-[10px] font-semibold text-blue-700 flex items-center gap-0.5">
                            <Check size={11} className="stroke-[2.5]" />
                            <span>Khớp</span>
                          </span>
                        ) : isIgnored ? (
                          <span className="text-[10px] font-normal text-slate-400">Bỏ qua</span>
                        ) : (
                          <span className="text-[10px] font-normal text-slate-500">Tự do</span>
                        )}
                      </div>
                    </th>
                  )
                })}
              </tr>

              {/* TẦNG 2: DROPDOWN ÁNH XẠ CSDL CHUẨN ANT DESIGN TRONG CODEHELP */}
              <tr className="bg-white sticky top-[30px] z-30 border-b border-slate-300 shadow-2xs">
                <th className="p-1 border-r border-slate-300 text-center text-[10px] font-bold text-slate-500 bg-[#f1f5f9] sticky left-0 z-40 uppercase">
                  Ánh xạ
                </th>
                {Array.from({ length: maxCols }).map((_, c) => {
                  const currentMapped = columnMappings[c] || `CUSTOM_${c}`

                  return (
                    <th
                      key={c}
                      className="p-1 border-r border-slate-300 bg-white min-w-[200px] max-w-[260px]"
                    >
                      <Select
                        size="small"
                        value={currentMapped}
                        onChange={(val) => handleMappingChange(c, val)}
                        className="w-full text-xs rounded-none font-normal"
                        popupMatchSelectWidth={false}
                        options={[
                          { label: t('-- Bỏ qua cột này --'), value: '__IGNORE__' },
                          { label: t('-- Cột mở rộng (Tự do) --'), value: `CUSTOM_${c}` },
                          ...availableSchema.map((s) => ({
                            label: `${s.title} (${s.key})`,
                            value: s.key
                          }))
                        ]}
                      />
                    </th>
                  )
                })}
              </tr>

              {/* TẦNG 3: TIÊU ĐỀ TRONG FILE EXCEL */}
              <tr className="bg-[#f8fafc] sticky top-[64px] z-30 border-b-2 border-slate-300 text-slate-800 text-xs">
                <th className="p-1 border-r border-slate-300 text-center text-[10px] font-bold text-blue-700 bg-blue-50 sticky left-0 z-40 uppercase">
                  Tiêu đề
                </th>
                {Array.from({ length: maxCols }).map((_, c) => {
                  const headerTitle = String(rawHeaderRow[c] || '').trim() || `(Trống)`

                  return (
                    <th
                      key={c}
                      className="p-1.5 border-r border-slate-300 text-left font-bold text-slate-800 bg-[#f8fafc] min-w-[200px] max-w-[260px] truncate"
                      title={headerTitle}
                    >
                      <div className="truncate text-xs">{headerTitle}</div>
                    </th>
                  )
                })}
              </tr>
            </thead>

            {/* THÂN BẢNG: LƯỚI Ô TÍNH CHUẨN CODEHELP THEME */}
            <tbody>
              {effectiveMatrix.slice(0, 60).map((row, rIdx) => {
                const isHeader = rIdx === headerRowIdx
                const isDataStart = rIdx === dataStartRowIdx
                const isDataRow = rIdx >= dataStartRowIdx

                return (
                  <tr
                    key={rIdx}
                    className={`border-b border-slate-200 transition-colors ${
                      isHeader
                        ? 'bg-[#eef6ff] font-bold text-blue-950'
                        : isDataStart
                          ? 'bg-[#ecfdf5] font-semibold text-emerald-950'
                          : isDataRow
                            ? rIdx % 2 === 1
                              ? 'bg-[#f8fafc] hover:bg-[#eef6ff]/60 text-slate-800'
                              : 'bg-white hover:bg-[#eef6ff]/60 text-slate-800'
                            : 'bg-slate-50/50 text-slate-400 italic'
                    }`}
                  >
                    {/* Cột số thứ tự dòng */}
                    <td
                      className={`p-1 border-r border-slate-300 text-center text-[10px] font-mono select-none sticky left-0 z-20 ${
                        isHeader
                          ? 'bg-[#dbeafe] text-blue-900 font-bold'
                          : isDataStart
                            ? 'bg-[#d1fae5] text-emerald-900 font-bold'
                            : 'bg-[#f1f5f9] text-slate-500'
                      }`}
                    >
                      <span>{rIdx + 1}</span>
                      {isHeader && (
                        <span className="block text-[8px] text-blue-700 leading-none">HEADER</span>
                      )}
                      {isDataStart && (
                        <span className="block text-[8px] text-emerald-700 leading-none">DATA</span>
                      )}
                    </td>

                    {/* Các ô dữ liệu Excel */}
                    {Array.from({ length: maxCols }).map((_, cIdx) => (
                      <td
                        key={cIdx}
                        className="p-1.5 border-r border-slate-200 whitespace-nowrap overflow-hidden text-ellipsis max-w-[260px] font-mono text-xs"
                        title={String(row?.[cIdx] || '')}
                      >
                        {String(row?.[cIdx] || '')}
                      </td>
                    ))}
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>

        {/* 4. FOOTER DIALOG CHUẨN 100% CODEHELP MODAL */}
        <div className="flex items-center justify-between px-4 py-2 bg-[#f8fafc] border-t border-slate-300 shrink-0">
          <div className="text-xs text-slate-600 flex items-center gap-1.5">
            <FileSpreadsheet size={14} className="text-slate-500 shrink-0" />
            <span>
              Tệp: <strong className="text-slate-800">{effectiveFile?.name || 'File Excel'}</strong>
            </span>
            {effectiveFile?.size && (
              <span className="text-slate-400 text-xs font-mono">
                ({(effectiveFile.size / 1024).toFixed(1)} KB)
              </span>
            )}
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleApply}
              className="px-4 py-1.5 bg-[#1677ff] hover:bg-[#0958d9] text-white font-semibold text-xs rounded-none shadow-2xs flex items-center gap-1.5 transition-colors cursor-pointer border border-[#1677ff]"
            >
              <Check size={13} className="stroke-[2.5]" />
              {t('Áp dụng')}
            </button>
            <button
              type="button"
              onClick={handleClose}
              className="px-4 py-1.5 bg-white hover:bg-slate-100 text-slate-700 font-medium text-xs rounded-none border border-slate-300 shadow-2xs transition-colors cursor-pointer"
            >
              {t('Đóng')}
            </button>
          </div>
        </div>
      </div>
    </div>,
    document.body
  )
}

import { useEffect } from 'react'
import { createPortal } from 'react-dom'
import { Loader2, FileSpreadsheet, Columns, Database, ShieldCheck } from 'lucide-react'

/**
 * ImportLoadingOverlay - Modal Hiển thị Tiến trình Nạp File Excel
 * Thiết kế vuông vức chuẩn ERP GsHub (phong cách CodeHelp Modal),
 * kèm tính năng khóa chuột, chặn thoát trang (F5, Ctrl+R, Alt+F4) và thông số nạp file.
 */
export default function ImportLoadingOverlay({
  isLoading = false,
  progressInfo = {},
  title = 'Đang Xử Lý & Nạp Dữ Liệu Excel',
  message = 'Hệ thống đang phân tích cấu trúc và đồng bộ dữ liệu...',
  subMessage = 'Thao tác đang được tạm khóa để bảo vệ toàn vẹn dữ liệu. Vui lòng không đóng trang.'
}) {
  // Chặn phím tắt và F5 khi đang nạp dữ liệu
  useEffect(() => {
    if (!isLoading) return

    const handleBeforeUnload = (e) => {
      e.preventDefault()
      e.returnValue = 'Dữ liệu đang được import. Bạn có chắc chắn muốn rời khỏi?'
      return e.returnValue
    }

    const handleKeyDown = (e) => {
      if (
        e.key === 'F5' ||
        ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'r') ||
        (e.altKey && e.key === 'F4') ||
        ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'w')
      ) {
        e.preventDefault()
        e.stopPropagation()
      }
    }

    window.addEventListener('beforeunload', handleBeforeUnload)
    window.addEventListener('keydown', handleKeyDown, true)

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload)
      window.removeEventListener('keydown', handleKeyDown, true)
    }
  }, [isLoading])

  if (!isLoading) return null

  // Format kích thước file
  const formatFileSize = (bytes) => {
    if (!bytes || isNaN(bytes)) return ''
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`
  }

  const fileName = progressInfo?.fileName || ''
  const fileSize = formatFileSize(progressInfo?.fileSize)
  const tabTitle = progressInfo?.tabTitle || ''
  const detectedCols = progressInfo?.detectedColumns || 0
  const totalRows = progressInfo?.totalRows || 0
  const percent = Math.min(100, Math.max(12, progressInfo?.percent || 25))
  const currentMsg = progressInfo?.message || message

