            // D. Khớp đặc biệt cho nhóm: THỜI GIAN LÃNG PHÍ / HAO PHÍ
            if (
              !matched &&
              (groupLower.includes('lãng phí') ||
                groupLower.includes('hao phí') ||
                groupLower.includes('lang phi') ||
                groupLower.includes('hao phi'))
            ) {
