                }
              } else if (
                titleLower.includes('tổng') ||
                titleLower.includes('tong') ||
                titleLower.includes('1+2+3+4') ||
                titleLower.includes('(5)')
              ) {
                matched = schemaList.find((s) => s.key === 'TotalDowntimeMinutes') || {
                  key: 'TotalDowntimeMinutes',
                  title: 'Tổng tg hao phí (5)=1+2+3+4',
                  group: 'Thời gian lãng phí'
                }
              }
            }

            // E. Xử lý các cột duplicate theo thứ tự xuất hiện nếu không có group phân biệt
            if (!matched) {
              if (
                titleLower === 'ngày phát hành lệnh' ||
                titleLower === 'ngay phat hanh lenh' ||
                titleLower === 'ngày phát hành'
              ) {
                if (!seenKeys['StageOrderReleaseDate']) {
                  matched = {
                    key: 'StageOrderReleaseDate',
                    title: 'Ngày phát hành lệnh CĐ',
                    group: 'Thông tin lệnh công đoạn'
                  }
                } else if (!seenKeys['OpOrderReleaseDate']) {
                  matched = {
                    key: 'OpOrderReleaseDate',
                    title: 'Ngày phát hành lệnh TT',
                    group: 'Thông tin lệnh thao tác'
                  }
                }
              } else if (
                titleLower === 'số lượng cần đạt' ||
                titleLower === 'sl cần đạt' ||
                titleLower === 'cần đạt'
              ) {
                if (!seenKeys['StageTargetQty']) {
                  matched = {
                    key: 'StageTargetQty',
                    title: 'SL cần đạt (CĐ)',
                    group: 'Thông tin lệnh công đoạn'
                  }
                } else if (!seenKeys['OpTargetQty']) {
                  matched = {
                    key: 'OpTargetQty',
                    title: 'SL cần đạt (TT)',
                    group: 'Thông tin lệnh thao tác'
                  }
                }
              } else if (
                titleLower === 'số lượng cần sản xuất' ||
                titleLower === 'sl cần sản xuất' ||
                titleLower === 'cần sản xuất' ||
                titleLower === 'cần sx' ||
                titleLower === 'sl cần sx'
              ) {
                if (!seenKeys['StagePlannedQty']) {
                  matched = {
                    key: 'StagePlannedQty',
                    title: 'SL cần sản xuất (CĐ)',
                    group: 'Thông tin lệnh công đoạn'
                  }
                } else if (!seenKeys['OpPlannedQty']) {
                  matched = {
                    key: 'OpPlannedQty',
                    title: 'SL cần sản xuất (TT)',
                    group: 'Thông tin lệnh thao tác'
                  }
                }
              } else if (
                titleLower === 'họ tên' ||
                titleLower === 'ho ten' ||
                titleLower.includes('họ tên') ||
                titleLower.includes('technician') ||
                titleLower === 'thợ' ||
                titleLower.includes('người vận hành')
              ) {
                // Nhận diện thợ máy (Thợ chính, Thợ phụ 1, Thợ phụ 2)
                technicianCounter++
                if (groupLower.includes('phụ 2') || titleLower.includes('phụ 2')) {
                  matched = schemaList.find((s) => s.key === 'AssistantWorker2Name') || {
                    key: 'AssistantWorker2Name',
                    title: 'Họ tên',
                    group: 'Thợ phụ 2'
                  }
                } else if (groupLower.includes('phụ 1') || titleLower.includes('phụ 1')) {
                  matched = schemaList.find((s) => s.key === 'AssistantWorker1Name') || {
                    key: 'AssistantWorker1Name',
                    title: 'Họ tên',
                    group: 'Thợ phụ 1'
                  }
                } else if (groupLower.includes('chính') || titleLower.includes('chính')) {
                  matched = schemaList.find((s) => s.key === 'LeadTechnicianName') || {
                    key: 'LeadTechnicianName',
                    title: 'Họ tên',
                    group: 'Thợ chính'
                  }
                } else {
                  // Phân bổ tuần tự nếu không có group chỉ định
                  if (!seenKeys['LeadTechnicianName']) {
                    matched = schemaList.find((s) => s.key === 'LeadTechnicianName') || {
                      key: 'LeadTechnicianName',
                      title: 'Họ tên',
                      group: 'Thợ chính'
                    }
                  } else if (!seenKeys['AssistantWorker1Name']) {
                    matched = schemaList.find((s) => s.key === 'AssistantWorker1Name') || {
                      key: 'AssistantWorker1Name',
                      title: 'Họ tên',
                      group: 'Thợ phụ 1'
                    }
                  } else if (!seenKeys['AssistantWorker2Name']) {
                    matched = schemaList.find((s) => s.key === 'AssistantWorker2Name') || {
                      key: 'AssistantWorker2Name',
                      title: 'Họ tên',
                      group: 'Thợ phụ 2'
                    }
                  } else {
                    matched = {
                      key: `AssistantWorker${technicianCounter}Name`,
                      title: 'Họ tên',
                      group: `Thợ phụ ${technicianCounter}`
                    }
                  }
                }
              }
            }

            // F. Khớp theo Group và Title linh hoạt (bỏ qua ký hiệu số thứ tự như (1), (5), (6),...)
            if (!matched && cleanGroup) {
              // F1. Ưu tiên khớp chính xác Title trong cùng Group
              matched = schemaList.find((s) => {
                const sGroup = clean(s.group)
                const sTitle = clean(s.title)
                if (
                  sGroup !== cleanGroup &&
                  !sGroup.includes(cleanGroup) &&
                  !cleanGroup.includes(sGroup)
                ) {
                  return false
                }
                const cleanSTitleNoParen = sTitle.replace(/\s*\(.*?\)/g, '').trim()
                const cleanColTitleNoParen = cleanTitle.replace(/\s*\(.*?\)/g, '').trim()
                return sTitle === cleanTitle || cleanSTitleNoParen === cleanColTitleNoParen
              })

              // F2. Khớp tương đối Title trong cùng Group (loại trừ nhầm lẫn Ngày vs Giờ)
              if (!matched) {
                matched = schemaList.find((s) => {
                  const sGroup = clean(s.group)
                  const sTitle = clean(s.title)
                  if (
                    sGroup !== cleanGroup &&
                    !sGroup.includes(cleanGroup) &&
                    !cleanGroup.includes(sGroup)
                  ) {
                    return false
                  }
                  const isSDate = sTitle.includes('ngày') || sTitle.includes('date')
                  const isColDate = cleanTitle.includes('ngày') || cleanTitle.includes('date')
                  if (isSDate !== isColDate) return false

                  return (
                    sTitle.length > 3 &&
                    cleanTitle.length > 3 &&
                    (sTitle.includes(cleanTitle) || cleanTitle.includes(sTitle))
                  )
                })
              }
            }

            // G. Khớp Title trên toàn bộ Schema (loại trừ các cột trùng tên cần phân định thứ tự như 'Họ tên')
            if (!matched) {
              // G1. Ưu tiên TUYỆT ĐỐI khớp chính xác Title 100% trên toàn bộ Schema
              matched = schemaList.find((s) => {
                const sTitle = clean(s.title)
                if (sTitle === 'họ tên' || sTitle === 'ho ten') return false
                const cleanSTitleNoParen = sTitle.replace(/\s*\(.*?\)/g, '').trim()
                const cleanColTitleNoParen = cleanTitle.replace(/\s*\(.*?\)/g, '').trim()
                return (
                  sTitle === cleanTitle ||
                  (cleanSTitleNoParen.length > 2 && cleanSTitleNoParen === cleanColTitleNoParen)
                )
              })

              // G2. Chỉ khi không có cột nào khớp chính xác thì mới xét khớp tương đối (và chặn nhầm lẫn Ngày vs Giờ)
              if (!matched) {
                matched = schemaList.find((s) => {
                  const sTitle = clean(s.title)
                  if (sTitle === 'họ tên' || sTitle === 'ho ten') return false
                  const isSDate = sTitle.includes('ngày') || sTitle.includes('date')
                  const isColDate = cleanTitle.includes('ngày') || cleanTitle.includes('date')
                  if (isSDate !== isColDate) return false

                  return (
                    sTitle.length > 3 &&
                    cleanTitle.length > 3 &&
                    (sTitle.includes(cleanTitle) || cleanTitle.includes(sTitle))
                  )
                })
              }
            }

            if (matched) {
              resolvedKey = matched.key
              resolvedTitle = matched.title || colTitle
              if (!colGroup && matched.group) {
                colGroup = matched.group
              }
            }
          }

          // 3. Quy tắc nhận diện bổ sung cho các cột đặc biệt (Phiếu duyệt, Tự động hóa)
          if (!resolvedKey) {
            const titleLower = cleanTitle
            const groupLower = cleanGroup

            if (titleLower.includes('họ tên') || titleLower.includes('technician')) {
              technicianCounter++
              if (
                groupLower.includes('chính') ||
                titleLower.includes('chính') ||
                technicianCounter === 1
              ) {
                resolvedKey = 'LeadTechnicianName'
                resolvedTitle = 'Họ tên'
                colGroup = colGroup || 'Thợ chính'
              } else if (
                groupLower.includes('phụ 1') ||
                titleLower.includes('phụ 1') ||
                technicianCounter === 2
              ) {
                resolvedKey = 'AssistantWorker1Name'
                resolvedTitle = 'Họ tên'
                colGroup = colGroup || 'Thợ phụ 1'
              } else if (
                groupLower.includes('phụ 2') ||
                titleLower.includes('phụ 2') ||
                technicianCounter === 3
              ) {
                resolvedKey = 'AssistantWorker2Name'
                resolvedTitle = 'Họ tên'
                colGroup = colGroup || 'Thợ phụ 2'
              } else {
                resolvedKey = `AssistantWorker${technicianCounter - 1}Name`
                resolvedTitle = 'Họ tên'
                colGroup = colGroup || `Thợ phụ ${technicianCounter - 1}`
              }
            } else if (
              titleLower.includes('mã phiếu') ||
              titleLower.includes('số phiếu tk') ||
              titleLower.includes('phiếu thống kê') ||
              titleLower === 'số phiếu'
            ) {
              resolvedKey =
                fileType === ARCHITECTURE_FILE_TYPES.MES_APPROVAL ? 'SlipNo' : 'StatSlipNo'
              resolvedTitle =
                fileType === ARCHITECTURE_FILE_TYPES.MES_APPROVAL ? 'Mã phiếu' : 'Số phiếu thống kê'
            } else if (
              titleLower.includes('mã lệnh thống kê bravo') ||
              titleLower.includes('thống kê bravo')
            ) {
              resolvedKey = 'BravoStatCode'
              resolvedTitle = 'Mã lệnh thống kê Bravo'
            } else if (
              titleLower.includes('thời gian duyệt phiếu ở mes') ||
              titleLower.includes('thời gian duyệt ở mes')
            ) {
              resolvedKey =
                fileType === ARCHITECTURE_FILE_TYPES.MES_APPROVAL
                  ? 'ApprovedTime'
                  : 'MesApprovedTime'
              resolvedTitle =
                fileType === ARCHITECTURE_FILE_TYPES.MES_APPROVAL
                  ? 'Thời gian duyệt'
                  : 'Thời gian duyệt phiếu ở MES'
            } else if (
              titleLower.includes('người phát hành') ||
              titleLower.includes('người tạo lệnh') ||
              titleLower.includes('người lập lệnh') ||
              titleLower.includes('pic điều phối') ||
              titleLower.includes('pic đp') ||
              titleLower.includes('pic dp')
            ) {
              resolvedKey = 'OrderIssuer'
              resolvedTitle = 'Người phát hành lệnh thao tác'
              colGroup = colGroup || 'THÔNG TIN PHÁT HÀNH LỆNH THAO TÁC'
            } else if (
              titleLower.includes('ngày phát hành') ||
              titleLower.includes('ngày tạo lệnh')
            ) {
              resolvedKey = 'OpOrderReleaseDate'
              resolvedTitle = 'Ngày phát hành lệnh thao tác'
              colGroup = colGroup || 'THÔNG TIN PHÁT HÀNH LỆNH THAO TÁC'
            } else {
              resolvedKey = colTitle.replace(/[\s/\\()+-]+/g, '_')
            }
          }

          if (seenKeys[resolvedKey]) {
            resolvedKey = `${resolvedKey}_${c}`
          }
          seenKeys[resolvedKey] = true

          headerDefs.push({
            origIndex: c,
            key: resolvedKey,
            title: resolvedTitle,
            group: colGroup
          })
        }

        const finalColumns = headerDefs.map((h) => ({
          id: h.key,
          key: h.key,
          title: h.title,
          group: h.group || ''
        }))

        onProgress?.({
          step: 'COLUMNS_READY',
          percent: 50,
          detectedColumns: finalColumns.length,
          columns: finalColumns,
          message: `Đã xác định ${finalColumns.length} cột tiêu đề. Bắt đầu xử lý dữ liệu...`
        })

        // ── 3. TRÍCH XUẤT STREAM DỮ LIỆU TỪNG DÒNG (TIẾT KIỆM BỘ NHỚ RAM 100%) ──
        const parsedRows = []
        const totalRowsToScan = range.e.r - dataStartRow + 1

        for (let r = dataStartRow; r <= range.e.r; r++) {
          const rowObj = {}
          let hasRowData = false

          for (let i = 0; i < headerDefs.length; i++) {
            const { origIndex, key, title, group } = headerDefs[i]
            const addr = XLSX.utils.encode_cell({ r, c: origIndex })
            const cell = worksheet[addr]
            let val = ''

            if (cell && cell.v !== undefined && cell.v !== null && cell.v !== '') {
              hasRowData = true
              const rawVal = cell.v
              val = cell.w !== undefined ? cell.w : cell.v
              if (typeof val === 'string') {
                val = val.trim()
              }

              const titleLower = title.toLowerCase()
              const keyLower = key.toLowerCase()

              const isNumericOrQtyCol =
                titleLower.includes('số lượng') ||
                titleLower.includes('sl ') ||
                titleLower.startsWith('sl') ||
                titleLower.includes('mét') ||
                titleLower.includes('trọng lượng') ||
                titleLower.includes('đơn giá') ||
                titleLower.includes('thành tiền') ||
                titleLower.includes('tỷ lệ') ||
                titleLower.includes('số dao') ||
                titleLower.includes('số part') ||
                titleLower.includes('số lỗ') ||
                titleLower.includes('rộng') ||
                titleLower.includes('dài') ||
                titleLower.includes('cao') ||
                titleLower.includes('tổng tg hao phí') ||
                titleLower.includes('hao phí') ||
                titleLower.includes('chờ nvl') ||
                titleLower.includes('chuẩn bị') ||
                titleLower.includes('sửa file') ||
                titleLower.includes('tổng thời gian') ||
                titleLower.includes('thời gian sx đm') ||
                titleLower.includes('thời gian thay bài') ||
                titleLower.includes('thời gian chỉnh bài') ||
                titleLower.includes('năng suất') ||
                titleLower.includes('capa') ||
                titleLower.includes('downtime') ||
                titleLower.includes('định mức') ||
                titleLower.includes('phút') ||
                titleLower.includes('(phút)') ||
                keyLower.includes('qty') ||
                keyLower.includes('count') ||
                keyLower.includes('weight') ||
                keyLower.includes('meters') ||
                keyLower.includes('rate') ||
                keyLower.includes('width') ||
                keyLower.includes('length') ||
                keyLower.includes('height') ||
                keyLower.includes('minutes') ||
                keyLower.includes('hours') ||
                keyLower.includes('capa')

              const isDateOrTimeCol =
                !isNumericOrQtyCol &&
                (titleLower.includes('ngày') ||
                  titleLower.includes('thời gian') ||
                  titleLower.includes('bắt đầu') ||
                  titleLower.includes('kết thúc') ||
                  titleLower.includes('giờ') ||
                  keyLower.includes('date') ||
                  keyLower.includes('time') ||
                  keyLower.includes('created') ||
                  keyLower.includes('approval') ||
                  keyLower.includes('approved') ||
                  keyLower.includes('perform'))

              if (!isNumericOrQtyCol && (isDateOrTimeCol || cell.t === 'd')) {
                // Ưu tiên rawVal (cell.v) nếu là number hoặc Date để lấy đủ giờ:phút:giây
                const valToFormat =
                  typeof rawVal === 'number' || rawVal instanceof Date ? rawVal : val
                val = formatVietnamDateTimeValue(valToFormat, `${key}_${title}`, fileType)
              }
            }

            rowObj[key] = val

            const nonUniqueTitles = ['Họ tên', 'Mã thợ']
            if (title && title !== key && !nonUniqueTitles.includes(title)) {
              if (rowObj[title] === undefined) {
                rowObj[title] = val
              }
            }
            if (group && title) {
              rowObj[`${group} - ${title}`] = val
              if (title === 'Họ tên' || title === 'Mã thợ') {
                rowObj[group] = val
              }
            }
          }

          if (hasRowData) {
            if (fileType !== 'mes_approval' && fileType !== ARCHITECTURE_FILE_TYPES.MES_APPROVAL) {
              normalizeRowOperationalTimePair(rowObj)
            }

            // Đồng bộ 2 chiều Key tiếng Anh <-> Tiêu đề tiếng Việt cho các cột Lệnh công đoạn & Lệnh thao tác
            if (rowObj.StageTargetQty !== undefined) {
              rowObj['SL cần đạt (CĐ)'] = rowObj.StageTargetQty
              rowObj['Số lượng cần đạt (CĐ)'] = rowObj.StageTargetQty
              rowObj['Số lượng cần đạt'] = rowObj['Số lượng cần đạt'] ?? rowObj.StageTargetQty
            }
            if (rowObj.StagePlannedQty !== undefined) {
              rowObj['SL cần sản xuất (CĐ)'] = rowObj.StagePlannedQty
              rowObj['Số lượng cần sản xuất (CĐ)'] = rowObj.StagePlannedQty
              rowObj['Số lượng cần sản xuất'] =
                rowObj['Số lượng cần sản xuất'] ?? rowObj.StagePlannedQty
            }
            if (rowObj.StageOrderReleaseDate !== undefined) {
              rowObj['Ngày phát hành lệnh CĐ'] = rowObj.StageOrderReleaseDate
              rowObj['Ngày phát hành lệnh (CĐ)'] = rowObj.StageOrderReleaseDate
            }
            if (rowObj.StageOrderNo !== undefined) {
              rowObj['Số lệnh công đoạn'] = rowObj.StageOrderNo
            }
            if (rowObj.StageOrderDate !== undefined) {
              rowObj['Ngày lệnh công đoạn'] = rowObj.StageOrderDate
            }
            if (rowObj.OpTargetQty !== undefined) {
              rowObj['SL cần đạt (TT)'] = rowObj.OpTargetQty
              rowObj['Số lượng cần đạt (TT)'] = rowObj.OpTargetQty
            }
            if (rowObj.OpPlannedQty !== undefined) {
              rowObj['SL cần sản xuất (TT)'] = rowObj.OpPlannedQty
              rowObj['Số lượng cần sản xuất (TT)'] = rowObj.OpPlannedQty
            }
            if (rowObj.OpOrderReleaseDate !== undefined) {
              rowObj['Ngày phát hành lệnh TT'] = rowObj.OpOrderReleaseDate
              rowObj['Ngày phát hành lệnh (TT)'] = rowObj.OpOrderReleaseDate
            }
            if (rowObj.OpUnit !== undefined) {
              rowObj['Đvt'] = rowObj.OpUnit
            }

            if (!rowObj.IdSeq) {
              rowObj.IdSeq =
                typeof crypto !== 'undefined' && crypto.randomUUID
                  ? crypto.randomUUID()
                  : `ROW-${Date.now()}-${r}`
            }
            if (rowObj.RowVersion === undefined) {
              rowObj.RowVersion = 1
            }
            if (!rowObj.CreatedAt) {
              rowObj.CreatedAt = new Date().toISOString()
            }
            if (!rowObj.WorkingTag && !rowObj.Status) {
              rowObj.WorkingTag = 'A'
            }
            parsedRows.push(rowObj)
          }

          // Nhường nhịp sự kiện cho UI & Garbage Collection mỗi 2,000 dòng
          if (r % 2000 === 0) {
            const currentPercent = Math.min(
              90,
              Math.round(50 + (38 * (r - dataStartRow)) / totalRowsToScan)
            )
            onProgress?.({
              step: 'STREAMING_DATA',
              percent: currentPercent,
              totalRows: parsedRows.length,
              message: `Đang xử lý ${parsedRows.length.toLocaleString('vi-VN')} dòng dữ liệu...`
            })
            await new Promise((res) => setTimeout(res, 0))
          }
        }

        onProgress?.({
          step: 'DATA_READY',
          percent: 92,
          detectedColumns: finalColumns.length,
          totalRows: parsedRows.length,
          message: `Đang hoàn tất xử lý ${parsedRows.length.toLocaleString('vi-VN')} dòng dữ liệu...`
        })

        // Xóa các ô trong worksheet để giải phóng bộ nhớ ngay lập tức
        for (const k of Object.keys(worksheet)) {
          if (k[0] !== '!') delete worksheet[k]
        }

        resolve({
          fileName: file.name,
          fileSize: file.size,
          rowCount: parsedRows.length,
          columns: finalColumns,
          data: parsedRows,
          uploadedAt: new Date().toISOString()
        })
      } catch (err) {
        console.error('Lỗi đọc file Excel:', err)
        reject(new Error(`Không thể đọc file: ${err.message}`))
      }
    }

    reader.onerror = () => reject(new Error('Đọc file thất bại'))
    reader.readAsArrayBuffer(file)
  })
}

/**
 * Trích xuất nhanh ma trận raw và thông tin header để phục vụ Modal Ánh Xạ Cột
 */
export const inspectUploadedFile = async (file, fileType) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target.result)
        const isHtml = isHtmlOrXmlSpreadsheet(data)
        const workbook = XLSX.read(data, {
          type: 'array',
          raw: isHtml ? true : false,
          cellNF: true,
          cellDates: false,
          cellText: true
        })

        let worksheet = null
        for (const sName of workbook.SheetNames) {
          const ws = workbook.Sheets[sName]
          if (ws && ws['!ref']) {
            const tempRows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: '' })
            if (tempRows.length > 0) {
              worksheet = ws
              break
            }
          }
        }
        if (!worksheet || !worksheet['!ref']) {
          worksheet = workbook.Sheets[workbook.SheetNames[0]]
        }

        const range = XLSX.utils.decode_range(worksheet?.['!ref'] || 'A1:Z50')
        const previewLimit = Math.min(range.e.r, range.s.r + 100)
        const rawRows = []
        for (let r = range.s.r; r <= previewLimit; r++) {
          const row = []
          for (let c = range.s.c; c <= range.e.c; c++) {
            const addr = XLSX.utils.encode_cell({ r, c })
            const cell = worksheet[addr]
            row.push(
              cell
                ? cell.w !== undefined
                  ? String(cell.w).trim()
                  : String(cell.v ?? '').trim()
                : ''
            )
          }
          rawRows.push(row)
        }

        const tabDef = TAB_DEFINITIONS.find((t) => t.id === fileType)
        const schemaList =
          tabDef?.columnsSchema ||
          (fileType === 'unfinished_op'
            ? UNFINISHED_OP_COLUMN_SCHEMA
            : fileType === 'summary_op'
              ? SUMMARY_OP_COLUMN_SCHEMA
              : fileType === 'mes_approval'
                ? MES_APPROVAL_COLUMN_SCHEMA
                : STAT_REPORT_COLUMN_SCHEMA)

        let detectedHeaderRow = 0
        let bestScore = -1
        const maxScan = Math.min(25, rawRows.length)
        for (let r = 0; r < maxScan; r++) {
          const row = rawRows[r]
          if (!Array.isArray(row)) continue
          const textCells = row.filter((c) => typeof c === 'string' && c.trim().length > 0)
          let matchCount = 0
          textCells.forEach((text) => {
            const lower = text.toLowerCase().trim()
            if (HEADER_KEYWORDS.some((kw) => lower.includes(kw))) {
              matchCount++
            }
          })
          const score = matchCount * 4 + textCells.length
          if (score > bestScore && (matchCount >= 1 || textCells.length >= 3)) {
            bestScore = score
            detectedHeaderRow = r
          }
        }

        resolve({
          rawMatrix: rawRows.slice(0, 100),
          detectedHeaderRow,
          detectedDataStartRow: detectedHeaderRow + 1,
          availableSchema: schemaList,
          tabTitle: tabDef?.title || fileType
        })
      } catch (err) {
        reject(err)
      }
    }
    reader.onerror = () => reject(new Error('Không thể đọc file để phân tích'))
    reader.readAsArrayBuffer(file)
  })
}

import dayjs from 'dayjs'
import customParseFormat from 'dayjs/plugin/customParseFormat.js'
import { STAT_REPORT_COLUMN_SCHEMA } from '../constants/calcConstants.js'
import { normalizeRowOperationalTimePair } from './fileParsers.js'

dayjs.extend(customParseFormat)

/**
 * Phân tích chuỗi giờ thành số phút trong ngày (0 - 1439)
 * Hỗ trợ các định dạng: "3:03", "03:03", "18:03:00", "06/10/26 18:03", "2026-10-06 18:03"
 */
function parseTimeToMinutesInDay(val) {
  if (val === undefined || val === null || val === '') return null

  if (typeof val === 'number') {
    if (val >= 0 && val <= 1) {
      return val * 1440
    }
    if (val > 1) {
      const frac = val - Math.floor(val)
      return frac * 1440
    }
    return val
  }

  const str = String(val).trim()
  if (!str) return null

  // Format số float dạng chuỗi
  if (/^\d+(\.\d+)?$/.test(str)) {
    const num = parseFloat(str)
    if (!isNaN(num)) {
      if (num >= 0 && num <= 1) return num * 1440
      if (num > 1) return (num - Math.floor(num)) * 1440
    }
  }

  // Format "HH:mm" hoặc "H:mm" hoặc "HH:mm:ss" (kèm AM/PM/SA/CH)
  const timeMatch = str.match(/(?:^|\s)(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\s*(AM|PM|SA|CH))?/i)
  if (timeMatch) {
    let hours = parseInt(timeMatch[1], 10)
    const minutes = parseInt(timeMatch[2], 10)
    const seconds = timeMatch[3] ? parseInt(timeMatch[3], 10) : 0
    const ampm = timeMatch[4] ? timeMatch[4].toUpperCase() : ''
    if ((ampm === 'PM' || ampm === 'CH') && hours < 12) hours += 12
    if ((ampm === 'AM' || ampm === 'SA') && hours === 12) hours = 0
    return hours * 60 + minutes + seconds / 60
  }

  return null
}

/**
 * Phân tích chuỗi ngày giờ thành unix timestamp (milliseconds)
 */
function parseFullDateTime(val) {
  if (val === undefined || val === null || val === '') return null

  if (typeof val === 'number') {
    if (val > 25569) {
      return (val - 25569) * 86400 * 1000
    }
  }

  const str = String(val).trim()
  if (!str) return null

  // Custom regex parse đa dạng định dạng ngày giờ Việt Nam & ERP (kèm AM/PM/SA/CH)
  const m = str.match(
    /(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM|SA|CH)?)?/i
  )
  if (m) {
    const day = parseInt(m[1], 10)
    const month = parseInt(m[2], 10)
    let year = parseInt(m[3], 10)
    if (year < 100) year += 2000
    let hours = m[4] ? parseInt(m[4], 10) : 0
    const mins = m[5] ? parseInt(m[5], 10) : 0
    const secs = m[6] ? parseInt(m[6], 10) : 0
    const ampm = m[7] ? m[7].toUpperCase() : ''
    if ((ampm === 'PM' || ampm === 'CH') && hours < 12) hours += 12
    if ((ampm === 'AM' || ampm === 'SA') && hours === 12) hours = 0

    return new Date(year, month - 1, day, hours, mins, secs).getTime()
  }

  // Thử các format dayjs
  const formats = [
    'DD/MM/YYYY HH:mm:ss',
    'DD/MM/YYYY HH:mm',
    'DD/MM/YY HH:mm:ss',
    'DD/MM/YY HH:mm',
    'YYYY-MM-DD HH:mm:ss',
    'YYYY-MM-DD HH:mm'
  ]

  for (const fmt of formats) {
    const d = dayjs(str, fmt, true)
    if (d.isValid()) return d.valueOf()
  }

  const d = dayjs(str)
  if (d.isValid()) return d.valueOf()

  return null
}

/**
 * Ghép chuỗi ngày và giờ thành định dạng hoàn chỉnh dd/MM/yy HH:mm:ss
 */
export function combineDateAndTime(dateVal, timeVal) {
  const dStr = dateVal !== undefined && dateVal !== null ? String(dateVal).trim() : ''
  const tStr = timeVal !== undefined && timeVal !== null ? String(timeVal).trim() : ''

  if (!dStr && !tStr) return ''
  if (!dStr) return tStr
  if (!tStr) return dStr

  // Nếu tStr đã bao gồm ngày tháng (chứa '/' hoặc '-' cùng khoảng trắng và giờ)
  if (/\d{1,4}[-/]\d{1,2}[-/]\d{2,4}\s+\d{1,2}:\d{2}/.test(tStr)) {
    return tStr
  }

  // Nếu dStr đã bao gồm cả giờ
  if (/\d{1,4}[-/]\d{1,2}[-/]\d{2,4}\s+\d{1,2}:\d{2}/.test(dStr)) {
    return dStr
  }

  return `${dStr} ${tStr}`
}

/**
 * Tính tổng thời gian sản xuất thực tế (phút) = (Ngày kết thúc + Giờ kết thúc) - (Ngày bắt đầu + Giờ bắt đầu) - Hao phí
 */
export function calcTotalProductionMinutes(
  startDateVal,
  startTimeVal,
  endDateVal,
  endTimeVal,
  downtime = 0
) {
  const startFull = combineDateAndTime(startDateVal, startTimeVal)
  const endFull = combineDateAndTime(endDateVal, endTimeVal)

  const startTs = parseFullDateTime(startFull)
  const endTs = parseFullDateTime(endFull)

  let diffMin = null
  if (startTs !== null && endTs !== null) {
    diffMin = (endTs - startTs) / 60000
    if (diffMin < 0) {
      diffMin += 1440
    }
  } else {
    const sMin = parseTimeToMinutesInDay(startTimeVal)
    const eMin = parseTimeToMinutesInDay(endTimeVal)
    if (sMin !== null && eMin !== null) {
      diffMin = eMin - sMin
      if (diffMin < 0) diffMin += 1440
    }
  }

  if (diffMin !== null) {
    const dt = parseFloat(String(downtime ?? 0).replace(/,/g, '')) || 0
    const rawRunTime = diffMin - dt
    return Math.max(0, Number(rawRunTime.toFixed(2)))
  }

  return null
}

/**
 * Định dạng số giây chênh lệch thành chuỗi "hh:mm:ss" (luôn lấy giá trị dương)
 */
function formatSecondsToHms(diffSec) {
  if (diffSec === null || diffSec === undefined || diffSec === '') return ''
  if (typeof diffSec === 'string') {
    const s = diffSec.trim()
    if (s.includes(':')) return s
  }
  if (isNaN(diffSec)) return ''

  const absSec = Math.abs(Math.round(diffSec))

  const h = Math.floor(absSec / 3600)
  const m = Math.floor((absSec % 3600) / 60)
  const s = absSec % 60

  const pad = (n) => String(n).padStart(2, '0')
  return `${pad(h)}:${pad(m)}:${pad(s)}`
}

/**
 * Chuẩn hóa số lệnh thao tác & mã phiếu thống kê để khớp chính xác giữa các sheet
 */
function normalizeCode(val) {
  if (val === undefined || val === null) return ''
  return String(val).trim().toUpperCase()
}

/**
 * Tạo danh sách các khóa tra cứu mở rộng (nguyên bản, bỏ ký tự đặc biệt, bỏ số 0 ở đầu)
 */
export function getLookupKeys(code) {
  if (!code) return []
  const norm = normalizeCode(code)
  const clean = norm.replace(/[^A-Z0-9]/g, '')
  const keys = new Set([norm])
  if (clean) {
    keys.add(clean)
    const noLeadingZero = clean.replace(/^0+/, '')
    if (noLeadingZero) keys.add(noLeadingZero)
  }
  return Array.from(keys)
}

/**
 * Trích xuất Số phiếu thống kê / Mã thống kê / Phiếu TK / Số phiếu duyệt từ đối tượng dòng dữ liệu
 */
export function extractTicketOrSlipCode(row) {
  if (!row || typeof row !== 'object') return ''

  // 1. Kiểm tra danh sách các trường thuộc tính phổ biến
  const directCandidates = [
    row.BravoStatCode,
    row.BravoStatSlipNo,
    row['Mã lệnh thống kê Bravo'],
    row['Mã lệnh thống kê bravo'],
    row['Mã lệnh thống kê'],
    row['Mã thống kê Bravo'],
    row['Mã thống kê bravo'],
    row['Mã lệnh TK Bravo'],
    row['Mã TK Bravo'],
    row.StatSlipNo,
    row.ApprovalSlipNo,
    row.TicketNo,
    row.StatTicketNo,
    row.SlipNo,
    row.StatCode,
    row.RegCode,
    row['Phiếu TK'],
    row['Phiếu tk'],
    row['phiếu tk'],
    row['Phiếu Tk'],
    row['Mã TK'],
    row['Mã tk'],
    row['mã tk'],
    row['Mã Thống kê'],
    row['Mã Thống Kê'],
    row['Mã thống kê'],
    row['mã thống kê'],
    row['Số phiếu thống kê'],
    row['Số phiếu TK'],
    row['Số phiếu tk'],
    row['Số phiếu'],
    row['Số thống kê'],
    row['Số TK'],
    row['Số tk'],
    row['Mã phiếu'],
    row['Mã phiếu TK'],
    row['Mã phiếu tk'],
    row['Mã phiếu thống kê'],
    row['Số phiếu duyệt'],
    row['Mã phiếu duyệt'],
    row['Phiếu thống kê'],
    row['Phiếu duyệt'],
    row.Phiếu_TK,
    row.Mã_TK,
    row.Mã_thống_kê,
    row.Mã_Thống_kê,
    row.Số_phiếu_TK,
    row.Số_phiếu_thống_kê,
    row.Số_phiếu_duyệt
  ]

  for (const c of directCandidates) {
    if (c !== undefined && c !== null && String(c).trim() !== '') {
      return normalizeCode(c)
    }
  }

  // 2. Quét động các thuộc tính nếu cột có tên đặc thù
  for (const [k, v] of Object.entries(row)) {
    if (v === undefined || v === null || String(v).trim() === '') continue
    const cleanKey = k.toLowerCase().replace(/[_\s\-\r\n\t]+/g, '')
    if (
      cleanKey.includes('phieutk') ||
      cleanKey.includes('matk') ||
      cleanKey.includes('sotk') ||
      cleanKey.includes('mathongke') ||
      cleanKey.includes('sothongke') ||
      cleanKey.includes('phieuthongke') ||
      cleanKey.includes('phieuduyet') ||
      cleanKey.includes('statslipno') ||
      cleanKey.includes('approvalslipno') ||
      cleanKey.includes('ticketno') ||
      cleanKey.includes('slipno') ||
      cleanKey.includes('statcode') ||
      cleanKey.includes('regcode') ||
      cleanKey.includes('sophieutk') ||
      cleanKey.includes('sophieuthongke') ||
      cleanKey.includes('sophieuduyet') ||
      cleanKey.includes('maphieutk') ||
      cleanKey.includes('maphieu') ||
      (cleanKey.includes('sophieu') && !cleanKey.includes('xuat') && !cleanKey.includes('nhap'))
    ) {
      return normalizeCode(v)
    }
  }

  return ''
}

/**
 * Trích xuất Thời gian duyệt từ đối tượng dòng duyệt MES
 */
export function extractMesApprovedTime(row) {
  if (!row || typeof row !== 'object') return ''

  const directCandidates = [
    row.ApprovedTime,
    row.ApprovalTime,
    row.MesApprovedTime,
    row.ApprovedDate,
    row.ApprovalDate,
    row.ApproveTime,
    row.TimeApproved,
    row['Thời gian duyệt'],
    row['Thời gian duyệt ở MES'],
    row['Thời gian duyệt phiếu ở MES'],
    row['Thời gian duyệt phiếu'],
    row['Thời gian phê duyệt'],
    row['Thời gian duyệt MES'],
    row['TG duyệt'],
    row['TG duyệt ở MES'],
    row['Ngày duyệt'],
    row['Ngày phê duyệt'],
    row['Ngày duyệt phiếu'],
    row['Ngày duyệt ở MES'],
    row['Giờ duyệt'],
    row.Thời_gian_duyệt,
    row.Thời_gian_duyệt_ở_MES,
    row.Thời_gian_duyệt_phiếu_ở_MES,
    row.TG_duyệt,
    row.TG_duyệt_ở_MES
  ]

  for (const c of directCandidates) {
    if (c !== undefined && c !== null && String(c).trim() !== '') {
      return String(c).trim()
    }
  }

  for (const [k, v] of Object.entries(row)) {
    if (v === undefined || v === null || String(v).trim() === '') continue
    const cleanKey = k.toLowerCase().replace(/[_\s\-\r\n\t]+/g, '')
    if (
      cleanKey.includes('approvedtime') ||
      cleanKey.includes('approvaltime') ||
      cleanKey.includes('mesapprovedtime') ||
      cleanKey.includes('thoigianduyet') ||
      cleanKey.includes('tgduyet') ||
      cleanKey.includes('ngayduyet') ||
      cleanKey.includes('thoigianpheduyet') ||
      cleanKey.includes('ngaypheduyet') ||
      cleanKey.includes('gioduyet') ||
      (cleanKey.includes('duyet') &&
        (cleanKey.includes('time') ||
          cleanKey.includes('date') ||
          cleanKey.includes('thoigian') ||
          cleanKey.includes('ngay') ||
          cleanKey.includes('gio') ||
          cleanKey.includes('tg')))
    ) {
      return String(v).trim()
    }
  }

  return ''
}

/**
 * Module tính toán TKSX (Thống kê sản xuất) và đối soát với Duyệt sản lượng MES & KHSX Lệnh thao tác
 */
export const calculateTKSX = (files = {}, masterInfo = {}, planResult = null) => {
  const calcVersion = masterInfo.calcVersion || masterInfo.version || masterInfo.Version || 'V1'
  const regCode = masterInfo.regCode || masterInfo.RegCode || files.masterInfo?.regCode || ''
  const statReportData = files.stat_report?.data || []
  const summaryOpData = files.summary_op?.data || []
  const unfinishedOpData = files.unfinished_op?.data || []
  const mesApprovalData = files.mes_approval?.data || []

  // ── 1. TẠO TỪ ĐIỂN TRA CỨU KẾ HOẠCH LỆNH THAO TÁC (TỪ KẾT QUẢ KHSX) ──
  const opOrderPlanMap = new Map()

  if (planResult && typeof planResult === 'object') {
    // Khi đã có kết quả tính KHSX (kể cả khi 0 dòng) -> chỉ lấy đúng các lệnh có trong KHSX của ngày báo cáo đó
    const planRows = planResult.calculatedRows || []
    planRows.forEach((row) => {
      const code = normalizeCode(
        row.OperationOrderNo ??
          row['Số lệnh thao tác'] ??
          row['Số lệnh TT'] ??
          row['Lệnh thao tác'] ??
          row.OperationOrder ??
          row.OperationNo ??
          ''
      )
      if (code) {
        const keys = getLookupKeys(code)
        keys.forEach((k) => opOrderPlanMap.set(k, 'Có trong KHSX'))
      }
    })
  } else {
    // Chỉ khi không có đối tượng planResult truyền vào mới tra cứu từ dữ liệu thô
    summaryOpData.forEach((row) => {
      const code = normalizeCode(
        row.OperationOrderNo ??
          row['Lệnh thao tác'] ??
          row['Số lệnh thao tác'] ??
          row['Số lệnh TT'] ??
          row.OperationOrder ??
          ''
      )
      if (code) {
        const keys = getLookupKeys(code)
        keys.forEach((k) => opOrderPlanMap.set(k, 'Có trong KHSX'))
      }
    })
  }

  // ── 2. TẠO TỪ ĐIỂN TRA CỨU THỜI GIAN DUYỆT MES (TỪ FILE 4) ──
  // Mục đích: Phục vụ Cột 94 (Thời gian duyệt phiếu ở MES) theo Phiếu TK / Mã thống kê
  const mesApprovalMap = new Map()

  mesApprovalData.forEach((row) => {
    const approvedTime = extractMesApprovedTime(row)
    if (!approvedTime) return

    // 1. Khóa chính: Mã lệnh thống kê Bravo (VD: TK2609-453717, TK2609-031222)
    const bravoCode =
      row.BravoStatCode ??
      row.BravoStatSlipNo ??
      row['Mã lệnh thống kê Bravo'] ??
      row['Mã lệnh thống kê bravo'] ??
      row['Mã lệnh thống kê'] ??
      row['Mã thống kê Bravo'] ??
      row['Mã thống kê'] ??
      ''
    if (bravoCode) {
      const keys = getLookupKeys(bravoCode)
      keys.forEach((k) => mesApprovalMap.set(k, approvedTime))
    }

    // 2. Khóa phụ: Mã phiếu duyệt MES (VD: SLIP-TH-GS1-260929-049)
    const slipNo =
      row.SlipNo ??
      row.ApprovalSlipNo ??
      row['Mã phiếu'] ??
      row['Số phiếu duyệt'] ??
      extractTicketOrSlipCode(row)
    if (slipNo) {
      const keys = getLookupKeys(slipNo)
      keys.forEach((k) => mesApprovalMap.set(k, approvedTime))
    }

    // 3. Khóa dự phòng: Mã lệnh thao tác (VD: CD03-0926-0364(234))
    const opOrderNo = normalizeCode(row.OperationOrderNo ?? row['Mã lệnh thao tác'] ?? '')
    if (opOrderNo) {
      const keys = getLookupKeys(opOrderNo)
      keys.forEach((k) => {
        if (!mesApprovalMap.has(k)) mesApprovalMap.set(k, approvedTime)
      })
    }
  })

  // ── 3. ĐẾM TẦN SUẤT SỐ PHIẾU THỐNG KÊ ĐỂ TÌM PHIẾU TRÙNG (CỘT 96) ──
  const slipCountMap = new Map()
  statReportData.forEach((row) => {
    const slipNo = extractTicketOrSlipCode(row)
    if (slipNo) {
      slipCountMap.set(slipNo, (slipCountMap.get(slipNo) || 0) + 1)
    }
  })

  // ── 4. TÍNH TOÁN CHI TIẾT TỪNG DÒNG (98 CỘT CHUẨN TKSX) ──
  let totalProducedQty = 0
  let totalQualifiedQty = 0
  let totalDefectQty = 0
  let totalDowntimeMinutes = 0
  let totalSyncDelaySec = 0
  let syncCount = 0
  let insidePlanCount = 0
  let outsidePlanCount = 0
  let mesUserCount = 0
  let bravoUserCount = 0
  let duplicateSlipCount = 0
  let mesMatchedCount = 0

  const statByMachine = {}
  const statByTeam = {}
  const statByTechnician = {}

  const calculatedRows = statReportData.map((row, index) => {
    const rowObj = { ...row }
    normalizeRowOperationalTimePair(rowObj)

    // Lấy các trường dữ liệu cơ bản
    const produced =
      parseFloat(
        String(
          rowObj.ProducedQty ?? rowObj['Số lượng sản xuất'] ?? rowObj['Số lượng thực hiện'] ?? 0
        ).replace(/,/g, '')
      ) || 0
    const qualified =
      parseFloat(String(rowObj.QualifiedQty ?? rowObj['Số lượng đạt'] ?? 0).replace(/,/g, '')) || 0
    const defect =
      parseFloat(String(rowObj.DefectQty ?? rowObj['Số lượng lỗi'] ?? 0).replace(/,/g, '')) || 0
    const downtime =
      parseFloat(
        String(
          rowObj.TotalDowntimeMinutes ??
            rowObj['Tổng tg hao phí\r\n(5)=1+2+3+4'] ??
            rowObj['Tổng tg hao phí\n(5)=1+2+3+4'] ??
            rowObj['Tổng tg hao phí (5)=1+2+3+4'] ??
            rowObj['Tổng tg hao phí'] ??
            0
        ).replace(/,/g, '')
      ) || 0

    // Cột 26 (Z): Bắt đầu & Cột 27 (AA): Kết thúc (Ưu tiên lấy thông tin thực tế thống kê nếu có)
    const startVal =
      rowObj.ActualStartTime ??
      rowObj['Thời gian bắt đầu (8)'] ??
      rowObj['THÔNG TIN THỐNG KÊ - Thời gian bắt đầu (8)'] ??
      rowObj.StartTime ??
      rowObj['Bắt đầu'] ??
      rowObj['Thời gian bắt đầu'] ??
      rowObj['Thời gian bắt đầu (5)'] ??
      rowObj['Thời gian bắt đầu\r\n(5)'] ??
      rowObj['Thời gian bắt đầu\n(5)'] ??
      rowObj['TG bắt đầu'] ??
      rowObj['Bat dau'] ??
      ''
    const endVal =
      rowObj.ActualEndTime ??
      rowObj['Thời gian kết thúc (9)'] ??
      rowObj['THÔNG TIN THỐNG KÊ - Thời gian kết thúc (9)'] ??
      rowObj.EndTime ??
      rowObj['Kết thúc'] ??
      rowObj['Thời gian kết thúc'] ??
      rowObj['Thời gian kết thúc (6)'] ??
      rowObj['Thời gian kết thúc\r\n(6)'] ??
      rowObj['Thời gian kết thúc\n(6)'] ??
      rowObj['TG kết thúc'] ??
      rowObj['Ket thuc'] ??
      ''

    const startDateVal =
      rowObj.ActualStartDate ??
      rowObj.StartDate ??
      rowObj['Ngày bắt đầu'] ??
      rowObj['Ngay bat dau'] ??
      rowObj.StatDate ??
      rowObj['Ngày thống kê'] ??
      ''
    const endDateVal =
      rowObj.ActualEndDate ??
      rowObj.EndDate ??
      rowObj['Ngày kết thúc'] ??
      rowObj['Ngay ket thuc'] ??
      rowObj.StatDate ??
      rowObj['Ngày thống kê'] ??
      ''

    // ── CỘT 91 (CM): Thời gian chạy thực tế (phút) = (Ngày kết thúc + Giờ kết thúc) - (Ngày bắt đầu + Giờ bắt đầu) - Hao phí ──
    let actualRunTime = calcTotalProductionMinutes(
      startDateVal,
      startVal,
      endDateVal,
      endVal,
      downtime
    )
    if (actualRunTime === null) {
      if (row.ActualRunTime !== undefined && row.ActualRunTime !== '') {
        actualRunTime = parseFloat(String(row.ActualRunTime).replace(/,/g, '')) || 0
      } else {
        const actualHours = parseFloat(
          String(
            rowObj.ActualTotalHours ??
              rowObj['Tổng thời gian kế hoạch(giờ) (10)=(9)-(8)'] ??
              rowObj['Tổng thời gian kế hoạch (10)=(9)-(8)'] ??
              ''
          ).replace(/,/g, '')
        )
        if (!isNaN(actualHours) && actualHours > 0) {
          actualRunTime = Math.max(0, Math.round(actualHours * 60 - downtime))
        } else {
          actualRunTime = ''
        }
      }
    }

    // ── CỘT 92 (CN): capa thực tế (Năng suất / giờ) ──
    // Công thức Excel: =+IF(CM3=0, 0, (T3*60 / CM3))
    let actualCapa = ''
    if (typeof actualRunTime === 'number') {
      if (actualRunTime > 0) {
        actualCapa = Number(((produced * 60) / actualRunTime).toFixed(2))
      } else {
        actualCapa = 0
      }
    } else if (row.ActualCapa !== undefined && row.ActualCapa !== '') {
      actualCapa = parseFloat(String(row.ActualCapa).replace(/,/g, '')) || 0
    }

    // ── CỘT 93 (CO): CHECK KHSX (So sánh với kết quả KHSX: 'Có trong KHSX' hoặc 'Khác KHSX') ──
    const opOrderNo = normalizeCode(
      row.OperationOrderNo ??
        row['Số lệnh thao tác'] ??
        row['Số lệnh TT'] ??
        row['Lệnh thao tác'] ??
        row['Lệnh TT'] ??
        row.OpOrderNo ??
        row.OperationNo ??
        ''
    )
    let checkKhsx = 'Khác KHSX'
    if (opOrderNo) {
      const keys = getLookupKeys(opOrderNo)
      const isPlan = keys.some((k) => opOrderPlanMap.has(k))
      if (isPlan) {
        checkKhsx = 'Có trong KHSX'
        insidePlanCount++
      } else {
        checkKhsx = 'Khác KHSX'
        outsidePlanCount++
      }
    } else {
      outsidePlanCount++
    }

    // ── CỘT 94 (CP): Thời gian duyệt phiếu ở MES ──
    // Đối soát Phiếu TK / Mã thống kê giữa file TKSX và file Duyệt MES
    const statSlipNo = extractTicketOrSlipCode(row)
    let mesApprovedTime = ''
    if (statSlipNo) {
      const keys = getLookupKeys(statSlipNo)
      for (const k of keys) {
        if (mesApprovalMap.has(k)) {
          mesApprovedTime = mesApprovalMap.get(k)
          break
        }
      }
    }
    if (!mesApprovedTime) {
      mesApprovedTime =
        extractMesApprovedTime(row) ||
        row.MesApprovedTime ||
        row['Thời gian duyệt phiếu ở MES'] ||
        row['Thời gian duyệt ở MES'] ||
        row['Thời gian duyệt'] ||
        ''
    }
    if (mesApprovedTime) {
      mesMatchedCount++
    }

    // ── CỘT 95 (CQ): Độ trễ thời gian đồng bộ 2 hệ thống ──
    // Công thức Excel: =+IF(OR(CL3="", CP3=""), "", TEXT(ABS(CP3 - CL3), "hh:mm:ss"))
    const slipCreatedDate = row.SlipCreatedDate ?? row['Ngày tạo phiếu'] ?? ''
    let syncLatencySeconds = ''
    if (slipCreatedDate && mesApprovedTime) {
      const createdTs = parseFullDateTime(slipCreatedDate)
      let approvedTs = parseFullDateTime(mesApprovedTime)
      if (createdTs && approvedTs) {
        let diffSec = Math.abs(Math.round((approvedTs - createdTs) / 1000))
        // Tự động phát hiện & sửa lỗi đảo ngày/tháng (MM/DD <-> DD/MM) trong file xuất từ MES
        if (diffSec > 86400) {
          const m = String(mesApprovedTime)
            .trim()
            .match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})(.*)/)
          if (m) {
            const swappedStr = `${m[2]}/${m[1]}/${m[3]}${m[4]}`
            const swappedTs = parseFullDateTime(swappedStr)
            if (swappedTs) {
              const swappedDiff = Math.abs(Math.round((swappedTs - createdTs) / 1000))
              if (swappedDiff < diffSec) {
                approvedTs = swappedTs
                diffSec = swappedDiff
                mesApprovedTime = swappedStr
              }
            }
          }
        }
        syncLatencySeconds = formatSecondsToHms(diffSec)
        totalSyncDelaySec += diffSec
        syncCount++
      }
    } else if (
      row.SyncLatencySeconds ||
      row.SyncDelayMinutes ||
      row.syncDelayMinutes ||
      row.syncLatencySeconds ||
      row['Độ trễ thời gian đồng bộ 2 hệ thống'] ||
      row['Độ trễ thời gian đồng bộ']
    ) {
      syncLatencySeconds = formatSecondsToHms(
        row.SyncLatencySeconds ??
          row.SyncDelayMinutes ??
          row.syncDelayMinutes ??
          row.syncLatencySeconds ??
          row['Độ trễ thời gian đồng bộ 2 hệ thống'] ??
          row['Độ trễ thời gian đồng bộ']
      )
    }

    // ── CỘT 96 (CR): Phiếu sinh trùng (0: không trùng, 1: trùng) ──
    // Công thức Excel: IF(COUNTIF($AE:$AE, AE)=1, 0, 1)
    let isDuplicateSlip = 0
    if (statSlipNo && (slipCountMap.get(statSlipNo) || 0) > 1) {
      isDuplicateSlip = 1
      duplicateSlipCount++
    }

    // ── CỘT 97 (CS): Vị trí tạo phiếu tk (MES hoặc Bravo) ──
    // Quy tắc: Cứ user/nhân viên thống kê có chữ "MES" (không phân biệt hoa/thường) là MES, còn lại Bravo
    const statEmp = String(row.StatEmployee ?? row['Nhân viên thống kê'] ?? '').trim()
    let createdLocation = 'Bravo'
    if (statEmp.toUpperCase().includes('MES')) {
      createdLocation = 'MES'
      mesUserCount++
    } else {
      bravoUserCount++
    }

    // ── CỘT 98 (CT): Sinh phiếu xuất/nhập tự động ──
    // Công thức Excel: =IF(AND(CF3=0,CG3=0),"Không sử dụng NVL",IF(CF3=0,"",IF(CH3="","Không có XKTĐ","Có XKTĐ"))&IF(AND(CF3<>0,CG3<>0),", ","")&IF(CG3=0,"",IF(CI3="","Không NKTĐ","Có NKTĐ")))
    const autoExport =
      parseInt(row.IsAutoExport ?? row.AutoExport ?? row['Xuất tự động'] ?? 0, 10) || 0
    const autoImport =
      parseInt(row.IsAutoImport ?? row.AutoImport ?? row['Nhập tự động'] ?? 0, 10) || 0
    const exportSlipNo = String(
      row.ExportSlipNo ??
        row['Số phiếu xuất'] ??
        row['Phiếu xuất'] ??
        row.ExportDocNo ??
        row.StatSlipNo_87 ??
        ''
    ).trim()
    const importSlipNo = String(
      row.ImportSlipNo ??
        row['Số phiếu nhập'] ??
        row['Phiếu nhập'] ??
        row.ImportDocNo ??
        row.StatSlipNo_88 ??
        ''
    ).trim()

    let autoExportImportGenerated = 'Không sử dụng NVL'
    if (autoExport === 0 && autoImport === 0) {
      autoExportImportGenerated = 'Không sử dụng NVL'
    } else {
      const parts = []
      if (autoExport !== 0) {
        parts.push(exportSlipNo ? 'Có XKTĐ' : 'Không có XKTĐ')
      }
      if (autoImport !== 0) {
        parts.push(importSlipNo ? 'Có NKTĐ' : 'Không NKTĐ')
      }
      autoExportImportGenerated = parts.join(', ') || 'Không sử dụng NVL'
    }

    // Đồng bộ 2 chiều thời gian thực hiện & ngày tháng
    const statDateVal = rowObj.StatDate ?? rowObj['Ngày thống kê'] ?? ''

    rowObj.StartTime = startVal
    rowObj['Bắt đầu'] = startVal
    rowObj['Thời gian bắt đầu'] = startVal

    rowObj.EndTime = endVal
    rowObj['Kết thúc'] = endVal
    rowObj['Thời gian kết thúc'] = endVal

    rowObj.StartDate = startDateVal
    rowObj['Ngày bắt đầu'] = startDateVal

    rowObj.EndDate = endDateVal
    rowObj['Ngày kết thúc'] = endDateVal

    rowObj.StatDate = statDateVal
    rowObj['Ngày thống kê'] = statDateVal

    // Gán lại đầy đủ cả key tiếng Anh & key tiếng Việt để hỗ trợ hiển thị 100% linh hoạt
    rowObj.CalcVersion = calcVersion
    rowObj['Version tính toán'] = calcVersion
    rowObj['Phiên bản'] = calcVersion
    rowObj.RegCode = regCode
    rowObj['Mã đăng ký'] = regCode

    rowObj.ActualRunTime = actualRunTime
    rowObj['Thời gian chạy thực tế'] = actualRunTime

    rowObj.ActualCapa = actualCapa
    rowObj['capa thực tế'] = actualCapa

    rowObj.CheckKhsx = checkKhsx
    rowObj['CHECK KHSX'] = checkKhsx
    rowObj['Check KHSX'] = checkKhsx
    rowObj['Cột 93'] = checkKhsx

    rowObj.MesApprovedTime = mesApprovedTime
    rowObj.MesApprovalTime = mesApprovedTime
    rowObj['Thời gian duyệt phiếu ở MES'] = mesApprovedTime
    rowObj['Thời gian duyệt ở MES'] = mesApprovedTime
    rowObj['Thời gian duyệt'] = mesApprovedTime

    rowObj.SyncLatencySeconds = syncLatencySeconds
    rowObj.SyncDelayMinutes = syncLatencySeconds
    rowObj.syncDelayMinutes = syncLatencySeconds
    rowObj.syncLatencySeconds = syncLatencySeconds
    rowObj['Độ trễ thời gian đồng bộ 2 hệ thống'] = syncLatencySeconds
    rowObj['Độ trễ thời gian đồng bộ'] = syncLatencySeconds

    rowObj.IsDuplicateSlip = isDuplicateSlip
    rowObj.IsDuplicateTicket = isDuplicateSlip
    rowObj['Phiếu sinh trùng'] = isDuplicateSlip

    rowObj.CreatedLocation = createdLocation
    rowObj.TicketCreationLocation = createdLocation
    rowObj['Vị trí tạo phiếu tk'] = createdLocation

    rowObj.AutoExportImportGenerated = autoExportImportGenerated
    rowObj.AutoIoStatus = autoExportImportGenerated
    rowObj['Sinh phiếu xuất/nhập tự động'] = autoExportImportGenerated

    // Thống kê tổng
    totalProducedQty += produced
    totalQualifiedQty += qualified
    totalDefectQty += defect
    totalDowntimeMinutes += downtime

    const machine = String(
      row.MachineName ??
        row['Tên máy sản xuất'] ??
        row.MachineCode ??
        row['Mã máy sản xuất'] ??
        'Khác'
    ).trim()
    const team = String(row.ProductionTeam ?? row['Tổ sản xuất'] ?? 'Khác').trim()
    const leadTech = String(
      row.LeadTechnicianName ?? row['Thợ chính'] ?? row['Họ tên thợ chính'] ?? 'Khác'
    ).trim()

    if (!statByMachine[machine]) {
      statByMachine[machine] = {
        machine,
        producedQty: 0,
        qualifiedQty: 0,
        defectQty: 0,
        ticketCount: 0
      }
    }
    statByMachine[machine].producedQty += produced
    statByMachine[machine].qualifiedQty += qualified
    statByMachine[machine].defectQty += defect
    statByMachine[machine].ticketCount += 1

    if (!statByTeam[team]) {
      statByTeam[team] = { team, producedQty: 0, qualifiedQty: 0, defectQty: 0 }
    }
    statByTeam[team].producedQty += produced
    statByTeam[team].qualifiedQty += qualified
    statByTeam[team].defectQty += defect

    if (leadTech && leadTech !== 'Khác') {
      if (!statByTechnician[leadTech]) {
        statByTechnician[leadTech] = {
          technician: leadTech,
          producedQty: 0,
          qualifiedQty: 0,
          defectQty: 0
        }
      }
      statByTechnician[leadTech].producedQty += produced
      statByTechnician[leadTech].qualifiedQty += qualified
      statByTechnician[leadTech].defectQty += defect
    }

    if (!rowObj.IdSeq) {
      rowObj.IdSeq =
        typeof crypto !== 'undefined' && crypto.randomUUID
          ? crypto.randomUUID()
          : `TKSX-${Date.now()}-${index + 1}`
    }
    if (rowObj.RowVersion === undefined) {
      rowObj.RowVersion = 1
    }
    if (!rowObj.CreatedAt) {
      rowObj.CreatedAt = new Date().toISOString()
    }
    if (!rowObj.WorkingTag && !rowObj.Status) {
      rowObj.WorkingTag = 'A'
    }

    return rowObj
  })

  // Đối soát với MES
  let mesApprovedProducedQty = 0
  let mesApprovedQualifiedQty = 0
  let mesApprovedDefectQty = 0

  mesApprovalData.forEach((row) => {
    const p = parseFloat(String(row['SL sản xuất'] ?? row.ProducedQty ?? 0).replace(/,/g, '')) || 0
    const q = parseFloat(String(row['SL đạt'] ?? row.QualifiedQty ?? 0).replace(/,/g, '')) || 0
    const d = parseFloat(String(row['SL lỗi'] ?? row.DefectQty ?? 0).replace(/,/g, '')) || 0
    mesApprovedProducedQty += p
    mesApprovedQualifiedQty += q
    mesApprovedDefectQty += d
  })

  const defectRate =
    totalProducedQty > 0 ? Number(((totalDefectQty / totalProducedQty) * 100).toFixed(2)) : 0
  const avgSyncDelay = syncCount > 0 ? Number((totalSyncDelaySec / syncCount).toFixed(1)) : 0

  return {
    version: calcVersion,
    calcVersion,
    regCode,
    totalProducedQty,
    totalQualifiedQty,
    totalDefectQty,
    defectRate,
    totalTickets: statReportData.length,
    totalDowntimeMinutes,
    avgSyncDelaySeconds: avgSyncDelay,
    insidePlanCount,
    outsidePlanCount,
    mesUserCount,
    bravoUserCount,
    duplicateSlipCount,
    mesApproval: {
      totalApprovedTickets: mesApprovalData.length,
      mesMatchedTickets: mesMatchedCount,
      approvedProducedQty: mesApprovedProducedQty,
      approvedQualifiedQty: mesApprovedQualifiedQty,
      approvedDefectQty: mesApprovedDefectQty,
      discrepancyProducedQty: totalProducedQty - mesApprovedProducedQty,
      discrepancyQualifiedQty: totalQualifiedQty - mesApprovedQualifiedQty
    },
    machineBreakdown: Object.values(statByMachine).sort((a, b) => b.producedQty - a.producedQty),
    teamBreakdown: Object.values(statByTeam).sort((a, b) => b.producedQty - a.producedQty),
    technicianBreakdown: Object.values(statByTechnician).sort(
      (a, b) => b.producedQty - a.producedQty
    ),
    // Bảng dữ liệu kết quả TKSX hoàn chỉnh
    calculatedRows,
    columns: files.stat_report?.columns || STAT_REPORT_COLUMN_SCHEMA
  }
}

