      const p = Number(item.planQty || item.TargetProdQty || item.StandardMeters) || 0
      const a = Number(item.actualQty || item.ProdQty || item.ActualMeters) || p || 0
      const pass = Number(item.passQty || item.StatPassQty) || a || 0
      const def = Number(item.defectQty) || Math.max(0, a - pass) || 0
      const pRate = a > 0 ? Number(((pass / a) * 100).toFixed(1)) : 100

      const rawStartDate =
        item.startDate || item.StartDate || item.prodDate || item.StatDate || item.statDate || ''
      const rawEndDate =
        item.endDate || item.EndDate || item.prodDate || item.StatDate || item.statDate || ''
      const rawStart =
        item.startTime || item.StartTime || item.TicketCreatedDate || item.createdTime
      const rawEnd = item.endTime || item.EndTime || item.MesApprovalTime || item.syncTime

      // Helper đọc giá trị từ cột thời gian chạy thực tế (ActualRunTime / DurationMinutes từ BE)
      const parseRawActualRunTime = () => {
        const rawRt =
          item.ActualRunTime ??
          item.actualRunTime ??
          item.DurationMinutes ??
          item.durationMinutes ??
          item.ActualProdTime ??
          item.actualProdTime
        if (rawRt !== undefined && rawRt !== null && rawRt !== '') {
          const str = String(rawRt).trim().replace(',', '.')
          if (str.includes(':')) {
            const parts = str.split(':').map((v) => parseFloat(v) || 0)
            return Number((parts[0] * 60 + (parts[1] || 0) + (parts[2] || 0) / 60).toFixed(1))
          }
          const val = parseFloat(str)
          if (!isNaN(val) && val >= 0) {
            return Number(val.toFixed(1))
          }
        }
        return undefined
      }

      let isTimeReversed = false
      let durMinutes = parseRawActualRunTime()

      // Tính Tổng thời gian hao phí (Breakdown + Waiting + Setup + Repair)
      const rawWaste =
        item.TotalWasteMinutes ??
        item.totalWasteMinutes ??
        item.TotalDowntimeMinutes ??
        item.totalDowntimeMinutes
      let wasteMin = 0
      if (rawWaste !== undefined && rawWaste !== null && rawWaste !== '') {
        wasteMin = parseFloat(String(rawWaste).replace(',', '.')) || 0
      } else {
        const bd =
          parseFloat(
            String(
              item.BreakdownMinutes ?? item.breakdownMinutes ?? item.DowntimeBreakdownMinutes ?? 0
            ).replace(',', '.')
          ) || 0
        const wm =
          parseFloat(
            String(
              item.WaitingMaterialMinutes ??
                item.waitingMaterialMinutes ??
                item.DowntimeWaitingMaterialMinutes ??
                0
            ).replace(',', '.')
          ) || 0
        const st =
          parseFloat(
            String(
              item.SetupMinutes ?? item.setupMinutes ?? item.DowntimeSetupMinutes ?? 0
            ).replace(',', '.')
          ) || 0
        const rp =
          parseFloat(
            String(
              item.RepairMinutes ?? item.repairMinutes ?? item.DowntimeFixingMinutes ?? 0
            ).replace(',', '.')
          ) || 0
        wasteMin = bd + wm + st + rp
      }

      // Nếu không có ActualRunTime hoặc ActualRunTime = 0, tính từ StartTime và EndTime rồi trừ hao phí
      if ((durMinutes === undefined || durMinutes === 0) && rawStart && rawEnd) {
        const sStr = String(rawStart).trim()
        const eStr = String(rawEnd).trim()

        if (sStr.includes(':') && eStr.includes(':')) {
          const sParts = sStr
            .split(' ')
            .pop()
            .split(':')
            .map((v) => parseFloat(v) || 0)
          const eParts = eStr
            .split(' ')
            .pop()
            .split(':')
            .map((v) => parseFloat(v) || 0)
          const sMin = (sParts[0] || 0) * 60 + (sParts[1] || 0) + (sParts[2] || 0) / 60
          const eMin = (eParts[0] || 0) * 60 + (eParts[1] || 0) + (eParts[2] || 0) / 60
          let diff = eMin - sMin
          if (diff < 0) diff += 1440 // Ca làm việc qua đêm
          if (wasteMin > 0) diff = Math.max(0, diff - wasteMin)
          if (diff >= 0 && diff <= 1440) {
            durMinutes = Number(diff.toFixed(1))
