      { id: 'capaStatus', title: 'Trạng thái Capa', width: colWidths['capaStatus'] || 135 },
      { id: 'pic', title: 'PIC Điều phối', width: colWidths['pic'] || 130 },
      { id: 'planDate', title: 'Ngày KH', width: colWidths['planDate'] || 95 },
