            allowOverlay: false,
            contentAlign: 'right',
            themeOverride: {
              textDark: Number(rate) >= 95 ? '#047857' : '#be123c',
              baseFontStyle: '700 12px'
            }
          }
        }
        case 'machineCode':
          return {
            kind: GridCellKind.Text,
            data: item.machineCode || '',
            displayData: item.machineCode || '',
            allowOverlay: false,
            themeOverride: { textDark: '#0284c7', baseFontStyle: '600 12px' }
