          return {
            kind: GridCellKind.Number,
            data: def,
            displayData: def.toLocaleString('vi-VN'),
            allowOverlay: false,
            contentAlign: 'right',
            themeOverride:
              def > 0
                ? { textDark: '#dc2626', baseFontStyle: '700 12px' }
                : { textDark: '#94a3b8', baseFontStyle: '500 12px' }
