        case 'ticketCount':
          return {
            kind: GridCellKind.Number,
            data: item.ticketCount,
            displayData: Number(item.ticketCount || 0).toLocaleString('vi-VN'),
            allowOverlay: false,
            contentAlign: 'right'
          }
        case 'actualQty':
          return {
            kind: GridCellKind.Number,
            data: item.totalActualQty,
