  const onDetailHeaderClicked = useCallback(
    (col) => {
      const colObj = detailGridCols[col]
      if (!colObj) return
      const colId = colObj.id
      setDetailSortConfig((prev) => {
        if (prev.key === colId) {
          return { key: colId, direction: prev.direction === 'desc' ? 'asc' : 'desc' }
        }
        return { key: colId, direction: 'desc' }
      })
    },
    [detailGridCols]
  )

  const getDetailCellContent = useCallback(
    ([col, row]) => {
      const item = displayDetailList[row]
      const colObj = detailGridCols[col]
      if (!item || !colObj) {
        return { kind: GridCellKind.Text, data: '', displayData: '', allowOverlay: false }
      }
      const colId = colObj.id
      if (!colId) {
        return { kind: GridCellKind.Text, data: '', displayData: '', allowOverlay: false }
      }

      let val = item[colId] ?? item[colId.charAt(0).toLowerCase() + colId.slice(1)] ?? ''

      if (
        colId === 'TotalWasteMinutes' &&
        (val === '' || val === null || val === undefined || val === 0 || val === '0')
      ) {
        const bd =
          parseFloat(
            String(item.BreakdownMinutes ?? item.breakdownMinutes ?? 0).replace(',', '.')
          ) || 0
        const wm =
          parseFloat(
            String(item.WaitingMaterialMinutes ?? item.waitingMaterialMinutes ?? 0).replace(
              ',',
              '.'
            )
          ) || 0
        const st =
          parseFloat(String(item.SetupMinutes ?? item.setupMinutes ?? 0).replace(',', '.')) || 0
        const rp =
          parseFloat(String(item.RepairMinutes ?? item.repairMinutes ?? 0).replace(',', '.')) || 0
        const sum = bd + wm + st + rp
        if (sum > 0) val = sum
      }

      if (colObj.kind === 'Boolean') {
        const boolVal =
          typeof val === 'boolean'
            ? val
            : val === 1 || val === '1' || val === 'true' || val === 'Có'
        return {
          kind: GridCellKind.Boolean,
          data: boolVal,
          allowOverlay: false
        }
      }

      if (colObj.kind === 'Number' || typeof val === 'number') {
        const numVal = typeof val === 'number' ? val : Number(val)
        const isValid = !isNaN(numVal) && val !== '' && val !== null && val !== undefined
        const finalNum = isValid ? numVal : 0
        const displayData = isValid ? finalNum.toLocaleString('vi-VN') : ''
        return {
          kind: GridCellKind.Number,
          data: finalNum,
          displayData,
          allowOverlay: false,
          contentAlign: 'right'
        }
      }

      const strVal = String(val ?? '')
      return {
        kind: GridCellKind.Text,
        data: strVal,
        displayData: strVal,
        allowOverlay: false
      }
