  const executeExportStatExcel = useCallback(
    async ({ fileName, saveDirectory, overwriteExisting, includeHeaders, exportableCols }) => {
      const validCols = exportableCols || rawStatCols.filter((c) => c.id && c.id !== 'WorkingTag')
