      const reportTitle = `BÁO CÁO NHẬT TRÌNH CHI TIẾT TOÀN BỘ PHIẾU THỐNG KÊ SẢN XUẤT - ${plantDisplayName}`
      const dateStr = dateRange?.[0] && dateRange?.[1] ? `${dateRange[0]} - ${dateRange[1]}` : ''
      const filterSummary = `Nhà máy: ${plantDisplayName}${dateStr ? ` | Thời gian: ${dateStr}` : ''}`

      const wb = generateExcelWorkbook({
        data: displayDetailList,
        columns: validCols,
        sheetName: 'NhatTrinh_ChiTiet_TKSX',
        reportTitle,
        filterInfo: filterSummary,
        includeHeaders: includeHeaders !== false,
        formatDateFn: getCleanDate
      })

      await saveWorkbookToFile(wb, fileName, saveDirectory, { overwriteExisting })
    },
    [displayDetailList, rawStatCols, plantKey, dateRange]
  )

  const handleExportDetailExcel = handleOpenExportModal
  const handleExportExcel = handleOpenExportModal

  return {
    // State
    dateRange,
    onDateRangeChange,
    setDateRange: onDateRangeChange,
    machineChartMode,
    setMachineChartMode,
    showManualMachines,
    setShowManualMachines,
    selectedTeam,
    setSelectedTeam,
    selectedMachine,
    setSelectedMachine,
    selectedDurationAudit,
    setSelectedDurationAudit,
    isCapturing,
    setIsCapturing,
    showFormulaModal,
    setShowFormulaModal,
    showAuditModal,
    setShowAuditModal,
    auditModalCategory,
    setAuditModalCategory,
    machineFullHeight,
    setMachineFullHeight,
    teamFullHeight,
    setTeamFullHeight,
    detailFullHeight,
    setDetailFullHeight,
    machineRowHeight,
    setMachineRowHeight,
    teamRowHeight,
    setTeamRowHeight,
    detailRowHeight,
    setDetailRowHeight,
    machineSearchText,
    setMachineSearchText,
    teamSearchText,
    setTeamSearchText,
    detailSearchText,
    setDetailSearchText,
    showDetailSearch,
    setShowDetailSearch,

    // Refs
    reportRootRef,
    chart1Ref,
    chart2Ref,
    chart3Ref,
    syncChartRef,
    autoExportChartRef,
    machineGridRef,
    teamGridRef,
    detailGridRef,

    // Computed Data
    rawData,
    filteredData,
    filterOptions,
    hasActiveFilters,
    kpiMetrics,
    machineAggregates,
    displayMachineList,
    machineGrandTotal,
    teamAggregates,
    displayTeamList,
    teamGrandTotal,
    missingAutoExportTickets,
    displayDetailList,
