            mesRate: Number(mesRate.toFixed(1)),
            autoExportRate: Number(autoExportRate.toFixed(1)),
            under10: u10,
            syncUnder10: u10,
            from11to30: f11to30,
            sync11to30: f11to30,
            from31to60: f31to60,
            sync31to60: f31to60,
            over60: o60,
            syncOver60: o60,
            syncEmpty: sEmpty,
            avgSyncDelaySeconds: avgDelaySec,
            avgDelaySec: avgDelaySec,
