          if (b.date === 'Khác') return -1
          return String(a.date).localeCompare(String(b.date))
        })
    }
    const map = new Map()
    filteredData.forEach((item) => {
      const dateKey = item.date || item.StatDate || item.prodDate || 'Khác'
      if (!map.has(dateKey)) {
