              className={activeFilterCount > 0 || showFilter ? 'text-blue-600' : 'text-slate-500'}
            />
            <span>{showFilter ? t('ĐÓNG BỘ LỌC') : t('BỘ LỌC')}</span>
            {activeFilterCount > 0 && (
