                  }}
                  disabled={loading}
                />
              </div>
            </div>

            {/* Khối 2: Loại báo cáo (nếu có) */}
            {setReportType && (
              <div className="inline-flex items-center bg-white rounded-md border border-slate-200/90 shadow-2xs h-[30px] px-1 hover:border-slate-300 transition-colors">
