        ? selectedTeam.length > 0 && !selectedTeam.includes('ALL')
        : selectedTeam && selectedTeam !== 'ALL'
      const teamSet = hasTeamFilter
        ? new Set(Array.isArray(selectedTeam) ? selectedTeam : [selectedTeam])
        : null

