        tickets: m.ticketCount,
        mesRate: m.ticketCount > 0 ? Number(((m.mesCount / m.ticketCount) * 100).toFixed(1)) : 0
      }
    })

    return listFinal.sort((a, b) => b.totalRuntimeHours - a.totalRuntimeHours)
