import { useMemo, useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import DynamicQueryBar from '../../../../components/query/core/DynamicQueryBar'

const STORAGE_KEY = 'S_ERP_QUERY_FIELDS_plan_registration'

const DEFAULT_VISIBLE_KEYS = ['FactoryName', 'ReportType', 'RegCode', 'ApplyDate']

export default function PlanRegistrationQuery({
  searchValues = {},
  setSearchValues,
  dynamicQueryFields = [],
  onAddQueryField,
  onRemoveQueryField,
  onResetQuery,
  handleSearchData,
  disabled = false
}) {
  const { t } = useTranslation()

  // Lưu trạng thái các trường được hiển thị
  const [visibleKeys, setVisibleKeys] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY)
      if (saved) {
        const parsed = JSON.parse(saved)
        if (Array.isArray(parsed) && parsed.length > 0) {
          return new Set(parsed)
        }
      }
    } catch {}
    return new Set(DEFAULT_VISIBLE_KEYS)
  })

  const allAvailableFields = useMemo(
    () => [
      {
        key: 'FactoryName',
        label: t('report.factoryName', 'Nhà máy'),
        type: 'select',
        options: [
          { value: '', label: 'Tất cả nhà máy' },
          { value: 'GS1 Hà Nội', label: 'GS1 Hà Nội' },
          { value: 'GS5 Quế Võ 1B', label: 'GS5 Quế Võ 1B' }
        ]
      },
      {
        key: 'ReportType',
        label: t('report.reportType', 'Loại báo cáo'),
        type: 'select',
        options: [
          { value: '', label: 'Tất cả loại báo cáo' },
          { value: 'plan', label: 'Kế hoạch sản xuất (KHSX)' },
          { value: 'statistics', label: 'Thống kê sản xuất (TKSX)' }
        ]
      },
      {
        key: 'RegCode',
        label: t('report.regCode', 'Mã đăng ký'),
        type: 'text',
        placeholder: 'Nhập mã đăng ký...'
      },
      {
        key: 'ApplyDate',
        label: t('report.applyDate', 'Ngày báo cáo'),
        type: 'date'
      },
      {
        key: 'Status',
        label: t('report.status', 'Trạng thái'),
        type: 'select',
        options: [
          { value: '', label: 'Tất cả trạng thái' },
          { value: 'published', label: 'Đã phát hành / Đã lưu' },
          { value: 'draft', label: 'Bản nháp' }
        ]
      },
      {
        key: 'CreatedBy',
        label: t('report.createdBy', 'Người đăng ký'),
        type: 'text',
        placeholder: 'Tên / mã người đăng ký...'
      }
    ],
    [t]
  )

  // Bật/tắt cột tìm kiếm động
  const handleToggleField = useCallback((fieldKey, isChecked) => {
    setVisibleKeys((prev) => {
      const next = new Set(prev)
      if (isChecked) {
        next.add(fieldKey)
      } else {
        next.delete(fieldKey)
      }
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(next)))
      } catch {}
      return next
    })
  }, [])

  // Đặt lại danh sách cột mặc định
  const handleResetFields = useCallback(() => {
    const next = new Set(DEFAULT_VISIBLE_KEYS)
    setVisibleKeys(next)
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(next)))
    } catch {}
  }, [])

  // Danh sách fields hiển thị
  const renderedFields = useMemo(() => {
    return allAvailableFields.map((f) => ({
      ...f,
      visible: visibleKeys.has(f.key)
    }))
  }, [allAvailableFields, visibleKeys])

  const currentValues = useMemo(() => {
    const base = {}
    allAvailableFields.forEach((f) => {
      base[f.key] = searchValues[f.key] || ''
    })
    return {
      ...base,
      ...searchValues
    }
  }, [allAvailableFields, searchValues])

  const handleFieldChange = (key, value) => {
    setSearchValues((prev) => ({
      ...prev,
      [key]: value
    }))
  }

  return (
    <div className="w-full bg-white">
      <DynamicQueryBar
        fields={renderedFields}
        allAvailableFields={allAvailableFields}
        values={currentValues}
        onChange={handleFieldChange}
        onSearch={handleSearchData}
        onReset={onResetQuery}
        onToggleField={handleToggleField}
        onResetFields={handleResetFields}
        disabled={disabled}
        columns={4}
      />
    </div>
  )
}

import { useCallback, useRef, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { DataEditor, GridCellKind } from '@glideapps/glide-data-grid'
import '@glideapps/glide-data-grid/dist/index.css'
import LayoutMenuSheet from '../../../../components/sheet/jsx/layoutMenu'
import LayoutStatusMenuSheet from '../../../../components/sheet/jsx/layoutStatusMenu'
import LayoutContextMenuSheet from '../../../../components/sheet/jsx/layoutContextMenu'
import { Drawer, Checkbox } from '../../../../../components/ui'
import { reorderColumns } from '../../../../components/sheet/js/reorderColumns'
import useOnFill from '../../../../components/hooks/sheet/onFillHook'
import useTableManager from '../../../../components/hooks/sheet/useTableManager'
import useTableConfig from '../../../../components/hooks/sheet/useTableConfig'
import { useDateFormat } from '../../../../hooks/useDateFormat'
import { usePageData } from '../../../../../context/PageDataContext'
import { togglePageInteraction } from '../../../../../utils/togglePageInteraction'

const EMPTY_ARRAY = []
const BOOLEAN_KEYS = new Set(['Utilities', 'Active', 'IsDataLock'])
const ONLY_DATE_KEYS = new Set(['ApplyDate', 'PlanDate', 'CreatedDate', 'UpdatedDate'])
const DATETIME_KEYS = new Set(['CreatedAt', 'UpdatedAt'])

const getReportTypeName = (val) => {
  if (!val) return ''
  const lower = String(val).toLowerCase().trim()
  if (lower === 'statistics' || lower === 'tksx') {
    return 'Thống kê sản xuất (TKSX)'
  }
  if (lower === 'plan' || lower === 'khsx') {
    return 'Kế hoạch sản xuất (KHSX)'
  }
  return String(val)
}

const getStatusName = (val) => {
  if (!val) return ''
  const lower = String(val).toLowerCase().trim()
  if (lower === 'published' || lower === 'done' || lower === 'active') {
    return 'Đã lưu / Đã phát hành'
  }
  return String(val)
}

export default function PlanRegistrationTable({
  tableTitle,
  setSelection,
  selection,
  setShowSearch,
  showSearch,
  setGridData,
  gridData = [],
  numRows,
  setNumRows,
  handleRowAppend,
  setCols,
  cols = [],
  canEdit,
  canCreate,
  defaultCols,
  onVisibleRegionChanged,
  onAddQueryField,
  onOpenDetail
}) {
  const { t } = useTranslation()
  const { formatDate, formatDateTime } = useDateFormat()
  const { setStatusMessage } = usePageData() || {}
  const gridRef = useRef(null)

  const onFill = useOnFill(setGridData, cols)
  const onSearchClose = useCallback(() => setShowSearch(false), [setShowSearch])

  const { freezeColumnsCount, handleFreezeColumn } = useTableConfig('plan_registration_table')

  const {
    showMenu,
    setShowMenu,
    onHeaderMenuClick,
    layerProps,
    renderLayer,
    hiddenColumns,
    handleHideColumn,
    handleReset,
    onColumnMoved,
    onColumnResize,
    handleSort,
    openDrawer: open,
    setOpenDrawer: setOpen,
    showDrawer,
    handleCheckboxChange,
    configurableCols,
    keybindings,
    getCellTheme,
    isReadOnlyColumn,
    gridTheme,
    onCellClicked,
    onCellActivated,
    onKeyDown,
    onCellContextMenu,
    onHeaderContextMenu
  } = useTableManager({
    tableId: 'plan_registration_table',
    defaultCols,
    cols,
    setCols,
    setGridData,
    gridData,
    selection,
    setSelection,
    canEdit,
    setShowSearch,
    onAddQueryField
  })

  const onClose = () => setOpen(false)

  const handleCellActivated = useCallback(
    (cell) => {
      onCellActivated?.(cell)
      const rowIndex = cell?.[1]
      if (rowIndex !== undefined && gridData?.[rowIndex] && onOpenDetail) {
        onOpenDetail(gridData[rowIndex])
      }
    },
    [gridData, onCellActivated, onOpenDetail]
  )

  // ── 1. PRE-COMPUTE METADATA CHO CÁC CỘT (O(1) Cell Provider Lookup) ──
  const colMetadata = useMemo(() => {
    return (cols || []).map((column) => {
      const columnKey = column.id || ''
      const isStatus = columnKey === 'WorkingTag' || columnKey === 'Status'
      const isBoolean = column.kind === 'Boolean' || BOOLEAN_KEYS.has(columnKey)
      const isOnlyDate = ONLY_DATE_KEYS.has(columnKey) || columnKey.endsWith('Date')
      const isDateTime = DATETIME_KEYS.has(columnKey) || columnKey.endsWith('At')
      const isDate = isOnlyDate || isDateTime
      const cellTheme = getCellTheme(columnKey, column)
      const isReadOnly = isReadOnlyColumn(columnKey, column) || column.readonly || false
      return {
        columnKey,
        isStatus,
        isBoolean,
        isOnlyDate,
        isDateTime,
        isDate,
        kind: column.kind,
        cellTheme,
        isReadOnly,
        hasMenu: column.hasMenu || false
      }
    })
  }, [cols, getCellTheme, isReadOnlyColumn])

  // ── 2. SIÊU TỐI ƯU HÓA HÀM TRUY XUẤT Ô (60 FPS VIRTUAL SCROLLING) ──
  const getData = useCallback(
    ([col, row]) => {
      const item = gridData[row]
      const meta = colMetadata[col]
      if (!meta || !item) {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false
        }
      }

      const value = item[meta.columnKey] ?? ''

      if (meta.isStatus && meta.columnKey === 'WorkingTag') {
        const strVal = String(value)
        return {
          kind: GridCellKind.Text,
          data: strVal,
          displayData: strVal,
          readonly: true,
          allowOverlay: false,
          hasMenu: meta.hasMenu,
          contentAlign: 'center',
          themeOverride: meta.cellTheme
        }
      }

      if (meta.isBoolean) {
        const booleanValue =
          typeof value === 'boolean' ? value : value === 1 || value === '1' || value === 'true'
        return {
          kind: GridCellKind.Boolean,
          data: booleanValue,
          readonly: meta.isReadOnly,
          allowOverlay: true,
          hasMenu: meta.hasMenu,
          themeOverride: meta.cellTheme
        }
      }

      if (meta.kind === 'Number' || typeof value === 'number') {
        const numVal = Number(value) || 0
        return {
          kind: GridCellKind.Number,
          data: numVal,
          displayData: numVal.toLocaleString('vi-VN'),
          readonly: meta.isReadOnly,
          allowOverlay: !meta.isReadOnly,
          hasMenu: meta.hasMenu,
          contentAlign: 'right',
          themeOverride: meta.cellTheme
        }
      }

      const strValue = typeof value === 'string' ? value : String(value)
      let displayData = strValue

      if (meta.columnKey === 'ReportType') {
        displayData = getReportTypeName(value)
      } else if (meta.columnKey === 'Status') {
        displayData = getStatusName(value)
      } else if (meta.isOnlyDate && value) {
        displayData = formatDate(value, 'DD/MM/YYYY') || strValue
      } else if (meta.isDateTime && value) {
        displayData = formatDateTime(value, 'DD/MM/YYYY HH:mm:ss') || strValue
      }

      return {
        kind: GridCellKind.Text,
        data: strValue,
        displayData: displayData,
        readonly: meta.isReadOnly,
        allowOverlay: !meta.isReadOnly,
        hasMenu: meta.hasMenu,
        themeOverride: meta.cellTheme
      }
    },
    [gridData, colMetadata, formatDate, formatDateTime]
  )

  const onKeyUp = useCallback(() => {}, [])

  // ── 3. CHỈNH SỬA Ô ĐƠN LẺ ──
  const onCellEdited = useCallback(
    async (cell, newValue) => {
      if (
        newValue.kind !== GridCellKind.Text &&
        newValue.kind !== GridCellKind.Custom &&
        newValue.kind !== GridCellKind.Boolean &&
        newValue.kind !== GridCellKind.Number
      ) {
        return
      }
      if (canEdit === false) {
        return
      }
      const indexes = reorderColumns(cols)
      const [col, row] = cell
      const key = indexes[col]

      if (isReadOnlyColumn(key) || key === 'WorkingTag' || key === 'Status' || key === 'Id') {
        return
      }

      setGridData((prevData) => {
        const updatedData = [...prevData]
        if (!updatedData[row]) updatedData[row] = {}

        const currentStatus = updatedData[row]['WorkingTag'] || ''
        const nextStatus = currentStatus === 'A' ? 'A' : 'U'
        updatedData[row][key] = newValue.data
        updatedData[row]['WorkingTag'] = nextStatus

        // Tự động tính toán Tỷ lệ đạt % khi sửa ActualQty hoặc PassQty
        if (key === 'ActualQty' || key === 'PassQty' || key === 'PlanQty') {
          const actual = Number(updatedData[row].ActualQty) || Number(updatedData[row].PlanQty) || 0
          const pass = Number(updatedData[row].PassQty) || 0
          if (actual > 0) {
            updatedData[row].PassRate = `${((pass / actual) * 100).toFixed(1)}%`
            updatedData[row].DefectQty = Math.max(0, actual - pass)
          }
        }

        return updatedData
      })
    },
    [cols, canEdit, isReadOnlyColumn, setGridData]
  )

  // ── 4. DÁN HÀNG LOẠT 10.000 DÒNG SIÊU TỐC TRONG 1 PASS O(N) KÈM KHÓA CHUỘT TRÁNH XUNG ĐỘT ──
  const onPaste = useCallback(
    (target, values) => {
      if (!values || values.length === 0 || canEdit === false) {
        return false
      }

      const [startCol, startRow] = target
      const indexes = reorderColumns(cols)
      const numPastedRows = values.length
      const numPastedCols = values[0]?.length || 0

      // Chặn và cảnh báo nếu số lượng dòng dán vượt quá giới hạn 3,000 dòng
      if (numPastedRows > 3000) {
        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'error',
            text: t(
              'Số lượng dòng dán ({{count}} dòng) vượt quá giới hạn tối đa cho phép (3,000 dòng)! Vui lòng chia nhỏ dữ liệu.',
              { count: numPastedRows.toLocaleString() }
            )
          })
        }
        return false
      }

      // Khóa chuột và chặn toàn bộ tương tác người dùng khi đang dán lượng lớn dữ liệu
      const isBatch = numPastedRows >= 10 || numPastedRows * numPastedCols >= 50
      if (isBatch) {
        const msg = t('Đang xử lý dán {{count}} dòng dữ liệu... Vui lòng không thao tác', {
          count: numPastedRows.toLocaleString()
        })
        togglePageInteraction(true, msg)
        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'info',
            text: msg
          })
        }
      }

      try {
        setGridData((prevData) => {
          const requiredLength = Math.max(prevData.length, startRow + numPastedRows)
          const nextData = new Array(requiredLength)

          // 1. Giữ nguyên các dòng trước vùng dán
          for (let r = 0; r < startRow; r++) {
            nextData[r] = prevData[r] || {}
          }

          // 2. Điền và xử lý hàng loạt các dòng được dán trong 1 vòng lặp O(N) duy nhất
          for (let r = 0; r < numPastedRows; r++) {
            const targetRow = startRow + r
            const existingRow = prevData[targetRow] ? { ...prevData[targetRow] } : {}
            const rowValues = values[r] || []
            const isNewRow =
              !existingRow.Id &&
              !existingRow.IdSeq &&
              (!existingRow.WorkingTag ||
                existingRow.WorkingTag === 'A' ||
                !existingRow.Status ||
                existingRow.Status === 'A')

            let hasRowModified = false

            for (let c = 0; c < numPastedCols; c++) {
              const targetCol = startCol + c
              if (targetCol >= cols.length) break

              const columnKey = indexes[targetCol]
              const column = cols[targetCol]

              if (
                !columnKey ||
                columnKey === 'WorkingTag' ||
                columnKey === 'Status' ||
                columnKey === 'Id' ||
                columnKey === 'IdxNo' ||
                isReadOnlyColumn(columnKey, column)
              ) {
                continue
              }

              let cellVal = rowValues[c] ?? ''
              if (column?.kind === 'Boolean' || BOOLEAN_KEYS.has(columnKey)) {
                cellVal =
                  cellVal === 'true' ||
                  cellVal === '1' ||
                  cellVal === true ||
                  String(cellVal).toLowerCase() === 'true'
              }

              existingRow[columnKey] = cellVal
              hasRowModified = true
            }

            if (hasRowModified || isNewRow) {
              existingRow.IdxNo = targetRow + 1
              const curStatus = existingRow.WorkingTag || existingRow.Status || ''
              const nextStatus = isNewRow ? 'A' : curStatus === 'A' ? 'A' : 'U'
              existingRow.WorkingTag = nextStatus
            }

            nextData[targetRow] = existingRow
          }

          // 3. Giữ nguyên các dòng sau vùng dán (nếu có)
          for (let r = startRow + numPastedRows; r < prevData.length; r++) {
            nextData[r] = prevData[r]
          }

          if (typeof setNumRows === 'function' && nextData.length !== prevData.length) {
            setNumRows(nextData.length)
          }

          return nextData
        })

        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'success',
            text: t('Đã dán thành công {{count}} dòng dữ liệu!', {
              count: numPastedRows.toLocaleString()
            })
          })
        }
      } finally {
        if (isBatch) {
          const unlockDelay = Math.min(1500, Math.max(250, Math.round(numPastedRows * 0.04)))
          requestAnimationFrame(() => {
            requestAnimationFrame(() => {
              setTimeout(() => {
                togglePageInteraction(false)
              }, unlockDelay)
            })
          })
        }
      }

      return false
    },
    [cols, canEdit, isReadOnlyColumn, setGridData, setNumRows, setStatusMessage, t]
  )

  const effectiveRows = numRows ?? gridData?.length ?? 0

  return (
    <div className="w-full h-full flex items-center justify-center">
      <div className="w-full h-full flex flex-col bg-white overflow-hidden">
        <h2 className="text-[10px] italic text-indigo-600 border-b border-slate-200 font-bold flex items-center gap-1.5 px-2 py-1 uppercase bg-white">
          <span className="w-1 h-3 bg-indigo-600 rounded-full inline-block shrink-0" />
          <span>{tableTitle || t('Đăng ký báo cáo KHSX & TKSX')}</span>
        </h2>
        <DataEditor
          ref={gridRef}
          theme={gridTheme}
          columns={cols}
          getCellContent={getData}
          onFill={onFill}
          rows={effectiveRows}
          showSearch={showSearch}
          onSearchClose={onSearchClose}
          rowMarkers="both"
          width="100%"
          height="100%"
          rowSelect="multi"
          columnSelect="single"
          gridSelection={selection}
          onGridSelectionChange={setSelection}
          getCellsForSelection={true}
          trailingRowOptions={{
            hint: ' ',
            sticky: true,
            tint: true
          }}
          freezeColumns={freezeColumnsCount}
          headerHeight={23}
          overscrollY={20}
          overscrollX={50}
