export default function DailyPlanRegistrationPage({
  permissions,
  canCreate,
  canEdit,
  canDelete,
  canView,
  controllers,
  cancelAllRequests,
  customLimits,
  ...restProps
}) {
  const { t } = useTranslation()
  const { formatDate, formatDateTime } = useDateFormat()
  const { setStatusMessage, setPageData, setSelectionStats } = usePageData() || {}
  const loadingBarRef = useRef(null)
  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
  const [isExportModalOpen, setIsExportModalOpen] = useState(false)

  const pagePerms = usePagePermissions({
    permissions,
    menuKey: 'report_data_import',
    canCreate,
    canEdit,
    canDelete,
    canView,
    ...restProps
  })

  // ── Master Registration Grid State ──
  const [masterGridData, setMasterGridData] = useState([])
  const [masterNumRows, setMasterNumRows] = useState(0)
  const [masterShowSearch, setMasterShowSearch] = useState(false)
  const [masterSelection, setMasterSelection] = useState({
    columns: CompactSelection.empty(),
    rows: CompactSelection.empty()
  })

  // Helper lấy danh sách index dòng đang chọn (hỗ trợ cả click đầu dòng, click ô hoặc quét vùng)
  const getSelectedRows = useCallback(() => {
    if (masterSelection?.rows && masterSelection.rows.toArray().length > 0) {
      return masterSelection.rows.toArray()
    }
    if (masterSelection?.current?.cell) {
      return [masterSelection.current.cell[1]]
    }
    if (masterSelection?.current?.range) {
      const { y, height } = masterSelection.current.range
      const rows = []
      for (let i = 0; i < height; i++) {
        rows.push(y + i)
      }
      return rows
    }
    return []
  }, [masterSelection])

  const masterDefaultCols = useProductionPlanColumns({
    isFieldVisible: pagePerms.isFieldVisible,
    isFieldReadOnly: pagePerms.isFieldReadOnly
  })
  const [masterCols, setMasterCols] = useState(masterDefaultCols)

  // Search Filter State
  const [searchValues, setSearchValues] = useState({
    FactoryName: '',
    ReportType: '',
    RegCode: '',
    ApplyDate: '',
    Status: ''
  })
  const [dynamicQueryFields, setDynamicQueryFields] = useState([])
  const originalDataRef = useRef([])

  // Modal xác nhận xóa
  const [confirmModal, setConfirmModal] = useState({
    isOpen: false,
    type: 'danger',
    title: '',
    message: '',
    subMessage: '',
    confirmText: 'Đồng ý',
    cancelText: 'Hủy bỏ',
    confirmVariant: 'danger',
    onConfirm: () => {}
  })

  // ── 1. Tải danh sách Master đăng ký báo cáo từ Database ──
  const fetchMasterData = useCallback(
    async (filters = {}) => {
      loadingBarRef?.current?.continuousStart?.()
      try {
        const res = await queryPlanMaster(filters)
        const dataList = res?.data || []
        const pageInfo = res?.pageInfo || res?.raw?.pageInfo || {}
        const total = Number(pageInfo?.total ?? pageInfo?.totalRows ?? dataList.length)
        const totalAll = Number(pageInfo?.totalAll || total)

        setMasterGridData(dataList)
        setMasterNumRows(dataList.length)
        originalDataRef.current = dataList

        const aCount = dataList.filter((r) => r.WorkingTag === 'A').length
        const uCount = dataList.filter((r) => r.WorkingTag === 'U').length
        const dCount = dataList.filter((r) => r.WorkingTag === 'D').length

        setPageData?.((prev) => ({
          ...prev,
          total,
          totalAll,
          loadedCount: dataList.length,
          totalColumns: masterCols.length,
          page: pageInfo?.page || 1,
          pageSize: pageInfo?.pageSize || dataList.length,
          totalPages: pageInfo?.totalPages || 1,
          rowStatusCounts: { aCount, uCount, dCount, eCount: 0 }
        }))

        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'success',
            text: t('Đã tải thành công {{loaded}} / {{total}} đợt đăng ký báo cáo', {
              loaded: dataList.length.toLocaleString('vi-VN'),
              total: total.toLocaleString('vi-VN')
            })
          })
        }

        return dataList
      } catch (err) {
        setMasterGridData([])
        setMasterNumRows(0)
        originalDataRef.current = []
        setPageData?.((prev) => ({
          ...prev,
          total: 0,
          totalAll: 0,
          loadedCount: 0,
          rowStatusCounts: { aCount: 0, uCount: 0, dCount: 0, eCount: 0 }
        }))
        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'error',
            text: t('Lỗi nạp danh sách đăng ký báo cáo từ máy chủ!')
          })
        }
        return []
      } finally {
        loadingBarRef?.current?.complete?.()
      }
    },
    [loadingBarRef, masterCols.length, setPageData, setStatusMessage, t]
  )

  // Tự động tính toán chỉ số thống kê kiểu Excel khi bôi đen / chọn ô trên bảng Master
  const statsRafRef = useRef(null)
  useEffect(() => {
    if (!setSelectionStats) return

    if (statsRafRef.current) {
      cancelAnimationFrame(statsRafRef.current)
    }

    statsRafRef.current = requestAnimationFrame(() => {
      const stats = calculateSelectionStats(masterSelection, masterGridData, masterCols)
      setSelectionStats(stats)
    })

    return () => {
      if (statsRafRef.current) {
        cancelAnimationFrame(statsRafRef.current)
      }
    }
  }, [masterSelection, masterGridData, masterCols, setSelectionStats])

  // Cập nhật thông tin Người tạo / Ngày tạo / Người sửa / Ngày sửa của dòng đang chọn xuống StatusBar
  useEffect(() => {
    const selectedRows = getSelectedRows()
    if (selectedRows.length > 0 && masterGridData.length > 0) {
      const firstRowIdx = selectedRows[0]
      const rowItem = masterGridData[firstRowIdx]
      if (rowItem) {
        setPageData?.((prev) => ({
          ...prev,
          createdBy: rowItem.CreatedByName || rowItem.CreatedBy || '',
          createdAt: rowItem.CreatedAt ? formatDateTime(rowItem.CreatedAt) : '',
          updatedBy: rowItem.UpdatedByName || rowItem.UpdatedBy || '',
          updatedAt: rowItem.UpdatedAt ? formatDateTime(rowItem.UpdatedAt) : ''
        }))
      }
    }
  }, [masterSelection, masterGridData, getSelectedRows, formatDateTime, setPageData])

  // Dọn dẹp thống kê khi unmount
  useEffect(() => {
    return () => {
      setSelectionStats && setSelectionStats(null)
    }
  }, [setSelectionStats])

  // Đồng bộ số lượng cột và số dòng hiển thị vào PageData
  useEffect(() => {
    setPageData?.((prev) => ({
      ...prev,
      totalColumns: masterCols.length,
      loadedCount: masterGridData.length
    }))
  }, [masterCols.length, masterGridData.length, setPageData])

  // Khởi tạo truy vấn danh sách Master khi load trang (chỉ 1 lần khi mount)
  useEffect(() => {
    fetchMasterData({})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ── 2. Xử lý Tìm kiếm Master ──
  const handleSearchData = useCallback(async () => {
    const dataList = await fetchMasterData(searchValues)
    if (dataList.length > 0) {
      setStatusMessage?.({
        type: 'success',
        text: `Tìm thấy ${dataList.length.toLocaleString('vi-VN')} đợt đăng ký báo cáo từ hệ thống`
      })
    } else {
      setStatusMessage?.({
        type: 'info',
        text: 'Không tìm thấy đợt đăng ký báo cáo phù hợp'
      })
    }
  }, [fetchMasterData, searchValues, setStatusMessage])

  // ── 3. Reset điều kiện tìm kiếm ──
  const onResetQuery = useCallback(() => {
    const emptyFilters = {
      FactoryName: '',
      ReportType: '',
      RegCode: '',
      ApplyDate: '',
      Status: ''
    }
    setSearchValues(emptyFilters)
    fetchMasterData({})
    setStatusMessage?.({
      type: 'info',
      text: 'Đã đặt lại điều kiện và tải lại danh sách đăng ký'
    })
  }, [fetchMasterData, setStatusMessage])

  const onAddQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => {
      if (prev.includes(fieldKey)) return prev
      return [...prev, fieldKey]
    })
  }, [])

  const onRemoveQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => prev.filter((k) => k !== fieldKey))
  }, [])

  // ── 4. Xử lý Lưu đăng ký mới từ Modal (Master + Chi tiết) ──
  const handleSaveRegistration = async (regData, onProgress = null) => {
    try {
      loadingBarRef?.current?.continuousStart?.()
      const res = await savePlanRegistration(regData, null, onProgress)
      loadingBarRef?.current?.complete?.()

      const savedMaster = res?.data || {}
      const finalCode = savedMaster?.RegCode || regData.regCode

      setStatusMessage?.({
        type: 'success',
        text: `Đã lưu thành công đăng ký báo cáo (${finalCode}) gồm ${regData.data?.length || 0} dòng chi tiết lên cơ sở dữ liệu!`
      })

      // Tự động load lại danh sách Master để hiển thị đợt đăng ký mới vừa tạo
      await fetchMasterData(searchValues)

      setIsAddModalOpen(false)
      return res
    } catch (err) {
      loadingBarRef?.current?.complete?.()
      setStatusMessage?.({
        type: 'error',
        text: `Lưu đăng ký thất bại: ${err?.message || 'Không thể kết nối đến máy chủ DataHub'}`
      })
      throw err
    }
  }

  // ── 5. Xóa đợt đăng ký Master đã chọn ──
  const handleDeleteData = useCallback(() => {
    if (!pagePerms.canDelete) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Bạn không có quyền xóa đợt đăng ký'
      })
      return
    }

    const selectedRows = getSelectedRows()
    if (selectedRows.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Vui lòng chọn ít nhất một đợt đăng ký trên bảng để xóa'
      })
      return
    }

    const selectedMasters = selectedRows.map((idx) => masterGridData[idx]).filter(Boolean)
    const masterSeqs = selectedMasters
      .map((m) => m.IdSeq || m.MasterSeq || m.RegCode)
      .filter(Boolean)

    if (masterSeqs.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Không tìm thấy ID hợp lệ của các đợt đăng ký đã chọn'
      })
      return
    }

    setConfirmModal({
      isOpen: true,
      type: 'danger',
      title: 'Xác nhận xóa đợt đăng ký',
      message: `Bạn có chắc chắn muốn xóa ${masterSeqs.length} đợt đăng ký đã chọn?`,
      subMessage:
        'Hành động này sẽ xóa vĩnh viễn đợt đăng ký cùng toàn bộ dữ liệu chi tiết đã nạp tương ứng trong cơ sở dữ liệu.',
      confirmText: 'Đồng ý xóa',
      cancelText: 'Hủy bỏ',
      confirmVariant: 'danger',
      onConfirm: async () => {
        setConfirmModal((prev) => ({ ...prev, isOpen: false }))
        loadingBarRef?.current?.continuousStart?.()
        try {
          await deletePlanMaster(masterSeqs)
          setStatusMessage?.({
            type: 'success',
            text: `Đã xóa thành công ${masterSeqs.length} đợt đăng ký và dữ liệu chi tiết tương ứng!`
          })
          await fetchMasterData(searchValues)
        } catch (err) {
          setStatusMessage?.({
            type: 'error',
            text: 'Xóa đợt đăng ký thất bại: ' + (err?.message || err)
          })
        } finally {
          loadingBarRef?.current?.complete?.()
        }
      }
    })
  }, [
    pagePerms.canDelete,
    masterSelection,
    masterGridData,
    setStatusMessage,
    fetchMasterData,
    searchValues
  ])

  // ── 6. Mở Modal Xuất danh sách Master ra Excel ──
  const handleOpenExportModal = useCallback(() => {
    if (!masterGridData || masterGridData.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Không có dữ liệu đợt đăng ký để xuất'
      })
      return
    }
    setIsExportModalOpen(true)
  }, [masterGridData, setStatusMessage])

  const executeExportMasterExcel = useCallback(
    async ({
      scope,
      fileName,
      saveDirectory,
      overwriteExisting,
      includeHeaders,
      exportableCols
    }) => {
      try {
        let dataToExport = masterGridData
        if (scope === 'selected') {
          const selectedRows = masterSelection?.rows?.items || []
          if (selectedRows.length > 0) {
            const indices = []
            selectedRows.forEach(([start, end]) => {
              for (let i = start; i < Math.min(masterGridData.length, end); i++) {
                indices.push(i)
              }
            })
            dataToExport = indices.map((idx) => masterGridData[idx]).filter(Boolean)
          } else if (masterSelection?.current?.range) {
            const { y, height } = masterSelection.current.range
            dataToExport = masterGridData.slice(y, Math.min(masterGridData.length, y + height))
          }
        }

        if (dataToExport.length === 0) {
          throw new Error('Không có dòng dữ liệu nào để xuất Excel!')
        }

        const filterSummary = formatFilterSummary(searchValues, formatDate)

        const wb = generateExcelWorkbook({
          data: dataToExport,
          columns: exportableCols || masterCols,
          sheetName: 'DanhSach_DangKy_BaoCao',
          reportTitle: t('DANH SÁCH ĐỢT ĐĂNG KÝ BÁO CÁO SẢN XUẤT (MASTER)'),
          filterInfo: filterSummary,
          includeHeaders: includeHeaders !== false,
          formatDateFn: formatDate
        })

        const saveResult = await saveWorkbookToFile(wb, fileName, saveDirectory, {
          overwriteExisting
        })

        setStatusMessage?.({
          type: 'success',
          text: `Đã xuất thành công ${dataToExport.length.toLocaleString('vi-VN')} dòng dữ liệu ra file [${saveResult?.filePath || fileName}]!`
        })
      } catch (err) {
        console.error('Lỗi khi xuất file Excel:', err)
        setStatusMessage?.({
          type: 'error',
          text: 'Xuất Excel thất bại: ' + (err?.message || err)
        })
        throw err
      }
    },
    [masterGridData, masterSelection, searchValues, formatDate, masterCols, t, setStatusMessage]
  )

  // ── Mở Form Đăng ký / Nạp mới: Electron -> Cửa sổ Windows con độc lập, Web -> Modal / Tab ──
  const handleOpenCreate = useCallback(() => {
    if (window.electron?.openChildWindow || window.electron?.ipcRenderer) {
      openChildWindow({
        path: '/sub/report/registration/create',
        title: 'Đăng ký & Nạp dữ liệu báo cáo sản xuất mới',
        width: 1380,
        height: 880,
        id: 'report-create-new'
      })
    } else {
      // Trên Web browser: mở modal nạp dữ liệu
      setIsAddModalOpen(true)
    }
  }, [])

  // ── Mở cửa sổ Windows mới xem dữ liệu chi tiết của đợt đăng ký đã chọn ──
  const handleOpenDetailWindow = useCallback(
    (targetRow = null) => {
      let selectedItem = targetRow
      if (!selectedItem) {
        const selectedIndices = getSelectedRows()
        if (selectedIndices && selectedIndices.length > 0 && masterGridData[selectedIndices[0]]) {
          selectedItem = masterGridData[selectedIndices[0]]
        } else if (masterGridData.length > 0) {
          selectedItem = masterGridData[0]
        }
      }

      if (!selectedItem || !selectedItem.RegCode) {
        setStatusMessage?.({
          type: 'warning',
          text: 'Vui lòng chọn 1 đợt đăng ký từ bảng để xem chi tiết dữ liệu!'
        })
        return
      }

      // Lưu cache để sub-window mở lên nhận ngay lập tức 0ms
      try {
        sessionStorage.setItem(`master_info_${selectedItem.RegCode}`, JSON.stringify(selectedItem))
        localStorage.setItem(`master_info_${selectedItem.RegCode}`, JSON.stringify(selectedItem))
      } catch {}

      const reportLabel = selectedItem.ReportType === 'statistics' ? 'TKSX' : 'KHSX'
      openChildWindow({
        path: `/sub/report/data/detail/${selectedItem.RegCode}`,
        title: `Chi tiết Đăng ký: ${selectedItem.RegCode} (${reportLabel})`,
        width: 1300,
        height: 850,
        id: `report-detail-${selectedItem.RegCode}`
      })
    },
    [getSelectedRows, masterGridData, setStatusMessage]
  )

  usePageHotkeys({
    onSearch: handleSearchData,
    onDelete: handleDeleteData,
    onOpenNewWindow: handleOpenDetailWindow
  })

  const cancelAllRequestsRef = useRef(cancelAllRequests)
  cancelAllRequestsRef.current = cancelAllRequests

  useEffect(() => {
    return () => {
      cancelAllRequestsRef.current?.()
    }
  }, [])

  return (
    <>
      <DataPageContainer
        loadingBarRef={loadingBarRef}
        actions={
          <PlanRegistrationActions
            handleSearchData={handleSearchData}
            handleDeleteDataSheet={handleDeleteData}
            handleOpenAddModal={handleOpenCreate}
            handleOpenDetailWindow={() => handleOpenDetailWindow()}
            handleExportExcel={handleOpenExportModal}
            permissions={pagePerms}
          />
        }
        query={
          <PlanRegistrationQuery
            searchValues={searchValues}
            setSearchValues={setSearchValues}
            dynamicQueryFields={dynamicQueryFields}
            onAddQueryField={onAddQueryField}
            onRemoveQueryField={onRemoveQueryField}
            onResetQuery={onResetQuery}
            handleSearchData={handleSearchData}
            disabled={!pagePerms.canView}
          />
        }
        table={
          <PlanRegistrationTable
            tableTitle={t('Danh sách đợt đăng ký báo cáo sản xuất (Master)')}
            canEdit={pagePerms.canEdit}
            canCreate={pagePerms.canCreate}
            defaultCols={masterDefaultCols}
            cols={masterCols}
            setCols={setMasterCols}
            gridData={masterGridData}
            setGridData={setMasterGridData}
            numRows={masterNumRows}
            setNumRows={setMasterNumRows}
            selection={masterSelection}
            setSelection={setMasterSelection}
            showSearch={masterShowSearch}
            setShowSearch={setMasterShowSearch}
            onAddQueryField={onAddQueryField}
            onOpenDetail={handleOpenDetailWindow}
          />
        }
      />

      {/* Modal nạp file Excel & Đăng ký báo cáo (KHSX / TKSX) */}
      <AddPlanRegistrationModal
        isOpen={isAddModalOpen}
        onClose={() => setIsAddModalOpen(false)}
        onSaveSuccess={async () => {
          setIsAddModalOpen(false)
          await fetchMasterData(searchValues)
        }}
        onSaveRegistration={handleSaveRegistration}
      />

      {/* Modal xác nhận xuất Excel */}
      <ExportExcelModal
        isOpen={isExportModalOpen}
        onClose={() => setIsExportModalOpen(false)}
        title={t('XÁC NHẬN XUẤT EXCEL - DANH SÁCH ĐỢT ĐĂNG KÝ')}
        reportName={t('Danh sách đợt đăng ký báo cáo sản xuất (Master)')}
        totalRows={masterGridData.length}
        loadedCount={masterGridData.length}
        selectedCount={
          masterSelection?.rows?.items?.reduce((acc, [s, e]) => acc + (e - s), 0) ||
          (masterSelection?.current?.range?.height ? masterSelection.current.range.height : 0)
        }
        columns={masterCols}
        activeFilters={searchValues}
        defaultFileName={`DanhSach_DangKy_BaoCao_${new Date().toISOString().slice(0, 10)}.xlsx`}
        onConfirmExport={executeExportMasterExcel}
      />

      {/* WindowsConfirmModal chuẩn hệ thống khi xóa */}
      <WindowsConfirmModal
        isOpen={confirmModal.isOpen}
        type={confirmModal.type}
        title={confirmModal.title}
        message={confirmModal.message}
        subMessage={confirmModal.subMessage}
        confirmText={confirmModal.confirmText}
        cancelText={confirmModal.cancelText}
        confirmVariant={confirmModal.confirmVariant}
        onConfirm={confirmModal.onConfirm}
        onCancel={() => setConfirmModal((prev) => ({ ...prev, isOpen: false }))}
      />
    </>
  )
}

/* eslint-disable react/prop-types */
import { useEffect, useRef, useState, useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { CompactSelection } from '@glideapps/glide-data-grid'
import * as XLSX from 'xlsx'

import { usePageHotkeys } from '../../../../hooks/usePageHotkeys'
import { usePagePermissions } from '../../../../hooks/usePagePermissions'
import { usePageData } from '../../../../../context/PageDataContext'
import DataPageContainer from '../../../../components/layout/DataPageContainer'
import { FormulaHandbookModal } from '../../production/handbook/FormulaHandbookModal'
import { calculateSelectionStats } from '../../../../hooks/useDataGridSheet'
import { loadFromLocalStorageSheet } from '../../../../../localStorage/sheet/sheet'
import { ensureStatusFirstColumn } from '../../../../../utils/systemColumns'
import ExportExcelModal from '../../../../components/modal/ExportExcelModal'
import {
  generateExcelWorkbook,
  saveWorkbookToFile,
  formatFilterSummary
} from '../../../../../utils/exportExcelUtils'
import { useDateFormat } from '../../../../hooks/useDateFormat'

import { usePlanImportColumns } from './columns/planImportColumns'
import PlanDetailQueryActions from './components/PlanDetailQueryActions'
import PlanDetailQueryFilters from './components/PlanDetailQueryFilters'
import PlanDetailQueryTable from './components/PlanDetailQueryTable'
import { queryPlanDetail } from '../services/planRegistrationService'

export default function PlanDetailQueryPage({
  permissions,
  canCreate,
  canEdit,
  canDelete,
  canView,
  cancelAllRequests,
  ...restProps
}) {
  const { t } = useTranslation()
  const { setPageData, setStatusMessage, setSelectionStats } = usePageData() || {}
  const loadingBarRef = useRef(null)

  const pagePerms = usePagePermissions({
    permissions,
    menuKey: 'report_plan_query',
    canCreate,
    canEdit,
    canDelete,
    canView,
    ...restProps
  })

  // Columns & Grid State
  const defaultCols = usePlanImportColumns({
    isFieldVisible: pagePerms.isFieldVisible,
    isFieldReadOnly: pagePerms.isFieldReadOnly
  })
  const [columns, setColumns] = useState(() => {
    const saved = loadFromLocalStorageSheet('S_ERP_COLS_plan_detail_query_table', [])
    if (saved && saved.length > 0) {
      return ensureStatusFirstColumn(saved, defaultCols)
    }
    return defaultCols.filter((col) => col.visible !== false)
  })
  const [gridData, setGridData] = useState([])
  const [selection, setSelection] = useState({
    columns: CompactSelection.empty(),
    rows: CompactSelection.empty()
  })

  // Pagination & Infinite Scroll State
  const [page, setPage] = useState(1)
  const pageSize = 1000
  const [totalRows, setTotalRows] = useState(0)
  const [isLoadingMore, setIsLoadingMore] = useState(false)
  const [hasMore, setHasMore] = useState(true)

  const isLoadingRef = useRef(false)
  const pageRef = useRef(1)
  const hasMoreRef = useRef(true)
  const gridDataRef = useRef([])
  const searchValuesRef = useRef({
    FactoryName: '',
    RegCode: '',
    ApplyDate: '',
    FromDate: '',
    ToDate: '',
    OpDate: '',
    PicDp: '',
    MachineName: '',
    ItemCode: '',
    StatusDpSx: '',
    CapaStatus: '',
    Keyword: ''
  })
  const colFilterValuesRef = useRef({})

  // Group By State
  const [groupBy, setGroupBy] = useState('none')

  // Per-column Header Filter State
  const [showColFilters, setShowColFilters] = useState(false)
  const [colFilterValues, setColFilterValues] = useState({})

  // Handbook Modal
  const [isHandbookOpen, setIsHandbookOpen] = useState(false)

  // Quản lý trạng thái các trường tìm kiếm động
  const STORAGE_KEY_PLAN_QUERY = 'S_ERP_QUERY_FIELDS_plan_detail'
  const DEFAULT_PLAN_VISIBLE_KEYS = [
    'FactoryName',
    'RegCode',
    'ApplyDate',
    'OperationNo',
    'PicDp',
    'OpDate',
    'ItemCode',
    'ItemName'
  ]

  const [visibleKeys, setVisibleKeys] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_PLAN_QUERY)
      if (saved) {
        const parsed = JSON.parse(saved)
        if (Array.isArray(parsed) && parsed.length > 0) {
          return new Set(parsed)
        }
      }
    } catch {}
    return new Set(DEFAULT_PLAN_VISIBLE_KEYS)
  })

  const handleToggleField = useCallback((fieldKey, isChecked) => {
    setVisibleKeys((prev) => {
      const next = new Set(prev)
      if (isChecked) {
        next.add(fieldKey)
      } else {
        next.delete(fieldKey)
      }
      try {
        localStorage.setItem(STORAGE_KEY_PLAN_QUERY, JSON.stringify(Array.from(next)))
      } catch {}
      return next
    })
  }, [])

  const handleResetQueryFields = useCallback(() => {
    const next = new Set(DEFAULT_PLAN_VISIBLE_KEYS)
    setVisibleKeys(next)
    try {
      localStorage.setItem(STORAGE_KEY_PLAN_QUERY, JSON.stringify(Array.from(next)))
    } catch {}
  }, [])

  // Dynamic Query Bar State
  const [searchValues, setSearchValues] = useState({
    FactoryName: '',
    RegCode: '',
    ApplyDate: '',
    OperationNo: '',
    OpDate: '',
    PicDp: '',
    MachineName: '',
    ItemCode: '',
    ItemName: '',
    StatusDpSx: '',
    CapaStatus: '',
    Keyword: ''
  })
  const [dynamicQueryFields, setDynamicQueryFields] = useState([])

  useEffect(() => {
    searchValuesRef.current = searchValues
  }, [searchValues])

  useEffect(() => {
    colFilterValuesRef.current = colFilterValues
  }, [colFilterValues])

  // ── 1. Truy vấn dữ liệu KHSX từ Backend API ──
  const fetchPlanDetailData = useCallback(
    async (currentPage = 1, append = false, customFilters = null) => {
      if (isLoadingRef.current) return
      isLoadingRef.current = true
      setIsLoadingMore(true)
      loadingBarRef?.current?.continuousStart?.()

      const filtersToUse = customFilters || searchValuesRef.current

      try {
        const payload = {
          page: String(currentPage),
          pageSize: String(pageSize),
          ...filtersToUse,
          ...colFilterValuesRef.current
        }

        const res = await queryPlanDetail(payload)
        const rawItems = res?.data || []
        const items = rawItems.map((row) => ({ ...row, WorkingTag: '' }))
        const pageInfo = res?.pageInfo || res?.raw?.pageInfo || res?.page || res?.raw?.page || {}
        const total = Number(
          pageInfo?.total ??
            pageInfo?.totalRows ??
            (append ? gridDataRef.current.length + items.length : items.length)
        )
        const totalAll = Number(pageInfo?.totalAll || total)

        let nextData = []
        if (append) {
          nextData = [...gridDataRef.current, ...items]
        } else {
          nextData = items
        }

        gridDataRef.current = nextData
        setGridData(nextData)
        setTotalRows(total)

        const hasMoreData = items.length > 0 && nextData.length < total
        hasMoreRef.current = hasMoreData
        setHasMore(hasMoreData)

        pageRef.current = currentPage
        setPage(currentPage)

        // Cập nhật đầy đủ chỉ số cho StatusBar dưới đáy
        setPageData?.((prev) => ({
          ...prev,
          total,
          totalAll,
          loadedCount: nextData.length,
          totalColumns: columns.length,
          page: currentPage,
          pageSize,
          totalPages: Math.ceil(total / pageSize) || 1,
          hasMore: hasMoreData,
          rowStatusCounts: { aCount: 0, uCount: 0, dCount: 0, eCount: 0 }
        }))

        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'success',
            text: t('Đã tải thành công {{loaded}} / {{total}} dòng dữ liệu KHSX', {
              loaded: nextData.length.toLocaleString('vi-VN'),
              total: total.toLocaleString('vi-VN')
            })
          })
        }

        return items
      } catch (err) {
        console.error('Error fetching plan detail data:', err)
        if (!append) {
          gridDataRef.current = []
          setGridData([])
          setTotalRows(0)
        }
        if (typeof setStatusMessage === 'function') {
          setStatusMessage({
            type: 'error',
            text: t('Lỗi nạp dữ liệu chi tiết KHSX từ máy chủ!')
          })
        }
        return []
      } finally {
        isLoadingRef.current = false
        setIsLoadingMore(false)
        loadingBarRef?.current?.complete?.()
      }
    },
    [columns.length, pageSize, setPageData, setStatusMessage, t]
  )

  // Load initial page
  useEffect(() => {
    fetchPlanDetailData(1, false, searchValues)
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Handle Search Trigger
  const handleSearch = useCallback(() => {
    pageRef.current = 1
    setPage(1)
    fetchPlanDetailData(1, false, searchValuesRef.current)
  }, [fetchPlanDetailData])

  // Handle Reset Filter
  const handleResetQuery = useCallback(() => {
    const emptyFilters = {
      FactoryName: '',
      RegCode: '',
      ApplyDate: '',
      OperationNo: '',
      OpDate: '',
      PicDp: '',
      MachineName: '',
      ItemCode: '',
      ItemName: '',
      StatusDpSx: '',
      CapaStatus: '',
      Keyword: ''
    }
    setSearchValues(emptyFilters)
    setColFilterValues({})
    searchValuesRef.current = emptyFilters
    colFilterValuesRef.current = {}
    pageRef.current = 1
    setPage(1)
    fetchPlanDetailData(1, false, emptyFilters)
  }, [fetchPlanDetailData])

  // Handle Ctrl+F / Right-click on cell -> Push into query & filter & auto reveal column
  const handleApplyFilterFromCell = useCallback(
    (colKey, value, colTitle) => {
      if (!colKey || colKey === 'WorkingTag' || colKey.startsWith('_')) return

      // 1. Tự động thêm cột vào thanh tìm kiếm nếu chưa hiển thị
      setVisibleKeys((prev) => {
        if (!prev.has(colKey)) {
          const next = new Set(prev)
          next.add(colKey)
          try {
            localStorage.setItem(STORAGE_KEY_PLAN_QUERY, JSON.stringify(Array.from(next)))
          } catch {}
          return next
        }
        return prev
      })

      // 2. Gán giá trị vào searchValues
      const nextFilters = {
        ...searchValuesRef.current,
        [colKey]: value || ''
      }
      setSearchValues(nextFilters)
      searchValuesRef.current = nextFilters

      // 3. Nhảy chuột (Focus) ngay vào ô input của cột đó trên thanh tìm kiếm
      setTimeout(() => {
        const targetInput =
          document.getElementById(`query-input-${colKey}`) ||
          document.querySelector(`[data-query-key="${colKey.toLowerCase()}"]`) ||
          document.querySelector(`input[name="${colKey}"]`)
        if (targetInput) {
          targetInput.focus()
          if (typeof targetInput.select === 'function') {
            targetInput.select()
          }
        }
      }, 60)

      if (typeof setStatusMessage === 'function') {
        setStatusMessage({
          type: 'success',
          text: t('Đã tự động tạo điều kiện tìm kiếm cho cột [{{col}}] với giá trị: "{{val}}"', {
            col: colTitle || colKey,
            val: value || t('Tất cả')
          })
        })
      }
    },
    [fetchPlanDetailData, setStatusMessage, t]
  )

  // Handle Infinite Scroll when scrolling reaches row 500 / near bottom
  const onVisibleRegionChanged = useCallback(
    (range) => {
      if (!hasMoreRef.current || isLoadingRef.current) return
      const bottomRow = range.y + range.height
      const currentCount = gridDataRef.current.length
      // Tự động tải tiếp trang khi cuộn đến dòng 500 hoặc cách đáy 500 dòng
      if (
        currentCount > 0 &&
        (bottomRow >= currentCount - 500 || (currentCount === 1000 && bottomRow >= 500))
      ) {
        fetchPlanDetailData(pageRef.current + 1, true)
      }
    },
    [fetchPlanDetailData]
  )

  // ── 2. Bộ lọc Client-Side / Realtime theo từng cột (Hỗ trợ nhiều giá trị dấu phẩy) & Nhóm Group ──
  const filteredAndGroupedData = useMemo(() => {
    let result = [...gridData]

    // Áp dụng bộ lọc từng cột nếu có (hỗ trợ nhiều giá trị cách nhau bằng dấu phẩy)
    const activeFilterEntries = Object.entries(colFilterValues).filter(
      ([, val]) => val && String(val).trim() !== ''
    )
    if (activeFilterEntries.length > 0) {
      result = result.filter((row) => {
        return activeFilterEntries.every(([colId, filterVal]) => {
          const cellVal = String(row[colId] || '').toLowerCase()
          const tokens = String(filterVal)
            .split(/[,;]+/)
            .map((s) => s.trim().toLowerCase())
            .filter(Boolean)
          if (tokens.length <= 1) {
            return cellVal.includes(tokens[0] || '')
          }
          return tokens.some((token) => cellVal.includes(token))
        })
      })
    }

    // Nếu không nhóm dữ liệu
    if (groupBy === 'none') {
      return result.map((item, index) => ({
        ...item,
        _displayIndex: index + 1,
        _isGroupHeader: false
      }))
    }

    // Nhóm dữ liệu theo trường đã chọn
    const groups = {}
    result.forEach((item) => {
      const groupKey = item[groupBy] || t('Chưa xác định / Khác')
      if (!groups[groupKey]) {
        groups[groupKey] = []
      }
      groups[groupKey].push(item)
    })

    const finalRows = []
    Object.entries(groups).forEach(([groupName, items]) => {
      const totalPlanQty = items.reduce((sum, r) => sum + (Number(r.PlanQty) || 0), 0)

      finalRows.push({
        _isGroupHeader: true,
        _groupTitle: `[${groupName}] - (${items.length} bản ghi)`,
        _totalPlanQty: totalPlanQty,
        [groupBy]: groupName
      })

      items.forEach((it, idx) => {
        finalRows.push({
          ...it,
          _displayIndex: idx + 1,
          _isGroupHeader: false
        })
      })
    })

    return finalRows
  }, [colFilterValues, gridData, groupBy, t])

  // ── 2.5. Tự động tính toán chỉ số thống kê kiểu Excel khi bôi đen / chọn ô trên bảng ──
  const statsRafRef = useRef(null)
  useEffect(() => {
    if (!setSelectionStats) return

    if (statsRafRef.current) {
      cancelAnimationFrame(statsRafRef.current)
    }

    statsRafRef.current = requestAnimationFrame(() => {
      const stats = calculateSelectionStats(selection, filteredAndGroupedData, columns)
      setSelectionStats(stats)
    })

    return () => {
      if (statsRafRef.current) {
        cancelAnimationFrame(statsRafRef.current)
      }
    }
  }, [selection, filteredAndGroupedData, columns, setSelectionStats])

  // Dọn dẹp thống kê khi unmount
  useEffect(() => {
    return () => {
      setSelectionStats && setSelectionStats(null)
    }
  }, [setSelectionStats])

  // Đồng bộ số lượng cột và số dòng hiển thị vào PageData
  useEffect(() => {
    setPageData?.((prev) => ({
      ...prev,
      totalColumns: columns.length,
      loadedCount: filteredAndGroupedData.length
    }))
  }, [columns.length, filteredAndGroupedData.length, setPageData])

  const [isExportModalOpen, setIsExportModalOpen] = useState(false)
  const { formatDate } = useDateFormat()

  const handleOpenExportModal = useCallback(() => {
    const totalCount = totalRows || filteredAndGroupedData.length
    if (totalCount === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: t('Không có dữ liệu phù hợp với điều kiện để xuất Excel!')
      })
      return
    }
    setIsExportModalOpen(true)
  }, [filteredAndGroupedData.length, setStatusMessage, t, totalRows])

  // ── 3. Thực hiện Xuất dữ liệu Excel chuẩn sau khi đã xác nhận thông tin ──
  const executeExportPlanExcel = useCallback(
    async ({
      scope,
      fileName,
      saveDirectory,
      overwriteExisting,
      includeHeaders,
      exportableCols
    }) => {
      loadingBarRef?.current?.continuousStart?.()
      try {
        let dataToExport = []

        if (scope === 'all' || !scope) {
          if (totalRows > gridData.length) {
            const BATCH_SIZE = 3000
            const totalBatches = Math.max(1, Math.ceil(totalRows / BATCH_SIZE))
            const collectedData = []

            for (let pageNum = 1; pageNum <= totalBatches; pageNum++) {
              setStatusMessage?.({
                type: 'info',
                text: t(
                  'Đang nạp an toàn từ máy chủ: {{current}}/{{total}} dòng (Đợt {{page}}/{{totalPages}})...',
                  {
                    current: collectedData.length.toLocaleString('vi-VN'),
                    total: totalRows.toLocaleString('vi-VN'),
                    page: pageNum,
                    totalPages: totalBatches
                  }
                )
              })

              const payload = {
                page: String(pageNum),
                pageSize: String(BATCH_SIZE),
                ...searchValuesRef.current,
                ...colFilterValuesRef.current
              }

              const res = await queryPlanDetail(payload)
              const batchItems = res?.data || []
              if (batchItems.length === 0) break

              // Push trực tiếp để tiết kiệm RAM tối đa, tránh tạo bản sao mảng
              for (let i = 0; i < batchItems.length; i++) {
                collectedData.push(batchItems[i])
              }

              if (collectedData.length >= totalRows) break

              // Nghỉ 40ms giữa các đợt để giải phóng Event Loop, giúp UI mượt và không gây tải dồn dập cho Server
              await new Promise((resolve) => setTimeout(resolve, 40))
            }

            dataToExport = collectedData.map((r, i) => ({
              ...r,
              WorkingTag: '',
              _displayIndex: i + 1,
              _isGroupHeader: false
            }))
          } else {
            dataToExport = filteredAndGroupedData
          }
        } else if (scope === 'selected') {
          const selectedRows = selection?.rows?.items || []
          if (selectedRows.length > 0) {
            const indices = []
            selectedRows.forEach(([start, end]) => {
              for (let i = start; i < Math.min(filteredAndGroupedData.length, end); i++) {
                indices.push(i)
              }
            })
            dataToExport = indices.map((idx) => filteredAndGroupedData[idx]).filter(Boolean)
          } else if (selection?.current?.range) {
            const { y, height } = selection.current.range
            dataToExport = filteredAndGroupedData.slice(
              y,
              Math.min(filteredAndGroupedData.length, y + height)
            )
          } else {
            dataToExport = filteredAndGroupedData
          }
        } else {
          dataToExport = filteredAndGroupedData
        }

        if (dataToExport.length === 0) {
          throw new Error(t('Không có dòng dữ liệu nào để xuất Excel!'))
        }

        const filterText = formatFilterSummary(
          { ...searchValuesRef.current, ...colFilterValuesRef.current },
          formatDate
        )

        const wb = generateExcelWorkbook({
          data: dataToExport,
          columns: exportableCols || columns,
          sheetName: 'ChiTiet_KHSX',
          reportTitle: t('BÁO CÁO TRUY VẤN CHI TIẾT KẾ HOẠCH SẢN XUẤT (ĐIỀU PHỐI KHSX)'),
          filterInfo: filterText,
          includeHeaders: includeHeaders !== false,
          formatDateFn: formatDate
        })

        const saveResult = await saveWorkbookToFile(wb, fileName, saveDirectory, {
          overwriteExisting
        })

        setStatusMessage?.({
          type: 'success',
          text: t('Đã xuất thành công đủ {{count}} dòng dữ liệu ra file [{{file}}]!', {
            count: dataToExport.length.toLocaleString('vi-VN'),
            file: saveResult?.filePath || fileName
          })
        })
      } catch (err) {
        console.error('Lỗi khi xuất file Excel:', err)
        setStatusMessage?.({
          type: 'error',
          text: t('Xuất file Excel thất bại: ') + (err?.message || err)
        })
        throw err
      } finally {
        loadingBarRef?.current?.complete?.()
      }
    },
    [
      columns,
      filteredAndGroupedData,
      formatDate,
      gridData.length,
      selection,
      setStatusMessage,
      t,
      totalRows
    ]
  )

  const drawerOpenerRef = useRef(null)
  const [showSearch, setShowSearch] = useState(false)

  // Phím tắt Hotkeys
  usePageHotkeys({
    onSearch: handleSearch,
    onRefresh: () => fetchPlanDetailData(1, false, searchValues),
    onExportExcel: handleOpenExportModal
  })

  return (
    <>
      <DataPageContainer
        loadingBarRef={loadingBarRef}
        actions={
          <PlanDetailQueryActions
            handleSearchData={handleSearch}
            handleExportExcel={handleOpenExportModal}
            isLoading={isLoadingMore}
            permissions={pagePerms}
          />
        }
        query={
          <PlanDetailQueryFilters
            columns={columns}
            searchValues={searchValues}
            setSearchValues={setSearchValues}
            visibleKeys={visibleKeys}
            onToggleField={handleToggleField}
            onResetFields={handleResetQueryFields}
            dynamicQueryFields={dynamicQueryFields}
            onAddQueryField={setDynamicQueryFields}
            onResetQuery={handleResetQuery}
            handleSearchData={handleSearch}
            disabled={!pagePerms.canView}
          />
        }
        table={
          <PlanDetailQueryTable
            tableTitle={t('Truy vấn chi tiết Kế hoạch sản xuất (KHSX)')}
            cols={columns}
            setCols={setColumns}
            defaultCols={defaultCols}
            gridData={filteredAndGroupedData}
            setGridData={setGridData}
            selection={selection}
            setSelection={setSelection}
            showSearch={showSearch}
            setShowSearch={setShowSearch}
            onVisibleRegionChanged={onVisibleRegionChanged}
            showColFilters={showColFilters}
            colFilterValues={colFilterValues}
            setColFilterValues={setColFilterValues}
            onApplyFilterFromCell={handleApplyFilterFromCell}
            onAddQueryField={handleApplyFilterFromCell}
            onRegisterDrawer={(fn) => {
              drawerOpenerRef.current = fn
            }}
            onExportExcel={handleOpenExportModal}
            isLoadingMore={isLoadingMore}
            hasMore={hasMore}
            loadedCount={gridData.length}
            displayCount={filteredAndGroupedData.length}
            totalRows={totalRows}
          />
        }
      />

      {/* Modal xác nhận và kiểm tra thông tin xuất Excel */}
      <ExportExcelModal
        isOpen={isExportModalOpen}
        onClose={() => setIsExportModalOpen(false)}
        title={t('XÁC NHẬN XUẤT EXCEL - CHI TIẾT KHSX')}
        reportName={t('Báo cáo Truy vấn chi tiết Kế hoạch sản xuất (Điều phối KHSX)')}
        totalRows={totalRows}
        loadedCount={gridData.length}
        selectedCount={
          selection?.rows?.items?.reduce((acc, [s, e]) => acc + (e - s), 0) ||
          (selection?.current?.range?.height ? selection.current.range.height : 0)
        }
        columns={columns}
        activeFilters={{ ...searchValues, ...colFilterValues }}
        defaultFileName={`TruyVan_ChiTiet_KHSX_${new Date().toISOString().slice(0, 10)}.xlsx`}
        onConfirmExport={executeExportPlanExcel}
      />

      {/* Modal cẩm nang công thức */}
      <FormulaHandbookModal
        isOpen={isHandbookOpen}
        onClose={() => setIsHandbookOpen(false)}
        defaultReportType="plan"
      />
    </>
  )
}

