import { useMemo, useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import DynamicQueryBar from '../../../../../components/query/core/DynamicQueryBar'

export const STORAGE_KEY = 'S_ERP_QUERY_FIELDS_plan_detail'

export const DEFAULT_VISIBLE_KEYS = [
  'FactoryName',
  'RegCode',
  'ApplyDate',
  'OperationNo',
  'PicDp',
  'OpDate',
  'ItemCode',
  'ItemName'
]

const DEFAULT_KEYS_SET = new Set(DEFAULT_VISIBLE_KEYS)

export default function PlanDetailQueryFilters({
  columns = [],
  searchValues = {},
  setSearchValues,
  dynamicQueryFields = [],
  visibleKeys: controlledVisibleKeys,
  onToggleField: controlledToggleField,
  onResetFields: controlledResetFields,
  onAddQueryField,
  onRemoveQueryField,
  onResetQuery,
  handleSearchData,
  disabled = false
}) {
  const { t } = useTranslation()

  // Lưu trạng thái các trường được hiển thị (nội bộ nếu không được truyền từ parent)
  const [internalVisibleKeys, setInternalVisibleKeys] = useState(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY)
      if (saved) {
        const parsed = JSON.parse(saved)
        if (Array.isArray(parsed) && parsed.length > 0) {
          return new Set(parsed)
        }
      }
    } catch {}
    return new Set(DEFAULT_VISIBLE_KEYS)
  })

  const visibleKeys = controlledVisibleKeys || internalVisibleKeys

  // Bật/tắt cột tìm kiếm động
  const handleToggleField = useCallback(
    (fieldKey, isChecked) => {
      if (controlledToggleField) {
        controlledToggleField(fieldKey, isChecked)
        return
      }
      setInternalVisibleKeys((prev) => {
        const next = new Set(prev)
        if (isChecked) {
          next.add(fieldKey)
        } else {
          next.delete(fieldKey)
        }
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(next)))
        } catch {}
        return next
      })
    },
    [controlledToggleField]
  )

  // Đặt lại danh sách cột mặc định
  const handleResetFields = useCallback(() => {
    if (controlledResetFields) {
      controlledResetFields()
      return
    }
    const next = new Set(DEFAULT_VISIBLE_KEYS)
    setInternalVisibleKeys(next)
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(next)))
    } catch {}
  }, [controlledResetFields])

  const handleFieldChange = useCallback(
    (key, value) => {
      setSearchValues((prev) => ({
        ...prev,
        [key]: value
      }))
    },
    [setSearchValues]
  )

  // Xóa bỏ một trường tìm kiếm không mặc định (Nút x) và xóa giá trị lọc của nó
  const handleRemoveField = useCallback(
    (fieldKey) => {
      handleToggleField(fieldKey, false)
      handleFieldChange(fieldKey, '')
    },
    [handleToggleField, handleFieldChange]
  )

  // Toàn bộ các trường tìm kiếm: TỰ ĐỘNG TẠO TỪ 100% CỘT TRÊN BẢNG KÈM CÁC TRƯỜNG ĐẶC BIỆT
  const allAvailableFields = useMemo(() => {
    const fields = []
    const forbidden = new Set([
      'workingtag',
      'status',
      'indexno',
      'idseq',
      '_displayindex',
      '_isgroupheader'
    ])

    // 1. Thêm các trường bộ lọc ngày và nhà máy lên đầu
    fields.push(
      {
        key: 'FactoryName',
        label: t('Nhà máy'),
        type: 'select',
        options: [
          { value: '', label: 'Tất cả nhà máy' },
          { value: 'GS1 Hà Nội', label: 'GS1 Hà Nội' },
          { value: 'GS5 Quế Võ 1B', label: 'GS5 Quế Võ 1B' }
        ]
      },
      {
        key: 'RegCode',
        label: t('Mã đợt đăng ký'),
        type: 'text',
        placeholder: 'Nhập mã đợt ĐK...'
      },
      {
        key: 'ApplyDate',
        label: t('Ngày áp dụng ĐK'),
        type: 'date'
      },
      {
        key: 'OperationNo',
        label: t('Số lệnh thao tác'),
        type: 'text',
        placeholder: 'Nhập số lệnh thao tác...'
      },
      {
        key: 'PicDp',
        label: t('PIC ĐP'),
        type: 'text',
        placeholder: 'Nhập PIC điều phối...'
      },
      {
        key: 'OpDate',
        label: t('Ngày thực hiện thao tác'),
        type: 'date'
      },
      {
        key: 'ItemCode',
        label: t('Mã hàng'),
        type: 'text',
        placeholder: 'Nhập mã hàng...'
      },
      {
        key: 'ItemName',
        label: t('Tên hàng'),
        type: 'text',
        placeholder: 'Nhập tên hàng...'
      }
    )

    // 2. Thêm TẤT CẢ các cột còn lại trên bảng sheet vào danh sách điều kiện tìm kiếm
    ;(columns || []).forEach((col) => {
      const k = col.id || col.key
      if (!k || forbidden.has(k.toLowerCase()) || fields.some((f) => f.key === k)) return

      const isDate =
        k.endsWith('Date') || (k.includes('Time') && !k.includes('ProdTime')) || col.kind === 'Date'
      let type = 'text'
      let options = undefined

      if (isDate) {
        type = 'date'
      }

      const colTitle = typeof col.title === 'string' ? col.title.replace(/\n/g, ' ') : k

      fields.push({
        key: k,
        label: colTitle ? t(colTitle) : k,
        type,
        options,
        placeholder: `Nhập ${colTitle}...`
      })
    })

    // 3. Thêm trường từ khóa Keyword
    if (!fields.some((f) => f.key === 'Keyword')) {
      fields.push({
        key: 'Keyword',
        label: t('Từ khóa tìm kiếm'),
        type: 'text',
        placeholder: 'Mã đơn, Phiếu KH, Tên SP, PIC...'
      })
    }

    return fields
  }, [columns, t])

  // Danh sách các fields hiển thị trên thanh QueryBar dựa trên visibleKeys
  // Nếu trường không thuộc danh sách mặc định (ví dụ được thêm qua Ctrl+F) thì gắn onRemove để hiển thị nút [x]
  const renderedFields = useMemo(() => {
    return allAvailableFields.map((f) => {
      const isDefault = DEFAULT_KEYS_SET.has(f.key)
      return {
        ...f,
        visible: visibleKeys.has(f.key),
        isDefault,
        onRemove: !isDefault ? () => handleRemoveField(f.key) : undefined
      }
    })
  }, [allAvailableFields, visibleKeys, handleRemoveField])

  const currentValues = useMemo(() => {
    const base = {}
    allAvailableFields.forEach((f) => {
      base[f.key] = searchValues[f.key] || ''
    })
    return {
      ...base,
      ...searchValues
    }
  }, [allAvailableFields, searchValues])

  return (
    <div className="w-full bg-white">
      <DynamicQueryBar
        fields={renderedFields}
        allAvailableFields={allAvailableFields}
        values={currentValues}
        onChange={handleFieldChange}
        onSearch={handleSearchData}
        onReset={onResetQuery}
        onToggleField={handleToggleField}
        onResetFields={handleResetFields}
        disabled={disabled}
        columns={4}
      />
    </div>
  )
}

/* eslint-disable react/prop-types */
import { useCallback, useRef, useMemo, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { DataEditor, GridCellKind } from '@glideapps/glide-data-grid'
import '@glideapps/glide-data-grid/dist/index.css'
import { RotateCw, SlidersHorizontal, X } from 'lucide-react'

import LayoutMenuSheet from '../../../../../components/sheet/jsx/layoutMenu'
import LayoutStatusMenuSheet from '../../../../../components/sheet/jsx/layoutStatusMenu'
import LayoutContextMenuSheet from '../../../../../components/sheet/jsx/layoutContextMenu'
import { Drawer, Checkbox } from '../../../../../../components/ui'
import useTableManager from '../../../../../components/hooks/sheet/useTableManager'
import useTableConfig from '../../../../../components/hooks/sheet/useTableConfig'
import { useDateFormat } from '../../../../../hooks/useDateFormat'

const EMPTY_ARRAY = []

export default function PlanDetailQueryTable({
  tableTitle,
  cols = [],
  setCols,
  defaultCols,
  gridData = [],
  setGridData,
  selection,
  setSelection,
  showSearch,
  setShowSearch,
  onVisibleRegionChanged,
  showColFilters = false,
  colFilterValues = {},
  setColFilterValues,
  onApplyFilterFromCell,
  onAddQueryField,
  onRegisterDrawer,
  onExportExcel,
  isLoadingMore = false,
  hasMore = false,
  loadedCount = 0,
  displayCount = 0,
  totalRows = 0
}) {
  const { t } = useTranslation()
  const { formatDate } = useDateFormat()
  const gridRef = useRef(null)

  const { freezeColumnsCount, handleFreezeColumn } = useTableConfig('plan_detail_query_table')

  const {
    showMenu,
    setShowMenu,
    onHeaderMenuClick,
    layerProps,
    renderLayer,
    hiddenColumns,
    handleHideColumn,
    handleReset,
    onColumnMoved,
    onColumnResize,
    handleSort,
    openDrawer: open,
    setOpenDrawer: setOpen,
    showDrawer,
    handleCheckboxChange,
    configurableCols,
    keybindings,
    getCellTheme,
    isReadOnlyColumn,
    gridTheme,
    onCellClicked,
    onCellActivated,
    onKeyDown: baseOnKeyDown,
    onCellContextMenu,
    onHeaderContextMenu
  } = useTableManager({
    tableId: 'plan_detail_query_table',
    defaultCols,
    cols,
    setCols,
    setGridData: setGridData || (() => {}),
    gridData,
    selection,
    setSelection,
    canEdit: false,
    setShowSearch,
    onAddQueryField: onAddQueryField || onApplyFilterFromCell
  })

  useEffect(() => {
    if (typeof onRegisterDrawer === 'function') {
      onRegisterDrawer(showDrawer)
    }
  }, [onRegisterDrawer, showDrawer])

  const onSearchClose = useCallback(() => {
    if (typeof setShowSearch === 'function') setShowSearch(false)
  }, [setShowSearch])

  const onClose = () => setOpen(false)

  // ── 1. PRE-COMPUTE METADATA CHO CÁC CỘT (O(1) Cell Provider Lookup) ──
  const colMetadata = useMemo(() => {
    return (cols || []).map((column) => {
      const columnKey = column.id || ''
      const isStatus =
        columnKey === 'StatusDpSx' || columnKey === 'CapaStatus' || columnKey === 'WorkingTag'
      const isNumber =
        column.kind === 'Number' ||
        columnKey.includes('Qty') ||
        columnKey.includes('Hours') ||
        columnKey.includes('Rate') ||
        columnKey.includes('Minute') ||
        columnKey.includes('Total') ||
        columnKey.includes('Output') ||
        columnKey.includes('Speed')
      const isDate = columnKey.endsWith('Date') || columnKey.includes('Time')
      const cellTheme = getCellTheme(columnKey, column)
      const isReadOnly = isReadOnlyColumn(columnKey, column) || column.readonly || true

      return {
        columnKey,
        isStatus,
        isNumber,
        isDate,
        kind: column.kind,
        title: column.title || columnKey,
        cellTheme,
        isReadOnly,
        hasMenu: column.hasMenu || false
      }
    })
  }, [cols, getCellTheme, isReadOnlyColumn])

  // ── 2. SIÊU TỐI ƯU HÓA HÀM TRUY XUẤT Ô (60 FPS VIRTUAL SCROLLING) ──
  const getCellContent = useCallback(
    ([col, row]) => {
      const rowItem = gridData[row]
      const meta = colMetadata[col]
      if (!meta || !rowItem) {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false
        }
      }

      // Xử lý dòng tiêu đề Nhóm (Group Header)
      if (rowItem._isGroupHeader) {
        if (col === 0 || col === 1) {
          return {
            kind: GridCellKind.Text,
            data: rowItem._groupTitle || '',
            displayData: rowItem._groupTitle || '',
            readonly: true,
            allowOverlay: false,
            themeOverride: {
              bgCell: '#f1f5f9',
              textDark: '#1e293b',
              baseFontStyle: 'bold 12px'
            }
          }
        }
        if (meta.columnKey === 'PlanQty' && rowItem._totalPlanQty !== undefined) {
          const num = Number(rowItem._totalPlanQty) || 0
          return {
            kind: GridCellKind.Number,
            data: num,
            displayData: num.toLocaleString('vi-VN'),
            readonly: true,
            allowOverlay: false,
            themeOverride: {
              bgCell: '#f1f5f9',
              textDark: '#2563eb',
              baseFontStyle: 'bold 12px'
            }
          }
        }
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false,
          themeOverride: { bgCell: '#f8fafc' }
        }
      }

      const val = rowItem[meta.columnKey]

      // Cột WorkingTag / Status trong màn hình truy vấn luôn để trống ""
      if (meta.columnKey === 'WorkingTag' || meta.columnKey === 'Status') {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false,
          contentAlign: 'center',
          themeOverride: meta.cellTheme
        }
      }

      // Cột trạng thái điều phối
      if (meta.columnKey === 'StatusDpSx') {
        const strVal = String(val || '')
        let bg = '#ffffff'
        let fg = '#334155'
        if (strVal === 'P' || strVal === 'Đang chờ') {
          bg = '#fef3c7'
          fg = '#b45309'
        } else if (strVal === 'R' || strVal === 'Đang chạy' || strVal === 'Đang SX') {
          bg = '#dbeafe'
          fg = '#1d4ed8'
        } else if (strVal === 'D' || strVal === 'Hoàn thành') {
          bg = '#dcfce7'
          fg = '#15803d'
        }
        return {
          kind: GridCellKind.Text,
          data: strVal,
          displayData: strVal,
          readonly: true,
          allowOverlay: false,
          themeOverride: { bgCell: bg, textDark: fg, baseFontStyle: 'bold 11px' }
        }
      }

      // Cột định mức Capa
      if (meta.columnKey === 'CapaStatus') {
        const strVal = String(val || '')
        const isMatch = strVal === 'Khớp' || strVal === 'Y' || strVal === 'OK'
        return {
          kind: GridCellKind.Text,
          data: strVal,
          displayData: strVal,
          readonly: true,
          allowOverlay: false,
          themeOverride: {
            bgCell: isMatch ? '#dcfce7' : '#fee2e2',
            textDark: isMatch ? '#166534' : '#991b1b',
            baseFontStyle: 'bold 11px'
          }
        }
      }

      // Cột ngày tháng
      if (meta.isDate && val) {
        const dateStr = formatDate(val)
        return {
          kind: GridCellKind.Text,
          data: String(val),
          displayData: dateStr || String(val),
          readonly: true,
          allowOverlay: false,
          themeOverride: meta.cellTheme
        }
      }

      // Cột số liệu
      if (meta.isNumber || typeof val === 'number') {
        const numVal = Number(val) || 0
        return {
          kind: GridCellKind.Number,
          data: numVal,
          displayData: numVal.toLocaleString('vi-VN'),
          readonly: true,
          allowOverlay: false,
          contentAlign: 'right',
          themeOverride: meta.cellTheme
        }
      }

      // Cột chuỗi mặc định
      const strVal = val !== undefined && val !== null ? String(val) : ''
      return {
        kind: GridCellKind.Text,
        data: strVal,
        displayData: strVal,
        readonly: true,
        allowOverlay: false,
        themeOverride: meta.cellTheme
      }
    },
    [gridData, colMetadata, formatDate]
  )

  // ── 3. BẮT SỰ KIỆN CTRL+F KHI ĐANG FOCUS Ô VÀ ĐẨY VÀO FILTER ──
  const handleKeyDown = useCallback(
    (event) => {
      const isCtrlOrMeta = event.ctrlKey || event.metaKey
      const key = event.key ? event.key.toLowerCase() : ''

      if (isCtrlOrMeta && key === 'f') {
        event.preventDefault()
        event.stopPropagation()

        const currentCell = selection?.current?.cell
        if (currentCell && typeof onApplyFilterFromCell === 'function') {
          const [col, row] = currentCell
          if (row >= 0 && row < (gridData?.length || 0)) {
            const rowItem = gridData[row]
            const meta = colMetadata[col]
            if (meta && rowItem && !rowItem._isGroupHeader) {
              const cellValue =
                rowItem[meta.columnKey] !== undefined && rowItem[meta.columnKey] !== null
                  ? String(rowItem[meta.columnKey])
                  : ''
              onApplyFilterFromCell(meta.columnKey, cellValue)
              return
            }
          }
        }
        if (typeof setShowSearch === 'function') {
          setShowSearch(true)
        }
        return
      }

      if (typeof baseOnKeyDown === 'function') {
        baseOnKeyDown(event)
      }
    },
    [selection, gridData, colMetadata, onApplyFilterFromCell, setShowSearch, baseOnKeyDown]
  )

  return (
    <div className="w-full h-full flex flex-col bg-white overflow-hidden select-none">
      {/* ── Table Header Banner (Chuẩn hệ thống) ── */}
      <h2 className="text-[10px] italic text-blue-600 border-b border-slate-200 font-bold flex items-center gap-1.5 px-2 py-1 uppercase bg-white">
        <span className="w-1 h-3 bg-blue-600 rounded-full inline-block shrink-0" />
        <span>{tableTitle || t('Danh sách Kế hoạch sản xuất chi tiết')}</span>
      </h2>

      {/* ── GlideDataGrid Data Editor ── */}
      <div className="flex-1 w-full h-full relative" onKeyDown={handleKeyDown}>
        <DataEditor
          ref={gridRef}
          theme={gridTheme}
          columns={cols}
          getCellContent={getCellContent}
          rows={gridData.length}
          showSearch={Boolean(showSearch)}
          onSearchClose={onSearchClose}
          rowMarkers="both"
          width="100%"
          height="100%"
          rowSelect="multi"
          columnSelect="single"
          gridSelection={selection}
          onGridSelectionChange={setSelection}
          getCellsForSelection={true}
          freezeColumns={freezeColumnsCount}
          headerHeight={23}
          rowHeight={23}
          overscrollY={20}
          overscrollX={50}
          smoothScrollY={true}
          smoothScrollX={true}
          keybindings={keybindings}
          isDraggable={false}
          highlightRegions={EMPTY_ARRAY}
          onColumnResize={onColumnResize}
          onHeaderMenuClick={onHeaderMenuClick}
          onHeaderContextMenu={onHeaderContextMenu}
          onColumnMoved={onColumnMoved}
          onKeyDown={handleKeyDown}
          onVisibleRegionChanged={onVisibleRegionChanged}
          onCellClicked={onCellClicked}
          onCellActivated={onCellActivated}
          onCellContextMenu={onCellContextMenu}
        />

        {/* ── Context Menu & Header Menus ── */}
        {showMenu !== null &&
          renderLayer(
            <div {...layerProps} className="z-[9999] outline-none">
              {showMenu.menuType === 'statusMenu' ? (
                <LayoutStatusMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleReset={handleReset}
                  showDrawer={showDrawer}
                  data={gridData}
                />
              ) : showMenu.menuType === 'contextMenu' ? (
                <LayoutContextMenuSheet
                  showMenu={showMenu}
                  cols={cols}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  data={gridData}
                  selection={selection}
                  canCreate={false}
                  onExportExcel={onExportExcel}
                />
              ) : (
                <LayoutMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  handleHideColumn={handleHideColumn}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleFreezeColumn={handleFreezeColumn}
                  showDrawer={showDrawer}
                />
              )}
            </div>
          )}

        {/* ── Cài đặt hiển thị cột (Drawer) ── */}
        <Drawer
          title={
            <span className="text-xs flex items-center justify-between font-bold text-slate-800">
              <span>{t('CÀI ĐẶT CỘT DỮ LIỆU')}</span>
              <button
                onClick={handleReset}
                className="text-[11px] font-normal text-blue-600 hover:underline"
              >
                {t('Khôi phục mặc định')}
              </button>
            </span>
          }
          styles={{ body: { padding: 15 } }}
          onClose={onClose}
          open={open}
        >
          <div className="flex flex-col gap-2 max-h-full overflow-y-auto">
            {(configurableCols || []).map((col) => (
              <div key={col.id} className="py-0.5">
                <Checkbox
                  checked={!hiddenColumns.includes(col.id)}
                  onChange={(e) => handleCheckboxChange(col.id, e.target.checked)}
                >
                  <span className="text-xs text-slate-700">{col.title || col.id}</span>
                </Checkbox>
              </div>
            ))}
          </div>
        </Drawer>
      </div>
    </div>
  )
}

import { useCallback, useRef, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { DataEditor, GridCellKind } from '@glideapps/glide-data-grid'
import '@glideapps/glide-data-grid/dist/index.css'
import LayoutMenuSheet from '../../../../../components/sheet/jsx/layoutMenu'
import LayoutStatusMenuSheet from '../../../../../components/sheet/jsx/layoutStatusMenu'
import LayoutContextMenuSheet from '../../../../../components/sheet/jsx/layoutContextMenu'
import { Drawer, Checkbox } from '../../../../../../components/ui'
import useOnFill from '../../../../../components/hooks/sheet/onFillHook'
import useTableManager from '../../../../../components/hooks/sheet/useTableManager'
import useTableConfig from '../../../../../components/hooks/sheet/useTableConfig'

const EMPTY_ARRAY = []

export default function PlanImportTable({
  tableTitle,
  setSelection,
  selection,
  setShowSearch,
  showSearch,
  setGridData,
  gridData = [],
  numRows,
  setNumRows,
  handleRowAppend,
  setCols,
  cols = [],
  canEdit = true,
  canCreate = true,
  defaultCols,
  onVisibleRegionChanged,
  onAddQueryField
}) {
  const { t } = useTranslation()
  const gridRef = useRef(null)

  const onFill = useOnFill(setGridData, cols)
  const onSearchClose = useCallback(() => setShowSearch(false), [setShowSearch])

  const { freezeColumnsCount, handleFreezeColumn } = useTableConfig('import_plan_table')

  const {
    showMenu,
    setShowMenu,
    onHeaderMenuClick,
    layerProps,
    renderLayer,
    hiddenColumns,
    handleHideColumn,
    handleReset,
    onColumnMoved,
    onColumnResize,
    handleSort,
    openDrawer: open,
    setOpenDrawer: setOpen,
    showDrawer,
    handleCheckboxChange,
    configurableCols,
    keybindings,
    getCellTheme,
    isReadOnlyColumn,
    gridTheme,
    onCellClicked,
    onCellActivated,
    onKeyDown,
    onCellContextMenu,
    onHeaderContextMenu
  } = useTableManager({
    tableId: 'import_plan_table',
    defaultCols,
    cols,
    setCols,
    setGridData,
    gridData,
    selection,
    setSelection,
    canEdit,
    setShowSearch,
    onAddQueryField
  })

  const onClose = () => setOpen(false)

  // Pre-compute Metadata
  const colMetadata = useMemo(() => {
    return (cols || []).map((column) => {
      const columnKey = column.id || ''
      const isStatus = columnKey === 'WorkingTag'
      const cellTheme = getCellTheme(columnKey, column)
      const isReadOnly = isReadOnlyColumn(columnKey, column) || column.readonly || false
      return {
        columnKey,
        isStatus,
        kind: column.kind,
        cellTheme,
        isReadOnly,
        hasMenu: column.hasMenu || false
      }
    })
  }, [cols, getCellTheme, isReadOnlyColumn])

  const getData = useCallback(
    ([col, row]) => {
      const item = gridData[row]
      const meta = colMetadata[col]
      if (!meta || !item) {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false
        }
      }

      const value =
        item[meta.columnKey] ??
        item[meta.columnKey.charAt(0).toLowerCase() + meta.columnKey.slice(1)] ??
        ''

      if (meta.isStatus && meta.columnKey === 'WorkingTag') {
        const strVal = String(value)
        return {
          kind: GridCellKind.Text,
          data: strVal,
          displayData: strVal,
          readonly: true,
          allowOverlay: false,
          hasMenu: meta.hasMenu,
          contentAlign: 'center',
          themeOverride: meta.cellTheme
        }
      }

      if (meta.kind === 'Number' || typeof value === 'number') {
        const numVal = Number(value) || 0
        return {
          kind: GridCellKind.Number,
          data: numVal,
          displayData: numVal.toLocaleString('vi-VN'),
          readonly: meta.isReadOnly,
          allowOverlay: !meta.isReadOnly,
          hasMenu: meta.hasMenu,
          contentAlign: 'right',
          themeOverride: meta.cellTheme
        }
      }

      const strValue = typeof value === 'string' ? value : String(value)

      return {
        kind: GridCellKind.Text,
        data: strValue,
        displayData: strValue,
        readonly: meta.isReadOnly,
        allowOverlay: !meta.isReadOnly,
        hasMenu: meta.hasMenu,
        themeOverride: meta.cellTheme
      }
    },
    [gridData, colMetadata]
  )

  const onKeyUp = useCallback(() => {}, [])

  const onCellEdited = useCallback(
    async (cell, newValue) => {
      if (
        newValue.kind !== GridCellKind.Text &&
        newValue.kind !== GridCellKind.Custom &&
        newValue.kind !== GridCellKind.Boolean &&
        newValue.kind !== GridCellKind.Number
      ) {
        return
      }
      if (canEdit === false) return
      const [col, row] = cell
      const meta = colMetadata[col]
      if (!meta || meta.isReadOnly || meta.columnKey === 'WorkingTag') return

      setGridData((prevData) => {
        const updatedData = [...prevData]
        if (!updatedData[row]) updatedData[row] = {}

        const currentStatus = updatedData[row]['WorkingTag'] || ''
        const nextStatus = currentStatus === 'A' ? 'A' : 'U'
        updatedData[row][meta.columnKey] = newValue.data
        updatedData[row]['WorkingTag'] = nextStatus

        return updatedData
      })
    },
    [colMetadata, canEdit, setGridData]
  )

  const effectiveRows = numRows ?? gridData?.length ?? 0

  return (
    <div className="w-full h-full flex items-center justify-center">
      <div className="w-full h-full flex flex-col bg-white overflow-hidden">
        <h2 className="text-[10px] italic text-blue-600 border-b border-slate-200 font-bold flex items-center gap-1.5 px-2 py-1 uppercase bg-white">
          <span className="w-1 h-3 bg-blue-600 rounded-full inline-block shrink-0" />
          <span>{tableTitle || t('Dữ liệu Đăng ký Kế hoạch sản xuất (Điều phối KHSX)')}</span>
        </h2>
        <DataEditor
          ref={gridRef}
          theme={gridTheme}
          columns={cols}
          getCellContent={getData}
          onFill={onFill}
          rows={effectiveRows}
          showSearch={showSearch}
          onSearchClose={onSearchClose}
          rowMarkers="both"
          width="100%"
          height="100%"
          rowSelect="multi"
          columnSelect="single"
          gridSelection={selection}
          onGridSelectionChange={setSelection}
          getCellsForSelection={true}
          trailingRowOptions={
            canCreate
              ? {
                  hint: ' ',
                  sticky: true,
                  tint: true
                }
              : undefined
          }
          freezeColumns={freezeColumnsCount}
          headerHeight={23}
          overscrollY={20}
          overscrollX={50}
          smoothScrollY={true}
          smoothScrollX={true}
          freezeTrailingRows={0}
          rowHeight={23}
          fillHandle={Boolean(canEdit)}
          keybindings={keybindings}
          isDraggable={false}
          onRowAppended={() => canCreate && handleRowAppend && handleRowAppend(1)}
          onCellEdited={canEdit ? onCellEdited : undefined}
          highlightRegions={EMPTY_ARRAY}
          onColumnResize={onColumnResize}
          onHeaderMenuClick={onHeaderMenuClick}
          onHeaderContextMenu={onHeaderContextMenu}
          onColumnMoved={onColumnMoved}
          onKeyDown={onKeyDown}
          onKeyUp={onKeyUp}
          onVisibleRegionChanged={onVisibleRegionChanged}
          onCellClicked={onCellClicked}
          onCellActivated={onCellActivated}
          onCellContextMenu={onCellContextMenu}
        />
        {showMenu !== null &&
          renderLayer(
            <div {...layerProps} className="z-[9999] outline-none">
              {showMenu.menuType === 'statusMenu' ? (
                <LayoutStatusMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleReset={handleReset}
                  showDrawer={showDrawer}
                  data={gridData}
                  handleRowAppend={handleRowAppend}
                />
              ) : showMenu.menuType === 'contextMenu' ? (
                <LayoutContextMenuSheet
                  showMenu={showMenu}
                  cols={cols}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  data={gridData}
                  handleRowAppend={handleRowAppend}
                  selection={selection}
                  canCreate={canCreate}
                />
              ) : (
                <LayoutMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  handleHideColumn={handleHideColumn}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleFreezeColumn={handleFreezeColumn}
                  showDrawer={showDrawer}
                />
              )}
            </div>
          )}
        <Drawer
          title={
            <span className="text-xs flex items-center justify-end font-bold">CÀI ĐẶT SHEET</span>
          }
          styles={{ body: { padding: 15 } }}
          onClose={onClose}
          open={open}
        >
          {(configurableCols || []).map((col) => (
            <div key={col.id} style={{ marginBottom: '10px' }}>
              <Checkbox
                checked={!hiddenColumns.includes(col.id)}
                onChange={(e) => handleCheckboxChange(col.id, e.target.checked)}
              >
                {col.title || col.id}
              </Checkbox>
            </div>
          ))}
        </Drawer>
      </div>
    </div>
  )
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import * as XLSX from 'xlsx'
import { queryPlanDetail } from '../../services/planRegistrationService'
import { usePageData } from '../../../../../../context/PageDataContext'

export function usePlanImport({
  gridData = [],
  setGridData,
  setNumRows,
  getSelectedRows,
  resetTable,
  canCreate,
  canEdit,
  canDelete,
  loadingBarRef
}) {
  const { t } = useTranslation()
  const { setStatusMessage, setPageData } = usePageData()
  const [searchValues, setSearchValues] = useState({
    PicDp: '',
    OperationNo: '',
    ItemCode: '',
    RoutingDocNo: '',
    MachineName: '',
    StatusDpSx: '',
    TimeStatus: '',
    CapaStatus: ''
  })

  const [dynamicQueryFields, setDynamicQueryFields] = useState([])
  const originalDataRef = useRef([])

  // Hàm load dữ liệu thực tế từ Database thông qua DataHub API
  const fetchPlanData = useCallback(
    async (filters = {}) => {
      loadingBarRef?.current?.continuousStart?.()
      try {
        const res = await queryPlanDetail(filters)
        const dataList = res?.data || []
        setGridData(dataList)
        setNumRows(dataList.length)
        originalDataRef.current = dataList

        setPageData?.((prev) => ({
          ...prev,
          total: dataList.length,
          totalAll: res?.pageInfo?.totalAll || dataList.length,
          loadedCount: dataList.length,
          totalColumns: 24
        }))

        return dataList
      } catch (err) {
        setGridData([])
        setNumRows(0)
        originalDataRef.current = []
        setPageData?.((prev) => ({
          ...prev,
          total: 0,
          totalAll: 0,
          loadedCount: 0
        }))
        return []
      } finally {
        loadingBarRef?.current?.complete?.()
      }
    },
    [loadingBarRef, setGridData, setNumRows, setPageData]
  )

  // Tự động truy vấn từ DB khi khởi tạo giao diện
  useEffect(() => {
    fetchPlanData({})
  }, [fetchPlanData])

  // Search từ Backend DataHub khi bấm TÌM KIẾM
  const handleSearchData = useCallback(async () => {
    const dataList = await fetchPlanData(searchValues)
    if (dataList.length > 0) {
      setStatusMessage?.({
        type: 'success',
        text: `Tìm thấy ${dataList.length.toLocaleString('vi-VN')} bản ghi kế hoạch sản xuất từ hệ thống`
      })
    } else {
      setStatusMessage?.({
        type: 'info',
        text: 'Không tìm thấy dữ liệu kế hoạch sản xuất phù hợp'
      })
    }
  }, [fetchPlanData, searchValues, setStatusMessage])

  const onResetQuery = useCallback(() => {
    const emptyFilters = {
      PicDp: '',
      OperationNo: '',
      ItemCode: '',
      RoutingDocNo: '',
      MachineName: '',
      StatusDpSx: '',
      TimeStatus: '',
      CapaStatus: ''
    }
    setSearchValues(emptyFilters)
    fetchPlanData({})
    setStatusMessage?.({
      type: 'info',
      text: 'Đã đặt lại điều kiện và tải lại dữ liệu'
    })
  }, [fetchPlanData, setStatusMessage])

  const onAddQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => {
      if (prev.includes(fieldKey)) return prev
      return [...prev, fieldKey]
    })
  }, [])

  const onRemoveQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => prev.filter((k) => k !== fieldKey))
  }, [])

  const handleRowAppend = useCallback(
    (count = 1) => {
      if (!canCreate) {
        setStatusMessage?.({
          type: 'warning',
          text: 'Bạn không có quyền thêm mới'
        })
        return
      }
      const newRows = Array.from({ length: count }, (_, idx) => ({
        WorkingTag: 'A',
        PicDp: 'Kế hoạch viên',
        OperationNo: `LTT-NEW-${Date.now().toString().slice(-4)}`,
        OpDate: new Date().toISOString().slice(0, 10),
        RoutingDocNo: `LCD-NEW-${Date.now().toString().slice(-4)}`,
        RoutingDocDate: new Date().toISOString().slice(0, 10),
        ItemCode: '',
        ItemName: '',
        OperationName: 'In Offset UV',
        OpTypeName: 'In Offset',
        MachineName: 'Máy In Offset Heidelberg XL-106',
        Unit: 'Chiếc',
        TargetPassQty: 0,
        TargetProdQty: 0,
        StatPassQty: 0,
        StartTime: '07:00',
        EndTime: '15:00',
        StandardProdTime: 8,
        ActualProdTime: 0,
        StandardCapa: 0,
        ActualCapa: 0,
        StatusDpSx: 'Chưa bắt đầu',
        TimeStatus: 'Đúng hạn',
        CapaStatus: 'Đạt capa'
      }))

      setGridData((prev) => [...prev, ...newRows])
      setNumRows((prev) => (prev ?? 0) + count)
      setStatusMessage?.({
        type: 'info',
        text: `Đã thêm ${count} dòng mới`
      })
    },
    [canCreate, setGridData, setNumRows, setStatusMessage]
  )

  const handleSaveData = useCallback(() => {
    if (!canEdit) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Bạn không có quyền chỉnh sửa'
      })
      return
    }
    const modifiedRows = gridData.filter((r) => r.WorkingTag === 'U' || r.WorkingTag === 'A')
    if (modifiedRows.length === 0) {
      setStatusMessage?.({
        type: 'info',
        text: 'Không có thay đổi nào cần lưu'
      })
      return
    }

    loadingBarRef?.current?.continuousStart?.()
    setTimeout(() => {
      const cleanData = gridData.map((r) => ({ ...r, WorkingTag: '' }))
      setGridData(cleanData)
      originalDataRef.current = cleanData
      loadingBarRef?.current?.complete?.()
      setStatusMessage?.({
        type: 'success',
        text: `Đã lưu thành công ${modifiedRows.length} bản ghi`
      })
    }, 400)
  }, [canEdit, gridData, loadingBarRef, setGridData, setStatusMessage])

  const handleDeleteData = useCallback(() => {
    if (!canDelete) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Bạn không có quyền xóa'
      })
      return
    }
    const selected = getSelectedRows?.() || []
    if (selected.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Vui lòng chọn dòng cần xóa'
      })
      return
    }

    const updated = gridData.filter((_, idx) => !selected.includes(idx))
    setGridData(updated)
    setNumRows(updated.length)
    setStatusMessage?.({
      type: 'success',
      text: `Đã xóa ${selected.length} dòng được chọn`
    })
  }, [canDelete, getSelectedRows, gridData, setGridData, setNumRows, setStatusMessage])

  const handleExportExcel = useCallback(() => {
    if (!gridData || gridData.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Không có dữ liệu để xuất'
      })
      return
    }
    try {
      const exportData = gridData.map((row) => {
        const copy = { ...row }
        delete copy.WorkingTag
        return copy
      })
      const ws = XLSX.utils.json_to_sheet(exportData)
      const wb = XLSX.utils.book_new()
      XLSX.utils.book_append_sheet(wb, ws, 'DangKy_KeHoach_SX')
      XLSX.writeFile(wb, `DangKy_KeHoach_SX_${new Date().toISOString().slice(0, 10)}.xlsx`)
      setStatusMessage?.({
        type: 'success',
        text: 'Đã xuất file Excel thành công'
      })
    } catch (err) {
      setStatusMessage?.({
        type: 'error',
        text: 'Xuất Excel thất bại: ' + (err?.message || err)
      })
    }
  }, [gridData, setStatusMessage])

  return {
    searchValues,
    setSearchValues,
    dynamicQueryFields,
    handleSearchData,
    onResetQuery,
    onAddQueryField,
    onRemoveQueryField,
    handleRowAppend,
    handleSaveData,
    handleDeleteData,
    handleExportExcel
  }
}

import { request } from '../../../../../services/apiClient'
import { normalizeProdStatsDetailRows, normalizePlanDetailRows } from './reportColumnNormalizer'

/**
 * Service kết nối Backend API cho Module Đăng ký & Báo cáo Sản xuất (KHSX & TKSX)
 */

// 1. Lưu đợt đăng ký mới (Master + Chi tiết KHSX hoặc TKSX)
export const savePlanRegistration = async (payload, signal = null, onProgress = null) => {
  // Lấy thông tin tài khoản đăng nhập hiện tại từ Client
  let currentUser = {}
  try {
    const rawUser = localStorage.getItem('userInfo') || sessionStorage.getItem('userInfo')
    if (rawUser) {
      currentUser = JSON.parse(rawUser)
    }
  } catch {}

  const createdBy =
    payload.createdBy ||
    currentUser.UserSeq ||
    currentUser.UserId ||
    currentUser.EmpID ||
    'SystemAdmin'
  const createdByName =
    payload.createdByName ||
    currentUser.UserName ||
    currentUser.Login ||
    currentUser.EmpName ||
    'Admin'

  const reportType = payload.ReportType || payload.reportType || 'plan'
  const isStat = reportType === 'statistics' || reportType === 'tksx'

  const rawInput =
    payload.SheetData ||
    payload.data ||
    (isStat ? payload.statsData || payload.StatsData : payload.planData || payload.PlanData) ||
    []

  // Chuẩn hóa và ánh xạ toàn diện tất cả 98 cột TKSX hoặc 24 cột KHSX
  const rawData = isStat
    ? normalizeProdStatsDetailRows(rawInput)
    : normalizePlanDetailRows(rawInput)
  const totalRows = rawData.length

  const factoryCode =
    payload.FactoryCode ||
    payload.factoryCode ||
    (String(payload.FactoryName || payload.factoryName || '').includes('GS5') ||
    String(payload.FactoryName || payload.factoryName || '').includes('Quế Võ')
      ? 'GS5'
      : 'GS1')

  const factoryName =
    payload.FactoryName ||
    payload.factoryName ||
    (factoryCode === 'GS5' ? 'GS5 Quế Võ 1B' : 'GS1 Hà Nội')

  const applyDate = payload.ApplyDate || payload.applyDate
  const regCodeInput = payload.RegCode || payload.regCode
  const remark = payload.Remark || payload.remark || ''

  // Kích thước mỗi chunk tối ưu: 1.000 dòng để đảm bảo payload nhẹ (~1MB), không bị timeout hay nghẽn socket
  const CHUNK_SIZE = 1000

  const version = payload.version || payload.calcVersion || payload.Version || '1.0'

  // Với số lượng dòng nhỏ (<= 1.000 dòng), gửi 1 lần duy nhất cùng Master
  if (totalRows <= CHUNK_SIZE) {
    const formattedPayload = {
      reportType,
      factoryCode,
      factoryName,
      applyDate,
      regCode: regCodeInput,
      version,
      calcVersion: version,
      remark,
      status: payload.status || (payload.isDraft ? 'draft' : 'published'),
      isDraft: Boolean(payload.isDraft),
      createdBy,
      createdByName,
      userSeq: currentUser.UserSeq || createdBy,
      userName: createdByName,
      totalRows,
      planData: isStat ? [] : rawData,
      statsData: isStat ? rawData : [],
      sheetData: rawData,
      data: rawData
    }

    onProgress?.({ current: totalRows, total: totalRows, percent: 100 })

    return request({
      url: '/report/plan/PlanRegistrationA',
      method: 'POST',
      data: formattedPayload,
      timeout: 180000,
      signal
    })
  }

  // Với số lượng dòng lớn (> 1.000 dòng, ví dụ 5.000 - 50.000 dòng):
  // Bước 1: Lưu Master kèm Chunk 1 (1.000 dòng đầu tiên)
  const firstChunk = rawData.slice(0, CHUNK_SIZE)
  const firstPayload = {
    reportType,
    factoryCode,
    factoryName,
    applyDate,
    regCode: regCodeInput,
    version,
    calcVersion: version,
    remark,
    status: payload.status || (payload.isDraft ? 'draft' : 'published'),
    isDraft: Boolean(payload.isDraft),
    createdBy,
    createdByName,
    userSeq: currentUser.UserSeq || createdBy,
    userName: createdByName,
    totalRows,
    planData: isStat ? [] : firstChunk,
    statsData: isStat ? firstChunk : [],
    sheetData: firstChunk,
    data: firstChunk
  }

  onProgress?.({
    current: firstChunk.length,
    total: totalRows,
    percent: Math.round((firstChunk.length / totalRows) * 100)
  })

  const masterRes = await request({
    url: '/report/plan/PlanRegistrationA',
    method: 'POST',
    data: firstPayload,
    timeout: 180000,
    signal
  })

  const savedMaster = masterRes?.data || {}
  const masterSeq = savedMaster?.IdSeq
  const regCode = savedMaster?.RegCode || payload.regCode

  // Bước 2: Lưu các Chunk tiếp theo tuần tự (kèm delay nhỏ 50ms giữa các chunk để giải phóng event loop)
  const detailUrl = isStat ? '/report/plan/ProdStatsDetailA' : '/report/plan/PlanDetailA'

  for (let start = CHUNK_SIZE; start < totalRows; start += CHUNK_SIZE) {
    if (signal?.aborted) {
      throw new Error('Thao tác lưu đã bị hủy bởi người dùng')
    }

    const chunk = rawData.slice(start, start + CHUNK_SIZE).map((item, idx) => ({
      ...item,
      MasterSeq: masterSeq,
      RegCode: regCode,
      RowSeq: start + idx + 1
    }))

    // Delay 50ms giữa các batch
    await new Promise((resolve) => setTimeout(resolve, 50))

    await request({
      url: detailUrl,
      method: 'POST',
      data: chunk,
      timeout: 180000,
      signal
    })

    const currentCount = Math.min(start + CHUNK_SIZE, totalRows)
    onProgress?.({
      current: currentCount,
      total: totalRows,
      percent: Math.round((currentCount / totalRows) * 100)
    })
  }

  return masterRes
}

