import { useCallback, useRef, useMemo, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { DataEditor, GridCellKind } from '@glideapps/glide-data-grid'
import '@glideapps/glide-data-grid/dist/index.css'
import { RotateCw, SlidersHorizontal, X } from 'lucide-react'

import LayoutMenuSheet from '../../../../../components/sheet/jsx/layoutMenu'
import LayoutStatusMenuSheet from '../../../../../components/sheet/jsx/layoutStatusMenu'
import LayoutContextMenuSheet from '../../../../../components/sheet/jsx/layoutContextMenu'
import { Drawer, Checkbox } from '../../../../../../components/ui'
import useTableManager from '../../../../../components/hooks/sheet/useTableManager'
import useTableConfig from '../../../../../components/hooks/sheet/useTableConfig'
import { useDateFormat } from '../../../../../hooks/useDateFormat'

const EMPTY_ARRAY = []

export default function StatDetailQueryTable({
  tableTitle,
  cols = [],
  setCols,
  defaultCols,
  gridData = [],
  setGridData,
  selection,
  setSelection,
  showSearch,
  setShowSearch,
  onVisibleRegionChanged,
  showColFilters = false,
  colFilterValues = {},
  setColFilterValues,
  onApplyFilterFromCell,
  onAddQueryField,
  onRegisterDrawer,
  onExportExcel,
  isLoadingMore = false,
  hasMore = false,
  loadedCount = 0,
  displayCount = 0,
  totalRows = 0
}) {
  const { t } = useTranslation()
  const { formatDate } = useDateFormat()
  const gridRef = useRef(null)

  const { freezeColumnsCount, handleFreezeColumn } = useTableConfig('stat_detail_query_table')

  const {
    showMenu,
    setShowMenu,
    onHeaderMenuClick,
    layerProps,
    renderLayer,
    hiddenColumns,
    handleHideColumn,
    handleReset,
    onColumnMoved,
    onColumnResize,
    handleSort,
    openDrawer: open,
    setOpenDrawer: setOpen,
    showDrawer,
    handleCheckboxChange,
    configurableCols,
    keybindings,
    getCellTheme,
    isReadOnlyColumn,
    gridTheme,
    onCellClicked,
    onCellActivated,
    onKeyDown: baseOnKeyDown,
    onCellContextMenu,
    onHeaderContextMenu
  } = useTableManager({
    tableId: 'stat_detail_query_table',
    defaultCols,
    cols,
    setCols,
    setGridData: setGridData || (() => {}),
    gridData,
    selection,
    setSelection,
    canEdit: false,
    setShowSearch,
    onAddQueryField: onAddQueryField || onApplyFilterFromCell
  })

  useEffect(() => {
    if (typeof onRegisterDrawer === 'function') {
      onRegisterDrawer(showDrawer)
    }
  }, [onRegisterDrawer, showDrawer])

  const onSearchClose = useCallback(() => {
    if (typeof setShowSearch === 'function') setShowSearch(false)
  }, [setShowSearch])

  const onClose = () => setOpen(false)

  // ── 1. PRE-COMPUTE METADATA CHO CÁC CỘT (O(1) Cell Provider Lookup) ──
  const colMetadata = useMemo(() => {
    return (cols || []).map((column) => {
      const columnKey = column.id || ''
      const isStatus = columnKey === 'WorkingTag' || columnKey === 'Status'
      const isNumber =
        columnKey !== 'SyncDelayMinutes' &&
        columnKey !== 'SyncLatencySeconds' &&
        (column.kind === 'Number' ||
          columnKey.includes('Qty') ||
          columnKey.includes('Hours') ||
          columnKey.includes('Rate') ||
          columnKey.includes('Minute') ||
          columnKey.includes('Total') ||
          columnKey.includes('Output') ||
          columnKey.includes('Speed') ||
          columnKey.includes('Waste') ||
          columnKey.includes('Pass'))
      const isDate = columnKey.endsWith('Date') || columnKey.includes('Time')
      const cellTheme = getCellTheme(columnKey, column)
      const isReadOnly = isReadOnlyColumn(columnKey, column) || column.readonly || true

      return {
        columnKey,
        isStatus,
        isNumber,
        isDate,
        kind: column.kind,
        title: column.title || columnKey,
        cellTheme,
        isReadOnly,
        hasMenu: column.hasMenu || false
      }
    })
  }, [cols, getCellTheme, isReadOnlyColumn])

  // ── 2. SIÊU TỐI ƯU HÓA HÀM TRUY XUẤT Ô (60 FPS VIRTUAL SCROLLING) ──
  const getCellContent = useCallback(
    ([col, row]) => {
      const rowItem = gridData[row]
      const meta = colMetadata[col]
      if (!meta || !rowItem) {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false
        }
      }

      // Xử lý dòng tiêu đề Nhóm (Group Header)
      if (rowItem._isGroupHeader) {
        if (col === 0 || col === 1) {
          return {
            kind: GridCellKind.Text,
            data: rowItem._groupTitle || '',
            displayData: rowItem._groupTitle || '',
            readonly: true,
            allowOverlay: false,
            themeOverride: {
              bgCell: '#f1f5f9',
              textDark: '#1e293b',
              baseFontStyle: 'bold 12px'
            }
          }
        }
        if (meta.columnKey === 'ActualQty' && rowItem._totalActualQty !== undefined) {
          const num = Number(rowItem._totalActualQty) || 0
          return {
            kind: GridCellKind.Number,
            data: num,
            displayData: num.toLocaleString('vi-VN'),
            readonly: true,
            allowOverlay: false,
            themeOverride: {
              bgCell: '#f1f5f9',
              textDark: '#16a34a',
              baseFontStyle: 'bold 12px'
            }
          }
        }
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false,
          themeOverride: { bgCell: '#f8fafc' }
        }
      }

      const val = rowItem[meta.columnKey]

      // Cột WorkingTag / Status trong màn hình truy vấn luôn để trống ""
      if (meta.columnKey === 'WorkingTag' || meta.columnKey === 'Status') {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false,
          contentAlign: 'center',
          themeOverride: meta.cellTheme
        }
      }

      // Cột ngày tháng
      if (meta.isDate && val) {
        const dateStr = formatDate(val)
        return {
          kind: GridCellKind.Text,
          data: String(val),
          displayData: dateStr || String(val),
          readonly: true,
          allowOverlay: false,
          themeOverride: meta.cellTheme
        }
      }

      // Cột số liệu
      if (
        (meta.isNumber || typeof val === 'number') &&
        !(typeof val === 'string' && val.includes(':'))
      ) {
        const numVal = Number(val) || 0
        return {
          kind: GridCellKind.Number,
          data: numVal,
          displayData: numVal.toLocaleString('vi-VN'),
          readonly: true,
          allowOverlay: false,
          contentAlign: 'right',
          themeOverride: meta.cellTheme
        }
      }

      // Cột chuỗi mặc định
      const strVal = val !== undefined && val !== null ? String(val) : ''
      const isCenter =
        meta.columnKey === 'SyncDelayMinutes' ||
        meta.columnKey === 'SyncLatencySeconds' ||
        meta.columnKey === 'MesApprovalTime' ||
        meta.columnKey === 'MesApprovedTime'
      return {
        kind: GridCellKind.Text,
        data: strVal,
        displayData: strVal,
        readonly: true,
        allowOverlay: false,
        contentAlign: isCenter ? 'center' : undefined,
        themeOverride: meta.cellTheme
      }
    },
    [gridData, colMetadata, formatDate]
  )

  // ── 3. BẮT SỰ KIỆN CTRL+F KHI ĐANG FOCUS Ô VÀ ĐẨY VÀO FILTER ──
  const handleKeyDown = useCallback(
    (event) => {
      const isCtrlOrMeta = event.ctrlKey || event.metaKey
      const key = event.key ? event.key.toLowerCase() : ''

      if (isCtrlOrMeta && key === 'f') {
        event.preventDefault()
        event.stopPropagation()

        const currentCell = selection?.current?.cell
        if (currentCell && typeof onApplyFilterFromCell === 'function') {
          const [col, row] = currentCell
          if (row >= 0 && row < (gridData?.length || 0)) {
            const rowItem = gridData[row]
            const meta = colMetadata[col]
            if (meta && rowItem && !rowItem._isGroupHeader) {
              const cellValue =
                rowItem[meta.columnKey] !== undefined && rowItem[meta.columnKey] !== null
                  ? String(rowItem[meta.columnKey])
                  : ''
              onApplyFilterFromCell(meta.columnKey, cellValue)
              return
            }
          }
        }
        if (typeof setShowSearch === 'function') {
          setShowSearch(true)
        }
        return
      }

      if (typeof baseOnKeyDown === 'function') {
        baseOnKeyDown(event)
      }
    },
    [selection, gridData, colMetadata, onApplyFilterFromCell, setShowSearch, baseOnKeyDown]
  )

  return (
    <div className="w-full h-full flex flex-col bg-white overflow-hidden select-none">
      {/* ── Table Header Banner (Chuẩn hệ thống) ── */}
      <h2 className="text-[10px] italic text-blue-600 border-b border-slate-200 font-bold flex items-center gap-1.5 px-2 py-1 uppercase bg-white">
        <span className="w-1 h-3 bg-blue-600 rounded-full inline-block shrink-0" />
        <span>{tableTitle || t('Danh sách Thống kê sản xuất chi tiết')}</span>
      </h2>

      {/* ── GlideDataGrid Data Editor ── */}
      <div className="flex-1 w-full h-full relative" onKeyDown={handleKeyDown}>
        <DataEditor
          ref={gridRef}
          theme={gridTheme}
          columns={cols}
          getCellContent={getCellContent}
          rows={gridData.length}
          showSearch={Boolean(showSearch)}
          onSearchClose={onSearchClose}
          rowMarkers="both"
          width="100%"
          height="100%"
          rowSelect="multi"
          columnSelect="single"
          gridSelection={selection}
          onGridSelectionChange={setSelection}
          getCellsForSelection={true}
          freezeColumns={freezeColumnsCount}
          headerHeight={23}
          rowHeight={23}
          overscrollY={20}
          overscrollX={50}
          smoothScrollY={true}
          smoothScrollX={true}
          keybindings={keybindings}
          isDraggable={false}
          highlightRegions={EMPTY_ARRAY}
          onColumnResize={onColumnResize}
          onHeaderMenuClick={onHeaderMenuClick}
          onHeaderContextMenu={onHeaderContextMenu}
          onColumnMoved={onColumnMoved}
          onKeyDown={handleKeyDown}
          onVisibleRegionChanged={onVisibleRegionChanged}
          onCellClicked={onCellClicked}
          onCellActivated={onCellActivated}
          onCellContextMenu={onCellContextMenu}
        />

        {/* ── Context Menu & Header Menus ── */}
        {showMenu !== null &&
          renderLayer(
            <div {...layerProps} className="z-[9999] outline-none">
              {showMenu.menuType === 'statusMenu' ? (
                <LayoutStatusMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleReset={handleReset}
                  showDrawer={showDrawer}
                  data={gridData}
                />
              ) : showMenu.menuType === 'contextMenu' ? (
                <LayoutContextMenuSheet
                  showMenu={showMenu}
                  cols={cols}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  data={gridData}
                  selection={selection}
                  canCreate={false}
                  onExportExcel={onExportExcel}
                />
              ) : (
                <LayoutMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  handleHideColumn={handleHideColumn}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleFreezeColumn={handleFreezeColumn}
                  showDrawer={showDrawer}
                />
              )}
            </div>
          )}

        {/* ── Cài đặt hiển thị cột (Drawer) ── */}
        <Drawer
          title={
            <span className="text-xs flex items-center justify-between font-bold text-slate-800">
              <span>{t('CÀI ĐẶT CỘT DỮ LIỆU')}</span>
              <button
                onClick={handleReset}
                className="text-[11px] font-normal text-blue-600 hover:underline"
              >
                {t('Khôi phục mặc định')}
              </button>
            </span>
          }
          styles={{ body: { padding: 15 } }}
          onClose={onClose}
          open={open}
        >
          <div className="flex flex-col gap-2 max-h-full overflow-y-auto">
            {(configurableCols || []).map((col) => (
              <div key={col.id} className="py-0.5">
                <Checkbox
                  checked={!hiddenColumns.includes(col.id)}
                  onChange={(e) => handleCheckboxChange(col.id, e.target.checked)}
                >
                  <span className="text-xs text-slate-700">{col.title || col.id}</span>
                </Checkbox>
              </div>
            ))}
          </div>
        </Drawer>
      </div>
    </div>
  )
}

import { useCallback, useRef, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { DataEditor, GridCellKind } from '@glideapps/glide-data-grid'
import '@glideapps/glide-data-grid/dist/index.css'
import LayoutMenuSheet from '../../../../../components/sheet/jsx/layoutMenu'
import LayoutStatusMenuSheet from '../../../../../components/sheet/jsx/layoutStatusMenu'
import LayoutContextMenuSheet from '../../../../../components/sheet/jsx/layoutContextMenu'
import { Drawer, Checkbox } from '../../../../../../components/ui'
import useOnFill from '../../../../../components/hooks/sheet/onFillHook'
import useTableManager from '../../../../../components/hooks/sheet/useTableManager'
import useTableConfig from '../../../../../components/hooks/sheet/useTableConfig'

const EMPTY_ARRAY = []
const BOOLEAN_KEYS = new Set([
  'AutoExport',
  'AutoImport',
  'WrongOpCode',
  'IsAdditionalStat',
  'IsDuplicateTicket'
])

export default function StatisticsImportTable({
  tableTitle,
  setSelection,
  selection,
  setShowSearch,
  showSearch,
  setGridData,
  gridData = [],
  numRows,
  setNumRows,
  handleRowAppend,
  setCols,
  cols = [],
  canEdit = true,
  canCreate = true,
  defaultCols,
  onVisibleRegionChanged,
  onAddQueryField
}) {
  const { t } = useTranslation()
  const gridRef = useRef(null)

  const onFill = useOnFill(setGridData, cols)
  const onSearchClose = useCallback(() => setShowSearch(false), [setShowSearch])

  const { freezeColumnsCount, handleFreezeColumn } = useTableConfig('import_stat_table')

  const {
    showMenu,
    setShowMenu,
    onHeaderMenuClick,
    layerProps,
    renderLayer,
    hiddenColumns,
    handleHideColumn,
    handleReset,
    onColumnMoved,
    onColumnResize,
    handleSort,
    openDrawer: open,
    setOpenDrawer: setOpen,
    showDrawer,
    handleCheckboxChange,
    configurableCols,
    keybindings,
    getCellTheme,
    isReadOnlyColumn,
    gridTheme,
    onCellClicked,
    onCellActivated,
    onKeyDown,
    onCellContextMenu,
    onHeaderContextMenu
  } = useTableManager({
    tableId: 'import_stat_table',
    defaultCols,
    cols,
    setCols,
    setGridData,
    gridData,
    selection,
    setSelection,
    canEdit,
    setShowSearch,
    onAddQueryField
  })

  const onClose = () => setOpen(false)

  // Pre-compute Metadata
  const colMetadata = useMemo(() => {
    return (cols || []).map((column) => {
      const columnKey = column.id || ''
      const isStatus = columnKey === 'WorkingTag'
      const isBoolean = column.kind === 'Boolean' || BOOLEAN_KEYS.has(columnKey)
      const cellTheme = getCellTheme(columnKey, column)
      const isReadOnly = isReadOnlyColumn(columnKey, column) || column.readonly || false
      return {
        columnKey,
        isStatus,
        isBoolean,
        kind: column.kind,
        cellTheme,
        isReadOnly,
        hasMenu: column.hasMenu || false
      }
    })
  }, [cols, getCellTheme, isReadOnlyColumn])

  const getData = useCallback(
    ([col, row]) => {
      const item = gridData[row]
      const meta = colMetadata[col]
      if (!meta || !item) {
        return {
          kind: GridCellKind.Text,
          data: '',
          displayData: '',
          readonly: true,
          allowOverlay: false
        }
      }

      const value =
        item[meta.columnKey] ??
        item[meta.columnKey.charAt(0).toLowerCase() + meta.columnKey.slice(1)] ??
        ''

      if (meta.isStatus && meta.columnKey === 'WorkingTag') {
        const strVal = String(value)
        return {
          kind: GridCellKind.Text,
          data: strVal,
          displayData: strVal,
          readonly: true,
          allowOverlay: false,
          hasMenu: meta.hasMenu,
          contentAlign: 'center',
          themeOverride: meta.cellTheme
        }
      }

      if (meta.isBoolean) {
        const booleanValue =
          typeof value === 'boolean'
            ? value
            : value === 1 || value === '1' || value === 'true' || value === 'Có'
        return {
          kind: GridCellKind.Boolean,
          data: booleanValue,
          readonly: meta.isReadOnly,
          allowOverlay: true,
          hasMenu: meta.hasMenu,
          themeOverride: meta.cellTheme
        }
      }

      if (
        meta.columnKey !== 'SyncDelayMinutes' &&
        (meta.kind === 'Number' || typeof value === 'number') &&
        !(typeof value === 'string' && value.includes(':'))
      ) {
        const numVal = Number(value) || 0
        return {
          kind: GridCellKind.Number,
          data: numVal,
          displayData: numVal.toLocaleString('vi-VN'),
          readonly: meta.isReadOnly,
          allowOverlay: !meta.isReadOnly,
          hasMenu: meta.hasMenu,
          contentAlign: 'right',
          themeOverride: meta.cellTheme
        }
      }

      const strValue = typeof value === 'string' ? value : String(value ?? '')
      const isCenter =
        meta.columnKey === 'SyncDelayMinutes' ||
        meta.columnKey === 'MesApprovalTime' ||
        meta.columnKey === 'StartTime' ||
        meta.columnKey === 'EndTime'

      return {
        kind: GridCellKind.Text,
        data: strValue,
        displayData: strValue,
        readonly: meta.isReadOnly,
        allowOverlay: !meta.isReadOnly,
        hasMenu: meta.hasMenu,
        contentAlign: isCenter ? 'center' : undefined,
        themeOverride: meta.cellTheme
      }
    },
    [gridData, colMetadata]
  )

  const onKeyUp = useCallback(() => {}, [])

  const onCellEdited = useCallback(
    async (cell, newValue) => {
      if (
        newValue.kind !== GridCellKind.Text &&
        newValue.kind !== GridCellKind.Custom &&
        newValue.kind !== GridCellKind.Boolean &&
        newValue.kind !== GridCellKind.Number
      ) {
        return
      }
      if (canEdit === false) return
      const [col, row] = cell
      const meta = colMetadata[col]
      if (!meta || meta.isReadOnly || meta.columnKey === 'WorkingTag') return

      setGridData((prevData) => {
        const updatedData = [...prevData]
        if (!updatedData[row]) updatedData[row] = {}

        const currentStatus = updatedData[row]['WorkingTag'] || ''
        const nextStatus = currentStatus === 'A' ? 'A' : 'U'
        updatedData[row][meta.columnKey] = newValue.data
        updatedData[row]['WorkingTag'] = nextStatus

        // Tự động tính tổng thời gian hao phí (5)=1+2+3+4
        if (
          meta.columnKey === 'BreakdownMinutes' ||
          meta.columnKey === 'WaitingMaterialMinutes' ||
          meta.columnKey === 'SetupMinutes' ||
          meta.columnKey === 'RepairMinutes'
        ) {
          const r = updatedData[row]
          const sum =
            (Number(r.BreakdownMinutes) || 0) +
            (Number(r.WaitingMaterialMinutes) || 0) +
            (Number(r.SetupMinutes) || 0) +
            (Number(r.RepairMinutes) || 0)
          r.TotalWasteMinutes = sum
        }

        // Tự động tính Tỷ lệ NG %
        if (
          meta.columnKey === 'ProdQty' ||
          meta.columnKey === 'PassQty' ||
          meta.columnKey === 'DefectQty'
        ) {
          const r = updatedData[row]
          const prod = Number(r.ProdQty) || 0
          const defect = Number(r.DefectQty) || 0
          if (prod > 0) {
            r.DefectRate = `${((defect / prod) * 100).toFixed(2)}%`
          }
        }

        return updatedData
      })
    },
    [colMetadata, canEdit, setGridData]
  )

  const effectiveRows = numRows ?? gridData?.length ?? 0

  return (
    <div className="w-full h-full flex items-center justify-center">
      <div className="w-full h-full flex flex-col bg-white overflow-hidden">
        <h2 className="text-[10px] italic text-indigo-600 border-b border-slate-200 font-bold flex items-center gap-1.5 px-2 py-1 uppercase bg-white">
          <span className="w-1 h-3 bg-indigo-600 rounded-full inline-block shrink-0" />
          <span>{tableTitle || t('Dữ liệu Đăng ký Báo cáo Thống kê sản xuất (TKSX)')}</span>
        </h2>
        <DataEditor
          ref={gridRef}
          theme={gridTheme}
          columns={cols}
          getCellContent={getData}
          onFill={onFill}
          rows={effectiveRows}
          showSearch={showSearch}
          onSearchClose={onSearchClose}
          rowMarkers="both"
          width="100%"
          height="100%"
          rowSelect="multi"
          columnSelect="single"
          gridSelection={selection}
          onGridSelectionChange={setSelection}
          getCellsForSelection={true}
          trailingRowOptions={
            canCreate
              ? {
                  hint: ' ',
                  sticky: true,
                  tint: true
                }
              : undefined
          }
          freezeColumns={freezeColumnsCount}
          headerHeight={23}
          overscrollY={20}
          overscrollX={50}
          smoothScrollY={true}
          smoothScrollX={true}
          freezeTrailingRows={0}
          rowHeight={23}
          fillHandle={Boolean(canEdit)}
          keybindings={keybindings}
          isDraggable={false}
          onRowAppended={() => canCreate && handleRowAppend && handleRowAppend(1)}
          onCellEdited={canEdit ? onCellEdited : undefined}
          highlightRegions={EMPTY_ARRAY}
          onColumnResize={onColumnResize}
          onHeaderMenuClick={onHeaderMenuClick}
          onHeaderContextMenu={onHeaderContextMenu}
          onColumnMoved={onColumnMoved}
          onKeyDown={onKeyDown}
          onKeyUp={onKeyUp}
          onVisibleRegionChanged={onVisibleRegionChanged}
          onCellClicked={onCellClicked}
          onCellActivated={onCellActivated}
          onCellContextMenu={onCellContextMenu}
        />
        {showMenu !== null &&
          renderLayer(
            <div {...layerProps} className="z-[9999] outline-none">
              {showMenu.menuType === 'statusMenu' ? (
                <LayoutStatusMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleReset={handleReset}
                  showDrawer={showDrawer}
                  data={gridData}
                  handleRowAppend={handleRowAppend}
                />
              ) : showMenu.menuType === 'contextMenu' ? (
                <LayoutContextMenuSheet
                  showMenu={showMenu}
                  cols={cols}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  data={gridData}
                  handleRowAppend={handleRowAppend}
                  selection={selection}
                  canCreate={canCreate}
                />
              ) : (
                <LayoutMenuSheet
                  showMenu={showMenu}
                  handleSort={handleSort}
                  handleHideColumn={handleHideColumn}
                  cols={cols}
                  renderLayer={renderLayer}
                  setShowSearch={setShowSearch}
                  setShowMenu={setShowMenu}
                  layerProps={layerProps}
                  handleFreezeColumn={handleFreezeColumn}
                  showDrawer={showDrawer}
                />
              )}
            </div>
          )}
        <Drawer
          title={
            <span className="text-xs flex items-center justify-end font-bold">CÀI ĐẶT SHEET</span>
          }
          styles={{ body: { padding: 15 } }}
          onClose={onClose}
          open={open}
        >
          {(configurableCols || []).map((col) => (
            <div key={col.id} style={{ marginBottom: '10px' }}>
              <Checkbox
                checked={!hiddenColumns.includes(col.id)}
                onChange={(e) => handleCheckboxChange(col.id, e.target.checked)}
              >
                {col.title || col.id}
              </Checkbox>
            </div>
          ))}
        </Drawer>
      </div>
    </div>
  )
}

import { useState, useCallback, useEffect, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import * as XLSX from 'xlsx'
import { queryProdStatsDetail } from '../../services/planRegistrationService'
import { usePageData } from '../../../../../../context/PageDataContext'

export function useStatisticsImport({
  gridData = [],
  setGridData,
  setNumRows,
  getSelectedRows,
  resetTable,
  canCreate,
  canEdit,
  canDelete,
  loadingBarRef
}) {
  const { t } = useTranslation()
  const { setStatusMessage, setPageData } = usePageData()
  const [searchValues, setSearchValues] = useState({
    OperationNo: '',
    ItemCode: '',
    MachineCode: '',
    TeamName: '',
    Shift: '',
    Customer: '',
    Status: ''
  })

  const [dynamicQueryFields, setDynamicQueryFields] = useState([])
  const originalDataRef = useRef([])

  // Hàm load dữ liệu thực tế từ Database thông qua DataHub API
  const fetchStatsData = useCallback(
    async (filters = {}) => {
      loadingBarRef?.current?.continuousStart?.()
      try {
        const res = await queryProdStatsDetail(filters)
        const dataList = res?.data || []
        setGridData(dataList)
        setNumRows(dataList.length)
        originalDataRef.current = dataList

        setPageData?.((prev) => ({
          ...prev,
          total: dataList.length,
          totalAll: res?.pageInfo?.totalAll || dataList.length,
          loadedCount: dataList.length,
          totalColumns: 65
        }))

        return dataList
      } catch (err) {
        setGridData([])
        setNumRows(0)
        originalDataRef.current = []
        setPageData?.((prev) => ({
          ...prev,
          total: 0,
          totalAll: 0,
          loadedCount: 0
        }))
        return []
      } finally {
        loadingBarRef?.current?.complete?.()
      }
    },
    [loadingBarRef, setGridData, setNumRows, setPageData]
  )

  // Tự động truy vấn từ DB khi khởi tạo giao diện
  useEffect(() => {
    fetchStatsData({})
  }, [fetchStatsData])

  // Search từ Backend DataHub khi bấm TÌM KIẾM
  const handleSearchData = useCallback(async () => {
    const dataList = await fetchStatsData(searchValues)
    if (dataList.length > 0) {
      setStatusMessage?.({
        type: 'success',
        text: `Tìm thấy ${dataList.length.toLocaleString('vi-VN')} bản ghi thống kê sản xuất từ hệ thống`
      })
    } else {
      setStatusMessage?.({
        type: 'info',
        text: 'Không tìm thấy dữ liệu thống kê sản xuất phù hợp'
      })
    }
  }, [fetchStatsData, searchValues, setStatusMessage])

  const onResetQuery = useCallback(() => {
    const emptyFilters = {
      OperationNo: '',
      ItemCode: '',
      MachineCode: '',
      TeamName: '',
      Shift: '',
      Customer: '',
      Status: ''
    }
    setSearchValues(emptyFilters)
    fetchStatsData({})
    setStatusMessage?.({
      type: 'info',
      text: 'Đã đặt lại điều kiện và tải lại dữ liệu'
    })
  }, [fetchStatsData, setStatusMessage])

  const onAddQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => {
      if (prev.includes(fieldKey)) return prev
      return [...prev, fieldKey]
    })
  }, [])

  const onRemoveQueryField = useCallback((fieldKey) => {
    setDynamicQueryFields((prev) => prev.filter((k) => k !== fieldKey))
  }, [])

  const handleRowAppend = useCallback(
    (count = 1) => {
      if (!canCreate) {
        setStatusMessage?.({
          type: 'warning',
          text: 'Bạn không có quyền thêm mới'
        })
        return
      }
      const newRows = Array.from({ length: count }, (_, idx) => ({
        WorkingTag: 'A',
        ItemCode: '',
        ItemName: '',
        Version: 'v1.0',
        Model: '',
        DefectMarginWeight: 0,
        TechMarginWeight: 0,
        OperationNo: `LSX-NEW-${Date.now().toString().slice(-4)}`,
        MainWorker: '',
        SubWorker1: '',
        SubWorker2: '',
        BreakdownReason: '',
        MachineCode: '',
        MachineName: '',
        OpTypeCode: '',
        OpTypeName: '',
        UvPlate: 'Không',
        MoldSetQty1: 0,
        MoldSetQty2: 0,
        MoldSetQty3: 0,
        ProdQty: 0,
        PassQty: 0,
        ActualMeters: 0,
        StandardMeters: 0,
        TeamName: '',
        Shift: 'Ca 1',
        StartTime: '07:00',
        EndTime: '15:00',
        StartDate: new Date().toISOString().slice(0, 10),
        EndDate: new Date().toISOString().slice(0, 10),
        StatDate: new Date().toISOString().slice(0, 10),
        StatTicketNo: `PTK-${Date.now().toString().slice(-5)}`,
        StatStaff: '',
        Customer: '',
        SalesStaff: '',
        OrderNo: '',
        ProcessName: '',
        Unit: 'Chiếc',
        ConvUnit: '',
        ProcessSpec: '',
        PartNo: '',
        CorrugatedPartNo: '',
        TrimPartNo: '',
        ColorQty: 0,
        OutPlateType: '',
        FrontColors: 0,
        BackColors: 0,
        JobNumber: '',
        Width: 0,
        Length: 0,
        Height: 0,
        ProductLine: '',
        RawWidth: 0,
        RawLength: 0,
        RawLineCode: '',
        RawLineName: '',
        FlipType: '',
        BomPlates: 0,
        Coating: '',
        SlitterBlades: 0,
        CodePositions: 0,
        PunchHoles: 0,
        StructureCode: '',
        StructureName: '',
        RoutingDocNo: '',
        RoutingDate: '',
        ReleaseDate: '',
        TargetPassQty: 0,
        TargetProdQty: 0,
        RoutingUnit: 'Chiếc',
        BreakdownMinutes: 0,
        WaitingMaterialMinutes: 0,
        SetupMinutes: 0,
        RepairMinutes: 0,
        TotalWasteMinutes: 0,
        RigidBoxGlue: 'Không',
        Outsourcing: 'Không',
        DefectQty: 0,
        DefectRate: '0.00%',
        DefectUnit: 'Chiếc',
        Status: 'Đang sản xuất',
        AutoExport: true,
        AutoImport: true,
        ExportDocNo: '',
        ImportDocNo: '',
        WrongOpCode: false,
        IsAdditionalStat: false,
        TicketCreatedDate: new Date().toISOString().slice(0, 16).replace('T', ' '),
        ActualRunTime: 0,
        ActualCapa: 0,
        CheckPlanStatus: 'Bình thường',
        MesApprovalTime: '',
        SyncDelayMinutes: '',
        IsDuplicateTicket: false,
        TicketCreationLocation: 'MES Client',
        AutoIoStatus: 'Chờ xử lý'
      }))

      setGridData((prev) => [...prev, ...newRows])
      setNumRows((prev) => (prev ?? 0) + count)
      setStatusMessage?.({
        type: 'info',
        text: `Đã thêm ${count} dòng mới`
      })
    },
    [canCreate, setGridData, setNumRows, setStatusMessage]
  )

  const handleSaveData = useCallback(() => {
    if (!canEdit) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Bạn không có quyền chỉnh sửa'
      })
      return
    }
    const modifiedRows = gridData.filter((r) => r.WorkingTag === 'U' || r.WorkingTag === 'A')
    if (modifiedRows.length === 0) {
      setStatusMessage?.({
        type: 'info',
        text: 'Không có thay đổi nào cần lưu'
      })
      return
    }

    loadingBarRef?.current?.continuousStart?.()
    setTimeout(() => {
      const cleanData = gridData.map((r) => ({ ...r, WorkingTag: '' }))
      setGridData(cleanData)
      originalDataRef.current = cleanData
      loadingBarRef?.current?.complete?.()
      setStatusMessage?.({
        type: 'success',
        text: `Đã lưu thành công ${modifiedRows.length} bản ghi`
      })
    }, 400)
  }, [canEdit, gridData, loadingBarRef, setGridData, setStatusMessage])

  const handleDeleteData = useCallback(() => {
    if (!canDelete) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Bạn không có quyền xóa'
      })
      return
    }
    const selected = getSelectedRows?.() || []
    if (selected.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Vui lòng chọn dòng cần xóa'
      })
      return
    }

    const updated = gridData.filter((_, idx) => !selected.includes(idx))
    setGridData(updated)
    setNumRows(updated.length)
    setStatusMessage?.({
      type: 'success',
      text: `Đã xóa ${selected.length} dòng được chọn`
    })
  }, [canDelete, getSelectedRows, gridData, setGridData, setNumRows, setStatusMessage])

  const handleExportExcel = useCallback(() => {
    if (!gridData || gridData.length === 0) {
      setStatusMessage?.({
        type: 'warning',
        text: 'Không có dữ liệu để xuất'
      })
      return
    }
    try {
      const exportData = gridData.map((row) => {
        const copy = { ...row }
        delete copy.WorkingTag
        return copy
      })
      const ws = XLSX.utils.json_to_sheet(exportData)
      const wb = XLSX.utils.book_new()
      XLSX.utils.book_append_sheet(wb, ws, 'DangKy_ThongKe_SX')
      XLSX.writeFile(wb, `DangKy_ThongKe_SX_${new Date().toISOString().slice(0, 10)}.xlsx`)
      setStatusMessage?.({
        type: 'success',
        text: 'Đã xuất file Excel thành công'
      })
    } catch (err) {
      setStatusMessage?.({
        type: 'error',
        text: 'Xuất Excel thất bại: ' + (err?.message || err)
      })
    }
  }, [gridData, setStatusMessage])

  return {
    searchValues,
    setSearchValues,
    dynamicQueryFields,
    handleSearchData,
    onResetQuery,
    onAddQueryField,
    onRemoveQueryField,
    handleRowAppend,
    handleSaveData,
    handleDeleteData,
    handleExportExcel
  }
}

import { useEffect, useRef } from 'react'
import { notification } from 'antd'
import { useTranslation } from 'react-i18next'

import { useDataGridSheet } from '../../../hooks/useDataGridSheet'
import { usePageHotkeys } from '../../../hooks/usePageHotkeys'
import { usePagePermissions } from '../../../hooks/usePagePermissions'
import DataPageContainer from '../../../components/layout/DataPageContainer'
import WindowsConfirmModal from '../../../components/modal/WindowsConfirmModal'

import { useActionColumns } from './columns/actionColumns'
import { useActionTechnique } from './hooks/useActionTechnique'
import ActionActions from './components/ActionActions'
import ActionQuery from './components/ActionQuery'
import ActionTable from './components/ActionTable'

export default function ActionTechniquePage({
  permissions,
  canCreate,
  canEdit,
  canDelete,
  canView,
  controllers,
  cancelAllRequests,
  customLimits,
  ...restProps
}) {
  const { t } = useTranslation()
  const loadingBarRef = useRef(null)

  const pagePerms = usePagePermissions({
    permissions,
    menuKey: restProps?.menuKey || 'system_actions',
    canCreate,
    canEdit,
    canDelete,
    canView,
    ...restProps
  })

  const defaultCols = useActionColumns({
    isFieldVisible: pagePerms.isFieldVisible,
    isFieldReadOnly: pagePerms.isFieldReadOnly
  })

  const { gridData, setGridData, setNumRows, resetTable, getSelectedRows, tableProps } =
    useDataGridSheet({
      storageKey: 'cols_system_actions',
      defaultCols,
      canCreate: pagePerms.canCreate,
      canView: pagePerms.canView
    })

  const {
    actionName,
    setActionName,
    actionKey,
    setActionKey,
    searchValues,
    setSearchValues,
    dynamicQueryFields,
    handleAddQueryField,
    handleRemoveQueryField,
    handleSearchData,
    handleSaveData,
    handleDeleteDataSheet,
    showConfirmModal,
    handleConfirmSearch,
    handleCancelSearch,
    handleResetQuery
  } = useActionTechnique({
    gridData,
    setGridData,
    setNumRows,
    getSelectedRows,
    resetTable,
    defaultCols,
    canCreate: pagePerms.canCreate,
    canEdit: pagePerms.canEdit,
    canView: pagePerms.canView,
    canSearch: pagePerms.canSearch,
    canDelete: pagePerms.canDelete,
    loadingBarRef,
    controllers
  })

  usePageHotkeys({
    onSearch: handleSearchData,
    onSave: handleSaveData,
    onDelete: handleDeleteDataSheet
  })

  const cancelAllRequestsRef = useRef(cancelAllRequests)
  cancelAllRequestsRef.current = cancelAllRequests

  useEffect(() => {
    notification.destroy()
    handleSearchData()
    return () => {
      cancelAllRequestsRef.current?.()
    }
  }, [])

  return (
    <>
      <DataPageContainer
        loadingBarRef={loadingBarRef}
        actions={
          <ActionActions
            handleSearchData={handleSearchData}
            handleSaveData={handleSaveData}
            handleDeleteDataSheet={handleDeleteDataSheet}
            permissions={pagePerms}
          />
        }
        query={
          <ActionQuery
            actionName={actionName}
            setActionName={setActionName}
            actionKey={actionKey}
            setActionKey={setActionKey}
            searchValues={searchValues}
            setSearchValues={setSearchValues}
            dynamicQueryFields={dynamicQueryFields}
            onAddQueryField={handleAddQueryField}
            onRemoveQueryField={handleRemoveQueryField}
            onResetQuery={handleResetQuery}
            handleSearchData={handleSearchData}
            disabled={!pagePerms.canView}
          />
        }
        table={
          <ActionTable
            {...tableProps}
            tableTitle={t('Danh mục Quyền nút & Hành động (Actions)')}
            canEdit={pagePerms.canEdit}
            canCreate={pagePerms.canCreate}
            defaultCols={defaultCols}
            onAddQueryField={handleAddQueryField}
          />
        }
      />

      <WindowsConfirmModal
        isOpen={showConfirmModal}
        onConfirm={handleConfirmSearch}
        onCancel={handleCancelSearch}
        title={t('Xác nhận dữ liệu chưa lưu')}
        message={t('Dữ liệu trên bảng đã được chỉnh sửa nhưng chưa được lưu!')}
        subMessage={t(
          'Nếu tiếp tục truy vấn, tất cả các thay đổi chưa lưu trên bảng sẽ bị hủy bỏ và tải lại từ máy chủ. Bạn có muốn tiếp tục?'
        )}
        confirmText={t('Tiếp tục truy vấn')}
        cancelText={t('Quay lại')}
        type="warning"
      />
    </>
  )
}

import { toRootMenuOrder } from '../rootMenuOrder.js'
/* eslint-disable react/prop-types, no-unused-vars, no-empty */
import { useState, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { updateIndexNo } from '../../../../components/sheet/js/updateIndexNo'
import { togglePageInteraction } from '../../../../../utils/togglePageInteraction'
import { useSaveGenericData } from '../../../../hooks/useSaveGenericData'
import { useAudLimit } from '../../../../hooks/useAudLimit'
import { filterValidRows } from '../../../../../utils/filterUorA'
import { PostAddRootMenu, PostRootMenuU, PostRootMenuD } from '../../../../../api/system'

export function useRootMenuMutation({
  gridData,
  setGridData,
  setNumRows,
  getSelectedRows,
  resetTable,
  canCreate,
  canEdit,
  canView,
  canSearch,
  canDelete,
  loadingBarRef,
  executeSearch,
  userFrom,
  setStatusMessage,
  customLimits
}) {
  const { t } = useTranslation()
  const [showConfirmModal, setShowConfirmModal] = useState(false)
  const { handleSave } = useSaveGenericData(loadingBarRef)
  const { validateSaveData, validateDeleteData, getLimit, limitModalProps } = useAudLimit({
    menuKey: 'ROOT_MENU',
    customLimits,
    setStatusMessage
  })

  const handleConfirmSearch = useCallback(() => {
    setShowConfirmModal(false)
    if (resetTable) resetTable()
    executeSearch({ isManual: true })
  }, [resetTable, executeSearch])

  const handleCancelSearch = useCallback(() => {
    setShowConfirmModal(false)
  }, [])

  const handleSearchData = useCallback(async () => {
    if (!canView || canSearch === false) {
      if (setStatusMessage) {
        setStatusMessage({
          type: 'warning',
          text: t('Bạn không có quyền tìm kiếm hoặc xem dữ liệu màn hình này!')
        })
      }
      return
    }

    const rowsA = filterValidRows(gridData || [], 'A')
    const hasEditedRows = (gridData || []).some((row) => {
      const tag = row?.WorkingTag || row?.Status
      return tag === 'U' || tag === 'E' || tag === 'D'
    })

    if (rowsA.length > 0 || hasEditedRows) {
      setShowConfirmModal(true)
      return
    }

    executeSearch({ isManual: true })
  }, [canView, canSearch, gridData, t, executeSearch, setStatusMessage])

  const handleSaveData = useCallback(async () => {
    if (!canCreate && !canEdit) {
      if (setStatusMessage) {
        setStatusMessage({
          type: 'warning',
          text: t('Bạn không có quyền thêm hoặc sửa dữ liệu!')
        })
      }
      return
    }

    const isSaveLimitValid = validateSaveData({ gridData })
    if (!isSaveLimitValid) {
      return
    }

    const validationErrors = []
    for (let i = 0; i < (gridData || []).length; i++) {
      const row = gridData[i]
      if (!row) continue

      const status = row.WorkingTag || row.Status
      const rowIdx = row.IdxNo || i + 1

      if ((status === 'U' || (status === 'A' && (row.Key || row.Label))) &&
          row.OrderSeq !== undefined && row.OrderSeq !== null && row.OrderSeq !== '' &&
          (!Number.isSafeInteger(Number(row.OrderSeq)) || Number(row.OrderSeq) <= 0)) {
        validationErrors.push(`Dòng ${rowIdx}: STT phải là số nguyên lớn hơn 0`)
      }

      if (status === 'A') {
        if (row.Key || row.Label || row.Link || row.Icon) {
          if (!row.Key || !String(row.Key).trim()) {
            validationErrors.push(`Dòng ${rowIdx}: Mã Key không được để trống`)
          }
          if (!row.Label || !String(row.Label).trim()) {
            validationErrors.push(`Dòng ${rowIdx}: Tên Root Menu không được để trống`)
          }
        }
      } else if (status === 'U') {
        if (!row.Key || !String(row.Key).trim()) {
          validationErrors.push(`Dòng ${rowIdx}: Mã Key không được để trống`)
        }
        if (!row.Label || !String(row.Label).trim()) {
          validationErrors.push(`Dòng ${rowIdx}: Tên Root Menu không được để trống`)
        }
      }
    }

    if (validationErrors.length > 0) {
      if (setStatusMessage) {
        setStatusMessage({
          type: 'error',
          text:
            validationErrors.slice(0, 2).join(' | ') +
            (validationErrors.length > 2 ? ` (+${validationErrors.length - 2} lỗi khác)` : '')
        })
      }
      return
    }

    await handleSave({
      canCreate: canCreate || canEdit,
      gridData,
      setGridData,
      maxRowsPerSave: getLimit('SAVE'),
      addFunction: PostAddRootMenu,
      updateFunction: PostRootMenuU,
      userFrom,
      setStatusMessage,
      loadingText: t('Đang lưu dữ liệu Root Menu...'),
      successText: t('Lưu danh sách Root Menu thành công!'),
      matchKey: 'Key',
      prepareAddRows: (rows) =>
        rows.map((item) => ({
          IdxNo: toRootMenuOrder(item),
          Key: item.Key || '',
          Label: item.Label || '',
          Link: item.Link || '',
          Icon: item.Icon || '',
          Utilities: item.Utilities !== undefined ? Boolean(item.Utilities) : true,
          CreatedBy: userFrom?.UserSeq || userFrom?.UserId || '',
          UpdatedBy: userFrom?.UserSeq || userFrom?.UserId || ''
        })),
      prepareUpdateRows: (rows) =>
        rows.map((item) => ({
          Id: Number(item.Id),
          IdxNo: toRootMenuOrder(item),
          Key: item.Key || '',
          Label: item.Label || '',
          Link: item.Link || '',
          Icon: item.Icon || '',
          Utilities: item.Utilities !== undefined ? Boolean(item.Utilities) : true,
          RowVersion:
            item.RowVersion !== undefined && item.RowVersion !== null ? Number(item.RowVersion) : 0,
          UpdatedAt: item.UpdatedAt ? String(item.UpdatedAt) : '',
          UpdatedBy: userFrom?.UserSeq || userFrom?.UserId || ''
        })),
      mapReturnedFields: (found) => ({
        WorkingTag: '',
        Status: '',
        OrderSeq: found.IdxNo,
        Id: found.Id,
        RowVersion:
          found.RowVersion !== undefined && found.RowVersion !== null
            ? Number(found.RowVersion)
            : 0,
        CreatedAt: found.CreatedAt || '',
        CreatedByName: found.CreatedByName || userFrom?.UserName || userFrom?.UserId || '',
        CreatedBy: found.CreatedBy || userFrom?.UserSeq || userFrom?.UserId || '',
        UpdatedAt: found.UpdatedAt || '',
        UpdatedByName: found.UpdatedByName || userFrom?.UserName || userFrom?.UserId || '',
        UpdatedBy: found.UpdatedBy || userFrom?.UserSeq || userFrom?.UserId || ''
      })
    })
  }, [
    canCreate,
    canEdit,
    gridData,
    setGridData,
    userFrom,
    handleSave,
    validateSaveData,
    getLimit,
    setStatusMessage,
    t
  ])

  const handleDeleteDataSheet = useCallback(() => {
    const selectedRows = getSelectedRows()
    if (!selectedRows || selectedRows.length === 0) {
      if (setStatusMessage) {
        setStatusMessage({
          type: 'warning',
          text: t('Vui lòng chọn dòng cần xóa!')
        })
      }
      return
    }

    const isDeleteLimitValid = validateDeleteData(selectedRows)
    if (!isDeleteLimitValid) {
      return
    }

    const rowsLocalToRemove = []
    const rowsDbToDelete = []

    for (let i = 0; i < selectedRows.length; i++) {
      const row = selectedRows[i]
      if (!row) continue
      const rawId = row.Id ?? row.IdSeq
      const numId = Number(rawId)
      if (
        rawId !== undefined &&
        rawId !== null &&
        String(rawId).trim() !== '' &&
        !isNaN(numId) &&
        numId > 0
      ) {
        rowsDbToDelete.push({ Id: numId, RowVersion: Number(row.RowVersion || 0) })
      } else {
        rowsLocalToRemove.push(row)
      }
    }

    if (rowsDbToDelete.length === 0 && rowsLocalToRemove.length > 0) {
      const localIdxs = new Set(
        rowsLocalToRemove.map((r) => r.IdxNo).filter((x) => x !== undefined)
      )
      setGridData((prev) => {
        const updated = prev.filter((x) => !localIdxs.has(x.IdxNo))
        return updateIndexNo(updated)
      })
      setNumRows((prev) => Math.max(0, prev - rowsLocalToRemove.length))
      if (resetTable) resetTable()
      if (setStatusMessage) {
        setStatusMessage({
          type: 'success',
          text: t('Đã xóa {{count}} dòng mới thêm!', { count: rowsLocalToRemove.length })
        })
      }
      return
    }

    if (rowsDbToDelete.length > 0) {
      if (!canDelete) {
        if (setStatusMessage) {
          setStatusMessage({
            type: 'warning',
            text: t('Bạn không có quyền xóa dữ liệu!')
          })
        }
        return
      }

      togglePageInteraction(true)
      loadingBarRef.current?.continuousStart()
      if (setStatusMessage) {
        setStatusMessage({ type: 'info', text: t('Đang xóa dữ liệu Root Menu...') })
      }

      PostRootMenuD(rowsDbToDelete)
        .then((response) => {
          if (response && response.success) {
            const deletedDbIds = new Set(rowsDbToDelete.map((item) => Number(item.Id)))
            const localIdxs = new Set(
              rowsLocalToRemove.map((r) => r.IdxNo).filter((x) => x !== undefined)
            )

            setGridData((prev) => {
              const updated = prev.filter((row) => {
                const rId = Number(row.Id)
                if (!isNaN(rId) && rId > 0 && deletedDbIds.has(rId)) return false
                if (row.IdxNo !== undefined && localIdxs.has(row.IdxNo)) return false
                return true
              })
              return updateIndexNo(updated)
            })
            setNumRows((prev) => Math.max(0, prev - selectedRows.length))
            if (resetTable) resetTable()
            if (setStatusMessage) {
              setStatusMessage({
                type: 'success',
                text: t('Xóa Root Menu thành công!')
              })
            }
          } else {
            if (setStatusMessage) {
              setStatusMessage({
                type: 'error',
                text: response?.message || t('Lỗi khi xóa dữ liệu!')
              })
            }
          }
        })
        .catch((error) => {
          if (setStatusMessage) {
            setStatusMessage({
              type: 'error',
              text: error.message || t('Có lỗi xảy ra!')
            })
          }
        })
        .finally(() => {
          loadingBarRef.current?.complete()
          togglePageInteraction(false)
        })
    }
  }, [
    canDelete,
    getSelectedRows,
    setGridData,
    setNumRows,
    resetTable,
    loadingBarRef,
    validateDeleteData,
    setStatusMessage,
    t
  ])

  return {
    showConfirmModal,
    handleConfirmSearch,
    handleCancelSearch,
    handleSearchData,
    handleSaveData,
    handleDeleteDataSheet,
    limitModalProps
  }
}

